		public void Recalc()
		{
			if (SoloPlugin.SharedDay > 10)
			{
				quota = 0.0;
				return;
			}
			if (job == 0 || job == 1)
			{
				quota = 0.0;
				return;
			}
			if (job == 4)
			{
				quota = ((usuryDue > 0.001) ? usuryDue : 0.0);
				return;
			}
			int num = day;
			if (num < 1)
			{
				num = 1;
			}
			int streak = num - 1;
			quota = QuotaFromLeftover(num, streak, money, loanExtra, hoopBonus);
			if (usuryDue > 0.001)
			{
				quota += usuryDue;
			}
		}

		public static double QuotaFromLeftover(int personalDay, int streak, double leftover, double loan, double hoop)
		{
			if (personalDay < 1)
			{
				personalDay = 1;
			}
			if (streak < 0)
			{
				streak = 0;
			}
			double num = 500.0 * (double)personalDay + 0.05 * leftover * (double)streak + loan + hoop;
			if (num < 0.0)
			{
				num = 0.0;
			}
			return num;
		}
	}
