	internal class MorphPuff : MonoBehaviour
	{
		private float _born;

		private Renderer _rend;

		private static Material _white;

		private void Awake()
		{
			_born = Time.unscaledTime;
			_rend = GetComponent<Renderer>();
			if (_rend == null)
			{
				return;
			}
			try
			{
				if (_white == null)
				{
					Shader shader = Shader.Find("Unlit/Color");
					if (shader == null)
					{
						shader = Shader.Find("Sprites/Default");
					}
					if (shader == null)
					{
						shader = Shader.Find("UI/Default");
					}
					if (shader == null)
					{
						shader = Shader.Find("Standard");
					}
					if (shader == null)
					{
						shader = Shader.Find("Legacy Shaders/Diffuse");
					}
					if (shader != null)
					{
						_white = new Material(shader);
						_white.color = Color.white;
						try
						{
							_white.SetColor("_Color", Color.white);
						}
						catch
						{
						}
						try
						{
							_white.SetColor("_BaseColor", Color.white);
						}
						catch
						{
						}
					}
				}
				if (_white != null)
				{
					_rend.sharedMaterial = _white;
				}
			}
			catch
			{
			}
		}

		private void Update()
		{
			float num = (Time.unscaledTime - _born) / 0.48f;
			if (num >= 1f)
			{
				UnityEngine.Object.Destroy(gameObject);
				return;
			}
			transform.localScale = Vector3.one * (0.22f + num * 1.6f);
			if (_rend == null)
			{
				return;
			}
			try
			{
				Color color = new Color(1f, 1f, 1f, 0.7f * (1f - num));
				_rend.material.color = color;
				try
				{
					_rend.material.SetColor("_Color", color);
				}
				catch
				{
				}
				try
				{
					_rend.material.SetColor("_BaseColor", color);
				}
				catch
				{
				}
			}
			catch
			{
			}
		}
	}
	internal class MorphFollow : MonoBehaviour
	{
		public Transform target;

		public Transform who;

		public List<Renderer> hide;

		public bool followAir;

		private Transform _look;

		private CharacterController _cc;

		private float _hideAt;

		private void LateUpdate()
		{
			if (target == null)
			{
				UnityEngine.Object.Destroy(gameObject);
				return;
			}
			if (_cc == null)
			{
				_cc = target.GetComponent<CharacterController>();
			}
			if (_cc == null && who != null)
			{
				_cc = who.GetComponentInChildren<CharacterController>();
			}
			if (_look == null && who != null)
			{
				try
				{
					PlayerCameraController componentInChildren = who.GetComponentInChildren<PlayerCameraController>(true);
					if (componentInChildren != null)
					{
						_look = componentInChildren.transform;
					}
				}
				catch
				{
				}
			}
			Vector3 position = target.position;
			if (_cc != null)
			{
				position.y = _cc.bounds.min.y;
			}
			if (!followAir)
			{
				float y = position.y;
				try
				{
					Vector3 origin = position;
					origin.y = y + 0.2f;
					RaycastHit hitInfo;
					if (Physics.Raycast(origin, Vector3.down, out hitInfo, 4f, -5, QueryTriggerInteraction.Ignore))
					{
						MorphFollow morphFollow = ((hitInfo.collider != null) ? hitInfo.collider.GetComponentInParent<MorphFollow>() : null);
						if (morphFollow == null)
						{
							y = hitInfo.point.y;
						}
					}
				}
				catch
				{
				}
				position.y = y;
			}
			Vector3 vector = Vector3.zero;
			try
			{
				PlayerProfile playerProfile = null;
				if (who != null)
				{
					playerProfile = who.GetComponent<PlayerProfile>() ?? who.GetComponentInParent<PlayerProfile>() ?? who.GetComponentInChildren<PlayerProfile>();
				}
				if (playerProfile != null)
				{
					vector = SoloPlugin.FaceFlatPublic(playerProfile);
				}
			}
			catch
			{
			}
			if (vector.sqrMagnitude < 0.01f && _look != null)
			{
				vector = _look.forward;
				vector.y = 0f;
			}
			if (vector.sqrMagnitude < 0.01f)
			{
				vector = target.forward;
				vector.y = 0f;
			}
			Quaternion rotation = ((!(vector.sqrMagnitude > 0.01f)) ? Quaternion.Euler(0f, target.eulerAngles.y, 0f) : Quaternion.LookRotation(vector.normalized, Vector3.up));
			transform.SetPositionAndRotation(position, rotation);
			try
			{
				PlayerController playerController = ((_cc != null) ? target.GetComponent<PlayerController>() : null);
				if (playerController == null && who != null)
				{
					playerController = who.GetComponent<PlayerController>();
				}
				if (playerController == null && who != null)
				{
					playerController = who.GetComponentInParent<PlayerController>();
				}
				if (playerController == null && who != null)
				{
					playerController = who.GetComponentInChildren<PlayerController>();
				}
				if (playerController != null && playerController.State == PlayerController.PlayerState.Ragdoll)
				{
					SoloPlugin.UnmorphFromKnock(playerController);
				}
			}
			catch
			{
			}
			if (hide != null)
			{
				for (int i = 0; i < hide.Count; i++)
				{
					if (hide[i] != null)
					{
						hide[i].enabled = false;
					}
				}
			}
			if (Time.unscaledTime >= _hideAt)
			{
				_hideAt = Time.unscaledTime + 0.25f;
				SoloPlugin.KeepMorphDisguise(who);
			}
		}
	}
