		internal static bool PayOrganCash(PlayerOrgans po, double amount)
		{
			PlayerProfile playerProfile = ProfileFromOrgans(po);
			if (playerProfile == null)
			{
				return false;
			}
			Acc acc = Ensure(playerProfile);
			if (acc == null)
			{
				return false;
			}
			if (EconomyFrozen())
			{
				return amount >= 0.0;
			}
			if (amount < 0.0 && acc.money + 0.0001 < 0.0 - amount)
			{
				return false;
			}
			acc.money += amount;
			if (acc.money < 0.0)
			{
				acc.money = 0.0;
			}
			Broadcast();
			return true;
		}

		internal static void CallOrganRpc(BodyShreddingMachine machine, string rpcName)
		{
