			if (value != null)
			{
				MethodInfo methodInfo = AccessTools.Method(value.GetType(), "RpcPlayOneShotWith3DPos");
				if (methodInfo != null)
				{
					methodInfo.Invoke(value, null);
				}
			}
		}

