		internal static PlayerProfile ProfileFromOrgans(PlayerOrgans po)
		{
			if (po == null)
			{
				return null;
			}
			PlayerProfile playerProfile = po.GetComponent<PlayerProfile>() ?? po.GetComponentInParent<PlayerProfile>() ?? po.GetComponentInChildren<PlayerProfile>();
			if (playerProfile != null)
			{
				return playerProfile;
			}
			try
			{
				return AccessTools.Field(typeof(PlayerOrgans), "_pp").GetValue(po) as PlayerProfile;
			}
			catch
			{
				return null;
			}
		}

		internal static PlayerProfile ProfileFromIdentity(NetworkIdentity ni)
		{
			if (ni == null)
			{
				return null;
			}
			return ni.GetComponent<PlayerProfile>() ?? ni.GetComponentInChildren<PlayerProfile>() ?? ni.GetComponentInParent<PlayerProfile>();
		}

		internal static PlayerProfile ProfileFromInventory(PlayerInventory inv)
		{
			if (inv == null)
			{
				return null;
			}
			PlayerProfile component = ProfileFromIdentity(inv.netIdentity);
			if (component != null)
			{
				return component;
			}
			if (inv.TryGetComponent<PlayerProfile>(out component) && component != null)
			{
				return component;
			}
			return inv.GetComponentInParent<PlayerProfile>() ?? inv.GetComponentInChildren<PlayerProfile>();
		}

		internal static bool IsBatItem(Item item)
		{
			if (item == null)
			{
				return false;
			}
			if (item is Bat)
			{
				return true;
			}
			string text = ((item.gameObject != null) ? item.gameObject.name : "");
			if (item.spawnableSo != null && !string.IsNullOrEmpty(item.spawnableSo.spawnableName))
			{
				text = text + " " + item.spawnableSo.spawnableName;
			}
			string s = text.ToLowerInvariant();
			if (!HasTxt(s, "bat") || HasTxt(s, "combat"))
			{
				return HasTxt(s, "baseball");
			}
			return true;
		}

		private static bool SpawnIsBat(SpawnableSO so)
		{
			if (so == null)
			{
				return false;
			}
			string text = so.spawnableName ?? "";
			if (so.prefab != null)
			{
				text = text + " " + so.prefab.name;
			}
			string s = text.ToLowerInvariant();
			if ((!HasTxt(s, "bat") || HasTxt(s, "combat")) && !HasTxt(text, "球棒"))
			{
				return HasTxt(s, "baseball");
			}
			return true;
		}

		private static bool SpawnIsGun(SpawnableSO so)
		{
			if (so == null)
			{
				return false;
			}
			string text = so.spawnableName ?? "";
			if (so.prefab != null)
			{
				text = text + " " + so.prefab.name;
			}
			string s = text.ToLowerInvariant();
			if (HasTxt(text, "额度枪") || HasTxt(text, "手枪"))
			{
				return true;
			}
			if (HasTxt(s, "pistol") || HasTxt(s, "handgun"))
			{
				return true;
			}
			if (HasTxt(s, "quota") && (HasTxt(s, "gun") || HasTxt(s, "pistol")))
			{
				return true;
			}
			return false;
		}

		private static bool SpawnIsBatOrGun(SpawnableSO so)
		{
			if (!SpawnIsBat(so))
			{
				return SpawnIsGun(so);
			}
			return true;
		}

