				return true;
			}
			return false;
		}

		private static int StashKindCount(Acc a, bool gun)
		{
			if (a == null)
			{
				return 0;
			}
			Dictionary<int, int> dictionary = ParseStash(a.stash);
			int num = 0;
			foreach (KeyValuePair<int, int> item in dictionary)
			{
				SpawnableSO so = FindSpawnable(item.Key);
				if (gun)
				{
					if (SpawnIsGun(so))
					{
						num += item.Value;
					}
				}
				else if (SpawnIsBat(so))
				{
					num += item.Value;
				}
			}
			return num;
		}

		private static bool PlayerOwnsKind(Acc a, PlayerProfile who, bool gun)
		{
			if (StashKindCount(a, gun) > 0)
			{
				return true;
			}
			if (who == null)
			{
				return false;
			}
			try
			{
				PlayerInventory playerInventory = InvOf(who);
				Item item = null;
				if (playerInventory != null)
				{
					try
					{
						item = playerInventory.holdingItem;
					}
					catch
					{
					}
					if (item == null)
					{
						try
						{
							item = playerInventory.NetworkholdingItem;
						}
						catch
						{
						}
					}
				}
				if (item != null)
				{
					if (gun && IsGunItem(item))
					{
						return true;
					}
					if (!gun && IsBatItem(item))
					{
						return true;
					}
				}
			}
			catch
			{
			}
			try
			{
				Item[] array = UnityEngine.Object.FindObjectsByType<Item>(FindObjectsSortMode.None);
				if (array != null)
				{
					Item[] array2 = array;
					foreach (Item item2 in array2)
					{
						if (item2 == null)
						{
							continue;
						}
						if (gun)
						{
							if (!IsGunItem(item2))
							{
								continue;
							}
						}
						else if (!IsBatItem(item2))
						{
							continue;
						}
						if (IsOwner(item2, who))
						{
							return true;
						}
					}
				}
			}
			catch
			{
			}
			return false;
		}

