		internal static int BatShopCost(Acc a)
		{
			if (IsGuard(a))
			{
				return 0;
			}
			int num = ShopPriceOverride("球棒");
			if (num <= 0)
			{
				num = 5;
			}
			num += ToolDayExtra();
			if (num < 1)
			{
				num = 1;
			}
			return num;
		}

		internal static int LocalTicketCount()
		{
			if (NetworkServer.active)
			{
				Acc acc = Ensure(LocalProfile());
				if (acc != null)
				{
					return acc.tickets;
				}
				return 0;
			}
			Acc[] view = View;
			Acc acc2 = FindMine(view, (view != null) ? view.Length : 0);
			if (acc2 != null)
			{
				return acc2.tickets;
			}
			return 0;
		}

		internal static bool WallBatNeedsPay(PlayerProfile who)
		{
			if (who == null)
			{
				return true;
			}
			try
			{
				if (PlayerInElevator(who.transform.position))
				{
					return false;
				}
			}
			catch
			{
			}
			return true;
		}

		internal static bool CanTakeWallBat(PlayerProfile who)
		{
			Acc acc = Ensure(who);
			if (PlayerOwnsKind(acc, who, false))
			{
				return false;
			}
			if (IsGuard(acc) || (who != null && who == LocalProfile() && LocalJob == 4))
			{
				return true;
			}
			if (!WallBatNeedsPay(who))
			{
				return true;
			}
			if (EconomyFrozen())
			{
				return false;
			}
			int num = ((!NetworkServer.active) ? LocalTicketCount() : ((acc != null) ? acc.tickets : 0));
			return num >= BatShopCost(acc);
		}

