		internal static uint NetIdOf(Component c)
		{
			if (c == null)
			{
				return 0u;
			}
			try
			{
				NetworkIdentity networkIdentity = c as NetworkIdentity;
				if (networkIdentity == null)
				{
					NetworkBehaviour networkBehaviour = c as NetworkBehaviour;
					if (networkBehaviour != null)
					{
						networkIdentity = networkBehaviour.netIdentity;
					}
				}
				if (networkIdentity == null)
				{
					networkIdentity = c.GetComponent<NetworkIdentity>();
				}
				if (networkIdentity == null)
				{
					networkIdentity = c.GetComponentInParent<NetworkIdentity>();
				}
				if (networkIdentity != null && networkIdentity.netId != 0)
				{
					return networkIdentity.netId;
				}
			}
			catch
			{
			}
			return 0u;
		}

		private static NetworkIdentity IdentityByNetId(uint id)
		{
			if (id == 0)
			{
				return null;
			}
			NetworkIdentity value;
			try
			{
				if (NetworkServer.active && NetworkServer.spawned != null && NetworkServer.spawned.TryGetValue(id, out value) && value != null)
				{
					return value;
				}
			}
			catch
			{
			}
			try
			{
				if (NetworkClient.spawned != null && NetworkClient.spawned.TryGetValue(id, out value) && value != null)
				{
					return value;
				}
			}
			catch
			{
			}
			return null;
		}

		internal static Acc FindAccByKey(string k)
		{
			if (string.IsNullOrEmpty(k))
			{
				return null;
			}
			Acc value;
			if (Accs.TryGetValue(k, out value) && value != null)
			{
				return value;
			}
			foreach (Acc value2 in Accs.Values)
			{
				if (value2 != null && value2.id == k)
				{
					return value2;
				}
			}
			Acc[] view = View;
			if (view != null)
			{
				Acc[] array = view;
				foreach (Acc acc in array)
				{
					if (acc != null && acc.id == k)
					{
						return acc;
					}
				}
			}
			return null;
		}

		internal static void ClaimOwned(Component c, PlayerProfile who)
		{
			uint num = NetIdOf(c);
			if (num != 0 && !(who == null))
			{
				Acc acc = Ensure(who);
				string value = Key(who);
				if (acc != null && !string.IsNullOrEmpty(acc.id))
				{
					value = acc.id;
				}
				BatOwnerKey[num] = value;
				string value2 = who.playerName;
				if (string.IsNullOrEmpty(value2) && acc != null)
				{
					value2 = acc.name;
				}
				if (string.IsNullOrEmpty(value2))
				{
					value2 = "玩家";
				}
				BatOwnerName[num] = value2;
			}
		}

		internal static void ClaimBat(Item item, PlayerProfile who)
		{
			ClaimOwned(item, who);
		}

		internal static void ClearOwned(Component c)
		{
			uint num = NetIdOf(c);
			if (num != 0)
			{
				BatOwnerKey.Remove(num);
				BatOwnerName.Remove(num);
			}
		}

		internal static void ClearBatOwner(Item item)
		{
			ClearOwned(item);
		}

		internal static bool HasOwner(Component c)
		{
			uint num = NetIdOf(c);
			if (num == 0)
			{
				return false;
			}
			string value;
			if (BatOwnerKey.TryGetValue(num, out value))
			{
				return !string.IsNullOrEmpty(value);
			}
			return false;
		}

		internal static bool KeyIsPlayer(string k, PlayerProfile who)
		{
			if (string.IsNullOrEmpty(k) || who == null)
			{
				return false;
			}
			if (k == Key(who))
			{
				return true;
			}
			if (!string.IsNullOrEmpty(who.playerName) && k == "p" + who.playerName)
			{
				return true;
			}
			Acc acc = FindAccByKey(k);
			if (acc != null)
			{
				if (!string.IsNullOrEmpty(acc.id) && acc.id == Key(who))
				{
					return true;
				}
