		private static bool IsDiceItem(Item item)
		{
			if (item == null)
			{
				return false;
			}
			try
			{
				string text = item.GetType().Name ?? "";
				string text2 = text.ToLowerInvariant();
				if (HasTxt(text2, "dice") || text2 == "die" || HasTxt(text2, "dicer"))
				{
					return true;
				}
			}
			catch
			{
			}
			string text3 = ((item.gameObject != null) ? item.gameObject.name : "");
			if (item.spawnableSo != null && !string.IsNullOrEmpty(item.spawnableSo.spawnableName))
			{
				text3 = text3 + " " + item.spawnableSo.spawnableName;
			}
			string text4 = text3 ?? "";
			string s = text4.ToLowerInvariant();
			if (HasTxt(text4, "骰宝"))
			{
				return false;
			}
			if (HasTxt(s, "craps") && !HasTxt(s, "dice") && !HasTxt(s, "die"))
			{
				return false;
			}
			if (HasTxt(text4, "骰子"))
			{
				return true;
			}
			if (HasTxt(s, "dice"))
			{
				return true;
			}
			if (HasTxt(s, "die") && !HasTxt(s, "diet") && !HasTxt(s, "dielectric"))
			{
				return true;
			}
			return false;
		}

