		internal static void FloorDiceThrowForce(PlayerInventory inv, ref float force, ref float torque)
		{
			if (inv == null)
			{
				return;
			}
			Item item = null;
			try
			{
				item = inv.NetworkholdingItem;
			}
			catch
			{
			}
			if (item == null)
			{
				try
				{
					item = inv.holdingItem;
				}
				catch
				{
				}
			}
			if (!IsDiceItem(item))
			{
				return;
			}
			if (_invPsF == null)
			{
				_invPsF = AccessTools.Field(typeof(PlayerInventory), "_ps");
			}
			PlayerSettings playerSettings = null;
			try
			{
				if (_invPsF != null)
				{
					playerSettings = _invPsF.GetValue(inv) as PlayerSettings;
				}
			}
			catch
			{
			}
			if (!(playerSettings == null))
			{
				float num = Mathf.Lerp(playerSettings.minItemThrowForce, playerSettings.maxItemThrowForce, 0.5f);
				float num2 = Mathf.Lerp(playerSettings.minItemThrowTorque, playerSettings.maxItemThrowTorque, 0.5f);
				if (force < num)
				{
					force = num;
				}
				if (torque < num2)
				{
					torque = num2;
				}
			}
		}

