		private static bool CrouchKeyDown()
		{
			try
			{
				Keyboard current = Keyboard.current;
				if (current != null && (current.leftCtrlKey.wasPressedThisFrame || current.rightCtrlKey.wasPressedThisFrame || current.cKey.wasPressedThisFrame))
				{
					return true;
				}
			}
			catch
			{
			}
			try
			{
				if (Input.GetKeyDown(KeyCode.LeftControl) || Input.GetKeyDown(KeyCode.RightControl) || Input.GetKeyDown(KeyCode.C) || Input.GetKeyDown(KeyCode.LeftMeta) || Input.GetKeyDown(KeyCode.RightMeta))
				{
					return true;
				}
			}
			catch
			{
			}
			return false;
		}

