		internal static Component FindOwnedRoot(Component c)
		{
			if (c == null)
			{
				return null;
			}
			if (HasOwner(c))
			{
				return c;
			}
			try
			{
				Transform parent = c.transform;
				int num = 0;
				while (parent != null && num < 16)
				{
					NetworkIdentity component = parent.GetComponent<NetworkIdentity>();
					if (component != null && HasOwner(component))
					{
						return component;
					}
					GameBase component2 = parent.GetComponent<GameBase>();
					if (component2 != null && HasOwner(component2))
					{
						return component2;
					}
					GachaMachine component3 = parent.GetComponent<GachaMachine>();
					if (component3 != null && HasOwner(component3))
					{
						return component3;
					}
					BodyShreddingMachine component4 = parent.GetComponent<BodyShreddingMachine>();
					if (component4 != null && HasOwner(component4))
					{
						return component4;
					}
					parent = parent.parent;
					num++;
				}
			}
			catch
			{
			}
			try
			{
				NetworkIdentity[] componentsInChildren = c.GetComponentsInChildren<NetworkIdentity>(true);
				if (componentsInChildren != null)
				{
					for (int i = 0; i < componentsInChildren.Length; i++)
					{
						if (componentsInChildren[i] != null && HasOwner(componentsInChildren[i]))
						{
							return componentsInChildren[i];
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				GameBase[] componentsInChildren2 = c.GetComponentsInChildren<GameBase>(true);
				if (componentsInChildren2 != null)
				{
					for (int j = 0; j < componentsInChildren2.Length; j++)
					{
						if (componentsInChildren2[j] != null && HasOwner(componentsInChildren2[j]))
						{
							return componentsInChildren2[j];
						}
					}
				}
			}
			catch
			{
			}
			return null;
		}

		internal static Component OwnedMachineRoot(Component c)
		{
			return FindOwnedRoot(c);
		}

		internal static bool CanPlayOwnedMachine(Component machine, PlayerProfile user)
		{
			Component component = FindOwnedRoot(machine);
			if (component == null)
			{
				return true;
			}
			if (IsOwner(component, user))
			{
				return true;
			}
			if (EconomyFrozen())
			{
				return false;
			}
			if (HasMachinePass(user, component))
			{
				return true;
			}
			if (NetworkServer.active)
			{
				Acc acc = Ensure(user);
				if (acc != null)
				{
					return acc.tickets >= 1;
				}
				return false;
			}
			return LocalTicketCount() >= 1;
		}

		internal static bool CanUseOwnedMachineLocal(Component machine, PlayerProfile user)
		{
			return CanPlayOwnedMachine(machine, user);
		}

		internal static void RefreshRentDay(Acc a)
		{
			if (a != null && a.rentDay != SharedDay)
			{
				a.rentDay = SharedDay;
				a.rentPass = "";
			}
		}

		private static bool PassHas(string pass, uint id)
		{
			if (string.IsNullOrEmpty(pass) || id == 0)
			{
				return false;
			}
			string text = id.ToString(CultureInfo.InvariantCulture);
			string[] array = pass.Split(new char[1] { ',' });
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] == text)
				{
					return true;
				}
			}
			return false;
		}

		private static void PassAdd(Acc a, uint id)
		{
			if (a == null || id == 0)
			{
				return;
			}
			RefreshRentDay(a);
			if (!PassHas(a.rentPass, id))
			{
				string text = id.ToString(CultureInfo.InvariantCulture);
				if (string.IsNullOrEmpty(a.rentPass))
				{
					a.rentPass = text;
				}
				else
				{
					a.rentPass = a.rentPass + "," + text;
				}
			}
		}

		private static bool HasMachinePass(PlayerProfile user, Component root)
		{
			uint num = NetIdOf(root);
			if (num == 0)
			{
				return false;
			}
			Acc acc = null;
			if (NetworkServer.active)
			{
				acc = Ensure(user);
			}
			else
			{
				string text = Key(user);
				Acc[] view = View;
				if (view != null)
				{
					Acc[] array = view;
					foreach (Acc acc2 in array)
					{
						if (acc2 != null && (acc2.id == text || (user != null && acc2.name == user.playerName)))
						{
							acc = acc2;
							break;
						}
					}
				}
			}
			if (acc == null)
			{
				return false;
			}
			if (acc.rentDay != SharedDay)
			{
				return false;
			}
			return PassHas(acc.rentPass, num);
		}

		internal static bool TryChargeMachineUse(Component machine, PlayerProfile user)
		{
			if (machine == null)
			{
				return true;
			}
			Component component = FindOwnedRoot(machine);
			if (component == null)
			{
				return true;
			}
			if (IsOwner(component, user))
			{
				return true;
			}
			if (user == null)
			{
				return false;
			}
			if (EconomyFrozen())
			{
				return false;
			}
			uint num = NetIdOf(component);
			if (HasMachinePass(user, component))
			{
				return true;
			}
			string value;
			if (num == 0 || !BatOwnerKey.TryGetValue(num, out value) || string.IsNullOrEmpty(value))
			{
				return true;
			}
			Acc acc = Ensure(user);
			if (acc == null || acc.tickets < 1)
			{
				return false;
			}
			acc.tickets--;
			Acc acc2 = FindAccByKey(value);
			if (acc2 != null)
			{
				acc2.tickets++;
			}
			PassAdd(acc, num);
			Broadcast();
			return true;
		}

		internal static void ApplyOwnerProfitCut(GameBase g, double multiplier)
		{
			if (!NetworkServer.active || g == null || multiplier <= 1.0001)
			{
				return;
			}
			Component component = FindOwnedRoot(g);
			if (component == null)
			{
				return;
			}
			PlayerProfile playerProfile = PayoutTarget(g) ?? PlayerForGame(g) ?? RoundOwnerProfile(g);
			if (playerProfile == null || IsOwner(component, playerProfile))
			{
				return;
			}
			uint num = NetIdOf(component);
			string value;
			if (num == 0 || !BatOwnerKey.TryGetValue(num, out value) || string.IsNullOrEmpty(value))
			{
				return;
			}
			Acc acc = FindAccByKey(value);
			Acc acc2 = Ensure(playerProfile);
			if (acc == null || acc2 == null || acc.id == acc2.id)
			{
				return;
			}
			double num2 = 0.0;
			string text = Key(playerProfile);
			if (!string.IsNullOrEmpty(text) && _betAmt.ContainsKey(text))
			{
				num2 = _betAmt[text];
			}
			if (num2 <= 0.0001)
			{
				try
				{
					num2 = g.currentBet.ToDouble();
				}
				catch
				{
				}
			}
			if (num2 <= 0.0001)
			{
				return;
			}
			double num3 = num2 * (multiplier - 1.0);
			if (!(num3 <= 0.0001))
			{
				double num4 = num3 * 0.1;
				if (num4 > acc2.money)
				{
					num4 = acc2.money;
				}
				if (!(num4 <= 0.0001))
				{
					acc2.money -= num4;
					acc.money += num4;
					string text2 = (string.IsNullOrEmpty(acc.name) ? "机主" : acc.name);
					string text3 = (string.IsNullOrEmpty(acc2.name) ? "玩家" : acc2.name);
					NotifyMoney(acc2, "-" + MoneyDollar(num4) + " to " + text2, false);
					NotifyMoney(acc, "+" + MoneyDollar(num4) + " 机器分成 ← " + text3, true);
					Broadcast();
				}
			}
		}

		private static void ClaimSpawnedOwned(GameObject go, PlayerProfile who)
		{
			if (go == null || who == null)
			{
				return;
			}
			try
			{
				NetworkIdentity[] componentsInChildren = go.GetComponentsInChildren<NetworkIdentity>(true);
				if (componentsInChildren != null)
				{
					for (int i = 0; i < componentsInChildren.Length; i++)
					{
						ClaimOwned(componentsInChildren[i], who);
					}
				}
			}
			catch
			{
			}
			try
			{
				GameBase[] componentsInChildren2 = go.GetComponentsInChildren<GameBase>(true);
				if (componentsInChildren2 != null)
				{
					for (int j = 0; j < componentsInChildren2.Length; j++)
					{
						ClaimOwned(componentsInChildren2[j], who);
					}
				}
			}
			catch
			{
			}
			try
			{
				BodyShreddingMachine[] componentsInChildren3 = go.GetComponentsInChildren<BodyShreddingMachine>(true);
				if (componentsInChildren3 != null)
				{
					for (int k = 0; k < componentsInChildren3.Length; k++)
					{
						ClaimOwned(componentsInChildren3[k], who);
					}
				}
			}
			catch
			{
			}
			try
			{
				Item[] componentsInChildren4 = go.GetComponentsInChildren<Item>(true);
				if (componentsInChildren4 != null)
				{
					for (int l = 0; l < componentsInChildren4.Length; l++)
					{
						ClaimOwned(componentsInChildren4[l], who);
					}
				}
			}
			catch
			{
			}
			TrackSpawnedGo(go);
		}

