		internal static bool CanPickupBat(Item item, PlayerProfile who)
		{
			if (item == null)
			{
				return false;
			}
			if (BatHasOwner(item))
			{
				return IsBatOwner(item, who);
			}
			return CanTakeWallBat(who);
		}

		internal static bool TryPayBatPickup(Item item, PlayerInventory inv)
		{
			PlayerProfile playerProfile = ProfileFromInventory(inv);
			if (playerProfile == null)
			{
				return false;
			}
			if (BatHasOwner(item))
			{
				return IsBatOwner(item, playerProfile);
			}
			if (!WallBatNeedsPay(playerProfile))
			{
				ClaimBat(item, playerProfile);
				NoteBoughtBat(item, playerProfile);
				Broadcast();
				return true;
			}
			if (EconomyFrozen())
			{
				return false;
			}
			Acc acc = Ensure(playerProfile);
			if (acc == null)
			{
				return false;
			}
			if (PlayerOwnsKind(acc, playerProfile, false))
			{
				NotifyMoney(acc, "每人只能买 1 根球棒", 2);
				return false;
			}
			int num = BatShopCost(acc);
			if (num < 0)
			{
				num = 0;
			}
			if (IsGuard(acc))
			{
				num = 0;
			}
			if (acc.tickets < num)
			{
				return false;
			}
			acc.tickets -= num;
			ClaimBat(item, playerProfile);
			NoteBoughtBat(item, playerProfile);
			Broadcast();
			return true;
		}

		private static void NoteBoughtBat(Item item, PlayerProfile who)
		{
			Acc acc = Ensure(who);
			int num = ItemSpawnId(item);
			if (acc != null && num != 0 && StashKindCount(acc, false) <= 0)
			{
				StashAdd(acc, num, 1);
			}
		}

