		internal static double ParseTypedAmount(string s)
		{
			if (string.IsNullOrEmpty(s))
			{
				return 0.0;
			}
			string s2 = s.Trim().Replace(",", "").Replace("$", "");
			double result;
			if (double.TryParse(s2, NumberStyles.Float, CultureInfo.InvariantCulture, out result))
			{
				return result;
			}
			if (double.TryParse(s2, NumberStyles.Float, CultureInfo.CurrentCulture, out result))
			{
				return result;
			}
			return 0.0;
		}

