		{
			if (kp == null && g != null)
			{
				try
				{
					kp = g.Keypad;
				}
				catch
				{
					kp = null;
				}
			}
			if (kp != null)
			{
				try
				{
					CacheKeypadFields();
					if (_kpInputF != null)
					{
						double num = ParseTypedAmount(_kpInputF.GetValue(kp) as string);
						if (num > 0.0)
						{
							return num;
						}
					}
				}
				catch
				{
				}
				try
				{
					double num2 = kp.GetCurrentInput().ToDouble();
					if (num2 > 0.0)
					{
						return num2;
					}
				}
				catch
				{
				}
			}
			if (g != null)
			{
				try
				{
					double num3 = g.currentBet.ToDouble();
					if (num3 > 0.0)
					{
						return num3;
					}
				}
				catch
				{
				}
			}
			return 0.0;
		}

