			uint num = NetIdOf(g);
			if (num != 0)
			{
				LendTyped[num] = true;
				LendLender[num] = Key(p);
				NoteLastPress(g, p);
				double num2 = ReadKeypadAmount(g, null);
				if (num2 > 0.0)
				{
					LendAmt[num] = num2;
				}
			}
		}

