		internal static void NoteKeypadInput(Keypad kp, string newValue)
		{
			if (kp == null || !NetworkServer.active)
			{
				return;
			}
			GameBase gameBase = GameFromKeypad(kp);
			if (gameBase == null || !GameHasCashout(gameBase))
			{
				return;
			}
			uint num = NetIdOf(gameBase);
			bool value;
			if (num != 0 && LendTyped.TryGetValue(num, out value) && value)
			{
				double num2 = ParseTypedAmount(newValue);
				if (num2 <= 0.0)
				{
					num2 = ReadKeypadAmount(gameBase, kp);
				}
				if (!(num2 <= 0.0))
				{
					LendAmt[num] = num2;
				}
			}
		}

		internal static PlayerProfile KeypadLimitPlayer(GameBase g)
		{
			if (g != null && GameHasCashout(g) && !GameIsPlaying(g))
			{
				PlayerProfile playerProfile = LendTypistProfile(g);
				if (playerProfile != null)
				{
					return playerProfile;
				}
				playerProfile = LastPressProfile(g);
				if (playerProfile != null)
				{
					return playerProfile;
				}
				return PendingPadPlayer;
			}
			PlayerProfile playerProfile2 = LastPressProfile(g);
			if (playerProfile2 != null)
			{
				return playerProfile2;
			}
			playerProfile2 = PlayerForGame(g);
			if (playerProfile2 != null)
			{
				return playerProfile2;
			}
			if (!NetworkServer.active)
			{
				playerProfile2 = LocalProfile();
				if (playerProfile2 != null)
				{
					return playerProfile2;
				}
			}
			if (PendingPadPlayer != null)
			{
				return PendingPadPlayer;
			}
			return BetUiPlayer() ?? LocalProfile();
		}

		internal static double KeypadMaxAmount(GameBase g)
		{
			if (g != null && GameHasCashout(g) && !GameIsPlaying(g))
			{
				PlayerProfile playerProfile = LendTypistProfile(g);
				if (playerProfile == null)
				{
					playerProfile = PendingPadPlayer;
				}
				if (playerProfile != null)
				{
					double num = Wallet(playerProfile);
					if (num < 1.0)
					{
						num = 1.0;
					}
					return num;
				}
				return 1000000000.0;
			}
			PlayerProfile p = KeypadLimitPlayer(g);
			return PlayMaxAmount(p);
		}

