		internal static void PushPadRpc(Keypad kp, double bet, PlayerProfile p)
		{
			if (kp == null)
			{
				return;
			}
			try
			{
				kp.Network_currentInput = bet.ToString("R", CultureInfo.InvariantCulture);
			}
			catch
			{
			}
			try
			{
				MethodInfo methodInfo = AccessTools.Method(typeof(Keypad), "RpcUpdateDisplay");
				if (methodInfo != null)
				{
					methodInfo.Invoke(kp, null);
				}
			}
			catch
			{
			}
			try
			{
				double num = MinBetAmount(p);
				double cash = OwnWallet(p);
				Color color = ((bet + 0.0001 >= num && !BetOverWallet(bet, cash)) ? new Color(0.25f, 1f, 0.35f, 1f) : new Color(1f, 0.22f, 0.18f, 1f));
				MethodInfo methodInfo2 = AccessTools.Method(typeof(Keypad), "RpcSetDisplayColor");
				if (methodInfo2 != null)
				{
					methodInfo2.Invoke(kp, new object[1] { color });
				}
			}
			catch
			{
			}
		}

		internal static void ApplyPresserBet(Keypad kp, double pct)
		{
			GameBase gameBase = GameFromKeypad(kp);
			if (gameBase == null && kp != null)
			{
				try
				{
					gameBase = kp.GetComponentInParent<GameBase>();
				}
				catch
				{
				}
			}
			PlayerProfile playerProfile = PendingPadPlayer ?? LastPressProfile(gameBase) ?? KeypadLimitPlayer(gameBase);
			if (playerProfile == null)
			{
				playerProfile = LocalProfile();
			}
			if (playerProfile != null)
			{
				PendingPadPlayer = playerProfile;
				if (gameBase != null)
				{
					NoteLastPress(gameBase, playerProfile);
				}
				AdoptMachinePlayer((kp != null) ? ((NetworkBehaviour)kp) : ((NetworkBehaviour)gameBase), playerProfile);
			}
			double num = OwnWallet(playerProfile);
			if (gameBase != null && GameHasCashout(gameBase) && !GameIsPlaying(gameBase))
			{
				num = Wallet(playerProfile);
			}
			double num2 = MinBetAmount(playerProfile);
			double num3 = num2;
			if (pct > 0.0001)
			{
				num3 = num * pct;
			}
			if (num3 < num2)
			{
				num3 = num2;
			}
			if (num3 > num)
			{
				num3 = num;
			}
			num3 = FitWalletBet(num3, num);
			RememberPadBet(gameBase, kp, num3);
			CacheKeypadFields();
			try
			{
				if (kp != null && _kpInputF != null)
				{
					_kpInputF.SetValue(kp, num3.ToString("R", CultureInfo.InvariantCulture));
				}
			}
			catch
			{
			}
			PaintKeypad(kp);
			if (!NetworkServer.active || gameBase == null || (GameIsPlaying(gameBase) && !IsPartnerTable(gameBase) && !IsRoulette(gameBase) && !GameHasCashout(gameBase)))
			{
				return;
			}
			try
			{
				gameBase.ServerSetBet(MoneyBNAtMost(num3, num));
			}
			catch
			{
			}
			RememberPadBet(gameBase, kp, num3);
			try
			{
				MethodInfo methodInfo = AccessTools.Method(typeof(Keypad), "ServerUpdateMinMaxBetText");
				if (kp != null && methodInfo != null)
				{
					ParameterInfo[] parameters = methodInfo.GetParameters();
					if (parameters != null && parameters.Length == 2)
					{
						methodInfo.Invoke(kp, new object[2]
						{
							MoneyBN(num2),
							MoneyBNAtMost(KeypadMaxAmount(gameBase), KeypadMaxAmount(gameBase))
						});
					}
					else if (parameters != null && parameters.Length == 0)
					{
						methodInfo.Invoke(kp, null);
					}
				}
			}
			catch
			{
			}
			if (NetworkServer.active)
			{
				PushPadRpc(kp, num3, playerProfile);
			}
			PaintKeypad(kp);
		}

		internal static GameBase FindGameByNetId(uint id)
		{
			GameBase g;
			Keypad kp;
			ResolvePad(id, out g, out kp);
			return g;
		}

		private static void ResolvePad(uint id, out GameBase g, out Keypad kp)
		{
			g = null;
			kp = null;
			NetworkIdentity networkIdentity = IdentityByNetId(id);
			if (networkIdentity == null)
			{
				return;
			}
			try
			{
				kp = networkIdentity.GetComponent<Keypad>();
			}
			catch
			{
				kp = null;
			}
			try
			{
				g = networkIdentity.GetComponent<GameBase>();
			}
			catch
			{
				g = null;
			}
			if (g == null && kp != null)
			{
				g = GameFromKeypad(kp);
