		internal static GameBase GameNearPlayer(PlayerProfile p, uint preferId)
		{
			GameBase gameBase = FindGameByNetId(preferId);
			if (gameBase != null)
			{
				return gameBase;
			}
			if (p == null)
			{
				return null;
			}
			Vector3 position;
			try
			{
				position = p.transform.position;
			}
			catch
			{
				return null;
			}
			GameBase result = null;
			float num = 64f;
			GameBase[] scanGames = _scanGames;
			if (scanGames == null)
			{
				return null;
			}
			GameBase[] array = scanGames;
			foreach (GameBase gameBase2 in array)
			{
				if (!(gameBase2 == null))
				{
					Vector3 position2 = gameBase2.transform.position;
					float num2 = position2.x - position.x;
					float num3 = position2.y - position.y;
					float num4 = position2.z - position.z;
					float num5 = num2 * num2 + num3 * num3 + num4 * num4;
					if (num5 < num)
					{
						num = num5;
						result = gameBase2;
					}
				}
			}
			return result;
		}

