		internal static string ButtonKind(Component c)
		{
			if (c == null)
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder();
			try
			{
				stringBuilder.Append(c.gameObject.name);
			}
			catch
			{
			}
			try
			{
				InteractableBase interactableBase = c as InteractableBase;
				if (interactableBase == null)
				{
					interactableBase = c.GetComponent<InteractableBase>();
				}
				if (interactableBase != null)
				{
					stringBuilder.Append(' ');
					stringBuilder.Append(interactableBase.InteractableName ?? "");
					stringBuilder.Append(' ');
					stringBuilder.Append(interactableBase.TooltipMessage ?? "");
				}
			}
			catch
			{
			}
			try
			{
				Transform tr = c.transform;
				AppendTmpTexts(tr, stringBuilder, 0);
			}
			catch
			{
			}
			string text = stringBuilder.ToString();
			string text2 = text.ToLowerInvariant();
			if (text.IndexOf("提现") >= 0 || text2.IndexOf("withdraw") >= 0 || text2.IndexOf("cashout") >= 0 || text2.IndexOf("cash-out") >= 0 || text2.IndexOf("cash out") >= 0)
			{
				return "cashout";
			}
			if (text.IndexOf("开始") >= 0 || text.IndexOf("前进") >= 0 || text2.IndexOf("start") >= 0 || text2.IndexOf("advance") >= 0 || text2.IndexOf("play") >= 0)
			{
				return "start";
			}
			if (text.IndexOf("最小") >= 0 || text.IndexOf("全仓") >= 0 || text2.IndexOf("1/4") >= 0 || text2.IndexOf("1/2") >= 0 || text2.IndexOf("setbetminimum") >= 0 || text2.IndexOf("setbetquarter") >= 0 || text2.IndexOf("setbethalf") >= 0 || text2.IndexOf("setbetall") >= 0 || text2.IndexOf("quarter") >= 0 || text2.IndexOf("all-in") >= 0 || text2.IndexOf("allin") >= 0)
			{
				return "preset";
			}
			string text3 = "";
			try
			{
				text3 = c.gameObject.name.Trim();
			}
			catch
			{
			}
			if (text3 == "C" || text3 == "c" || text2.IndexOf("clear") >= 0)
			{
				return "preset";
			}
			if (text3 == "000" || text3 == "00" || (text3.Length == 1 && text3[0] >= '0' && text3[0] <= '9'))
			{
				return "digit";
			}
			if (text2.IndexOf("appenddigit") >= 0 || text2.IndexOf("digit") >= 0)
			{
				return "digit";
			}
			try
			{
				if (c.GetComponentInParent<Keypad>() != null)
				{
					return "digit";
				}
			}
			catch
			{
			}
			return "";
		}

		private static void AppendTmpTexts(Transform tr, StringBuilder sb, int depth)
		{
			if (tr == null || depth > 3)
			{
				return;
			}
			try
			{
				sb.Append(' ').Append(tr.name);
				Component[] components = tr.GetComponents<Component>();
				if (components != null)
				{
					Component[] array = components;
					foreach (Component component in array)
					{
						if (component == null)
						{
							continue;
						}
						string text = component.GetType().Name;
						if (text.IndexOf("TextMeshPro") < 0 && text != "Text")
						{
							continue;
						}
						try
						{
							PropertyInfo property = component.GetType().GetProperty("text");
							if (property != null)
							{
								string value = property.GetValue(component, null) as string;
								if (!string.IsNullOrEmpty(value))
								{
									sb.Append(' ').Append(value);
								}
							}
						}
						catch
						{
						}
					}
				}
				int num = tr.childCount;
				if (num > 10)
				{
					num = 10;
				}
				for (int j = 0; j < num; j++)
				{
					AppendTmpTexts(tr.GetChild(j), sb, depth + 1);
				}
			}
			catch
			{
			}
		}

		private static double PadPresetPct(Component c)
		{
			if (c == null)
			{
				return -1.0;
			}
			StringBuilder stringBuilder = new StringBuilder();
			try
			{
				stringBuilder.Append(c.gameObject.name);
			}
			catch
			{
			}
			try
			{
				InteractableBase interactableBase = c as InteractableBase;
				if (interactableBase == null)
				{
					interactableBase = c.GetComponent<InteractableBase>();
				}
				if (interactableBase != null)
				{
					stringBuilder.Append(' ');
					stringBuilder.Append(interactableBase.InteractableName ?? "");
					stringBuilder.Append(' ');
					stringBuilder.Append(interactableBase.TooltipMessage ?? "");
				}
			}
			catch
			{
			}
			try
			{
				AppendTmpTexts(c.transform, stringBuilder, 0);
			}
			catch
			{
			}
			string text = stringBuilder.ToString();
			string text2 = text.ToLowerInvariant();
			if (text2.IndexOf("1/4") >= 0 || text2.IndexOf("quarter") >= 0 || text2.IndexOf("setbetquarter") >= 0)
			{
				return 0.25;
			}
			if (text2.IndexOf("1/2") >= 0 || text2.IndexOf("half") >= 0 || text2.IndexOf("setbethalf") >= 0)
			{
				return 0.5;
			}
			if (text.IndexOf("全仓") >= 0 || text2.IndexOf("all-in") >= 0 || text2.IndexOf("allin") >= 0 || text2.IndexOf("setbetall") >= 0)
			{
				return 1.0;
			}
			if (text.IndexOf("最小") >= 0 || text2.IndexOf("setbetminimum") >= 0)
			{
				return 0.0;
			}
			return -1.0;
		}

		internal static bool HandlePadButton(Component c, PlayerInteract pi)
		{
			PlayerProfile playerProfile = ProfileFromInteract(pi);
			if (playerProfile == null)
			{
				playerProfile = PendingPadPlayer;
			}
			if (playerProfile == null && !NetworkServer.active)
			{
				playerProfile = LocalProfile();
			}
			if (MorphBlocksMachine(c, playerProfile))
			{
				NoteMorphNoPlay(playerProfile);
				return true;
			}
			if (playerProfile != null)
			{
				PendingPadPlayer = playerProfile;
			}
			if (playerProfile != null)
			{
				AdoptMachinePlayer(c, playerProfile);
			}
			GameBase g = GameFrom(c);
			switch (ButtonKind(c))
			{
			case "digit":
				MarkLendTyped(g, playerProfile);
				return false;
			case "preset":
				MarkLendPreset(g);
				if (!NetworkServer.active)
				{
					Keypad keypad = c as Keypad;
					if (keypad == null)
					{
						try
						{
							keypad = c.GetComponentInParent<Keypad>();
						}
						catch
						{
						}
					}
					double num = PadPresetPct(c);
					if (keypad != null && num >= 0.0)
					{
						RequestPadPct(keypad, num);
					}
				}
				return false;
			case "cashout":
				return false;
			default:
				return false;
			}
		}

		internal static bool TryPlayerLend(GameBase g, PlayerProfile receiver)
		{
			if (!NetworkServer.active || g == null || receiver == null)
			{
				return false;
			}
			if (EconomyFrozen())
			{
				return false;
			}
			if (!GameHasCashout(g))
			{
				return false;
			}
			if (GameIsPlaying(g))
			{
				return false;
			}
			uint num = NetIdOf(g);
			if (num == 0)
			{
				return false;
			}
			bool value;
			if (!LendTyped.TryGetValue(num, out value) || !value)
			{
				return false;
			}
			string value2;
			if (!LendLender.TryGetValue(num, out value2) || string.IsNullOrEmpty(value2))
			{
				return false;
			}
			PlayerProfile playerProfile = FindProfileByKey(value2);
			if (playerProfile == null)
			{
				return false;
			}
			string text = Key(receiver);
			if (string.IsNullOrEmpty(text) || text == value2)
			{
				return false;
			}
			double value3 = 0.0;
			LendAmt.TryGetValue(num, out value3);
			if (value3 < 1.0)
			{
				value3 = ReadKeypadAmount(g, null);
			}
			if (value3 < 1.0)
			{
				return false;
			}
			Acc acc = Ensure(playerProfile);
			Acc acc2 = Ensure(receiver);
			if (acc == null || acc2 == null)
			{
				return false;
			}
			if (acc.money + 0.0001 < value3)
			{
				value3 = acc.money;
			}
			if (value3 < 1.0)
			{
				NotifyMoney(acc, "现金不够，转账失败", 0);
				return true;
			}
			if (AccHasDuel(acc) || AccHasDuel(acc2))
			{
				NoteDuelToast(receiver, "别想作弊了 七七早就想到你会这样做 :P", 0);
				if (playerProfile != null && playerProfile != receiver)
				{
					NoteDuelToast(playerProfile, "别想作弊了 七七早就想到你会这样做 :P", 0);
				}
				LendTyped[num] = false;
				LendLender.Remove(num);
				LendAmt.Remove(num);
				return true;
			}
			acc.money -= value3;
			acc2.money += value3;
			LendTyped[num] = false;
			LendLender.Remove(num);
			LendAmt.Remove(num);
			NotifyPair(acc, acc2, value3, "提现");
			Broadcast();
			return true;
		}

