		internal static PlayerProfile FindProfileByKey(string k)
		{
			if (string.IsNullOrEmpty(k))
			{
				return null;
			}
			List<PlayerProfile> list = PresentProfiles();
			for (int i = 0; i < list.Count; i++)
			{
				if (ProfileMatchesKey(list[i], k))
				{
					return list[i];
				}
			}
			if (ProfileMatchesKey(LocalProfile(), k))
			{
				return LocalProfile();
			}
			return null;
		}

		private static PlayerProfile ResolveMorphProfile(string key)
		{
			PlayerProfile playerProfile = FindProfileByKey(key);
			if (playerProfile != null)
			{
				return playerProfile;
			}
			if (ProfileMatchesKey(LocalProfile(), key))
			{
				return LocalProfile();
			}
			try
			{
				PlayerProfile[] array = UnityEngine.Object.FindObjectsByType<PlayerProfile>(FindObjectsSortMode.None);
				if (array == null)
				{
					return null;
				}
				for (int i = 0; i < array.Length; i++)
				{
					if (ProfileMatchesKey(array[i], key))
					{
						return array[i];
					}
				}
			}
			catch
			{
			}
			return null;
		}

		internal static PlayerProfile PlayerForGame(GameBase game)
		{
			if (game != null)
			{
				if (!LastPressGetsMoney && GameIsPlaying(game))
				{
					PlayerProfile playerProfile = RoundOwnerProfile(game);
					if (playerProfile != null)
					{
						return playerProfile;
					}
				}
				uint num = NetIdOf(game);
				string value;
				if (num != 0 && GamePressKey.TryGetValue(num, out value))
				{
					PlayerProfile playerProfile2 = FindProfileByKey(value);
					if (playerProfile2 != null)
					{
						return playerProfile2;
					}
				}
				try
				{
					if (_gbInteractF == null)
					{
						_gbInteractF = AccessTools.Field(typeof(GameBase), "interactingPlayer");
					}
					PlayerProfile playerProfile3 = ((_gbInteractF != null) ? (_gbInteractF.GetValue(game) as PlayerProfile) : null);
					if (playerProfile3 != null)
					{
						return playerProfile3;
					}
				}
				catch
				{
				}
			}
			return LastBetPlayer ?? LocalProfile();
		}

