		internal static void PaintKeypad(Keypad kp)
		{
			if (kp == null)
			{
				return;
			}
			CacheKeypadFields();
			GameBase gameBase = GameFromKeypad(kp);
			PlayerProfile playerProfile = KeypadLimitPlayer(gameBase);
			if (playerProfile == null)
			{
				playerProfile = LocalProfile();
			}
			double num = KeypadMinAmount(gameBase);
			double num2 = KeypadMaxAmount(gameBase);
			if (num2 < 0.0)
			{
				num2 = 0.0;
			}
			string text = "最小";
			string text2 = "最大";
			try
			{
				if (_kpMinLocF != null)
				{
					string text3 = _kpMinLocF.GetValue(kp) as string;
					if (!string.IsNullOrEmpty(text3) && text3.IndexOf('{') < 0)
					{
						text = text3;
					}
				}
				if (_kpMaxLocF != null)
				{
					string text4 = _kpMaxLocF.GetValue(kp) as string;
					if (!string.IsNullOrEmpty(text4) && text4.IndexOf('{') < 0)
					{
						text2 = text4;
					}
				}
			}
			catch
			{
			}
			if (_kpMinMaxF != null)
			{
				SetTmpText(_kpMinMaxF.GetValue(kp), text + ": " + MoneyDollar(num) + "    " + text2 + ": " + MoneyDollarFloor(num2));
			}
			double num3 = num;
			bool flag = false;
			try
			{
				if (_kpInputF != null)
				{
					string text5 = _kpInputF.GetValue(kp) as string;
					double result;
					if (!string.IsNullOrEmpty(text5) && double.TryParse(text5, NumberStyles.Float, CultureInfo.InvariantCulture, out result) && result > 0.0)
					{
						num3 = result;
						flag = true;
					}
				}
			}
			catch
			{
			}
			if (!flag)
			{
				if (gameBase != null)
				{
					try
					{
						double num4 = gameBase.currentBet.ToDouble();
						if (num4 > 0.0)
						{
							num3 = num4;
						}
					}
					catch
					{
					}
				}
				num3 = ShownPadBet(gameBase, kp, num3);
			}
			object obj4 = null;
			if (_kpDispF != null)
			{
				obj4 = _kpDispF.GetValue(kp);
			}
			if (obj4 != null)
			{
				SetTmpText(obj4, MoneyDollar(num3));
				double cash = OwnWallet(playerProfile);
				bool flag2 = num3 + 0.0001 >= num && !BetOverWallet(num3, cash);
				SetTmpColor(obj4, flag2 ? new Color(0.25f, 1f, 0.35f, 1f) : new Color(1f, 0.22f, 0.18f, 1f));
			}
		}

		internal static void AdoptMachinePlayer(Component c, PlayerProfile p)
		{
			if (p == null)
			{
				return;
			}
			GameBase gameBase = GameFrom(c);
			NoteLastPress(gameBase, p);
