				PaintKeypad(keypad);
			}
			catch
			{
			}
			if (!NetworkServer.active || GameIsPlaying(gameBase))
			{
				return;
			}
			if (GameHasCashout(gameBase))
			{
				try
				{
					Keypad keypad3 = gameBase.Keypad;
					if (keypad3 != null)
