						}
						PaintKeypad(keypad3);
					}
					return;
				}
				catch
				{
					return;
				}
			}
			double num = MinBetAmount(p);
			double num2 = PlayMaxAmount(p);
			if (num2 < 0.0)
			{
				num2 = 0.0;
			}
			double num3 = num;
			try
			{
				num3 = gameBase.currentBet.ToDouble();
			}
			catch
			{
			}
			if (num3 < num)
			{
				num3 = num;
			}
			if (num3 > num2)
			{
				num3 = num2;
			}
			try
			{
				gameBase.ServerSetBet(MoneyBNAtMost(num3, num2));
			}
			catch
