		internal static double GameStakeAmount(GameBase g)
		{
			double num = 0.0;
			if (g == null)
			{
				return 0.0;
			}
			try
			{
				num = g.currentBet.ToDouble();
			}
			catch
			{
			}
			try
			{
				Roulette roulette = g as Roulette;
				if (roulette != null)
				{
					MethodInfo methodInfo = AccessTools.Method(typeof(Roulette), "GetTotalBet");
					if (methodInfo != null)
					{
						object obj2 = methodInfo.Invoke(roulette, null);
						BigNumber bigNumber = ((obj2 is BigNumber) ? ((BigNumber)obj2) : default(BigNumber));
						double num2 = 0.0;
						try
						{
							num2 = bigNumber.ToDouble();
						}
						catch
						{
						}
						if (num2 > num)
						{
							num = num2;
						}
					}
				}
			}
			catch
			{
			}
			if (num < 0.0)
			{
				num = 0.0;
			}
			return num;
		}

		internal static void CaptureSideRide(GameBase g, PlayerProfile p)
		{
			if (g == null || p == null)
			{
				return;
			}
			uint num = NetIdOf(g);
			if (num != 0)
			{
				string key = Key(p);
				double num2 = GameStakeAmount(g);
				double num3 = 0.0;
				if (_betAmt.ContainsKey(key))
				{
					num3 = _betAmt[key];
				}
				if (num2 < num3)
				{
					num2 = num3;
				}
				double num4 = 0.0;
				if (_betMoney.ContainsKey(key))
				{
					num4 = _betMoney[key];
				}
				double num5 = Wallet(p);
				if (num4 < 0.0001)
				{
					num4 = num5;
				}
				if (num2 > 0.0001 && num5 + num2 > num4 + 0.0001)
				{
					num4 = num5 + num2;
				}
				double num6 = 1.0;
				if (num4 > 0.0001)
				{
					num6 = num2 / num4;
				}
				if (num6 < 0.0)
				{
					num6 = 0.0;
				}
				if (num6 > 1.0)
				{
					num6 = 1.0;
				}
				SideRidePct[num] = num6;
				SideSettled[num] = false;
			}
		}

