		private static bool TryMineOn(string toKey, out double amt, out double cost)
		{
			amt = 0.0;
			cost = 0.0;
			if (string.IsNullOrEmpty(toKey))
			{
				return false;
			}
			string text = Key(LocalProfile());
			if (NetworkServer.active)
			{
				for (int i = 0; i < SideBets.Count; i++)
				{
					SideWager sideWager = SideBets[i];
					if (sideWager != null && !(sideWager.to != toKey) && !(sideWager.from != text))
					{
						amt += sideWager.amt;
						cost += sideWager.cost;
					}
				}
			}
			else
			{
				for (int j = 0; j < ViewSideRows.Count; j++)
				{
					SideViewRow sideViewRow = ViewSideRows[j];
					if (sideViewRow != null && !(sideViewRow.to != toKey) && !(sideViewRow.from != text))
					{
						amt += sideViewRow.amt;
						cost += sideViewRow.cost;
					}
				}
			}
			if (!(amt > 0.0001))
			{
				return cost > 0.0001;
			}
			return true;
		}

		private static float SideActLeft(string k)
		{
			float num = _localSideActUntil;
			float value;
			if (!string.IsNullOrEmpty(k) && SideActUntil.TryGetValue(k, out value) && value > num)
			{
				num = value;
			}
			float num2 = num - Time.unscaledTime;
			if (num2 < 0f)
			{
				return 0f;
			}
			return num2;
		}

		private static void ArmSideAct(Acc a, string k)
		{
			float num = Time.unscaledTime + 30f;
			if (!string.IsNullOrEmpty(k))
			{
				SideActUntil[k] = num;
			}
			bool flag = false;
			try
			{
				flag = AccIsPlayer(a, LocalProfile());
			}
			catch
			{
			}
			if (flag)
			{
				_localSideActUntil = num;
			}
			if (!NetworkServer.active || a == null)
			{
				return;
			}
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value != null && !(value.identity == null))
					{
						PlayerProfile p = ProfileFromIdentity(value.identity);
						if (AccIsPlayer(a, p) && !value.identity.isLocalPlayer)
						{
							value.Send(new SoloMsg
							{
								json = "SIDECD\t30"
							});
						}
					}
				}
			}
			catch
			{
			}
		}

