		private static bool BossHoverNear(PlayerProfile p)
		{
			PlayerProfile playerProfile = LocalProfile();
			if (playerProfile == null || p == null)
			{
				return false;
			}
			Transform transform = null;
			Transform transform2 = null;
			try
			{
				transform = playerProfile.transform;
			}
			catch
			{
			}
			try
			{
				transform2 = p.transform;
			}
			catch
			{
			}
			if (transform == null || transform2 == null)
			{
				return false;
			}
			float num = 6f;
			return (transform.position - transform2.position).sqrMagnitude <= num * num;
		}

		internal static void PlaceSideBet(PlayerProfile from, string toKey, double amt)
		{
			if (!NetworkServer.active || from == null || string.IsNullOrEmpty(toKey))
			{
				return;
			}
			if (EconomyFrozen())
			{
				_sideNote = "结算日不能押注。";
				return;
			}
			string text = Key(from);
			if (text == toKey)
			{
				_sideNote = "不能押自己。";
				return;
			}
			PlayerProfile playerProfile = FindProfileByKey(toKey);
			if (playerProfile == null)
			{
				_sideNote = "找不到玩家。";
				return;
			}
			if (amt < 1.0)
			{
				_sideNote = "最少 $1。";
				return;
			}
			double num = Wallet(from);
			double num2 = num * 0.5;
			if (amt > num2 + 0.0001)
			{
				_sideNote = "最多押自己现金的 50%。";
				return;
			}
			if (amt > num + 0.0001)
			{
				_sideNote = "钱不够。";
				return;
			}
			Acc acc = Ensure(from);
			if (acc == null)
			{
				return;
			}
			if (GetJob(acc) != 1)
			{
				_sideNote = "只有赌场老板能押注。";
				return;
			}
			float num3 = SideActLeft(text);
			if (num3 > 0.05f)
			{
				_sideNote = "冷却中 " + Mathf.CeilToInt(num3) + "s";
				return;
			}
			RefreshGoalDay(acc);
			if (!string.IsNullOrEmpty(acc.betLock) && acc.betLock != toKey)
			{
				_sideNote = "每天只能押一名玩家。";
				return;
			}
			if (!string.IsNullOrEmpty(acc.betLock) && acc.betLock == toKey)
			{
				_sideNote = "今天已经押过，只能提现。";
				return;
			}
			acc.betLock = toKey;
			acc.betCost += amt;
			TouchGoalHud(acc);
			acc.money -= amt;
			if (acc.money < 0.0)
			{
				acc.money = 0.0;
			}
			for (int i = 0; i < SideBets.Count; i++)
			{
				SideWager sideWager = SideBets[i];
				if (sideWager != null && !(sideWager.from != text) && !(sideWager.to != toKey))
				{
					sideWager.amt += amt;
					sideWager.cost += amt;
					_sideNote = "已加押 " + MoneyDollar(amt);
					Acc acc2 = Ensure(playerProfile);
					NotifyMoney(acc, "-" + MoneyDollar(amt) + " 押在 " + ((acc2 != null && !string.IsNullOrEmpty(acc2.name)) ? acc2.name : "玩家"), false);
					ArmSideAct(acc, text);
					Broadcast();
					return;
				}
			}
			SideBets.Add(new SideWager
			{
				from = text,
				to = toKey,
				amt = amt,
				cost = amt
			});
			_sideNote = "已押 " + MoneyDollar(amt) + " 在 " + (playerProfile.playerName ?? "");
			NotifyMoney(acc, "-" + MoneyDollar(amt) + " 押在 " + (playerProfile.playerName ?? "玩家"), false);
			ArmSideAct(acc, text);
			Broadcast();
		}

		internal static void CashSideBet(PlayerProfile from, string toKey, double amt)
		{
			if (!NetworkServer.active || from == null || string.IsNullOrEmpty(toKey))
			{
				return;
			}
			string text = Key(from);
			Acc acc = Ensure(from);
			if (acc == null)
			{
				return;
			}
			if (GetJob(acc) != 1)
			{
				_sideNote = "只有赌场老板能提现。";
				return;
			}
			float num = SideActLeft(text);
			if (num > 0.05f)
			{
				_sideNote = "冷却中 " + Mathf.CeilToInt(num) + "s";
				return;
			}
			if (amt < 1.0)
			{
				_sideNote = "最少提现 $1。";
				return;
			}
			for (int i = 0; i < SideBets.Count; i++)
			{
				SideWager sideWager = SideBets[i];
				if (sideWager == null || sideWager.from != text || sideWager.to != toKey)
				{
					continue;
				}
				if (amt > sideWager.amt)
				{
					amt = sideWager.amt;
				}
				if (amt < 0.0001)
				{
					_sideNote = "没有可提的押金。";
					return;
				}
				sideWager.amt -= amt;
				sideWager.cost -= amt;
				if (sideWager.cost < 0.0)
				{
					sideWager.cost = 0.0;
				}
				acc.money += amt;
				RefreshGoalDay(acc);
				acc.betCash += amt;
				TouchGoalHud(acc);
				if (sideWager.amt < 0.01)
				{
					SideBets.RemoveAt(i);
				}
				_sideNote = "已提现 " + MoneyDollar(amt);
				Acc acc2 = FindAccByKey(toKey);
				string text2 = ((acc2 != null && !string.IsNullOrEmpty(acc2.name)) ? acc2.name : "玩家");
				NotifyMoney(acc, MoneyDollar(amt) + " 提现 ← " + text2, 2);
				ArmSideAct(acc, text);
				Broadcast();
				return;
			}
			_sideNote = "没有押在这个人身上。";
		}

		internal static void ApplySideRide(GameBase g, double multiplier)
		{
			if (!NetworkServer.active || g == null)
			{
				return;
			}
			uint num = NetIdOf(g);
			if (num != 0)
			{
				bool value;
				if (SideSettled.TryGetValue(num, out value) && value)
				{
					return;
				}
				SideSettled[num] = true;
			}
			PlayerProfile playerProfile = PayoutTarget(g) ?? PlayerForGame(g) ?? RoundOwnerProfile(g);
			if (playerProfile == null)
			{
				return;
			}
			string text = Key(playerProfile);
			Acc acc = Ensure(playerProfile);
			if (acc == null)
			{
				return;
			}
			if (multiplier < 0.0)
			{
				multiplier = 0.0;
			}
			double num2 = multiplier;
			double value2 = 1.0;
			if (num == 0 || !SideRidePct.TryGetValue(num, out value2))
			{
				double num3 = GameStakeAmount(g);
				double num4 = Wallet(playerProfile);
				value2 = ((!(num4 > 0.0001)) ? 1.0 : (num3 / num4));
			}
			if (value2 < 0.0)
			{
				value2 = 0.0;
			}
			if (value2 > 1.0)
			{
				value2 = 1.0;
			}
			for (int i = 0; i < SideBets.Count; i++)
			{
				SideWager sideWager = SideBets[i];
				if (sideWager == null || sideWager.to != text || sideWager.amt < 0.0001)
				{
					continue;
				}
				double amt = sideWager.amt;
				double num5 = amt * value2;
				double num6 = amt - num5;
				if (num5 < 0.0)
				{
					num5 = 0.0;
				}
				if (num6 < 0.0)
				{
					num6 = 0.0;
				}
				if (num2 > 1.0001)
				{
					sideWager.amt = num6 + num5 * num2;
					continue;
				}
				if (num2 >= 0.999)
				{
					sideWager.amt = num6 + num5 * num2;
					continue;
				}
				double num7 = num5 * num2;
				double num8 = ((num2 <= 0.0001) ? (num5 * 0.2) : (num7 * 0.2));
				if (num8 < 0.0)
				{
					num8 = 0.0;
				}
				if (num8 > acc.money)
				{
					num8 = acc.money;
				}
				acc.money -= num8;
				if (acc.money < 0.0)
				{
					acc.money = 0.0;
				}
				sideWager.amt = num6 + num7 + num8;
				if (sideWager.amt < 0.0)
				{
					sideWager.amt = 0.0;
				}
				sideWager.hostPnL -= num8;
			}
			Broadcast();
		}

		internal static void RequestSideBet(string toKey, double amt)
		{
			if (string.IsNullOrEmpty(toKey))
			{
				return;
			}
			if (NetworkServer.active)
			{
				PlaceSideBet(LocalProfile(), toKey, amt);
				return;
			}
			try
			{
				NetworkClient.Send(new SideMsg
				{
					json = "B\t" + toKey + "\t" + amt.ToString("R", CultureInfo.InvariantCulture)
				});
				_sideNote = "已发送。";
			}
			catch
			{
				_sideNote = "发送失败。";
			}
		}

		internal static void RequestSideCash(string toKey, double amt)
		{
			if (string.IsNullOrEmpty(toKey))
			{
				return;
			}
			if (NetworkServer.active)
			{
				CashSideBet(LocalProfile(), toKey, amt);
				return;
			}
			try
			{
				NetworkClient.Send(new SideMsg
				{
					json = "C\t" + toKey + "\t" + amt.ToString("R", CultureInfo.InvariantCulture)
				});
				_sideNote = "已发送提现。";
			}
			catch
			{
				_sideNote = "发送失败。";
