		private static void ReturnBetsOn(PlayerProfile hostP)
		{
			if (!NetworkServer.active || hostP == null)
			{
				return;
			}
			string text = Key(hostP);
			Acc acc = Ensure(hostP);
			if (acc == null || string.IsNullOrEmpty(text))
			{
				return;
			}
			int num = 0;
			double num2 = 0.0;
			for (int num3 = SideBets.Count - 1; num3 >= 0; num3--)
			{
				SideWager sideWager = SideBets[num3];
				if (sideWager != null && !(sideWager.to != text))
				{
					Acc acc2 = FindAccByKey(sideWager.from);
					if (acc2 == null)
					{
						SideBets.RemoveAt(num3);
					}
					else
					{
						double num4 = sideWager.amt;
						if (num4 < 0.0)
						{
							num4 = 0.0;
						}
						if (sideWager.hostPnL > 0.0001)
						{
							double num5 = sideWager.hostPnL;
							if (num5 > acc.money)
							{
								num5 = acc.money;
							}
							if (num5 < 0.0)
							{
								num5 = 0.0;
							}
							acc.money -= num5;
							if (acc.money < 0.0)
							{
								acc.money = 0.0;
							}
							num4 += num5;
						}
						acc2.money += num4;
						num2 += num4;
						num++;
						NotifyMoney(acc2, MoneyDollar(num4) + " 押注退回 ← " + (acc.name ?? "玩家"), true);
						NotifyMoney(acc, "退还 " + MoneyDollar(num4) + " → " + (acc2.name ?? "玩家"), 2);
						SideBets.RemoveAt(num3);
					}
				}
			}
			if (num == 0)
			{
				NotifyMoney(acc, "没有需要退还的押注", 2);
			}
			else
			{
				NotifyMoney(acc, "已退还 " + num + " 笔押注 " + MoneyDollar(num2), 2);
			}
			Broadcast();
		}

