		private static bool HasTippedToday(string from, string to)
		{
			if (string.IsNullOrEmpty(from) || string.IsNullOrEmpty(to))
			{
				return false;
			}
			int sharedDay = SharedDay;
			List<TipRec> list = (NetworkServer.active ? Tips : ViewTips);
			for (int i = 0; i < list.Count; i++)
			{
				TipRec tipRec = list[i];
				if (tipRec != null && tipRec.from == from && tipRec.to == to && tipRec.day == sharedDay)
				{
					return true;
				}
			}
			return false;
		}

		private static double TipAmountOf(PlayerProfile from, int kind)
		{
			switch (kind)
			{
			case 0:
				return 10.0;
			case 1:
				return 100.0;
			case 2:
				return 1000.0;
			default:
			{
				double num = Wallet(from);
				double num2 = num * 0.01;
				if (num2 < 0.0)
				{
					num2 = 0.0;
				}
				return num2;
			}
			}
		}

		internal static void PlaceTip(PlayerProfile from, string toKey, int kind)
		{
			if (!NetworkServer.active || from == null || string.IsNullOrEmpty(toKey))
			{
				return;
			}
			if (EconomyFrozen())
			{
				_tipNote = "结算日不能打赏。";
				return;
			}
			string text = Key(from);
			if (text == toKey)
			{
				_tipNote = "不能打赏自己。";
				return;
			}
			if (HasTippedToday(text, toKey))
			{
				_tipNote = "今天已经打赏过这个人了。";
				return;
			}
			PlayerProfile playerProfile = FindProfileByKey(toKey);
			if (playerProfile == null)
			{
				_tipNote = "找不到玩家。";
				return;
			}
			if (kind < 0)
			{
				kind = 0;
			}
			if (kind > 3)
			{
				kind = 3;
			}
			double num = TipAmountOf(from, kind);
			if (num < 0.01)
			{
				_tipNote = "金额太小。";
				return;
			}
			Acc acc = Ensure(from);
			Acc acc2 = Ensure(playerProfile);
			if (acc == null || acc2 == null)
			{
				return;
			}
			if (GetJob(acc) != 1)
			{
				_tipNote = "只有赌场老板能打赏。";
				return;
			}
			if (AccHasDuel(acc) || AccHasDuel(acc2))
			{
				_tipNote = "玩家对决中 无法打赏";
				NotifyMoney(acc, "玩家对决中 无法打赏", 0);
				NotifyMoney(acc2, "玩家对决中 无法打赏", 0);
				return;
			}
			if (acc.money + 0.0001 < num)
			{
				_tipNote = "钱不够。";
				return;
			}
			acc.money -= num;
			if (acc.money < 0.0)
			{
				acc.money = 0.0;
			}
			acc2.money += num;
			Tips.Add(new TipRec
			{
				from = text,
				to = toKey,
				day = SharedDay
			});
			_tipNote = "已打赏 " + MoneyDollar(num);
			NotifyPair(acc, acc2, num, "打赏");
			Broadcast();
		}

		internal static void RequestTip(string toKey, int kind)
		{
			if (string.IsNullOrEmpty(toKey))
			{
				return;
			}
			if (NetworkServer.active)
			{
				PlaceTip(LocalProfile(), toKey, kind);
				return;
			}
			try
			{
				NetworkClient.Send(new SideMsg
				{
					json = "I\t" + toKey + "\t" + kind
				});
				_tipNote = "已发送。";
			}
			catch
			{
				_tipNote = "发送失败。";
			}
		}

