		private static string CleanSideName(string n)
		{
			if (string.IsNullOrEmpty(n))
			{
				return "?";
			}
			return n.Replace("\t", " ").Replace("\n", " ").Replace("\r", "");
		}

		private static string BuildSideLines()
		{
			Dictionary<string, double> dictionary = new Dictionary<string, double>();
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < SideBets.Count; i++)
			{
				SideWager sideWager = SideBets[i];
				if (sideWager != null && !string.IsNullOrEmpty(sideWager.to))
				{
					double value;
					if (!dictionary.TryGetValue(sideWager.to, out value))
					{
						value = 0.0;
					}
					dictionary[sideWager.to] = value + sideWager.amt;
					Acc acc = FindAccByKey(sideWager.from);
					string value2 = ((acc != null) ? CleanSideName(acc.name) : sideWager.from);
					stringBuilder.Append("SF\t").Append(sideWager.to).Append('\t')
						.Append(sideWager.from)
						.Append('\t')
						.Append(value2)
						.Append('\t')
						.Append(sideWager.amt.ToString("R", CultureInfo.InvariantCulture))
						.Append('\t')
						.Append(sideWager.cost.ToString("R", CultureInfo.InvariantCulture))
						.Append('\t')
						.Append(sideWager.hostPnL.ToString("R", CultureInfo.InvariantCulture))
						.Append('\n');
				}
			}
			foreach (KeyValuePair<string, double> item in dictionary)
			{
				stringBuilder.Append("SP\t").Append(item.Key).Append('\t')
					.Append(item.Value.ToString("R", CultureInfo.InvariantCulture))
					.Append('\n');
			}
			for (int j = 0; j < Tips.Count; j++)
			{
				TipRec tipRec = Tips[j];
				if (tipRec != null && tipRec.day == SharedDay)
				{
					stringBuilder.Append("TP\t").Append(tipRec.from).Append('\t')
						.Append(tipRec.to)
						.Append('\t')
						.Append(tipRec.day)
						.Append('\n');
				}
			}
			return stringBuilder.ToString();
		}

