		private static bool ParseSideLine(string line)
		{
			if (string.IsNullOrEmpty(line))
			{
				return false;
			}
			if (line.StartsWith("TP\t"))
			{
				string[] array = line.Split(new char[1] { '\t' });
				if (array.Length < 4)
				{
					return true;
				}
				int result;
				int.TryParse(array[3], out result);
				ViewTips.Add(new TipRec
				{
					from = array[1],
					to = array[2],
					day = result
				});
				return true;
			}
			if (line.StartsWith("SF\t"))
			{
				string[] array2 = line.Split(new char[1] { '\t' });
				if (array2.Length < 5)
				{
					return true;
				}
				double result2;
				double.TryParse(array2[4], NumberStyles.Float, CultureInfo.InvariantCulture, out result2);
				double result3 = result2;
				if (array2.Length >= 6)
				{
					double.TryParse(array2[5], NumberStyles.Float, CultureInfo.InvariantCulture, out result3);
				}
				double result4 = 0.0;
				if (array2.Length >= 7)
				{
					double.TryParse(array2[6], NumberStyles.Float, CultureInfo.InvariantCulture, out result4);
				}
				ViewSideRows.Add(new SideViewRow
				{
					to = array2[1],
					from = array2[2],
					name = array2[3],
					amt = result2,
					cost = result3,
					hostPnL = result4
				});
				return true;
			}
			if (!line.StartsWith("SP\t"))
			{
				return false;
			}
			string[] array3 = line.Split(new char[1] { '\t' });
			if (array3.Length < 3)
			{
				return true;
			}
			double result5;
			double.TryParse(array3[2], NumberStyles.Float, CultureInfo.InvariantCulture, out result5);
			ViewSide[array3[1]] = result5;
			return true;
		}

		internal static BigNumber MoneyBN(double v)
		{
			if (double.IsNaN(v) || double.IsInfinity(v) || v <= 0.0)
			{
				return new BigNumber(0.0, 0L);
			}
			try
			{
				if (v < 1000000000000.0)
				{
					return BigNumber.FromDouble(v);
				}
			}
			catch
			{
			}
			double num = v;
			long num2 = 0L;
			while (num >= 10.0 && num2 < 100000)
			{
				num /= 10.0;
				num2++;
			}
			while (num > 0.0 && num < 1.0 && num2 > -100000)
			{
				num *= 10.0;
				num2--;
			}
			return new BigNumber(num, num2);
		}

		internal static double FitWalletBet(double bet, double cash)
		{
			if (double.IsNaN(bet) || bet < 0.0)
			{
				bet = 0.0;
			}
			if (double.IsNaN(cash) || cash < 0.0)
			{
				cash = 0.0;
			}
			if (bet > cash)
			{
				bet = cash;
			}
			try
			{
				for (int i = 0; i < 16; i++)
				{
					double num = MoneyBN(bet).ToDouble();
					if (!double.IsNaN(num) && !double.IsInfinity(num) && num <= cash + 0.0001)
					{
						bet = num;
						break;
					}
					bet = cash * (1.0 - (double)(i + 1) * 1E-07);
					if (bet < 0.0)
					{
						bet = 0.0;
					}
				}
			}
			catch
			{
			}
			if (bet > cash)
			{
				bet = cash;
			}
			return bet;
		}

		internal static BigNumber MoneyBNAtMost(double v, double cap)
		{
			if (cap < 0.0)
			{
				cap = 0.0;
			}
			double v2 = FitWalletBet(v, cap);
			BigNumber result = MoneyBN(v2);
			try
			{
				double num = result.ToDouble();
				if (double.IsNaN(num) || double.IsInfinity(num) || num > cap)
				{
					result = MoneyBN((cap > 0.0) ? (cap * 0.999999) : 0.0);
				}
			}
			catch
			{
			}
			return result;
		}

		internal static bool BetOverWallet(double bet, double cash)
		{
			if (double.IsNaN(bet))
			{
				return true;
			}
			if (double.IsNaN(cash) || cash < 0.0)
			{
				cash = 0.0;
			}
			if (bet <= cash)
			{
				return false;
			}
			double num = Math.Abs(cash) * 2E-12;
			if (num < 1.0)
			{
				num = 1.0;
			}
			if (Math.Abs(cash) >= 1000000000000.0)
			{
				num = Math.Max(num, Math.Abs(cash) * 1E-10);
			}
			return bet > cash + num;
		}

		internal static string MoneyShort(double v)
		{
			if (double.IsNaN(v) || double.IsInfinity(v))
			{
				return "0";
			}
			bool flag = v < 0.0;
			if (flag)
			{
				v = 0.0 - v;
			}
			int num = -1;
			if (v >= 1000.0)
			{
				while (v >= 1000.0 && num < MoneySuffix.Length - 1)
				{
					v /= 1000.0;
					num++;
				}
			}
			if (num < 0)
			{
				double num2 = Math.Round(v, 0, MidpointRounding.AwayFromZero);
				if (num2 < 1000.0)
				{
					return (flag ? "-" : "") + num2.ToString("0", CultureInfo.InvariantCulture);
				}
				v = num2 / 1000.0;
				num = 0;
			}
			v = Math.Round(v, 2, MidpointRounding.AwayFromZero);
			while (v >= 1000.0 && num < MoneySuffix.Length - 1)
			{
				v /= 1000.0;
				num++;
				v = Math.Round(v, 2, MidpointRounding.AwayFromZero);
			}
			string text = v.ToString("0.##", CultureInfo.InvariantCulture);
			if (num < 0)
			{
				return (flag ? "-" : "") + text;
			}
			return (flag ? "-" : "") + text + MoneySuffix[num];
		}

		internal static string MoneyDollar(double v)
		{
			return "$" + MoneyShort(v);
		}

		internal static string MoneyDollarFloor(double v)
		{
			return "$" + MoneyFloorShort(v);
		}

		internal static string MoneyFloorShort(double v)
		{
			if (double.IsNaN(v) || double.IsInfinity(v))
			{
				return "0";
			}
			bool flag = v < 0.0;
			if (flag)
			{
				v = 0.0 - v;
			}
			int num = -1;
			if (v >= 1000.0)
			{
				while (v >= 1000.0 && num < MoneySuffix.Length - 1)
				{
					v /= 1000.0;
					num++;
				}
			}
			if (num < 0)
			{
				double num2 = Math.Floor(v + 1E-09);
				if (num2 < 0.0)
				{
					num2 = 0.0;
				}
				if (num2 < 1000.0)
				{
					return (flag ? "-" : "") + num2.ToString("0", CultureInfo.InvariantCulture);
				}
				v = num2 / 1000.0;
				num = 0;
			}
			v = Math.Floor(v * 100.0 + 1E-09) / 100.0;
			while (v >= 1000.0 && num < MoneySuffix.Length - 1)
			{
				v /= 1000.0;
				num++;
				v = Math.Floor(v * 100.0 + 1E-09) / 100.0;
			}
			string text = v.ToString("0.##", CultureInfo.InvariantCulture);
			if (num < 0)
			{
				return (flag ? "-" : "") + text;
			}
			return (flag ? "-" : "") + text + MoneySuffix[num];
		}

