					double result;
					if (!string.IsNullOrEmpty(text) && double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out result) && result > 0.0)
					{
						num2 = result;
						flag = true;
					}
				}
				if (!flag)
