		internal static bool ChallengeBetMeetsHalf(ChallengeContext context, BetAmountConditionData cond)
		{
			PlayerProfile playerProfile = LastGamePlayer ?? LastBetPlayer;
			Acc acc = ((playerProfile != null) ? Ensure(playerProfile) : null);
			double num = 0.0;
			try
			{
				if (context != null)
				{
					num = context.bet.ToDouble();
				}
			}
			catch
			{
			}
			double num2 = ((acc != null) ? (acc.money + num) : num);
			if (playerProfile != null)
			{
				string key = Key(playerProfile);
				if (_betMoney.ContainsKey(key))
				{
					num2 = _betMoney[key];
				}
			}
			if (num2 < 0.0)
			{
				num2 = 0.0;
			}
			if (IsTotalBetCondition(cond))
			{
				double num3 = TycoonBetTarget();
				double num4 = 0.0;
				try
				{
					ConditionState conditionState = PlayerConditionState(cond);
					if (conditionState != null)
					{
						num4 = conditionState.totalBetAmount.ToDouble();
					}
				}
				catch
				{
				}
				return num4 + 0.0001 >= num3;
			}
			double num5 = num2 * 0.5;
			return num + 0.0001 >= num5;
		}

