		internal static ConditionState PlayerConditionState(ChallengeConditionData cond)
		{
			if (cond == null)
			{
				return null;
			}
			string key = ChalPlayerKey();
			Dictionary<ChallengeConditionData, ConditionState> value;
			if (!PlayerCond.TryGetValue(key, out value) || value == null)
			{
				value = new Dictionary<ChallengeConditionData, ConditionState>();
				PlayerCond[key] = value;
			}
			ConditionState value2;
			if (!value.TryGetValue(cond, out value2) || value2 == null)
			{
				return value[cond] = new ConditionState();
			}
			return value2;
		}

