		internal static string BuildBatOwnerLines()
		{
			if (BatOwnerName.Count == 0)
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder();
			foreach (KeyValuePair<uint, string> item in BatOwnerName)
			{
				string value = "";
				BatOwnerKey.TryGetValue(item.Key, out value);
				string text = item.Value ?? "";
				text = text.Replace('\t', ' ').Replace('\n', ' ');
				stringBuilder.Append("BO\t").Append(item.Key).Append('\t')
					.Append(value ?? "")
					.Append('\t')
					.Append(text)
					.Append('\n');
			}
			return stringBuilder.ToString();
		}

		internal static string BuildChalProgLines(PlayerProfile who)
		{
			if (who == null)
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder();
			string chalScope = ChalScope;
			ChalScope = Key(who);
			try
			{
				ChallengeManager[] array = UnityEngine.Object.FindObjectsByType<ChallengeManager>(FindObjectsSortMode.None);
				if (array == null || array.Length == 0 || array[0] == null)
				{
					return "";
				}
				object value = AccessTools.Field(typeof(ChallengeManager), "activeChallenges").GetValue(array[0]);
				Dictionary<Challenge, ChallengeProgress> dictionary = value as Dictionary<Challenge, ChallengeProgress>;
				if (dictionary == null)
				{
					return "";
				}
				ChallengeContext context = new ChallengeContext();
				foreach (KeyValuePair<Challenge, ChallengeProgress> item in dictionary)
				{
					Challenge key = item.Key;
					ChallengeProgress value2 = item.Value;
					if (!(key == null))
					{
						float num = 0f;
						string text = "";
						try
						{
							num = key.GetProgress(context);
						}
						catch
						{
						}
						try
						{
							text = key.GetProgressText(context);
						}
						catch
						{
						}
						if (value2 != null && value2.isCompleted)
						{
							num = 1f;
						}
						if (text == null)
						{
							text = "";
						}
						text = text.Replace('\t', ' ').Replace('\n', ' ');
						stringBuilder.Append("CP\t").Append(key.challengeID).Append('\t')
							.Append(num.ToString("R", CultureInfo.InvariantCulture))
							.Append('\t')
							.Append(text)
							.Append('\n');
					}
				}
			}
			catch
			{
			}
			ChalScope = chalScope;
			return stringBuilder.ToString();
		}

		internal static void ApplyPersonalChallengeView(Challenge challenge, ChallengeProgress prog)
		{
			if (challenge == null || prog == null)
			{
				return;
			}
			if (prog.isCompleted)
			{
				prog.progress = 1f;
				return;
			}
			int challengeID = challenge.challengeID;
			if (!NetworkServer.active)
			{
				float value;
				if (ViewChalProg.TryGetValue(challengeID, out value))
				{
					prog.progress = value;
				}
				string value2;
				if (ViewChalText.TryGetValue(challengeID, out value2) && !string.IsNullOrEmpty(value2))
				{
					prog.progressText = value2;
				}
				return;
			}
			PlayerProfile playerProfile = LocalProfile();
			if (!(playerProfile == null))
			{
				string chalScope = ChalScope;
				ChalScope = Key(playerProfile);
				try
				{
					ChallengeContext context = new ChallengeContext();
					prog.progress = challenge.GetProgress(context);
					prog.progressText = challenge.GetProgressText(context);
				}
				catch
				{
				}
				ChalScope = chalScope;
			}
		}

