		internal static bool VerifyLicense(string buyer, string ids, string sig, out HashSet<ulong> idSet)
		{
			idSet = new HashSet<ulong>();
			if (string.IsNullOrEmpty(buyer) || string.IsNullOrEmpty(ids) || string.IsNullOrEmpty(sig))
			{
				return false;
			}
			try
			{
				byte[] data = Encoding.UTF8.GetBytes("SOLOBANK1|" + buyer + "|" + ids);
				using (RSACryptoServiceProvider rsa = new RSACryptoServiceProvider())
				{
					rsa.PersistKeyInCsp = false;
					string pub = "<RSAKeyValue><Modulus></Modulus><Exponent>AQAB</Exponent></RSAKeyValue>";
					rsa.FromXmlString(pub);
					if (!rsa.VerifyData(data, new SHA256Managed(), Convert.FromBase64String(sig)))
					{
						return false;
					}
				}
				if (GuestHostOf(ids) != 0)
				{
					return true;
				}
				string[] parts = ids.Split(',');
				foreach (string s in parts)
				{
					ulong id;
					if (ulong.TryParse(s.Trim(), out id) && id != 0)
					{
						idSet.Add(id);
					}
				}
				return idSet.Count > 0;
			}
			catch
			{
				return false;
			}
		}

		internal static ulong GuestHostOf(string ids)
		{
			if (string.IsNullOrEmpty(ids) || !ids.StartsWith("GUEST:"))
			{
				return 0uL;
			}
			ulong result;
			if (ulong.TryParse(ids.Substring(6).Trim(), out result))
			{
				return result;
			}
			return 0uL;
		}

		internal static ulong LobbyOwnerId()
		{
			try
			{
				LobbyManager instance = MonoSingleton<LobbyManager>.Instance;
				if (instance == null)
				{
					return 0uL;
				}
				Steamworks.CSteamID currentLobbyID = instance.GetCurrentLobbyID();
				if (currentLobbyID == Steamworks.CSteamID.Nil)
				{
					return 0uL;
				}
				return Steamworks.SteamMatchmaking.GetLobbyOwner(currentLobbyID).m_SteamID;
			}
			catch
			{
				return 0uL;
			}
		}

		internal static bool GuestJoinAllowed()
		{
			if (!_licLoaded)
			{
				LoadLicense();
			}
			if (_licGuestHost == 0)
			{
				return false;
			}
			ulong num = LobbyOwnerId();
			if (num == _licGuestHost)
			{
				_guestWaitAt = 0f;
				return true;
			}
			if (num == 0)
			{
				if (_guestWaitAt <= 0f)
				{
					_guestWaitAt = Time.unscaledTime;
				}
				return Time.unscaledTime - _guestWaitAt < 20f;
			}
			_licMsgUntil = Time.unscaledTime + 4f;
			return false;
		}

		private static void LoadLicense()
		{
			_licLoaded = true;
			_licGuestHost = 0uL;
			_licIds.Clear();
			_licBuyer = null;
			_licIdsRaw = null;
			_licSig = null;
			try
			{
				string text = Path.GetDirectoryName(typeof(SoloPlugin).Assembly.Location);
				string path = Path.Combine(text, "license.key");
				if (!File.Exists(path))
				{
					path = Path.Combine(Paths.ConfigPath, "license.key");
				}
				if (!File.Exists(path))
				{
					LicLog("no license.key found next to dll or in config");
					return;
				}
				string buyer = null;
				string ids = null;
				string sig = null;
				string[] lines = File.ReadAllLines(path, Encoding.UTF8);
				foreach (string raw in lines)
				{
					string line = raw.Trim();
					if (line.StartsWith("buyer:"))
					{
						buyer = line.Substring(6).Trim();
					}
					else if (line.StartsWith("ids:"))
					{
						ids = line.Substring(4).Trim();
					}
					else if (line.StartsWith("sig:"))
					{
						sig = line.Substring(4).Trim();
					}
				}
				HashSet<ulong> set;
				if (!VerifyLicense(buyer, ids, sig, out set))
				{
					return;
				}
				_licIds = set;
				_licGuestHost = GuestHostOf(ids);
				_licBuyer = buyer;
				_licIdsRaw = ids;
				_licSig = sig;
				LicLog("loaded key: buyer=" + buyer + " ids=" + ids + " count=" + set.Count + " path=" + path);
			}
			catch (Exception ex)
			{
				_licIds.Clear();
				LicLog("load error: " + ex.Message);
				if (_inst != null)
				{
					_inst.Logger.LogWarning("license: " + ex.Message);
				}
			}
		}

