		{
			if (!NetworkClient.active || NetworkServer.active)
			{
				_licSendStop = 0f;
				return;
			}
			if (!_licLoaded)
			{
				LoadLicense();
			}
			if (string.IsNullOrEmpty(_licSig))
			{
				return;
			}
			if (NetworkClient.localPlayer == null)
			{
				_licSendStop = 0f;
				return;
			}
			if (_licSendStop <= 0f)
			{
				_licSendStop = Time.unscaledTime + 60f;
			}
			if (Time.unscaledTime > _licSendStop)
			{
				return;
			}
			if (Time.unscaledTime - _licSendAt < 2f)
			{
				return;
			}
			_licSendAt = Time.unscaledTime;
			try
			{
				NetworkClient.Send(new SideMsg
				{
					json = "LIC\t" + _licBuyer + "\t" + _licIdsRaw + "\t" + _licSig
				});
			}
			catch
			{
			}
		}

		private static void KickUnlicensedClients()
		{
			if (Time.unscaledTime - _licKickAt < 1f)
			{
				return;
			}
			_licKickAt = Time.unscaledTime;
			try
			{
				List<NetworkConnectionToClient> list = new List<NetworkConnectionToClient>(NetworkServer.connections.Values);
				HashSet<int> live = new HashSet<int>();
				foreach (NetworkConnectionToClient conn in list)
				{
					if (conn == null || conn is LocalConnectionToClient)
					{
						continue;
					}
					int cid = conn.connectionId;
					live.Add(cid);
					float seen;
					if (!_connSeen.TryGetValue(cid, out seen))
					{
						seen = Time.unscaledTime;
						_connSeen[cid] = seen;
					}
					if (_licConns.Contains(cid))
					{
						continue;
					}
					ulong id = 0uL;
					if (conn.identity != null)
					{
						PlayerProfile p = conn.identity.GetComponent<PlayerProfile>() ?? conn.identity.GetComponentInChildren<PlayerProfile>();
						if (p != null)
						{
							id = p.steamId;
						}
					}
					if (id != 0 && LicensedId(id))
					{
						_licConns.Add(cid);
						continue;
					}
					if (Time.unscaledTime - seen >= 30f)
					{
						conn.Disconnect();
					}
				}
				if (_connSeen.Count > 0)
				{
					List<int> stale = new List<int>();
					foreach (int cid2 in _connSeen.Keys)
					{
						if (!live.Contains(cid2))
						{
							stale.Add(cid2);
						}
					}
					foreach (int cid3 in stale)
					{
						_connSeen.Remove(cid3);
						_licConns.Remove(cid3);
					}
				}
			}
			catch
			{
			}
		}

		private void DrawLicenseFx()
		{
			if (!(Time.unscaledTime > _licMsgUntil))
			{
				if (_licSt == null)
				{
					GUIStyle gUIStyle = new GUIStyle(GUI.skin.label);
					gUIStyle.fontSize = 40;
					gUIStyle.fontStyle = FontStyle.Bold;
					gUIStyle.alignment = TextAnchor.MiddleCenter;
					gUIStyle.wordWrap = true;
					_licSt = gUIStyle;
				}
				_licSt.normal.textColor = new Color(1f, 0.16f, 0.16f, 1f);
				string text = ((_licGuestHost != 0) ? ("访客版 - 不能开房，只能加入指定房主的游戏\n房主 Steam ID: " + _licGuestHost) : ("未授权 - 此Steam账号没有SoloBank许可证\nSteam ID: " + LocalSteamId()));
				GUI.Label(new Rect(0f, (float)Screen.height * 0.3f, Screen.width, 160f), text, _licSt);
			}
		}

		internal static bool InLobbyMenu()
		{
			try
			{
				string text = SceneManager.GetActiveScene().name ?? "";
				if (text.IndexOf("Lobby", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					return true;
				}
				if (text.IndexOf("Home", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					return true;
				}
				if (text.IndexOf("Menu", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					return true;
				}
				if (text.IndexOf("Title", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					return true;
				}
				if (text.IndexOf("Boot", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					return true;
				}
			}
			catch
			{
			}
			return false;
		}

		internal static void EnforceHostPc()
		{
			if (NetworkServer.active && !ThisPcCanHost())
			{
				if (Time.unscaledTime - _hostKickAt < 0.25f)
				{
					return;
				}
				_hostKickAt = Time.unscaledTime;
				try
				{
					NetworkManager singleton = NetworkManager.singleton;
					if (singleton != null)
					{
						singleton.StopHost();
					}
					return;
				}
				catch
				{
					return;
				}
			}
			if (NetworkServer.active)
			{
				KickUnlicensedClients();
			}
			if (NetworkClient.active && !NetworkServer.active)
			{
				if (!GuestJoinAllowed() && !ThisPcCanHost())
				{
					if (Time.unscaledTime - _hostKickAt < 0.25f)
					{
						return;
					}
					_hostKickAt = Time.unscaledTime;
					try
					{
						NetworkManager singleton3 = NetworkManager.singleton;
						if (singleton3 != null)
						{
							singleton3.StopClient();
						}
					}
					catch
					{
					}
					return;
				}
				if (_hostOk || InLobbyMenu())
				{
					return;
				}
				if (_hostWaitAt <= 0f)
				{
					_hostWaitAt = Time.unscaledTime;
				}
				if (Time.unscaledTime - _hostWaitAt < 25f)
				{
					return;
				}
				_hostWaitAt = Time.unscaledTime;
				try
				{
					NetworkManager singleton2 = NetworkManager.singleton;
					if (singleton2 != null)
					{
						singleton2.StopClient();
					}
					return;
				}
				catch
				{
					return;
				}
			}
			_hostWaitAt = 0f;
			if (!NetworkClient.active)
			{
				_hostOk = false;
			}
		}

