		private static void TryRegisterClient()
		{
			if (!NetworkClient.active)
			{
				return;
			}
			try
			{
				NetworkClient.ReplaceHandler<SoloMsg>(OnMsg, false);
				NetworkClient.ReplaceHandler<ShopMsg>(OnShopClientNop, false);
				NetworkClient.ReplaceHandler<SideMsg>(OnSideClientNop, false);
				_clientHandler = true;
			}
			catch
			{
				try
				{
					NetworkClient.RegisterHandler<SoloMsg>(OnMsg, false);
					try
					{
						NetworkClient.RegisterHandler<ShopMsg>(OnShopClientNop, false);
					}
					catch
					{
					}
					try
					{
						NetworkClient.RegisterHandler<SideMsg>(OnSideClientNop, false);
					}
					catch
					{
					}
					_clientHandler = true;
				}
				catch
				{
				}
			}
		}

