		private static bool ParseBatOwnerLine(string line)
		{
			if (string.IsNullOrEmpty(line) || !line.StartsWith("BO\t"))
			{
				return false;
			}
			string[] array = line.Split(new char[1] { '\t' });
			if (array.Length < 4)
			{
				return true;
			}
			uint result;
			if (!uint.TryParse(array[1], out result) || result == 0)
			{
				return true;
			}
			BatOwnerKey[result] = array[2] ?? "";
			BatOwnerName[result] = array[3] ?? "";
			return true;
		}

		private static bool ParseChalProgLine(string line)
		{
			if (string.IsNullOrEmpty(line) || !line.StartsWith("CP\t"))
			{
				return false;
			}
			string[] array = line.Split(new char[1] { '\t' });
			if (array.Length < 3)
			{
				return true;
			}
			int result;
			if (!int.TryParse(array[1], out result))
			{
				return true;
			}
			float result2;
			float.TryParse(array[2], NumberStyles.Float, CultureInfo.InvariantCulture, out result2);
			ViewChalProg[result] = result2;
			if (array.Length >= 4)
			{
				ViewChalText[result] = array[3];
			}
			return true;
		}

		private static Acc ParseAccLine(string line)
		{
			if (string.IsNullOrEmpty(line))
			{
				return null;
			}
			string[] array = line.Split(new char[1] { '\t' });
			if (array.Length < 5)
			{
				return null;
			}
			Acc acc = new Acc();
			acc.name = array[0];
			double.TryParse(array[1], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.money);
			int.TryParse(array[2], out acc.tickets);
			int.TryParse(array[3], out acc.day);
			double.TryParse(array[4], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.quota);
			if (array.Length >= 6)
			{
				acc.id = array[5];
			}
			if (array.Length >= 7)
			{
				double.TryParse(array[6], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.loanExtra);
			}
			if (array.Length >= 8)
			{
				int.TryParse(array[7], out acc.shopBuyT);
			}
			if (array.Length >= 9)
			{
				int.TryParse(array[8], out acc.shopSellT);
			}
			if (array.Length >= 10)
			{
				int.TryParse(array[9], out acc.shopDay);
			}
			if (array.Length >= 11)
			{
				double.TryParse(array[10], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.loanUsed);
			}
			if (array.Length >= 12)
			{
				int.TryParse(array[11], out acc.loanDay);
			}
			if (array.Length >= 13)
			{
				int.TryParse(array[12], out acc.bonusDraw);
			}
			if (array.Length >= 14)
			{
				int.TryParse(array[13], out acc.hoopDay);
			}
			if (array.Length >= 20)
			{
				int.TryParse(array[19], out acc.confStacks);
			}
			if (array.Length >= 21)
			{
				int.TryParse(array[20], out acc.insStacks);
			}
			if (array.Length >= 22)
			{
				int.TryParse(array[21], out acc.stakeStacks);
			}
			if (array.Length >= 23)
			{
				acc.stash = array[22] ?? "";
			}
			if (array.Length >= 24)
			{
				int.TryParse(array[23], out acc.catches);
			}
			if (array.Length >= 25)
			{
				int.TryParse(array[24], out acc.kit);
			}
			if (array.Length >= 26)
			{
				int.TryParse(array[25], out acc.goalTier);
			}
			if (array.Length >= 27)
			{
				int.TryParse(array[26], out acc.goalOk);
			}
			if (array.Length >= 28)
			{
				int.TryParse(array[27], out acc.goalDay);
			}
			if (array.Length >= 29)
			{
				double.TryParse(array[28], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.stealPct);
			}
			if (array.Length >= 30)
			{
				double.TryParse(array[29], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.winDay);
			}
			if (array.Length >= 31)
			{
				int.TryParse(array[30], out acc.protectStreak);
			}
			if (array.Length >= 32)
			{
				acc.betLock = array[31] ?? "";
			}
			if (array.Length >= 33)
			{
				double.TryParse(array[32], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.betCost);
			}
			if (array.Length >= 34)
			{
				double.TryParse(array[33], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.betCash);
			}
			if (array.Length >= 35)
			{
				int.TryParse(array[34], out acc.robbedDay);
			}
			if (array.Length >= 36)
			{
				int.TryParse(array[35], out acc.job);
			}
			if (array.Length >= 37)
			{
				double.TryParse(array[36], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.usuryDue);
			}
			if (array.Length >= 38)
			{
				acc.usuryFrom = array[37] ?? "";
			}
			if (array.Length >= 39)
			{
				acc.duelPeer = array[38] ?? "";
			}
			if (array.Length >= 40)
			{
				double.TryParse(array[39], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.duelCash0);
			}
			if (array.Length >= 41)
			{
				int.TryParse(array[40], out acc.duelDay);
			}
			if (acc.job != 0)
			{
				if (!string.IsNullOrEmpty(acc.id))
				{
					Jobs[acc.id] = acc.job;
				}
				if (!string.IsNullOrEmpty(acc.name))
				{
					Jobs["p" + acc.name] = acc.job;
				}
			}
			if (array.Length >= 15)
			{
				double.TryParse(array[14], NumberStyles.Float, CultureInfo.InvariantCulture, out acc.hoopBonus);
			}
			if (array.Length >= 16)
			{
				int.TryParse(array[15], out acc.payStreak);
			}
			if (acc.payStreak < 0)
			{
				acc.payStreak = 0;
			}
			acc.allowBet = 1;
			if (array.Length >= 17)
			{
				int.TryParse(array[16], out acc.allowBet);
			}
			if (array.Length >= 18)
			{
				int.TryParse(array[17], out acc.rentDay);
			}
			if (array.Length >= 19)
			{
				acc.rentPass = array[18] ?? "";
			}
			if (string.IsNullOrEmpty(acc.name))
			{
				return null;
			}
			return acc;
		}

		private static void ApplyPayload(string raw)
		{
			if (string.IsNullOrEmpty(raw))
			{
				return;
			}
			if (raw.StartsWith("SB2"))
			{
				string[] array = raw.Split(new char[1] { '\n' });
				if (array.Length < 4)
				{
					return;
				}
				int result;
				if (int.TryParse(array[1], out result) && result > 0)
				{
					SharedDay = result;
				}
				int result2;
				int.TryParse(array[2], out result2);
				int result3;
				int.TryParse(array[3], out result3);
				List<Acc> list = new List<Acc>();
				if (!NetworkServer.active)
				{
					BatOwnerKey.Clear();
					BatOwnerName.Clear();
					ViewSide.Clear();
					ViewSideRows.Clear();
					ViewTips.Clear();
				}
				for (int i = 4; i < array.Length; i++)
				{
					if (!ParseBatOwnerLine(array[i]) && !ParseChalProgLine(array[i]) && !ParseSideLine(array[i]))
					{
						Acc acc = ParseAccLine(array[i]);
						if (acc != null)
						{
							list.Add(acc);
						}
					}
				}
				View = list.ToArray();
				if (NetworkServer.active)
				{
					return;
				}
				PlayerProfile playerProfile = LocalProfile();
				for (int j = 0; j < list.Count; j++)
				{
					Acc acc2 = list[j];
					if (acc2 != null && acc2.job >= 1 && playerProfile != null && (AccIsPlayer(acc2, playerProfile) || acc2.name == playerProfile.playerName))
					{
						LocalJob = acc2.job;
					}
				}
				return;
			}
			if (raw.StartsWith("SB1"))
			{
				string[] array2 = raw.Split(new char[1] { '\n' });
				if (array2.Length < 2)
				{
					return;
				}
				int result4;
				if (int.TryParse(array2[1], out result4) && result4 > 0)
				{
					SharedDay = result4;
				}
				List<Acc> list2 = new List<Acc>();
				for (int k = 2; k < array2.Length; k++)
				{
					Acc acc3 = ParseAccLine(array2[k]);
					if (acc3 != null)
					{
						list2.Add(acc3);
					}
				}
				View = list2.ToArray();
				return;
			}
			AccList accList = JsonUtility.FromJson<AccList>(raw);
			if (accList == null)
			{
				return;
			}
			if (accList.sharedDay > 0)
			{
				SharedDay = accList.sharedDay;
			}
			if (accList.items == null)
			{
				return;
			}
			List<Acc> list3 = new List<Acc>();
			for (int l = 0; l < accList.items.Length; l++)
			{
				Acc acc4 = accList.items[l];
				if (acc4 != null && !string.IsNullOrEmpty(acc4.name))
				{
					list3.Add(acc4);
				}
			}
			View = list3.ToArray();
		}

		public static string Key(PlayerProfile p)
		{
			if (p == null)
			{
				return "";
			}
			if (p.steamId != 0)
			{
				return "s" + p.steamId;
			}
			NetworkIdentity networkIdentity = p.netIdentity;
			if (networkIdentity == null)
			{
				networkIdentity = p.GetComponent<NetworkIdentity>();
			}
			if (networkIdentity != null && networkIdentity.netId != 0)
			{
				return "n" + networkIdentity.netId;
			}
			if (!string.IsNullOrEmpty(p.playerName))
			{
				return "p" + p.playerName;
			}
			return "i" + p.GetInstanceID();
		}

		private static bool ProfileMatchesKey(PlayerProfile p, string k)
		{
			if (p == null || string.IsNullOrEmpty(k))
			{
				return false;
			}
			if (Key(p) == k)
			{
				return true;
			}
			if (p.steamId != 0 && k == "s" + p.steamId)
			{
				return true;
			}
			if (!string.IsNullOrEmpty(p.playerName) && k == "p" + p.playerName)
			{
				return true;
			}
			uint num = NetIdOf(p);
			if (num != 0 && k == "n" + num)
			{
				return true;
			}
			Acc a = FindAccByKey(k);
			if (AccIsPlayer(a, p))
			{
				return true;
			}
			return false;
		}

		internal static Acc Ensure(PlayerProfile p)
		{
			if (p == null)
			{
				return null;
			}
			string text = Key(p);
			if (string.IsNullOrEmpty(text))
			{
				return null;
			}
			Acc value;
			if (!Accs.TryGetValue(text, out value))
			{
				if (!string.IsNullOrEmpty(p.playerName))
				{
					foreach (Acc value2 in Accs.Values)
					{
						if (value2 != null && value2.name == p.playerName)
						{
							value = value2;
							MoveJobKey(value.id, text);
							value.id = text;
							Accs[text] = value;
							break;
						}
					}
				}
				if (value == null)
				{
					Acc acc = new Acc();
					acc.id = text;
					acc.name = p.playerName;
					acc.money = 0.0;
					acc.tickets = 0;
					acc.day = 1;
					acc.quota = 0.0;
					acc.loanExtra = 0.0;
					acc.loanUsed = 0.0;
					acc.loanDay = SharedDay;
					value = acc;
					Accs[text] = value;
				}
			}
			else if (!string.IsNullOrEmpty(value.id) && value.id != text)
			{
				MoveJobKey(value.id, text);
				value.id = text;
			}
			if (!string.IsNullOrEmpty(p.playerName))
			{
				value.name = p.playerName;
			}
			int job = GetJob(value);
			if (job != 0)
			{
				RememberJob(p, value, job);
			}
			RefreshLoanDay(value);
			RefreshRentDay(value);
			FixMissingQuota(value);
			return value;
		}

		internal static bool SeenHas(List<int> seen, int id)
		{
			for (int i = 0; i < seen.Count; i++)
			{
				if (seen[i] == id)
				{
					return true;
				}
			}
			return false;
		}

		private static bool ProfileIsNpcBody(PlayerProfile p)
		{
			if (p == null)
			{
				return false;
			}
			try
			{
				if (p.GetComponentInParent<NPC>() != null)
				{
					return true;
				}
				if (p.GetComponentInChildren<NPC>(true) != null)
				{
					return true;
				}
			}
			catch
			{
			}
			return false;
		}

		internal static void AddPresent(List<PlayerProfile> into, List<int> seen, PlayerProfile p)
		{
			if (p == null || into == null || ProfileIsNpcBody(p) || (p.steamId == 0 && string.IsNullOrEmpty(p.playerName)))
			{
				return;
			}
			int instanceID = p.GetInstanceID();
			if (seen != null)
			{
				if (SeenHas(seen, instanceID))
				{
					return;
				}
				seen.Add(instanceID);
			}
			into.Add(p);
		}

		internal static List<PlayerProfile> PresentProfiles()
		{
			List<PlayerProfile> list = new List<PlayerProfile>();
			List<int> seen = new List<int>();
			try
			{
				if (NetworkServer.active)
				{
					foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
					{
						if (connection.Value != null)
						{
							AddPresent(list, seen, ProfileFromIdentity(connection.Value.identity));
						}
					}
					return list;
				}
			}
			catch
			{
			}
			try
			{
				PropertyInfo propertyInfo = AccessTools.Property(typeof(LocalManager), "Instance") ?? AccessTools.Property(typeof(LocalManager).BaseType, "Instance");
				object obj2 = ((propertyInfo != null) ? propertyInfo.GetValue(null, null) : null);
				if (obj2 != null)
				{
					List<PlayerReferences> list2 = AccessTools.Field(typeof(LocalManager), "players").GetValue(obj2) as List<PlayerReferences>;
					if (list2 != null)
					{
						for (int i = 0; i < list2.Count; i++)
						{
							PlayerReferences playerReferences = list2[i];
							if (playerReferences != null)
							{
								PlayerProfile playerProfile = null;
								if (playerReferences.identity != null)
								{
									playerProfile = ProfileFromIdentity(playerReferences.identity);
								}
								if (playerProfile == null && playerReferences.controller != null)
								{
									playerProfile = playerReferences.controller.GetComponent<PlayerProfile>() ?? playerReferences.controller.GetComponentInChildren<PlayerProfile>();
								}
								AddPresent(list, seen, playerProfile);
							}
						}
					}
				}
			}
			catch
			{
			}
			AddPresent(list, seen, LocalProfile());
			return list;
		}

		internal static List<Acc> NamedAccs()
		{
			List<string> list = new List<string>();
			foreach (KeyValuePair<string, Acc> acc in Accs)
			{
				if (acc.Value == null || string.IsNullOrEmpty(acc.Value.name))
				{
					list.Add(acc.Key);
				}
			}
			for (int i = 0; i < list.Count; i++)
			{
				Accs.Remove(list[i]);
			}
			List<Acc> list2 = new List<Acc>(Accs.Values);
			list2.Sort((Acc x, Acc y) => y.money.CompareTo(x.money));
			return list2;
		}

		internal static List<Acc> PresentAccs()
		{
			List<PlayerProfile> list = PresentProfiles();
			List<Acc> list2 = new List<Acc>();
			List<string> list3 = new List<string>();
			for (int i = 0; i < list.Count; i++)
			{
				Acc acc = Ensure(list[i]);
				if (acc == null || string.IsNullOrEmpty(acc.name))
				{
					continue;
				}
				string text = (string.IsNullOrEmpty(acc.id) ? Key(list[i]) : acc.id);
				bool flag = false;
				for (int j = 0; j < list3.Count; j++)
				{
					if (list3[j] == text)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					list3.Add(text);
					list2.Add(acc);
				}
			}
			list2.Sort((Acc x, Acc y) => y.money.CompareTo(x.money));
			return list2;
		}

		internal static void FixMissingQuota(Acc a)
		{
			if (a == null)
			{
				return;
			}
			if (EconomyFrozen())
			{
				a.quota = 0.0;
				return;
			}
			switch (GetJob(a))
			{
			case 0:
			case 1:
				a.quota = 0.0;
				return;
			case 4:
				a.quota = ((a.usuryDue > 0.001) ? a.usuryDue : 0.0);
				return;
			}
			if (a.quota < 0.001)
			{
				a.Recalc();
			}
		}

		internal static void EnsureAll()
		{
			List<PlayerProfile> list = PresentProfiles();
			for (int i = 0; i < list.Count; i++)
			{
				Ensure(list[i]);
			}
		}

		internal static void RefreshShopDay(Acc a)
		{
			if (a != null && a.shopDay != SharedDay)
			{
				a.shopDay = SharedDay;
				a.shopBuyT = 0;
				a.shopSellT = 0;
			}
		}

		internal static double NextTicketBuyCost(Acc a)
		{
			RefreshShopDay(a);
			int num = SharedDay;
			if (num < 1)
			{
				num = 1;
			}
			int num2 = ((a != null) ? a.shopBuyT : 0);
			if (num2 < 0)
			{
				num2 = 0;
			}
			return 500.0 * (double)num + 100.0 * (double)num2;
		}

		internal static int GetJob(Acc a)
		{
			if (a == null)
			{
				return 0;
			}
			int value;
			if (!string.IsNullOrEmpty(a.id) && Jobs.TryGetValue(a.id, out value) && value != 0)
			{
				return value;
			}
			if (!string.IsNullOrEmpty(a.name) && Jobs.TryGetValue("p" + a.name, out value) && value != 0)
			{
				return value;
			}
			if (a.job != 0)
			{
				return a.job;
			}
			try
			{
				if (LocalJob != 0 && AccIsPlayer(a, LocalProfile()))
				{
					return LocalJob;
				}
			}
			catch
			{
			}
			return 0;
		}

		internal static int GetJob(PlayerProfile p)
		{
			if (p == null)
			{
				return 0;
			}
			Acc a = Ensure(p);
			int value = GetJob(a);
			if (value != 0)
			{
				return value;
			}
			string text = Key(p);
			if (!string.IsNullOrEmpty(text) && Jobs.TryGetValue(text, out value) && value != 0)
			{
				return value;
			}
			if (p.steamId != 0 && Jobs.TryGetValue("s" + p.steamId, out value) && value != 0)
			{
				return value;
			}
			if (!string.IsNullOrEmpty(p.playerName) && Jobs.TryGetValue("p" + p.playerName, out value) && value != 0)
			{
				return value;
			}
			return 0;
		}

		private static void RememberJob(PlayerProfile p, Acc a, int job)
		{
			if (job < 1 || job > 4)
			{
				return;
			}
			if (a != null)
			{
				a.job = job;
				if (!string.IsNullOrEmpty(a.id))
				{
					Jobs[a.id] = job;
				}
				if (!string.IsNullOrEmpty(a.name))
				{
					Jobs["p" + a.name] = job;
				}
			}
			if (!(p == null))
			{
				string text = Key(p);
				if (!string.IsNullOrEmpty(text))
				{
					Jobs[text] = job;
				}
				if (p.steamId != 0)
				{
					Jobs["s" + p.steamId] = job;
				}
				if (!string.IsNullOrEmpty(p.playerName))
				{
					Jobs["p" + p.playerName] = job;
				}
			}
		}

		private static void MoveJobKey(string from, string to)
		{
			if (!string.IsNullOrEmpty(to) && !(from == to))
			{
				int value = 0;
				if (!string.IsNullOrEmpty(from) && Jobs.TryGetValue(from, out value) && value != 0)
				{
					Jobs[to] = value;
				}
			}
		}

		internal static bool IsBoss(Acc a)
		{
			if (GetJob(a) == 1)
			{
				return true;
			}
			if (LocalJob == 1 && AccIsPlayer(a, LocalProfile()))
			{
				return true;
			}
			return false;
		}

		internal static bool IsGambler(Acc a)
		{
			if (GetJob(a) == 2)
			{
				return true;
			}
			if (LocalJob == 2 && AccIsPlayer(a, LocalProfile()))
			{
				return true;
			}
			return false;
		}

		internal static bool AccHasDuel(Acc a)
		{
			if (a == null)
			{
				return false;
			}
			if (a.duelDay != SharedDay)
			{
				return false;
			}
			return !string.IsNullOrEmpty(a.duelPeer);
		}

		internal static bool AccDuelNoBuffs(Acc a)
		{
			if (!AccHasDuel(a))
			{
				return false;
			}
			return a.duelPeer[0] == '!';
		}

		internal static string DuelPeerKey(Acc a)
		{
			if (a == null || string.IsNullOrEmpty(a.duelPeer))
			{
				return "";
			}
			if (a.duelPeer[0] == '!')
			{
				return a.duelPeer.Substring(1);
			}
			return a.duelPeer;
		}

		private static double DuelPctOf(Acc a)
		{
			if (a == null)
			{
				return 100.0;
			}
			if (a.duelCash0 < 0.001)
			{
				if (a.money > 0.001)
				{
					return 999.0;
				}
				return 100.0;
			}
			return 100.0 * a.money / a.duelCash0;
		}

		private static void ClearDuel(Acc a)
		{
			if (a != null)
			{
				a.duelPeer = "";
				a.duelCash0 = 0.0;
				a.duelDay = 0;
			}
		}

		private static void ClearAllDuels()
		{
			foreach (Acc value in Accs.Values)
			{
				ClearDuel(value);
			}
			DuelUntil.Clear();
			DuelWinDay.Clear();
			LocalDuelUntil = 0f;
			_duelLocalDay = 0;
			_duelGateDay = 0;
			_duelGateFired = false;
		}

		internal static Acc LocalAccRow()
		{
			PlayerProfile p = LocalProfile();
			if (NetworkServer.active)
			{
				return Ensure(p);
			}
			Acc[] view = View;
			int n = ((view != null) ? view.Length : 0);
			return FindMine(view, n);
		}

		private static bool LocalDuelWindowOpen()
		{
			if (LocalDuelUntil <= 0.02f)
			{
				return false;
			}
			return Time.unscaledTime < LocalDuelUntil;
		}

		private static Acc AccOfProfile(PlayerProfile p)
		{
			if (p == null)
			{
				return null;
			}
			if (NetworkServer.active)
			{
				return Ensure(p);
			}
			string text = Key(p);
			Acc[] view = View;
			if (view != null)
			{
				Acc[] array = view;
				foreach (Acc acc in array)
				{
					if (acc != null && (acc.id == text || AccIsPlayer(acc, p)))
					{
						return acc;
					}
				}
			}
			return null;
		}

		private static bool MarkRangeOk(PlayerProfile me, PlayerProfile vic)
		{
			if (me == null || vic == null || me == vic)
			{
				return false;
			}
			if (LocalJob != 2 && GetJob(me) != 2)
			{
				return false;
			}
			Acc acc = LocalAccRow();
			if (acc == null || !IsGambler(acc))
			{
				return false;
			}
			if (AccHasDuel(acc))
			{
				return false;
			}
			if (!LocalDuelWindowOpen())
			{
				return false;
			}
			if (me.transform == null || vic.transform == null)
			{
				return false;
			}
			try
			{
				Vector3 position = me.transform.position;
				if (!PlayerInElevator(position) && !PlayerOnCasinoFloor(position))
				{
					return false;
				}
			}
			catch
			{
				return false;
			}
			if (Vector3.Distance(me.transform.position, vic.transform.position) > 6f)
			{
				return false;
			}
			return true;
		}

