		private static void TryDuelMark(PlayerProfile from, string toKey)
		{
			if (!NetworkServer.active || from == null || string.IsNullOrEmpty(toKey))
			{
				return;
			}
			Acc acc = Ensure(from);
			if (acc == null || !IsGambler(acc) || AccHasDuel(acc))
			{
				return;
			}
			string text = (string.IsNullOrEmpty(acc.id) ? Key(from) : acc.id);
			float value;
			int value2;
			if (!DuelUntil.TryGetValue(text, out value) || Time.unscaledTime > value + 0.75f || (DuelWinDay.TryGetValue(text, out value2) && value2 != SharedDay))
			{
				return;
			}
			PlayerProfile playerProfile = FindProfileByKey(toKey);
			if (playerProfile == null || playerProfile == from)
			{
				return;
			}
			Acc acc2 = Ensure(playerProfile);
			if (acc2 == null)
			{
				return;
			}
			if (AccHasDuel(acc2))
			{
				NotifyMoney(acc, "此玩家正在决斗中 无法标记", 0);
				return;
			}
			try
			{
				if (from.transform == null || playerProfile.transform == null || Vector3.Distance(from.transform.position, playerProfile.transform.position) > 6.5f)
				{
					return;
				}
			}
			catch
			{
				return;
			}
			string text2 = (string.IsNullOrEmpty(acc2.id) ? Key(playerProfile) : acc2.id);
			if (string.IsNullOrEmpty(text) || string.IsNullOrEmpty(text2) || text == text2)
			{
				return;
			}
			acc.duelPeer = "!" + text2;
			acc2.duelPeer = text;
			acc.duelCash0 = acc.money;
			acc2.duelCash0 = acc2.money;
			acc.duelDay = SharedDay;
			acc2.duelDay = SharedDay;
			string text3 = "";
			try
			{
				text3 = playerProfile.playerName ?? "";
			}
			catch
			{
			}
			if (string.IsNullOrEmpty(text3))
			{
				text3 = acc2.name ?? "玩家";
			}
			NotifyMoney(acc, "你已标记" + text3, 3);
			NotifyMoney(acc2, "你已被赌徒标记", 0);
			Broadcast();
			try
			{
				ulong result;
				if (!string.IsNullOrEmpty(acc.id) && acc.id.Length > 1 && acc.id[0] == 's' && ulong.TryParse(acc.id.Substring(1), out result))
				{
					SyncUpgradePanel(result);
				}
				ulong result2;
				if (!string.IsNullOrEmpty(acc2.id) && acc2.id.Length > 1 && acc2.id[0] == 's' && ulong.TryParse(acc2.id.Substring(1), out result2))
				{
					SyncUpgradePanel(result2);
				}
			}
			catch
			{
			}
			QueueRestoreGamblerUi();
		}

		private static void SettleDuels(List<Acc> live)
		{
			if (live == null)
			{
				return;
			}
			Dictionary<string, bool> dictionary = new Dictionary<string, bool>();
			for (int i = 0; i < live.Count; i++)
			{
				Acc acc = live[i];
				if (acc == null || !AccHasDuel(acc) || (!string.IsNullOrEmpty(acc.id) && dictionary.ContainsKey(acc.id)))
				{
					continue;
				}
				Acc acc2 = FindAccByKey(DuelPeerKey(acc));
				if (acc2 == null || !AccHasDuel(acc2))
				{
					continue;
				}
				bool flag = false;
				for (int j = 0; j < live.Count; j++)
				{
					Acc acc3 = live[j];
					if (acc3 != null && (acc3 == acc2 || (!string.IsNullOrEmpty(acc2.id) && acc3.id == acc2.id)))
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					continue;
				}
				if (!string.IsNullOrEmpty(acc.id))
				{
					dictionary[acc.id] = true;
				}
				if (!string.IsNullOrEmpty(acc2.id))
				{
					dictionary[acc2.id] = true;
				}
				double num = DuelPctOf(acc);
				double num2 = DuelPctOf(acc2);
				if (!(Math.Abs(num - num2) < 0.0001))
				{
					Acc acc4 = ((num > num2) ? acc : acc2);
					Acc acc5 = ((num > num2) ? acc2 : acc);
					double num3 = acc5.money;
					if (num3 < 0.0)
					{
						num3 = 0.0;
					}
					acc5.money = 0.0;
					acc4.money += num3;
					string text = (string.IsNullOrEmpty(acc5.name) ? "玩家" : acc5.name);
					string text2 = (string.IsNullOrEmpty(acc4.name) ? "玩家" : acc4.name);
					NotifyMoney(acc4, "你赢了！" + text + "的" + MoneyDollar(num3) + "将全归你", 1);
					NotifyMoney(acc5, "你输了！" + text2 + "将获得你的所有现金", 0);
					if (IsBoss(acc5))
					{
						acc5.money = BossStartMoney;
						NotifyMoney(acc5, "老板资金已重置为 " + MoneyDollar(BossStartMoney), 1);
					}
				}
			}
		}

		private static bool AllPresentInElevator(List<PlayerProfile> ps)
		{
			if (ps == null)
			{
				return false;
			}
			int num = 0;
			for (int i = 0; i < ps.Count; i++)
			{
				PlayerProfile playerProfile = ps[i];
				if (playerProfile == null)
				{
					continue;
				}
				try
				{
					if (playerProfile.transform == null)
					{
						return false;
					}
					if (!PlayerInElevator(playerProfile.transform.position))
					{
						return false;
					}
					num++;
				}
				catch
				{
					return false;
				}
			}
			return num > 0;
		}

		private static void TickDuelWindows()
		{
			Acc a = LocalAccRow();
			if (AccDuelNoBuffs(a) && Time.frameCount % 12 == 0)
			{
				PaintLocalUpgradeUi();
			}
			if (NetworkServer.active)
			{
				if (_duelGateDay != SharedDay)
				{
					_duelGateDay = SharedDay;
					_duelGateFired = false;
					DuelUntil.Clear();
					DuelWinDay.Clear();
				}
				List<PlayerProfile> list = PresentProfiles();
				for (int i = 0; i < list.Count; i++)
				{
					PlayerProfile playerProfile = list[i];
					if (!(playerProfile == null))
					{
						Acc acc = Ensure(playerProfile);
						if (acc != null && acc.duelDay != SharedDay)
						{
							ClearDuel(acc);
						}
					}
				}
				if (!_duelGateFired && AllPresentInElevator(list))
				{
					_duelGateFired = true;
					for (int j = 0; j < list.Count; j++)
					{
						PlayerProfile playerProfile2 = list[j];
						if (playerProfile2 == null)
						{
							continue;
						}
						Acc acc2 = Ensure(playerProfile2);
						if (acc2 != null && IsGambler(acc2) && !AccHasDuel(acc2))
						{
							string text = (string.IsNullOrEmpty(acc2.id) ? Key(playerProfile2) : acc2.id);
							if (!string.IsNullOrEmpty(text))
							{
								DuelUntil[text] = Time.unscaledTime + 30f;
								DuelWinDay[text] = SharedDay;
								SendSoloTo(playerProfile2, "DUELCD");
							}
						}
					}
				}
			}
			Acc acc3 = LocalAccRow();
			if (acc3 == null || !IsGambler(acc3))
			{
				if (LocalJob != 2)
				{
					LocalDuelUntil = 0f;
				}
				return;
			}
			if (_duelLocalDay != SharedDay)
			{
				_duelLocalDay = SharedDay;
				LocalDuelUntil = 0f;
			}
			if (AccHasDuel(acc3))
			{
				LocalDuelUntil = -1f;
			}
			else if (!(LocalDuelUntil < -0.5f) && LocalDuelUntil > 0.02f && Time.unscaledTime >= LocalDuelUntil)
			{
				LocalDuelUntil = -1f;
			}
		}

