			}
			if (GetJob(p) != 3)
			{
				return false;
			}
			try
			{
				PlayerBuff playerBuff = p.GetComponent<PlayerBuff>();
				if (playerBuff == null)
				{
					playerBuff = p.GetComponentInChildren<PlayerBuff>();
				}
				if (playerBuff == null)
				{
					return false;
				}
				if (playerBuff.GetValue(PlayerBuffType.TipsyFortune) > 0.001f)
				{
					return true;
				}
				if (playerBuff.GetValue(PlayerBuffType.InspiringMelody) > 0.001f)
				{
					return true;
				}
				if (playerBuff.GetValue(PlayerBuffType.Immunity) > 0.001f)
				{
					return true;
				}
			}
			catch
			{
			}
			return false;
		}

