				a.hoopDay = 0;
				a.payStreak = 0;
				a.usuryDue = 0.0;
				a.usuryFrom = "";
				switch (job)
				{
				case 1:
					a.money = 10000.0;
					a.tickets = 20;
					a.quota = 0.0;
					break;
				case 4:
					a.money = 500.0;
					a.tickets = 5;
					a.quota = 0.0;
					break;
				default:
					a.money = 1000.0;
					a.tickets = 15;
					a.quota = 500.0;
