		internal static void UnlockEveryCosmetic()
		{
			CosmeticsUnlockManager cosmeticsUnlockManager = null;
			try
			{
				cosmeticsUnlockManager = MonoSingleton<CosmeticsUnlockManager>.Instance;
			}
			catch
			{
			}
			if (cosmeticsUnlockManager == null)
			{
				return;
			}
			try
			{
				CosmeticDataManager.Initialize();
			}
			catch
			{
			}
			object obj3 = null;
			try
			{
				if (_unlockSetF == null)
				{
					_unlockSetF = AccessTools.Field(typeof(CosmeticsUnlockManager), "unlockedCosmetics");
				}
				if (_unlockSetF != null)
				{
					obj3 = _unlockSetF.GetValue(cosmeticsUnlockManager);
				}
			}
			catch
			{
			}
			if (obj3 == null)
			{
				return;
			}
			MethodInfo methodInfo = null;
			try
			{
				methodInfo = obj3.GetType().GetMethod("Add", new Type[1] { typeof(int) });
			}
			catch
			{
			}
			if (methodInfo == null)
			{
				return;
			}
			try
			{
				IEnumerable allCosmetics = CosmeticDataManager.GetAllCosmetics();
				if (allCosmetics != null)
				{
					foreach (object item in allCosmetics)
					{
						CosmeticData cosmeticData = item as CosmeticData;
						if (!(cosmeticData == null))
						{
							try
							{
								methodInfo.Invoke(obj3, new object[1] { cosmeticData.cosmeticId });
							}
							catch
							{
							}
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				MethodInfo methodInfo2 = AccessTools.Method(typeof(CosmeticsUnlockManager), "SaveToFile");
				if (methodInfo2 != null)
				{
					methodInfo2.Invoke(cosmeticsUnlockManager, null);
				}
			}
			catch
			{
			}
			int num = 0;
			int num2 = 0;
			try
			{
				num = cosmeticsUnlockManager.GetTotalCosmeticsCount();
			}
			catch
			{
			}
			try
			{
				num2 = cosmeticsUnlockManager.GetUnlockedCount();
			}
			catch
			{
			}
			if (num > 0 && num2 >= num)
			{
				_cosUnlockDone = true;
			}
		}

