		private static bool GoalMetNow(Acc a)
		{
			if (a == null)
			{
				return false;
			}
			int job = GetJob(a);
			int goalTier = a.goalTier;
			if (goalTier > 2)
			{
				return true;
			}
			switch (job)
			{
			case 3:
				return a.stealPct + 0.0001 >= ThiefNeed(goalTier);
			case 2:
				return a.winDay + 0.0001 >= GamblerNeed(goalTier);
			case 1:
			{
				double num = BossStakeNeed(goalTier);
				if (a.betCost + 0.0001 < num * 0.99)
				{
					return false;
				}
				return a.betCash + 0.0001 >= a.betCost * BossMult(goalTier) * 0.99;
			}
			case 4:
				return false;
			default:
				return false;
			}
		}

		private static void TouchGoalHud(Acc a)
		{
			if (a == null)
			{
				return;
			}
			RefreshGoalDay(a);
			switch (GetJob(a))
			{
			case 4:
				return;
			case 2:
				a.goalOk = (GoalMetNow(a) ? 1 : 0);
				return;
			}
			if (GoalMetNow(a))
			{
				a.goalOk = 1;
			}
		}

		private static int GoalJobOf(Acc a)
		{
			if (a == null)
			{
				return LocalJob;
			}
			int num = GetJob(a);
			if (num < 1)
			{
				num = a.job;
			}
			if (num < 1)
			{
				try
				{
					if (AccIsPlayer(a, LocalProfile()))
					{
						num = LocalJob;
					}
				}
				catch
				{
				}
			}
			if (num < 1)
			{
				num = LocalJob;
			}
			return num;
		}

