		internal static string GoalTitle(Acc a)
		{
			if (a != null && a.goalTier > 2)
			{
				return "目标已全部达成";
			}
			int num = GoalJobOf(a);
			int num2 = ((a != null) ? a.goalTier : 0);
			if (num2 > 2)
			{
				num2 = 2;
			}
			switch (num)
			{
			case 3:
				return "目标：累计偷取他人现金 " + ThiefNeed(num2).ToString("0", CultureInfo.InvariantCulture) + "%";
			case 2:
				return "目标：赢至少 " + MoneyShort(GamblerNeed(num2));
			case 1:
			{
				string text = MoneyShort(BossStakeNeed(num2));
				string text2 = BossMult(num2).ToString("0.#", CultureInfo.InvariantCulture);
				return "目标：至少押" + text + " 赚" + text2 + "x";
			}
			case 4:
				return "目标：连续保护老板" + GuardNeedWord(num2) + "天";
			default:
				return "";
			}
		}

		internal static string GoalProg(Acc a)
		{
			if (a == null)
			{
				return "";
			}
			if (a.goalTier > 2)
			{
				return "";
			}
			int num = GoalJobOf(a);
			int num2 = a.goalTier;
			if (num2 > 2)
			{
				num2 = 2;
			}
			switch (num)
			{
			case 3:
				return "（已偷 " + a.stealPct.ToString("0.#", CultureInfo.InvariantCulture) + "%）";
			case 2:
				return "（已赢 " + MoneyShort(a.winDay) + "）";
			case 1:
			{
				double num3 = BossStakeNeed(num2);
				double num4 = BossMult(num2);
				double num5 = a.betCost;
				if (num5 < 0.0)
				{
					num5 = 0.0;
				}
				double v = ((num5 + 0.0001 >= num3) ? (num5 * num4) : (num3 * num4));
				return "（本金" + MoneyShort(num5) + "-至少提" + MoneyShort(v) + "/已提" + MoneyDollar(a.betCash) + "）";
			}
			case 4:
				return "（已连续 " + a.protectStreak.ToString(CultureInfo.InvariantCulture) + " 天）";
			default:
				return "";
			}
		}

		internal static string GoalText(Acc a)
		{
			string text = GoalTitle(a);
			string text2 = GoalProg(a);
			if (string.IsNullOrEmpty(text))
			{
				return "";
			}
			if (string.IsNullOrEmpty(text2))
			{
				return text;
			}
			return text + "\n" + text2;
		}

		private static void EvaluateClassGoals()
		{
			List<Acc> list = PresentAccs();
			if (list == null)
			{
				return;
			}
			bool flag = BossRobbedToday();
			for (int i = 0; i < list.Count; i++)
			{
				Acc acc = list[i];
				if (acc == null)
				{
					continue;
				}
				RefreshGoalDay(acc);
				acc.goalPayCash = 0.0;
				acc.goalPayTix = 0;
				int job = GetJob(acc);
				switch (job)
				{
				default:
					acc.goalOk = 0;
					break;
				case 4:
					if (flag)
					{
						acc.protectStreak = 0;
					}
					else
					{
						acc.protectStreak++;
					}
					if (acc.goalTier > 2)
					{
						acc.goalOk = 1;
					}
					else if (acc.protectStreak >= GuardNeed(acc.goalTier))
					{
						double num3 = GuardAward(acc.goalTier);
						acc.money += num3;
						acc.goalPayCash = num3;
						acc.goalOk = 1;
						acc.goalTier++;
					}
					else
					{
						acc.goalOk = 0;
					}
					break;
				case 1:
				case 2:
				case 3:
				{
					if (acc.goalTier > 2)
					{
						acc.goalOk = 1;
						break;
					}
					if (acc.goalOk == 0 && !GoalMetNow(acc))
					{
						acc.goalOk = 0;
						break;
					}
					double num = 0.0;
					int num2 = 0;
					switch (job)
					{
					case 3:
						num = ThiefAward(acc.goalTier);
						break;
					case 2:
						num2 = GamblerTix(acc.goalTier);
						break;
					case 1:
						num = BossAwardCash(acc.goalTier);
						num2 = BossAwardTix(acc.goalTier);
						break;
					}
					acc.money += num;
					acc.tickets += num2;
					acc.goalPayCash = num;
					acc.goalPayTix = num2;
					acc.goalOk = 1;
					acc.goalTier++;
					break;
				}
				}
			}
		}

