		private static void RefreshChaseView()
		{
			float unscaledTime = Time.unscaledTime;
			List<string> list = null;
			float num = 0f;
			string stealChaseKey = "";
			string stealChaseName = "";
			foreach (KeyValuePair<string, float> item in ViewChaseUntil)
			{
				if (item.Value <= unscaledTime)
				{
					if (list == null)
					{
						list = new List<string>();
					}
					list.Add(item.Key);
				}
				else if (item.Value > num)
				{
					num = item.Value;
					stealChaseKey = item.Key;
					string value;
					if (!ViewChaseName.TryGetValue(item.Key, out value))
					{
						value = "";
					}
					stealChaseName = value;
				}
			}
			if (list != null)
			{
				for (int i = 0; i < list.Count; i++)
				{
					ViewChaseUntil.Remove(list[i]);
					ViewChaseName.Remove(list[i]);
				}
			}
			StealChaseUntil = num;
			StealChaseKey = stealChaseKey;
			StealChaseName = stealChaseName;
		}

		private static void ApplyChaseView(string key, string name, float sec)
		{
			if (string.IsNullOrEmpty(key))
			{
				if (sec <= 0.01f)
				{
					ViewChaseUntil.Clear();
					ViewChaseName.Clear();
				}
				RefreshChaseView();
				return;
			}
			if (sec <= 0.01f)
			{
				ViewChaseUntil.Remove(key);
				ViewChaseName.Remove(key);
			}
			else
			{
				ViewChaseUntil[key] = Time.unscaledTime + sec;
				ViewChaseName[key] = name ?? "";
			}
			RefreshChaseView();
		}

