		private static StealRun FindStealRun(Acc ta, PlayerProfile p)
		{
			StealRun value;
			if (ta != null && !string.IsNullOrEmpty(ta.id) && StealRuns.TryGetValue(ta.id, out value))
			{
				return value;
			}
			foreach (KeyValuePair<string, StealRun> stealRun in StealRuns)
			{
				value = stealRun.Value;
				if (value == null)
				{
					continue;
				}
				if (ta != null && !string.IsNullOrEmpty(ta.id) && value.thief == ta.id)
				{
					return value;
				}
				if (!(p == null))
				{
					Acc value2 = null;
					if (!string.IsNullOrEmpty(value.thief))
					{
						Accs.TryGetValue(value.thief, out value2);
					}
					if (value2 != null && AccIsPlayer(value2, p))
					{
						return value;
					}
					string text = Key(p);
					if (!string.IsNullOrEmpty(text) && text == value.thief)
					{
						return value;
					}
				}
			}
			return null;
		}

		private static StealRun FindStealRunByVictim(string vid)
		{
			if (string.IsNullOrEmpty(vid) || vid == "npc")
			{
				return null;
			}
			StealRun stealRun = null;
			foreach (KeyValuePair<string, StealRun> stealRun2 in StealRuns)
			{
				StealRun value = stealRun2.Value;
				if (value != null && !(value.victim != vid) && (stealRun == null || value.until > stealRun.until))
				{
					stealRun = value;
				}
			}
			return stealRun;
		}

		private static void QueueNote(Acc a, string line, int tone)
		{
			if (a != null && !string.IsNullOrEmpty(line))
			{
				string text = tone.ToString(CultureInfo.InvariantCulture) + "\t" + line.Replace('\t', ' ').Replace('\n', ' ');
				if (string.IsNullOrEmpty(a.notes))
				{
					a.notes = text;
				}
				else
				{
					a.notes = a.notes + "\n" + text;
				}
			}
		}

		internal static void FlushPendingNotes()
		{
			foreach (Acc value in Accs.Values)
			{
				if (value == null)
				{
					continue;
				}
				if (Math.Abs(value.notePay) > 0.0001)
				{
					value.money += value.notePay;
					if (value.money < 0.0)
					{
						value.money = 0.0;
					}
					value.notePay = 0.0;
				}
				if (string.IsNullOrEmpty(value.notes))
				{
					continue;
				}
				string notes = value.notes;
				value.notes = "";
				string[] array = notes.Split(new char[1] { '\n' });
				string[] array2 = array;
				foreach (string text in array2)
				{
					if (!string.IsNullOrEmpty(text))
					{
						int num = text.IndexOf('\t');
						int result = 2;
						string line = text;
						if (num > 0)
						{
							int.TryParse(text.Substring(0, num), out result);
							line = text.Substring(num + 1);
						}
						NotifyMoney(value, line, result);
					}
				}
			}
		}

		internal static void TakeBossCut(Acc loser, double lost)
		{
			if (!NetworkServer.active || loser == null || lost < 0.01)
			{
				return;
			}
			List<Acc> list = PresentAccs();
			if (list == null)
			{
				return;
			}
			int num = 0;
			int num2 = 0;
			for (int i = 0; i < list.Count; i++)
			{
				Acc acc = list[i];
				if (acc == null)
				{
					continue;
				}
				if (IsBoss(acc))
				{
					if (acc != loser && (string.IsNullOrEmpty(loser.id) || !(acc.id == loser.id)))
					{
						num++;
					}
				}
				else
				{
					num2++;
				}
			}
			if (num < 1 || num2 < 1)
			{
				return;
			}
			double num3 = 0.03;
			switch (num2)
			{
			case 1:
				num3 = 0.2;
				break;
			case 2:
				num3 = 0.1;
				break;
			case 3:
				num3 = 0.05;
				break;
			}
			double num4 = lost * num3 / (double)num;
			if (num4 < 0.01 || (!string.IsNullOrEmpty(loser.id) && loser.id == _bossCutWho && Math.Abs(num4 - _bossCutAmt) < 0.02 && Time.unscaledTime - _bossCutAt < 0.45f))
			{
				return;
			}
			_bossCutWho = loser.id ?? "";
			_bossCutAmt = num4;
			_bossCutAt = Time.unscaledTime;
			string text = (string.IsNullOrEmpty(loser.name) ? "玩家" : loser.name);
			string line = "你从" + text + "那儿赚了 " + MoneyDollar(num4);
			for (int j = 0; j < list.Count; j++)
			{
				Acc acc2 = list[j];
				if (acc2 != null && acc2 != loser && (string.IsNullOrEmpty(loser.id) || !(acc2.id == loser.id)) && IsBoss(acc2))
				{
					acc2.money += num4;
					NotifyMoney(acc2, line, 3);
				}
			}
		}

		internal static int ShopHalfInt(Acc a, int cost)
		{
			if (cost < 1)
			{
				return cost;
			}
			if (!IsBoss(a))
			{
				return cost;
			}
			int num = (cost + 1) / 2;
			if (num < 1)
			{
				num = 1;
			}
			return num;
		}

		internal static double ShopHalfCash(Acc a, double cost)
		{
			if (cost <= 0.0)
			{
				return cost;
			}
			if (!IsBoss(a))
			{
				return cost;
			}
			return Math.Ceiling(cost / 2.0);
		}

		internal static void PickJob(PlayerProfile p, int job)
		{
			if (!NetworkServer.active || p == null || job < 1 || job > 4)
			{
				return;
			}
			Acc acc = Ensure(p);
			if (acc == null)
			{
				return;
			}
			int job2 = GetJob(p);
			if ((job2 == 0 || job2 == job) && (job != 1 || CountLiveJob(1) <= 0 || job2 == 1) && (job != 3 || CountLiveJob(3) < 2 || job2 == 3) && (job != 4 || (CountLiveJob(1) >= 1 && (CountLiveJob(4) <= 0 || job2 == 4))))
			{
				RememberJob(p, acc, job);
				ApplyClassKit(acc, job);
				if (AccIsPlayer(acc, LocalProfile()))
				{
					LocalJob = job;
					LocalCatches = acc.catches;
				}
				BroadcastSeats();
				SendJobSync(p);
				Broadcast();
			}
		}

