		private static void SendSoloTo(PlayerProfile p, string json)
		{
			if (p == null || string.IsNullOrEmpty(json))
			{
				return;
			}
			Acc a = Ensure(p);
			if (AccIsPlayer(a, LocalProfile()) || p == LocalProfile())
			{
				OnMsg(new SoloMsg
				{
					json = json
				});
			}
			else
			{
				if (!NetworkServer.active)
				{
					return;
				}
				NetworkIdentity networkIdentity = null;
				try
				{
					networkIdentity = p.netIdentity;
					if (networkIdentity == null)
					{
						networkIdentity = p.GetComponent<NetworkIdentity>();
					}
					if (networkIdentity == null)
					{
						networkIdentity = p.GetComponentInParent<NetworkIdentity>();
					}
				}
				catch
				{
				}
				try
				{
					foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
					{
						NetworkConnectionToClient value = connection.Value;
						if (value == null || value.identity == null)
						{
							continue;
						}
						PlayerProfile playerProfile = ProfileFromIdentity(value.identity);
						bool flag = false;
						if (networkIdentity != null && value.identity == networkIdentity)
						{
							flag = true;
						}
						if (!flag && AccIsPlayer(a, playerProfile))
						{
							flag = true;
						}
						if (!flag && playerProfile == p)
						{
							flag = true;
						}
						if (flag)
						{
							if (value.identity.isLocalPlayer)
							{
								OnMsg(new SoloMsg
								{
									json = json
								});
							}
							else
							{
								value.Send(new SoloMsg
								{
									json = json
								});
							}
						}
					}
				}
				catch
				{
				}
			}
		}

		private static void OfferUsury(PlayerProfile bossP, string toKey, double amt, double rate)
		{
			if (!NetworkServer.active || bossP == null || string.IsNullOrEmpty(toKey))
			{
				return;
			}
			if (EconomyFrozen())
			{
				NotifyMoney(Ensure(bossP), "结算日不能放贷", 2);
				return;
			}
			if (GetJob(bossP) != 1)
			{
				NotifyMoney(Ensure(bossP), "只有赌场老板能放贷", 2);
				return;
			}
			if (rate != 1.1 && rate != 1.5 && rate != 2.0)
			{
				NotifyMoney(Ensure(bossP), "利息只能是 1.1x / 1.5x / 2x", 2);
				return;
			}
			if (amt < 1.0)
			{
				NotifyMoney(Ensure(bossP), "最少贷 $1", 2);
				return;
			}
			string text = Key(bossP);
			if (text == toKey)
			{
				NotifyMoney(Ensure(bossP), "不能贷给自己", 2);
				return;
			}
			PlayerProfile playerProfile = FindProfileByKey(toKey);
			if (playerProfile == null)
			{
				NotifyMoney(Ensure(bossP), "找不到玩家", 2);
				return;
			}
			Acc acc = Ensure(bossP);
			Acc acc2 = Ensure(playerProfile);
			if (acc == null || acc2 == null)
			{
				return;
			}
			if (AccHasDuel(acc) || AccHasDuel(acc2))
			{
				NotifyMoney(acc, "玩家对决中 无法贷款", 0);
				NotifyMoney(acc2, "玩家对决中 无法贷款", 0);
				return;
			}
			if (amt > acc.money + 0.0001)
			{
				NotifyMoney(acc, "现金不够", 2);
				return;
			}
			if (acc2.usuryDue > 0.001)
			{
				NotifyMoney(acc, "对方已有贷款", 2);
				return;
			}
			if (!string.IsNullOrEmpty(_usuryPendTgt))
			{
				NotifyMoney(acc, "等上一笔贷款对方同意", 2);
				return;
			}
			double num = Math.Round(amt * rate, 2);
			if (num < amt)
			{
				num = amt;
			}
			_usuryPendBoss = text;
			_usuryPendTgt = toKey;
			_usuryPendAmt = amt;
			_usuryPendDue = num;
			string text2 = (string.IsNullOrEmpty(bossP.playerName) ? "赌场老板" : bossP.playerName);
			SendSoloTo(playerProfile, "UASK\t" + text2.Replace('\t', ' ') + "\t" + amt.ToString("R", CultureInfo.InvariantCulture) + "\t" + num.ToString("R", CultureInfo.InvariantCulture));
		}

		private static void AnswerUsury(PlayerProfile from, bool yes)
		{
			if (!NetworkServer.active || from == null)
			{
				return;
			}
			string text = Key(from);
			if (string.IsNullOrEmpty(_usuryPendTgt) || text != _usuryPendTgt)
			{
				SendSoloTo(from, "UEND");
				return;
			}
			PlayerProfile playerProfile = FindProfileByKey(_usuryPendBoss);
			string text2 = "";
			try
			{
				text2 = from.playerName ?? "";
			}
			catch
			{
			}
			Acc acc = Ensure(from);
			if (string.IsNullOrEmpty(text2) && acc != null)
			{
				text2 = acc.name ?? "";
			}
			if (string.IsNullOrEmpty(text2))
			{
				text2 = "玩家";
			}
			if (!yes || playerProfile == null)
			{
				if (playerProfile != null)
				{
					NotifyMoney(Ensure(playerProfile), text2 + "说你还不如去抢", 0);
					SendSoloTo(playerProfile, "UEND");
				}
				SendSoloTo(from, "UEND");
				ClearUsuryPend();
				return;
			}
			Acc acc2 = Ensure(playerProfile);
			Acc acc3 = Ensure(from);
			double usuryPendAmt = _usuryPendAmt;
			double usuryPendDue = _usuryPendDue;
			if (acc2 == null || acc3 == null || usuryPendAmt < 1.0 || acc2.money + 0.0001 < usuryPendAmt || acc3.usuryDue > 0.001)
			{
				SendSoloTo(playerProfile, "UEND");
				SendSoloTo(from, "UEND");
				ClearUsuryPend();
				return;
			}
			acc2.money -= usuryPendAmt;
			acc3.money += usuryPendAmt;
			acc3.usuryDue = usuryPendDue;
			acc3.usuryFrom = _usuryPendBoss;
			acc3.quota += usuryPendDue;
			int job = GetJob(acc3);
			if (job == 4)
			{
				acc3.quota = usuryPendDue;
			}
			NotifyMoney(acc2, text2 + "对你给的利息很满意", 3);
			SendSoloTo(playerProfile, "UEND");
			SendSoloTo(from, "UEND");
			ClearUsuryPend();
			Broadcast();
		}

		private static void PeelUsuryFromQuota(Acc a, double due)
		{
			if (a == null)
			{
				return;
			}
			int job = GetJob(a);
			if (job == 1 || job == 4)
			{
				a.quota = 0.0;
				return;
			}
			a.quota -= due;
			if (a.quota < 0.0)
			{
				a.quota = 0.0;
			}
		}

		private static void SettleUsuryOne(Acc a)
		{
			if (a == null || a.usuryDue < 0.001)
			{
				return;
			}
			double usuryDue = a.usuryDue;
			string text = a.usuryFrom ?? "";
			a.usuryDue = 0.0;
			a.usuryFrom = "";
			PeelUsuryFromQuota(a, usuryDue);
			Acc acc = null;
			if (!string.IsNullOrEmpty(text))
			{
				PlayerProfile playerProfile = FindProfileByKey(text);
				if (playerProfile != null)
				{
					acc = Ensure(playerProfile);
				}
				if (acc == null && Accs.ContainsKey(text))
				{
					acc = Accs[text];
				}
			}
			if (acc == null)
			{
				foreach (Acc value in Accs.Values)
				{
					if (value != null && GetJob(value) == 1)
					{
						acc = value;
						break;
					}
				}
			}
			double num = a.money;
			if (num > usuryDue)
			{
				num = usuryDue;
			}
			if (num < 0.0)
			{
				num = 0.0;
			}
			if (num > 0.001 && acc != null)
			{
				a.money -= num;
				if (a.money < 0.0)
				{
					a.money = 0.0;
				}
				acc.money += num;
				NotifyMoney(acc, "高利贷返还" + MoneyDollar(num), 1);
			}
			if (num + 0.001 >= usuryDue)
			{
				if (num > 0.001)
				{
					NotifyMoney(a, "贷款利息" + MoneyDollar(usuryDue), 0);
				}
				return;
			}
			if (acc != null && num < 0.001)
			{
				NotifyMoney(acc, "贷款本金已丢失 你下次不要给TA贷款了", 0);
			}
			NotifyMoney(a, "你没还上贷款 老板大概率不会再给你贷款了", 0);
		}

		internal static void SendJobSync(PlayerProfile p)
		{
			if (p == null)
			{
				return;
			}
			Acc a = Ensure(p);
			int job = GetJob(p);
			if (AccIsPlayer(a, LocalProfile()))
			{
				LocalJob = job;
			}
			if (!NetworkServer.active)
			{
				return;
			}
			string json = "JOB\t" + job;
			NetworkIdentity networkIdentity = null;
			try
			{
				networkIdentity = p.netIdentity;
				if (networkIdentity == null)
				{
					networkIdentity = p.GetComponent<NetworkIdentity>();
				}
				if (networkIdentity == null)
				{
					networkIdentity = p.GetComponentInParent<NetworkIdentity>();
				}
			}
			catch
			{
			}
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value == null || value.identity == null)
					{
						continue;
					}
					PlayerProfile playerProfile = ProfileFromIdentity(value.identity);
					bool flag = false;
					if (networkIdentity != null && value.identity == networkIdentity)
					{
						flag = true;
					}
					if (!flag && AccIsPlayer(a, playerProfile))
					{
						flag = true;
					}
					if (!flag && playerProfile == p)
					{
						flag = true;
					}
					if (flag)
					{
						if (value.identity.isLocalPlayer)
						{
							LocalJob = job;
							continue;
						}
						value.Send(new SoloMsg
						{
							json = json
						});
					}
				}
			}
			catch
			{
			}
		}

		internal static void SendJobSyncAll(int jobForce)
		{
			if (jobForce == 0)
			{
				LocalJob = 0;
			}
			if (!NetworkServer.active)
			{
				return;
			}
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value != null && !(value.identity == null))
					{
						PlayerProfile p = ProfileFromIdentity(value.identity);
						int num = ((jobForce >= 0) ? jobForce : GetJob(p));
						if (value.identity.isLocalPlayer)
						{
							LocalJob = num;
							continue;
						}
						value.Send(new SoloMsg
						{
							json = "JOB\t" + num
						});
					}
				}
			}
			catch
			{
			}
		}

