		private static bool PlayerInsideCasinoFloors(Vector3 pos)
		{
			try
			{
				EnsureElevFloors();
				CasinoFloor[] scanFloors = _scanFloors;
				if (scanFloors == null)
				{
					return false;
				}
				CasinoFloor[] array = scanFloors;
				foreach (CasinoFloor casinoFloor in array)
				{
					if (!(casinoFloor == null) && !(casinoFloor.gameObject == null) && casinoFloor.gameObject.activeInHierarchy)
					{
						int num = 0;
						try
						{
							num = casinoFloor.floorIndex;
						}
						catch
						{
						}
						if (num >= 1 && num <= 4 && PointInCasinoFloor(casinoFloor, pos))
						{
							return true;
						}
					}
				}
			}
			catch
			{
			}
			return false;
		}

		private static bool BoundsHasPlayer(Bounds bb, Vector3 pos)
		{
			if (bb.Contains(pos))
			{
				return true;
			}
			Vector3 point = pos;
			point.y -= 1.6f;
			return bb.Contains(point);
		}

		private static bool PointInCasinoFloor(CasinoFloor f, Vector3 pos)
		{
			if (f == null)
			{
				return false;
			}
			try
			{
				BoxCollider[] array = AccessTools.Field(typeof(CasinoFloor), "sfxTriggerBox").GetValue(f) as BoxCollider[];
				if (array != null)
				{
					BoxCollider[] array2 = array;
					foreach (BoxCollider boxCollider in array2)
					{
						if (!(boxCollider == null) && boxCollider.enabled)
						{
							Bounds bounds = boxCollider.bounds;
							bounds.Expand(1.2f);
							if (BoundsHasPlayer(bounds, pos))
							{
								return true;
							}
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				Collider[] componentsInChildren = f.GetComponentsInChildren<Collider>(true);
				if (componentsInChildren != null)
				{
					Collider[] array3 = componentsInChildren;
					foreach (Collider collider in array3)
					{
						if (collider == null || !collider.enabled)
						{
							continue;
						}
						Bounds bounds2 = collider.bounds;
						if (!(bounds2.size.x < 3f) || !(bounds2.size.z < 3f) || !(bounds2.size.y < 3f))
						{
							bounds2.Expand(0.8f);
							if (BoundsHasPlayer(bounds2, pos))
							{
								return true;
							}
						}
					}
				}
			}
			catch
			{
			}
			return false;
		}

