		private static Vector3 FlatDir(Vector3 v)
		{
			v.y = 0f;
			if (v.sqrMagnitude < 0.0001f)
			{
				return Vector3.zero;
			}
			return v.normalized;
		}

		internal static Vector3 FaceFlatPublic(PlayerProfile p)
		{
			return FaceFlat(p);
		}

		private static Vector3 FaceFlat(PlayerProfile p)
		{
			if (p == null || p.transform == null)
			{
				return Vector3.zero;
			}
			Vector3 result = Vector3.zero;
			Vector3 result2 = FlatDir(p.transform.forward);
			try
			{
				Component[] componentsInChildren = p.GetComponentsInChildren<Component>(true);
				if (componentsInChildren != null)
				{
					Component[] array = componentsInChildren;
					foreach (Component component in array)
					{
						if (!(component == null) && !(component.transform == null) && !(component.GetType().Name != "PlayerCameraController"))
						{
							Vector3 vector = FlatDir(component.transform.forward);
							if (vector.sqrMagnitude > 0.5f)
							{
								result = vector;
								break;
							}
						}
					}
				}
			}
			catch
			{
			}
			if (result.sqrMagnitude > 0.5f)
			{
				return result;
			}
			return result2;
		}

		public static bool JobBehind(PlayerProfile thief, PlayerProfile victim)
		{
			if (thief == null || victim == null || thief.transform == null || victim.transform == null)
			{
				return false;
			}
			Vector3 rhs = FlatDir(thief.transform.position - victim.transform.position);
			if (rhs.sqrMagnitude < 0.2f)
			{
				return false;
			}
			Vector3 lhs = MorphFaceFlat(victim);
			if (lhs.sqrMagnitude < 0.5f)
			{
				lhs = FaceFlat(victim);
			}
			if (lhs.sqrMagnitude < 0.5f)
			{
				lhs = FlatDir(victim.transform.forward);
			}
			if (lhs.sqrMagnitude < 0.5f)
			{
				return false;
			}
			return Vector3.Dot(lhs, rhs) < 0.28f;
		}

		public static bool JobInFront(PlayerProfile thief, PlayerProfile victim)
		{
			if (thief == null || victim == null || thief.transform == null || victim.transform == null)
			{
				return false;
			}
			Vector3 rhs = FlatDir(thief.transform.position - victim.transform.position);
			if (rhs.sqrMagnitude < 0.2f)
			{
				return false;
			}
			Vector3 lhs = MorphFaceFlat(victim);
			if (lhs.sqrMagnitude < 0.5f)
			{
				lhs = FaceFlat(victim);
			}
			if (lhs.sqrMagnitude < 0.5f)
			{
				lhs = FlatDir(victim.transform.forward);
			}
			if (lhs.sqrMagnitude < 0.5f)
			{
				return false;
			}
			return Vector3.Dot(lhs, rhs) > 0.32f;
		}

		private static Vector3 MorphFaceFlat(PlayerProfile p)
		{
			Transform transform = MorphVisOf(p);
			if (transform == null)
			{
				return Vector3.zero;
			}
			return FlatDir(transform.forward);
		}

		private static Transform MorphVisOf(PlayerProfile p)
		{
			if (p == null)
			{
				return null;
			}
			string text = Key(p);
			GameObject value;
			if (!string.IsNullOrEmpty(text) && MorphClone.TryGetValue(text, out value) && value != null)
			{
				return value.transform;
			}
			Acc acc = Ensure(p);
			if (acc != null && !string.IsNullOrEmpty(acc.id) && MorphClone.TryGetValue(acc.id, out value) && value != null)
			{
				return value.transform;
			}
			return null;
		}

