			if (p == LocalProfile() && LocalMorphed())
			{
				return true;
			}
			if (MorphVisOf(p) != null)
			{
				return true;
			}
			string text = Key(p);
			float value;
			if (!string.IsNullOrEmpty(text) && ViewMorphUntil.TryGetValue(text, out value) && value > Time.unscaledTime)
			{
				return true;
			}
			Acc acc = Ensure(p);
			if (acc != null && ServerMorphed(acc.id))
			{
				return true;
			}
			return false;
		}

