		private static float StealSkillCoolLeft()
		{
			float unscaledTime = Time.unscaledTime;
			float num = 0f;
			if (StealCoolUntil > unscaledTime + 0.02f)
			{
				num = StealCoolUntil - unscaledTime;
			}
			if (_stealCdRole == 1 && _stealCdUntil > unscaledTime + 0.02f)
			{
				float num2 = _stealCdUntil - unscaledTime;
				if (num2 > num)
				{
					num = num2;
