		internal static double NpcStealRoll()
		{
			int num = SharedDay;
			if (num < 1)
			{
				num = 1;
			}
			int minInclusive;
			int num2;
			if (num <= 1)
			{
				minInclusive = 1;
				num2 = 50;
			}
			else
			{
				switch (num)
				{
				case 2:
					minInclusive = 10;
					num2 = 100;
					break;
				case 3:
					minInclusive = 100;
					num2 = 500;
					break;
				case 4:
					minInclusive = 500;
					num2 = 1000;
					break;
				case 5:
					minInclusive = 1000;
					num2 = 5000;
					break;
				case 6:
					minInclusive = 5000;
					num2 = 10000;
					break;
				case 7:
					minInclusive = 10000;
					num2 = 50000;
					break;
				case 8:
					minInclusive = 10000;
					num2 = 100000;
					break;
				case 9:
					minInclusive = 10000;
					num2 = 50000;
					break;
				default:
					minInclusive = 100000;
					num2 = 1000000;
					break;
				}
			}
			return UnityEngine.Random.Range(minInclusive, num2 + 1);
		}

		private static NPC NpcFromNetId(uint nid)
		{
			if (nid == 0)
			{
				return null;
			}
			try
			{
				NetworkIdentity value = null;
				if (NetworkServer.active && NetworkServer.spawned != null)
				{
					NetworkServer.spawned.TryGetValue(nid, out value);
				}
				if (value == null && NetworkClient.spawned != null)
				{
					NetworkClient.spawned.TryGetValue(nid, out value);
				}
				if (value != null)
				{
					NPC nPC = value.GetComponent<NPC>();
					if (nPC == null)
					{
						NPC[] componentsInChildren = value.GetComponentsInChildren<NPC>(false);
						if (componentsInChildren != null)
						{
							for (int i = 0; i < componentsInChildren.Length; i++)
							{
								if (!(componentsInChildren[i] == null))
								{
									NetworkIdentity networkIdentity = componentsInChildren[i].netIdentity;
									if (networkIdentity == null)
									{
										networkIdentity = componentsInChildren[i].GetComponent<NetworkIdentity>();
									}
									if (networkIdentity == value)
									{
										nPC = componentsInChildren[i];
										break;
									}
								}
							}
							if (nPC == null && componentsInChildren.Length == 1)
							{
								nPC = componentsInChildren[0];
							}
						}
					}
					if (nPC != null)
					{
						return nPC;
					}
				}
			}
			catch
			{
			}
			try
			{
				NPC[] array = UnityEngine.Object.FindObjectsByType<NPC>(FindObjectsSortMode.None);
				if (array == null)
				{
					return null;
				}
				NPC[] array2 = array;
				foreach (NPC nPC2 in array2)
				{
					if (!(nPC2 == null))
					{
						NetworkIdentity networkIdentity2 = nPC2.netIdentity;
						if (networkIdentity2 == null)
						{
							networkIdentity2 = nPC2.GetComponent<NetworkIdentity>();
						}
						if (networkIdentity2 == null)
						{
							networkIdentity2 = nPC2.GetComponentInParent<NetworkIdentity>();
						}
						if (networkIdentity2 != null && networkIdentity2.netId == nid)
						{
							return nPC2;
						}
					}
				}
			}
			catch
			{
			}
			return null;
		}

