		public static NPC HoveredNpc(Camera cam, PlayerProfile me)
		{
			if (cam == null)
			{
				return null;
			}
			Vector3 origin = cam.transform.position + cam.transform.forward * 0.08f;
			Vector3 forward = cam.transform.forward;
			RaycastHit[] array = null;
			try
			{
				array = Physics.SphereCastAll(origin, 0.62f, forward, 12f, -5, QueryTriggerInteraction.Ignore);
			}
			catch
			{
				return null;
			}
			if (array == null || array.Length == 0)
			{
				return null;
			}
			Transform transform = null;
			try
			{
				if (me != null)
				{
					transform = me.transform;
				}
			}
			catch
			{
			}
			float num = 99f;
			NPC result = null;
			for (int i = 0; i < array.Length; i++)
			{
				Collider collider = array[i].collider;
				if (collider == null)
				{
					continue;
				}
				Transform transform2 = collider.transform;
				if (transform != null)
				{
					try
					{
						if (transform2 == transform || transform2.IsChildOf(transform))
						{
							continue;
						}
						goto IL_00db;
					}
					catch
					{
						goto IL_00db;
					}
				}
				goto IL_00db;
				IL_00db:
				NPC nPC = null;
				try
				{
					nPC = collider.GetComponentInParent<NPC>();
				}
				catch
				{
				}
				if (nPC == null)
				{
					continue;
				}
				try
				{
					if (nPC.GetComponentInParent<PlayerProfile>() != null)
					{
						continue;
					}
				}
				catch
				{
				}
				if (array[i].distance < num)
				{
					num = array[i].distance;
					result = nPC;
				}
			}
			return result;
		}

