		internal static void ApplyNpcMark(uint nid, float delay, float last)
		{
			if (nid == 0)
			{
				NpcMarkShow.Clear();
				NpcMarkUntil.Clear();
				_npcMarkNet = 0u;
				_npcMarkShowAt = 0f;
				_npcMarkUntil = 0f;
			}
			else if (last <= 0.01f)
			{
				NpcMarkShow.Remove(nid);
				NpcMarkUntil.Remove(nid);
				if (_npcMarkNet == nid)
				{
					_npcMarkNet = 0u;
					_npcMarkShowAt = 0f;
					_npcMarkUntil = 0f;
				}
			}
			else
			{
				NpcMarkShow[nid] = Time.unscaledTime + delay;
				NpcMarkUntil[nid] = Time.unscaledTime + last;
				_npcMarkNet = nid;
				_npcMarkShowAt = Time.unscaledTime + delay;
				_npcMarkUntil = Time.unscaledTime + last;
			}
		}

		private static void BroadcastNpcMark(uint nid, float delay, float last)
		{
			ApplyNpcMark(nid, delay, last);
			if (!NetworkServer.active)
			{
				return;
			}
			string json = "NPCMK\t" + nid.ToString(CultureInfo.InvariantCulture) + "\t" + delay.ToString("R", CultureInfo.InvariantCulture) + "\t" + last.ToString("R", CultureInfo.InvariantCulture);
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value != null && (!(value.identity != null) || !value.identity.isLocalPlayer))
					{
						value.Send(new SoloMsg
						{
							json = json
						});
					}
				}
			}
			catch
			{
			}
		}

