		private static bool LocalMorphed()
		{
			if (LocalMorphUntil > Time.unscaledTime + 0.02f)
			{
				return true;
			}
			PlayerProfile playerProfile = LocalProfile();
			if (playerProfile == null)
			{
				return false;
			}
			string text = Key(playerProfile);
			float value;
			if (!string.IsNullOrEmpty(text) && ViewMorphUntil.TryGetValue(text, out value) && value > Time.unscaledTime + 0.02f)
			{
				return true;
			}
			Acc acc = Ensure(playerProfile);
			if (acc != null)
			{
				if (!string.IsNullOrEmpty(acc.id) && acc.id != text && ViewMorphUntil.TryGetValue(acc.id, out value) && value > Time.unscaledTime + 0.02f)
				{
					return true;
				}
				if (ServerMorphed(acc.id) || ServerMorphed(text))
				{
					return true;
				}
			}
			return false;
		}

