		private static string LookalikeName(string real)
		{
			if (string.IsNullOrEmpty(real))
			{
				return real;
			}
			string text = real.Trim();
			if (text == "七七")
			{
				return "七八";
			}
			if (text == "豆瓣酱")
			{
				return "黄豆酱";
			}
			if (string.Equals(text, "mingyu", StringComparison.OrdinalIgnoreCase))
			{
				return "mingyue";
			}
			switch (text)
			{
			case "吉他和舞鞋":
				return "吉他和拖鞋";
			case "望舒":
				return "舒望";
			case "2 2":
				return "2 3";
			default:
			{
				int length = text.Length;
				if (length == 2 && text[0] == text[1])
				{
					char c = BumpChar(text[1]);
					if (c != text[1])
					{
						return text[0].ToString() + c;
					}
				}
				if (length == 2 && text[0] > '\u007f' && text[1] > '\u007f' && text[0] != text[1])
				{
					return text[1].ToString() + text[0];
				}
				int num = -1;
				for (int num2 = text.Length - 1; num2 >= 0; num2--)
				{
					if (text[num2] >= '0' && text[num2] <= '9')
					{
						num = num2;
						break;
					}
				}
				if (num >= 0)
				{
					char c2 = text[num];
					if (c2 >= '0' && c2 < '9')
					{
						return text.Substring(0, num) + (char)(c2 + 1) + text.Substring(num + 1);
					}
				}
				if (length >= 2 && text.EndsWith("yu", StringComparison.OrdinalIgnoreCase))
				{
					return text + "e";
				}
				if (length >= 4 && text.EndsWith("舞鞋"))
				{
					return text.Substring(0, length - 2) + "拖鞋";
				}
				return text;
			}
			}
		}

		private static char BumpChar(char c)
		{
			switch (c)
			{
			case '一':
				return '二';
			case '二':
				return '三';
			case '三':
				return '四';
			case '四':
				return '五';
			case '五':
				return '六';
			case '六':
				return '七';
			case '七':
				return '八';
			case '八':
				return '九';
			case '九':
				return '十';
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
				return (char)(c + 1);
			default:
				return c;
			}
		}

		private static void SetDisguiseName(PlayerProfile p, string key, string fake)
		{
			if (p == null || string.IsNullOrEmpty(key) || string.IsNullOrEmpty(fake))
			{
				return;
			}
			object obj = NameLabelOf(p);
			Component component = obj as Component;
			if (component != null && component.gameObject != null && !component.gameObject.activeSelf)
			{
				component.gameObject.SetActive(true);
			}
			string text = ReadCompText(obj);
			string value;
			if (!MorphTrueName.TryGetValue(key, out value) || string.IsNullOrEmpty(value))
			{
				if (!string.IsNullOrEmpty(text) && text != fake)
				{
					MorphTrueName[key] = text;
				}
				else if (!string.IsNullOrEmpty(p.playerName))
				{
					MorphTrueName[key] = p.playerName;
				}
			}
			MorphFakeName[key] = fake;
			WriteCompText(obj, fake);
		}

