			Component component = lab as Component;
			if (component == null || component.transform == null)
			{
				return;
			}
			int instanceID;
			try
			{
				instanceID = component.GetInstanceID();
			}
			catch
			{
				return;
			}
			RectTransform rectTransform = component as RectTransform;
			if (rectTransform == null)
			{
				try
				{
					rectTransform = component.GetComponent<RectTransform>();
				}
				catch
				{
					rectTransform = null;
				}
			}
			if (rectTransform != null)
			{
				Vector2 anchoredPosition = rectTransform.anchoredPosition;
				Vector2 value;
				if (!NameLabAnch.TryGetValue(instanceID, out value) || !((anchoredPosition - value).sqrMagnitude < 0.0001f))
				{
					Vector2 vector = (rectTransform.anchoredPosition = new Vector2(anchoredPosition.x, anchoredPosition.y + 15f));
					Vector2 value2 = vector;
					NameLabAnch[instanceID] = value2;
				}
				return;
			}
			Camera main = Camera.main;
			if (main == null)
			{
				return;
			}
			Transform transform = component.transform;
			Vector3 position = transform.position;
			Vector3 value3;
			if (!NameLabWorld.TryGetValue(instanceID, out value3) || !((position - value3).sqrMagnitude < 1E-12f))
			{
				Vector3 position2 = main.WorldToScreenPoint(position);
				if (!(position2.z < 0.1f))
				{
					position2.y += 15f;
					Vector3 vector3 = (transform.position = main.ScreenToWorldPoint(position2));
					Vector3 value4 = vector3;
					NameLabWorld[instanceID] = value4;
				}
			}
		}

