		private static int EquippedCount(PlayerCustomization c)
		{
			int num = 0;
			Dictionary<CosmeticType, int> dictionary = EquippedOf(c);
			if (dictionary != null)
			{
				foreach (KeyValuePair<CosmeticType, int> item in dictionary)
				{
					if (item.Value >= 0)
					{
						num++;
					}
				}
			}
			for (int i = 0; i < 7; i++)
			{
				if (MeshOfFilter(SlotFilter(c, i)) != null)
				{
					num += 2;
				}
			}
			return num;
		}

