		private static MeshFilter SlotFilter(PlayerCustomization c, int slot)
		{
			if (c == null || slot < 0 || slot > 6)
			{
				return null;
			}
			try
			{
				if (_slotFf == null)
				{
					_slotFf = new FieldInfo[7];
					_slotFf[0] = AccessTools.Field(typeof(PlayerCustomization), "hat");
					_slotFf[1] = AccessTools.Field(typeof(PlayerCustomization), "hair");
					_slotFf[2] = AccessTools.Field(typeof(PlayerCustomization), "mustache");
					_slotFf[3] = AccessTools.Field(typeof(PlayerCustomization), "beard");
					_slotFf[4] = AccessTools.Field(typeof(PlayerCustomization), "neckwear");
					_slotFf[5] = AccessTools.Field(typeof(PlayerCustomization), "clothing");
					_slotFf[6] = AccessTools.Field(typeof(PlayerCustomization), "facewear");
				}
				if (_slotFf[slot] == null)
				{
					return null;
				}
				return _slotFf[slot].GetValue(c) as MeshFilter;
			}
			catch
			{
				return null;
			}
		}

		private static void SnapshotLookMeshes(PlayerProfile p, string key)
		{
			if (p == null || string.IsNullOrEmpty(key) || MorphMeshOrig.ContainsKey(key))
			{
				return;
			}
			PlayerCustomization playerCustomization = CustOf(p);
			if (playerCustomization == null)
			{
				return;
			}
			Mesh[] array = new Mesh[7];
			Material[] array2 = new Material[7];
			bool[] array3 = new bool[7];
			for (int i = 0; i < 7; i++)
			{
				MeshFilter meshFilter = SlotFilter(playerCustomization, i);
				if (!(meshFilter == null))
				{
					array[i] = MeshOfFilter(meshFilter);
					Renderer component = meshFilter.GetComponent<Renderer>();
					if (!(component == null))
					{
						array2[i] = component.sharedMaterial;
						array3[i] = component.enabled;
					}
				}
			}
			MorphMeshOrig[key] = array;
			MorphMatOrig[key] = array2;
			MorphSlotOn[key] = array3;
			MorphLookOrig[key] = CaptureLook(p);
			string text = Key(p);
			if (!string.IsNullOrEmpty(text) && text != key)
			{
				MorphMeshOrig[text] = array;
				MorphMatOrig[text] = array2;
				MorphSlotOn[text] = array3;
				if (!MorphLookOrig.ContainsKey(text))
				{
					MorphLookOrig[text] = MorphLookOrig[key];
				}
			}
			Acc acc = Ensure(p);
			if (acc != null && !string.IsNullOrEmpty(acc.id) && acc.id != key)
			{
				MorphMeshOrig[acc.id] = array;
				MorphMatOrig[acc.id] = array2;
				MorphSlotOn[acc.id] = array3;
				if (!MorphLookOrig.ContainsKey(acc.id))
				{
					MorphLookOrig[acc.id] = MorphLookOrig[key];
				}
			}
		}

