		private static bool SlotNameHits(int slot, string n)
		{
			if (string.IsNullOrEmpty(n) || slot < 0 || slot > 6)
			{
				return false;
			}
			string[][] array = new string[7][]
			{
				new string[2] { "Hat", "Cap" },
				new string[1] { "Hair" },
				new string[4] { "Mustache", "Moustache", "Stache", "胡子" },
				new string[4] { "Beard", "Sideburn", "Goatee", "络腮" },
				new string[3] { "Neckwear", "Neck", "Scarf" },
				new string[4] { "Clothing", "Clothes", "Shirt", "Outfit" },
				new string[3] { "Facewear", "Glasses", "Goggle" }
			};
			string[] array2 = array[slot];
			bool flag = false;
			for (int i = 0; i < array2.Length; i++)
			{
				if (n.IndexOf(array2[i], StringComparison.OrdinalIgnoreCase) >= 0)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				return false;
			}
			if (slot == 1 && n.IndexOf("Hat", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				return false;
			}
			if (slot == 2 && n.IndexOf("Beard", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				return false;
			}
			return true;
		}

