		private static bool ReadSlotVisual(PlayerCustomization c, PlayerProfile p, int slot, out Mesh mesh, out Material mat, out bool on)
		{
			mesh = null;
			mat = null;
			on = false;
			MeshFilter meshFilter = SlotFilter(c, slot);
			if (meshFilter != null)
			{
				mesh = MeshOfFilter(meshFilter);
				Renderer renderer = meshFilter.GetComponent<Renderer>();
				if (renderer == null)
				{
					renderer = meshFilter.GetComponent<MeshRenderer>();
				}
				if (renderer == null)
				{
					renderer = meshFilter.GetComponent<SkinnedMeshRenderer>();
				}
				if (renderer == null)
				{
					renderer = meshFilter.GetComponentInChildren<Renderer>(true);
				}
				if (renderer != null)
				{
					mat = renderer.sharedMaterial;
					on = renderer.enabled;
				}
				if (mesh != null)
				{
					return true;
				}
				SkinnedMeshRenderer skinnedMeshRenderer = meshFilter.GetComponent<SkinnedMeshRenderer>();
				if (skinnedMeshRenderer == null)
				{
					skinnedMeshRenderer = meshFilter.GetComponentInChildren<SkinnedMeshRenderer>(true);
				}
				if (skinnedMeshRenderer != null && skinnedMeshRenderer.sharedMesh != null)
				{
					mesh = skinnedMeshRenderer.sharedMesh;
					mat = skinnedMeshRenderer.sharedMaterial;
					on = skinnedMeshRenderer.enabled;
					return true;
				}
			}
			if (p == null || p.transform == null)
			{
				return false;
			}
			try
			{
				Transform[] componentsInChildren = p.GetComponentsInChildren<Transform>(true);
				if (componentsInChildren == null)
				{
					return false;
				}
				Mesh mesh2 = null;
				Material material = null;
				bool flag = false;
				int num = -1;
				Transform[] array = componentsInChildren;
				foreach (Transform transform in array)
				{
					if (transform == null || !SlotNameHits(slot, transform.name ?? ""))
					{
						continue;
					}
					MeshFilter component = transform.GetComponent<MeshFilter>();
					Mesh mesh3 = MeshOfFilter(component);
					Material material2 = null;
					bool flag2 = true;
					if (mesh3 == null)
					{
						SkinnedMeshRenderer component2 = transform.GetComponent<SkinnedMeshRenderer>();
						if (component2 != null && component2.sharedMesh != null)
						{
							mesh3 = component2.sharedMesh;
							material2 = component2.sharedMaterial;
							flag2 = component2.enabled;
						}
					}
					else
					{
						Renderer renderer2 = transform.GetComponent<Renderer>();
						if (renderer2 == null)
						{
							renderer2 = transform.GetComponentInChildren<Renderer>(true);
						}
						if (renderer2 != null)
						{
							material2 = renderer2.sharedMaterial;
							flag2 = renderer2.enabled;
						}
					}
					if (!(mesh3 == null))
					{
						int num2 = 0;
						try
						{
							num2 = mesh3.vertexCount;
						}
						catch
						{
						}
						if (num2 > num)
						{
							num = num2;
							mesh2 = mesh3;
							material = material2;
							flag = flag2;
						}
					}
				}
				if (mesh2 != null)
				{
					mesh = mesh2;
					mat = material;
					on = flag;
					return true;
				}
			}
			catch
			{
			}
			return false;
		}

