		private static void WriteSlotVisual(PlayerProfile p, PlayerCustomization c, int slot, Mesh mesh, Material mat, bool on)
		{
			MeshFilter meshFilter = SlotFilter(c, slot);
			WriteSlot(meshFilter, mesh, mat, on);
			if (meshFilter != null)
			{
				Renderer[] componentsInChildren = meshFilter.GetComponentsInChildren<Renderer>(true);
				if (componentsInChildren != null)
				{
					for (int i = 0; i < componentsInChildren.Length; i++)
					{
						MeshFilter meshFilter2 = ((componentsInChildren[i] != null) ? componentsInChildren[i].GetComponent<MeshFilter>() : null);
						ApplyRendererLook(componentsInChildren[i], (meshFilter2 != null) ? meshFilter2 : meshFilter, mesh, mat, on);
					}
				}
			}
			if (p == null || p.transform == null || mesh == null || slot < 0 || slot > 6)
			{
				return;
			}
			try
			{
				Transform[] componentsInChildren2 = p.GetComponentsInChildren<Transform>(true);
				if (componentsInChildren2 == null)
				{
					return;
				}
				Transform[] array = componentsInChildren2;
				foreach (Transform transform in array)
				{
					if (!(transform == null) && SlotNameHits(slot, transform.name ?? ""))
					{
						MeshFilter component = transform.GetComponent<MeshFilter>();
						Renderer renderer = transform.GetComponent<Renderer>();
						if (renderer == null)
						{
							renderer = transform.GetComponentInChildren<Renderer>(true);
						}
						ApplyRendererLook(renderer, component, mesh, mat, on);
					}
				}
			}
			catch
			{
			}
		}

