				}
				Renderer renderer = mf.GetComponent<Renderer>();
				if (renderer == null)
				{
					renderer = mf.GetComponentInChildren<Renderer>(true);
				}
				ApplyRendererLook(renderer, mf, mesh, mat, on);
			}
		}

		private static void HideEmptyMorphSlots(PlayerProfile p, int[] ids, bool[] copied)
		{
			if (p == null || ids == null)
			{
				return;
			}
			PlayerCustomization[] array = CustsOf(p);
			bool flag = p == LocalProfile();
			for (int i = 0; i < 7 && i < ids.Length; i++)
			{
				if (ids[i] >= 0 || (copied != null && i < copied.Length && copied[i]))
				{
					continue;
				}
				for (int j = 0; j < array.Length; j++)
				{
					HideSlotVisual(p, array[j], i);
				}
				if (!flag)
				{
					continue;
				}
				try
				{
					if (_cmdClearM == null)
					{
						_cmdClearM = AccessTools.Method(typeof(PlayerCustomization), "CmdClearCategory");
					}
					PlayerCustomization playerCustomization = null;
					for (int k = 0; k < array.Length; k++)
					{
						if (array[k] != null && array[k].isLocalPlayer)
						{
							playerCustomization = array[k];
							break;
						}
					}
					if (playerCustomization == null && array.Length > 0)
					{
						playerCustomization = array[0];
					}
					if (playerCustomization != null && _cmdClearM != null)
					{
						MorphSkipCosSave = true;
						try
						{
							_cmdClearM.Invoke(playerCustomization, new object[1] { (CosmeticType)i });
						}
						finally
						{
							MorphSkipCosSave = false;
						}
					}
				}
				catch
				{
					MorphSkipCosSave = false;
				}
			}
		}

