		private static bool ReplicaSlotAgrees(PlayerCustomization c, int slot, int wantId)
		{
			if (wantId < 0)
			{
				return true;
			}
			Dictionary<CosmeticType, int> dictionary = EquippedOf(c);
			if (dictionary == null)
			{
				return false;
			}
			int value;
			try
			{
				if (!dictionary.TryGetValue((CosmeticType)slot, out value))
				{
					return false;
				}
			}
			catch
			{
				return false;
			}
			return value == wantId;
		}

		private static bool CopyLookMeshes(PlayerProfile fromP, PlayerProfile toP, int[] ids, bool[] copied)
		{
			PlayerCustomization[] array = CustsOf(fromP);
			PlayerCustomization[] array2 = CustsOf(toP);
			if (array == null || array.Length == 0 || array2 == null || array2.Length == 0)
			{
				return false;
			}
			bool result = false;
			for (int i = 0; i < 7; i++)
			{
				int num = ((ids != null && i < ids.Length) ? ids[i] : (-1));
				Mesh mesh = null;
				Material mat = null;
				bool flag = false;
				bool flag2 = false;
				for (int j = 0; j < array.Length; j++)
				{
					Mesh mesh2;
					Material mat2;
					bool on;
					if (!ReadSlotVisual(array[j], fromP, i, out mesh2, out mat2, out on) || mesh2 == null || (!on && num < 0))
					{
						continue;
					}
					if (num >= 0)
					{
						int num2 = MeshToCosmeticId(mesh2);
						if (num2 >= 0 && num2 != num)
						{
							continue;
						}
					}
					mesh = mesh2;
					mat = mat2;
					flag = on;
					flag2 = true;
					break;
				}
				if (flag2)
				{
					if (copied != null && i < copied.Length)
					{
						copied[i] = true;
					}
					for (int k = 0; k < array2.Length; k++)
					{
						WriteSlotVisual(toP, array2[k], i, mesh, mat, flag);
					}
					result = true;
				}
			}
			return result;
		}

		private static int MeshToCosmeticId(Mesh mesh)
		{
			if (mesh == null)
			{
				return -1;
			}
			try
			{
				foreach (CosmeticData allCosmetic in CosmeticDataManager.GetAllCosmetics())
				{
					if (allCosmetic == null || allCosmetic.cosmeticModel == null)
					{
						continue;
					}
					MeshFilter[] componentsInChildren = allCosmetic.cosmeticModel.GetComponentsInChildren<MeshFilter>(true);
					if (componentsInChildren != null)
					{
						for (int i = 0; i < componentsInChildren.Length; i++)
						{
							Mesh mesh2 = MeshOfFilter(componentsInChildren[i]);
							if (mesh2 != null && mesh2 == mesh)
							{
								return allCosmetic.cosmeticId;
							}
						}
					}
					SkinnedMeshRenderer[] componentsInChildren2 = allCosmetic.cosmeticModel.GetComponentsInChildren<SkinnedMeshRenderer>(true);
					if (componentsInChildren2 == null)
					{
						continue;
					}
					for (int j = 0; j < componentsInChildren2.Length; j++)
					{
						if (componentsInChildren2[j] != null && componentsInChildren2[j].sharedMesh != null && componentsInChildren2[j].sharedMesh == mesh)
						{
							return allCosmetic.cosmeticId;
						}
					}
				}
			}
			catch
			{
			}
			return -1;
		}

		private static void RestoreLookMeshes(PlayerProfile p, string key)
		{
			if (p == null || string.IsNullOrEmpty(key))
			{
				return;
			}
			Mesh[] value = null;
			MorphMeshOrig.TryGetValue(key, out value);
			if (value == null && p != null)
			{
				string text = Key(p);
				if (!string.IsNullOrEmpty(text))
				{
					MorphMeshOrig.TryGetValue(text, out value);
				}
			}
			Material[] value2;
			MorphMatOrig.TryGetValue(key, out value2);
			bool[] value3;
			MorphSlotOn.TryGetValue(key, out value3);
			if (value != null)
			{
				PlayerCustomization[] array = CustsOf(p);
				if (array != null)
				{
					PlayerCustomization[] array2 = array;
					foreach (PlayerCustomization playerCustomization in array2)
					{
						if (playerCustomization == null)
						{
							continue;
						}
						for (int j = 0; j < 7; j++)
						{
							MeshFilter mf = SlotFilter(playerCustomization, j);
							Material mat = ((value2 != null && j < value2.Length) ? value2[j] : null);
							bool flag = ((value3 != null && j < value3.Length) ? value3[j] : (value[j] != null));
							RestoreSlot(mf, value[j], mat, flag);
							if (!flag)
							{
								HideSlotVisual(p, playerCustomization, j);
							}
						}
					}
				}
			}
			MorphMeshOrig.Remove(key);
			MorphMatOrig.Remove(key);
			MorphSlotOn.Remove(key);
			ClearExtraTint(p);
			ClearMorphTint(p, key);
			string value4;
			if (MorphLookOrig.TryGetValue(key, out value4))
			{
				MorphLookOrig.Remove(key);
				int[] ids = new int[7];
				Color col;
				if (ParseLook(value4, out col, ids))
				{
					ApplyIdsLocal(p, ids);
					HideEmptyMorphSlots(p, ids, null);
				}
			}
			try
			{
				if (!(p != null))
				{
					return;
				}
				UIColorManager[] componentsInChildren = p.GetComponentsInChildren<UIColorManager>(true);
				if (componentsInChildren == null)
				{
					return;
				}
				for (int k = 0; k < componentsInChildren.Length; k++)
				{
					if (componentsInChildren[k] != null)
					{
						componentsInChildren[k].ApplyColors();
					}
				}
			}
			catch
			{
			}
		}

