		private static Color ReadPlayerColor(PlayerProfile p)
		{
			Color result = new Color(0f, 0f, 0f, 0f);
			string text = "";
			ulong num = SteamOf(p, null);
			try
			{
				if (num == 0 && p != null)
				{
					num = p.steamId;
				}
			}
			catch
			{
			}
			try
			{
				if (p != null)
				{
					text = p.playerName ?? "";
				}
			}
			catch
			{
			}
			try
			{
				LobbySettings lobbySettings = CachedLobby();
				if (lobbySettings != null && lobbySettings.players != null)
				{
					for (int i = 0; i < lobbySettings.players.Count; i++)
					{
						PlayerInfo playerInfo = lobbySettings.players[i];
						if (playerInfo != null)
						{
							if (num != 0 && playerInfo.steamId == num)
							{
								return playerInfo.playerColor;
							}
							if (!string.IsNullOrEmpty(text) && playerInfo.playerName == text)
							{
								return playerInfo.playerColor;
							}
						}
					}
				}
			}
			catch
			{
			}
			Color result2 = SampleBodyColor(p);
			if (result2.a > 0.2f && result2.r + result2.g + result2.b > 0.12f)
			{
				return result2;
			}
			return result;
		}

		private static SkinnedMeshRenderer MainBodySkin(PlayerProfile p)
		{
			if (p == null || p.transform == null)
			{
				return null;
			}
			SkinnedMeshRenderer result = null;
			int num = 0;
			try
			{
				SkinnedMeshRenderer[] componentsInChildren = p.GetComponentsInChildren<SkinnedMeshRenderer>(false);
				if (componentsInChildren == null)
				{
					return null;
				}
				SkinnedMeshRenderer[] array = componentsInChildren;
				foreach (SkinnedMeshRenderer skinnedMeshRenderer in array)
				{
					if (skinnedMeshRenderer == null || skinnedMeshRenderer.sharedMesh == null || !skinnedMeshRenderer.enabled || !skinnedMeshRenderer.gameObject.activeInHierarchy)
					{
						continue;
					}
					string text = skinnedMeshRenderer.gameObject.name ?? "";
					if (text.IndexOf("Hat", StringComparison.OrdinalIgnoreCase) < 0 && text.IndexOf("Hair", StringComparison.OrdinalIgnoreCase) < 0 && text.IndexOf("Mustache", StringComparison.OrdinalIgnoreCase) < 0 && text.IndexOf("Beard", StringComparison.OrdinalIgnoreCase) < 0 && text.IndexOf("Arm", StringComparison.OrdinalIgnoreCase) < 0 && text.IndexOf("Hand", StringComparison.OrdinalIgnoreCase) < 0)
					{
						int vertexCount = skinnedMeshRenderer.sharedMesh.vertexCount;
						if (vertexCount > num)
						{
							num = vertexCount;
							result = skinnedMeshRenderer;
						}
					}
				}
			}
			catch
			{
			}
			return result;
		}

		private static Color SampleBodyColor(PlayerProfile p)
		{
			Color result = new Color(0f, 0f, 0f, 0f);
			try
			{
				SkinnedMeshRenderer skinnedMeshRenderer = MainBodySkin(p);
				if (skinnedMeshRenderer == null)
				{
					return result;
				}
				MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
				skinnedMeshRenderer.GetPropertyBlock(materialPropertyBlock);
				if (materialPropertyBlock != null)
				{
					Color result2 = ReadBlockColor(materialPropertyBlock);
					if (result2.a > 0.2f && result2.r + result2.g + result2.b > 0.12f)
					{
						return result2;
					}
				}
				Material sharedMaterial = skinnedMeshRenderer.sharedMaterial;
				if (sharedMaterial == null)
				{
					return result;
				}
				if (sharedMaterial.HasProperty("_Tint"))
				{
					return sharedMaterial.GetColor("_Tint");
				}
				if (sharedMaterial.HasProperty("_Color"))
				{
					return sharedMaterial.GetColor("_Color");
				}
				if (sharedMaterial.HasProperty("_BaseColor"))
				{
					return sharedMaterial.GetColor("_BaseColor");
				}
			}
			catch
			{
			}
			return result;
		}

		private static Color CaptureLiveColor(PlayerProfile p)
		{
			Color color = ReadPlayerColor(p);
			if (ColorUsable(color) && !ColorIsBlankGlow(color))
			{
				return color;
			}
			Color color2 = new Color(0f, 0f, 0f, 0f);
			try
			{
				UIColorManager uIColorManager = null;
				if (p != null)
				{
					uIColorManager = p.GetComponent<UIColorManager>();
				}
				if (uIColorManager == null && p != null)
				{
					uIColorManager = p.GetComponentInChildren<UIColorManager>();
				}
				if (uIColorManager == null && p != null)
				{
					uIColorManager = p.GetComponentInParent<UIColorManager>();
				}
				if (uIColorManager != null)
				{
					if (_getColM == null)
					{
						_getColM = AccessTools.Method(typeof(UIColorManager), "GetPlayerColor");
					}
					if (_getColM != null)
					{
						color2 = (Color)_getColM.Invoke(uIColorManager, null);
					}
				}
			}
			catch
			{
			}
			if (ColorUsable(color2) && !ColorIsBlankGlow(color2))
			{
				return color2;
			}
			color2 = SampleBodyColor(p);
			if (ColorUsable(color2) && !ColorIsBlankGlow(color2))
			{
				return color2;
			}
			if (ColorUsable(color))
			{
				return color;
			}
			return new Color(0f, 0f, 0f, 0f);
		}

		private static bool ColorUsable(Color col)
		{
			if (col.a > 0.2f)
			{
				return col.r + col.g + col.b > 0.12f;
			}
			return false;
		}

		private static bool ColorIsBlankGlow(Color col)
		{
			if (col.r > 0.92f && col.g > 0.92f)
			{
				return col.b > 0.92f;
			}
			return false;
		}

		private static ulong SteamOf(PlayerProfile p, UIColorManager um)
		{
			try
			{
				if (p != null && p.steamId != 0)
				{
					return p.steamId;
				}
			}
			catch
			{
			}
			try
			{
				SteamIdComponent component = null;
				if (um != null)
				{
					um.TryGetComponent<SteamIdComponent>(out component);
				}
				if (component == null && p != null)
				{
					p.TryGetComponent<SteamIdComponent>(out component);
				}
				if (component == null && p != null)
				{
					component = p.GetComponentInChildren<SteamIdComponent>();
				}
				if (component == null && p != null)
				{
					component = p.GetComponentInParent<SteamIdComponent>();
				}
				if (component != null)
				{
					return component.SteamId;
				}
			}
			catch
			{
			}
			return 0uL;
		}

		private static void RememberMorphTint(PlayerProfile p, string extra, Color col)
		{
			if (!ColorUsable(col) || ColorIsBlankGlow(col))
			{
				return;
			}
			if (p != null && p == LocalProfile())
			{
				LocalMorphPaint = col;
				LocalMorphPaintOn = true;
			}
			if (p != null)
			{
				string text = Key(p);
				if (!string.IsNullOrEmpty(text))
				{
					MorphTint[text] = col;
				}
				ulong num = SteamOf(p, null);
				if (num != 0)
				{
					MorphTint["s" + num] = col;
				}
				if (p.steamId != 0)
				{
					MorphTint["s" + p.steamId] = col;
				}
				uint num2 = NetIdOf(p);
				if (num2 != 0)
				{
					MorphTint["n" + num2] = col;
				}
				if (!string.IsNullOrEmpty(p.playerName))
				{
					MorphTint["p" + p.playerName] = col;
				}
			}
			if (!string.IsNullOrEmpty(extra))
			{
				MorphTint[extra] = col;
			}
		}

		private static bool UmIsLocalView(UIColorManager um)
		{
			if (um == null)
			{
				return false;
			}
			try
			{
				NetworkIdentity componentInParent = um.GetComponentInParent<NetworkIdentity>();
				if (componentInParent != null && componentInParent.isLocalPlayer)
				{
					return true;
				}
			}
			catch
			{
			}
			try
			{
				Transform parent = um.transform;
				int num = 0;
				while (parent != null && num < 10)
				{
					string text = parent.name ?? "";
					if (text.IndexOf("FirstPerson", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						return true;
					}
					if (text.IndexOf("FPCam", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						return true;
					}
					if (text.IndexOf("ViewModel", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						return true;
					}
					if (text.IndexOf("Arm", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						return true;
					}
					if (text.IndexOf("Hand", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						return true;
					}
					parent = parent.parent;
					num++;
				}
			}
			catch
			{
			}
			return false;
		}

		internal static bool TryMorphTint(PlayerProfile p, UIColorManager um, out Color col)
		{
			col = Color.white;
			if (LocalMorphPaintOn && ColorUsable(LocalMorphPaint) && !ColorIsBlankGlow(LocalMorphPaint))
			{
				if (UmIsLocalView(um))
				{
					col = LocalMorphPaint;
					return true;
				}
				if (p != null && p == LocalProfile())
				{
					col = LocalMorphPaint;
					return true;
				}
			}
			if (p != null)
			{
				string text = Key(p);
				if (!string.IsNullOrEmpty(text) && MorphTint.TryGetValue(text, out col) && ColorUsable(col) && !ColorIsBlankGlow(col))
				{
					return true;
				}
				ulong num = SteamOf(p, um);
				if (num != 0 && MorphTint.TryGetValue("s" + num, out col) && ColorUsable(col) && !ColorIsBlankGlow(col))
				{
					return true;
				}
				if (p.steamId != 0 && MorphTint.TryGetValue("s" + p.steamId, out col) && ColorUsable(col) && !ColorIsBlankGlow(col))
				{
					return true;
				}
				uint num2 = NetIdOf(p);
				if (num2 != 0 && MorphTint.TryGetValue("n" + num2, out col) && ColorUsable(col) && !ColorIsBlankGlow(col))
				{
					return true;
				}
				if (!string.IsNullOrEmpty(p.playerName) && MorphTint.TryGetValue("p" + p.playerName, out col) && ColorUsable(col) && !ColorIsBlankGlow(col))
				{
					return true;
				}
			}
			try
			{
				ulong num3 = SteamOf(p, um);
				if (num3 != 0 && MorphTint.TryGetValue("s" + num3, out col) && ColorUsable(col) && !ColorIsBlankGlow(col))
				{
					return true;
				}
			}
			catch
			{
			}
			col = Color.white;
			return false;
		}

		private static void ClearMorphTint(PlayerProfile p, string extra)
		{
			if (p != null && p == LocalProfile())
			{
				LocalMorphPaintOn = false;
			}
			if (!string.IsNullOrEmpty(extra))
			{
				MorphTint.Remove(extra);
			}
			if (!(p == null))
			{
				string text = Key(p);
				if (!string.IsNullOrEmpty(text))
				{
					MorphTint.Remove(text);
				}
				ulong num = SteamOf(p, null);
				if (num != 0)
				{
					MorphTint.Remove("s" + num);
				}
				if (p.steamId != 0)
				{
					MorphTint.Remove("s" + p.steamId);
				}
				uint num2 = NetIdOf(p);
				if (num2 != 0)
				{
					MorphTint.Remove("n" + num2);
				}
				if (!string.IsNullOrEmpty(p.playerName))
				{
					MorphTint.Remove("p" + p.playerName);
				}
			}
		}

		private static string CaptureLook(PlayerProfile p)
		{
			int[] array = new int[7];
			for (int i = 0; i < 7; i++)
			{
				array[i] = -1;
			}
			Color color = CaptureLiveColor(p);
			FillIdsFrom(p, array);
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(ColorUtility.ToHtmlStringRGBA(color)).Append('|');
			for (int j = 0; j < 7; j++)
			{
				if (j > 0)
				{
					stringBuilder.Append(',');
				}
				stringBuilder.Append(array[j].ToString(CultureInfo.InvariantCulture));
			}
			return stringBuilder.ToString();
		}

		private static void FillIdsFrom(PlayerProfile p, int[] ids)
		{
			if (p == null || ids == null || ids.Length < 7)
			{
				return;
			}
			if (p == LocalProfile())
			{
				try
				{
					CosmeticsUnlockManager instance = MonoSingleton<CosmeticsUnlockManager>.Instance;
					if (instance != null)
					{
						Dictionary<CosmeticType, int> equippedCosmetics = instance.GetEquippedCosmetics();
						if (equippedCosmetics != null)
						{
							foreach (KeyValuePair<CosmeticType, int> item in equippedCosmetics)
							{
								int key = (int)item.Key;
								if (key >= 0 && key < 7 && item.Value >= 0 && ids[key] < 0)
								{
									ids[key] = item.Value;
								}
							}
						}
					}
				}
				catch
				{
				}
			}
			PlayerCustomization[] array = CustsOf(p);
			for (int i = 0; i < array.Length; i++)
			{
				try
				{
					Dictionary<CosmeticType, int> dictionary = EquippedOf(array[i]);
					if (dictionary == null)
					{
						continue;
					}
					foreach (KeyValuePair<CosmeticType, int> item2 in dictionary)
					{
						int key2 = (int)item2.Key;
						Mesh mesh;
						Material mat;
						bool on;
						if (key2 >= 0 && key2 < 7 && item2.Value >= 0 && ids[key2] < 0 && ReadSlotVisual(array[i], p, key2, out mesh, out mat, out on) && on)
						{
							ids[key2] = item2.Value;
						}
					}
				}
				catch
				{
				}
			}
			PlayerCustomization c = CustOf(p);
			for (int j = 0; j < 7; j++)
			{
				Mesh mesh2;
				Material mat2;
				bool on2;
				if (ids[j] < 0 && ReadSlotVisual(c, p, j, out mesh2, out mat2, out on2) && !(mesh2 == null) && on2)
				{
					int num = MeshToCosmeticId(mesh2);
					if (num >= 0)
					{
						ids[j] = num;
					}
				}
			}
		}

		private static int ApplyIdsLocal(PlayerProfile p, int[] ids)
		{
			return ApplyIdsLocal(p, ids, null);
		}

		private static int ApplyIdsLocal(PlayerProfile p, int[] ids, bool[] skipSlot)
		{
			if (p == null || ids == null)
			{
				return 0;
			}
			PlayerCustomization[] array = CustsOf(p);
			if (array == null || array.Length == 0)
			{
				return 0;
