		private static bool StampCosmeticOntoSlot(PlayerProfile p, PlayerCustomization c, CosmeticData d, int id)
		{
			if (c == null || d == null)
			{
				return false;
			}
			MeshFilter meshFilter = null;
			try
			{
				if (_slotTypeM == null)
				{
					_slotTypeM = AccessTools.Method(typeof(PlayerCustomization), "GetMeshFilterForType");
				}
				if (_slotTypeM != null)
				{
					meshFilter = _slotTypeM.Invoke(c, new object[1] { d.cosmeticType }) as MeshFilter;
				}
			}
			catch
			{
			}
			if (meshFilter == null)
			{
				meshFilter = SlotFilter(c, (int)d.cosmeticType);
			}
			if (meshFilter != null)
			{
				WakeSlot(meshFilter);
			}
			Mesh mesh;
			Material mat;
			CosmeticVisualFromData(d, out mesh, out mat);
			if (mesh == null)
			{
				return false;
			}
			int slot = 0;
			try
			{
				slot = (int)d.cosmeticType;
			}
			catch
			{
			}
			WriteSlotVisual(p, c, slot, mesh, mat, true);
			if (meshFilter != null && meshFilter != SlotFilter(c, slot))
			{
				WriteSlot(meshFilter, mesh, mat, true);
			}
			try
			{
				if (_shadowDupM == null)
				{
					_shadowDupM = AccessTools.Method(typeof(PlayerCustomization), "CreateShadowOnlyDuplicate");
				}
				if (_shadowDupM != null && meshFilter != null)
				{
					_shadowDupM.Invoke(c, new object[4] { d.cosmeticType, meshFilter, mesh, mat });
				}
			}
			catch
			{
			}
			try
			{
				Dictionary<CosmeticType, int> dictionary = EquippedOf(c);
				if (dictionary != null)
				{
					dictionary[d.cosmeticType] = id;
				}
			}
			catch
			{
			}
			return true;
		}

		private static void WakeSlot(MeshFilter mf)
		{
			if (mf == null)
			{
				return;
			}
			try
			{
				mf.gameObject.SetActive(true);
			}
			catch
			{
			}
			Transform parent = mf.transform;
			int num = 0;
			while (parent != null && num < 8)
			{
				try
				{
					if (parent.GetComponent<PlayerProfile>() != null || parent.GetComponent<PlayerController>() != null)
					{
						break;
					}
				}
				catch
				{
				}
				try
				{
					parent.gameObject.SetActive(true);
				}
				catch
				{
				}
				parent = parent.parent;
				num++;
			}
		}

		private static bool ParseLook(string raw, out Color col, int[] ids)
		{
			col = Color.white;
			if (ids == null || ids.Length < 7)
			{
				return false;
			}
			for (int i = 0; i < 7; i++)
			{
				ids[i] = -1;
			}
			if (string.IsNullOrEmpty(raw))
			{
				return false;
			}
			int num = raw.IndexOf('|');
			string text = ((num >= 0) ? raw.Substring(0, num) : raw);
			string text2 = ((num >= 0 && num + 1 < raw.Length) ? raw.Substring(num + 1) : "");
			string[] array = text.Split(new char[1] { ',' });
			float result = 1f;
			float result2 = 1f;
			float result3 = 1f;
			float result4 = 1f;
			if (text.Length >= 6 && text.IndexOf('.') < 0 && text.IndexOf(',') < 0)
			{
				Color color;
				if (ColorUtility.TryParseHtmlString("#" + text, out color))
				{
					col = color;
				}
				else
				{
					col = Color.white;
				}
			}
			else
			{
				if (array.Length >= 1)
				{
					float.TryParse(array[0], NumberStyles.Float, CultureInfo.InvariantCulture, out result);
				}
				if (array.Length >= 2)
				{
					float.TryParse(array[1], NumberStyles.Float, CultureInfo.InvariantCulture, out result2);
				}
				if (array.Length >= 3)
				{
					float.TryParse(array[2], NumberStyles.Float, CultureInfo.InvariantCulture, out result3);
				}
				if (array.Length >= 4)
				{
					float.TryParse(array[3], NumberStyles.Float, CultureInfo.InvariantCulture, out result4);
				}
				col = new Color(result, result2, result3, result4);
			}
			if (!string.IsNullOrEmpty(text2))
			{
				string[] array2 = text2.Split(new char[1] { ',' });
				int num2 = ((array2.Length < 7) ? array2.Length : 7);
				for (int j = 0; j < num2; j++)
				{
					int.TryParse(array2[j], NumberStyles.Integer, CultureInfo.InvariantCulture, out ids[j]);
				}
			}
			return true;
		}

		private static Color ReadBlockColor(MaterialPropertyBlock b)
		{
			Color color = b.GetColor("_Tint");
			if (color.a > 0.2f && color.r + color.g + color.b > 0.12f)
			{
				return color;
			}
			color = b.GetColor("_Color");
			if (color.a > 0.2f && color.r + color.g + color.b > 0.12f)
			{
				return color;
			}
			color = b.GetColor("_BaseColor");
			if (color.a > 0.2f && color.r + color.g + color.b > 0.12f)
			{
				return color;
			}
			return new Color(0f, 0f, 0f, 0f);
		}

		private static PlayerInfo FindPlayerInfo(ulong sid, string nm)
		{
			try
			{
				LobbySettings lobbySettings = CachedLobby();
				if (lobbySettings == null || lobbySettings.players == null)
				{
					return null;
				}
				for (int i = 0; i < lobbySettings.players.Count; i++)
				{
					PlayerInfo playerInfo = lobbySettings.players[i];
					if (playerInfo != null && sid != 0 && playerInfo.steamId == sid)
					{
						return playerInfo;
					}
				}
				if (string.IsNullOrEmpty(nm))
				{
					return null;
				}
				for (int j = 0; j < lobbySettings.players.Count; j++)
				{
					PlayerInfo playerInfo2 = lobbySettings.players[j];
					if (playerInfo2 != null && playerInfo2.playerName == nm)
					{
						return playerInfo2;
					}
				}
			}
			catch
			{
			}
			return null;
		}

		private static void ApplyPlayerColor(PlayerProfile p, Color col)
		{
			if (p == null || !ColorUsable(col) || ColorIsBlankGlow(col))
			{
				return;
			}
			RememberMorphTint(p, Key(p), col);
			try
			{
				UIColorManager[] componentsInChildren = p.GetComponentsInChildren<UIColorManager>(true);
				if (componentsInChildren != null)
				{
					for (int i = 0; i < componentsInChildren.Length; i++)
					{
						if (!(componentsInChildren[i] == null))
						{
							componentsInChildren[i].ApplyColors();
							PaintPlayerColorGroups(componentsInChildren[i], col);
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				if (!(p == LocalProfile()))
				{
					return;
				}
				UIColorManager[] array = UnityEngine.Object.FindObjectsByType<UIColorManager>(FindObjectsSortMode.None);
				if (array == null)
				{
					return;
				}
				for (int j = 0; j < array.Length; j++)
				{
					if (!(array[j] == null) && UmIsLocalView(array[j]))
					{
						array[j].ApplyColors();
						PaintPlayerColorGroups(array[j], col);
					}
				}
			}
			catch
			{
			}
		}

		private static void EnsureColorFields()
		{
			if (_cgF == null)
			{
				_cgF = AccessTools.Field(typeof(UIColorManager), "colorGroups");
			}
			if (_rtMatF == null)
			{
				_rtMatF = AccessTools.Field(typeof(UIColorManager), "_runtimeMaterials");
			}
			if (_cgT == null)
			{
				_cgT = AccessTools.Inner(typeof(UIColorManager), "ColorGroup");
			}
			if (_cgT == null)
			{
				_cgT = typeof(UIColorManager).GetNestedType("ColorGroup", BindingFlags.Public | BindingFlags.NonPublic);
			}
			if (_cgT != null)
			{
				if (_toneF == null)
				{
					_toneF = AccessTools.Field(_cgT, "tone");
				}
				if (_skinsF == null)
				{
					_skinsF = AccessTools.Field(_cgT, "skinnedMeshRenderers");
				}
				if (_meshesF == null)
				{
					_meshesF = AccessTools.Field(_cgT, "meshRenderers");
				}
			}
		}

		private static void TintRendererColor(UIColorManager um, Renderer r, Color col)
		{
			if (r == null)
			{
				return;
			}
			try
			{
				Material material = null;
				if (um != null && _rtMatF != null)
				{
					IDictionary dictionary = _rtMatF.GetValue(um) as IDictionary;
					if (dictionary != null && dictionary.Contains(r))
					{
						material = dictionary[r] as Material;
					}
					if (material == null && Application.isPlaying)
					{
						Material sharedMaterial = r.sharedMaterial;
						if (sharedMaterial != null)
						{
							object obj = (dictionary[r] = new Material(sharedMaterial));
							Material material3 = (r.material = (Material)obj);
							material = material3;
						}
					}
				}
				if (material == null)
				{
					material = r.material;
				}
				if (!(material == null))
				{
					Color color = material.color;
					material.color = new Color(col.r, col.g, col.b, (color.a > 0.01f) ? color.a : 1f);
					if (material.HasProperty("_Tint"))
					{
						material.SetColor("_Tint", col);
					}
					if (material.HasProperty("_Color"))
					{
						material.SetColor("_Color", new Color(col.r, col.g, col.b, (color.a > 0.01f) ? color.a : 1f));
					}
				}
			}
			catch
			{
			}
		}

		private static void PaintPlayerColorGroups(UIColorManager um, Color col)
		{
			if (um == null || !ColorUsable(col))
			{
				return;
			}
			try
			{
				EnsureColorFields();
				if (_cgF == null)
				{
					return;
				}
				IList list = _cgF.GetValue(um) as IList;
				if (list == null)
				{
					return;
				}
				for (int i = 0; i < list.Count; i++)
				{
					object obj = list[i];
					if (obj == null)
					{
						continue;
					}
					int num = 0;
					try
					{
						num = Convert.ToInt32(_toneF.GetValue(obj));
					}
					catch
					{
						continue;
					}
					if (num != 5)
					{
						continue;
					}
					IList list2 = ((_skinsF != null) ? (_skinsF.GetValue(obj) as IList) : null);
					if (list2 != null)
					{
						for (int j = 0; j < list2.Count; j++)
						{
							TintRendererColor(um, list2[j] as Renderer, col);
						}
					}
					IList list3 = ((_meshesF != null) ? (_meshesF.GetValue(obj) as IList) : null);
					if (list3 != null)
					{
						for (int k = 0; k < list3.Count; k++)
						{
							TintRendererColor(um, list3[k] as Renderer, col);
						}
					}
				}
			}
			catch
			{
			}
		}

