		private static void ApplyLook(PlayerProfile p, string look, PlayerProfile vic)
		{
			if (p == null)
			{
				return;
			}
			string text = Key(p);
			if (string.IsNullOrEmpty(text))
			{
				Acc acc = Ensure(p);
				if (acc != null)
				{
					text = acc.id;
				}
			}
			SnapshotLookMeshes(p, text);
			ClearExtraTint(p);
			Color col = new Color(0f, 0f, 0f, 0f);
			int[] array = new int[7];
			for (int i = 0; i < 7; i++)
			{
				array[i] = -1;
			}
			if (!string.IsNullOrEmpty(look))
			{
				ParseLook(look, out col, array);
			}
			if (vic != null && vic != p)
			{
				FillIdsFrom(vic, array);
			}
			ApplyIdsLocal(p, array);
			bool[] copied = new bool[7];
			if (vic != null && vic != p)
			{
				CopyLookMeshes(vic, p, array, copied);
			}
			HideEmptyMorphSlots(p, array, copied);
			Color col2 = CaptureLiveColor(vic);
			if (!ColorUsable(col2) || ColorIsBlankGlow(col2))
			{
				col2 = col;
			}
			if (ColorUsable(col2) && !ColorIsBlankGlow(col2))
			{
				ApplyPlayerColor(p, col2);
			}
		}

		private static void HideMorphHud(PlayerProfile p, string key, bool hide)
		{
			if (p == null || string.IsNullOrEmpty(key))
			{
				return;
			}
			if (!hide)
			{
				List<GameObject> value;
				if (MorphHudHide.TryGetValue(key, out value) && value != null)
				{
					for (int i = 0; i < value.Count; i++)
					{
						if (value[i] != null)
						{
							value[i].SetActive(true);
						}
					}
				}
				MorphHudHide.Remove(key);
				return;
			}
			List<GameObject> list = new List<GameObject>();
			try
			{
				PlayerVoiceSpriteIndicator[] componentsInChildren = p.GetComponentsInChildren<PlayerVoiceSpriteIndicator>(true);
				if (componentsInChildren != null)
				{
					for (int j = 0; j < componentsInChildren.Length; j++)
					{
						if (!(componentsInChildren[j] == null) && !(componentsInChildren[j].gameObject == null))
						{
							componentsInChildren[j].gameObject.SetActive(false);
							list.Add(componentsInChildren[j].gameObject);
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				Transform[] componentsInChildren2 = p.GetComponentsInChildren<Transform>(true);
				if (componentsInChildren2 != null)
				{
					Transform[] array = componentsInChildren2;
					foreach (Transform transform in array)
					{
						if (!(transform == null))
						{
							string text = transform.name;
							if (!string.IsNullOrEmpty(text) && (text.IndexOf("Mic", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("Voice", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("Speak", StringComparison.OrdinalIgnoreCase) >= 0) && transform.gameObject.activeSelf)
							{
								transform.gameObject.SetActive(false);
								list.Add(transform.gameObject);
							}
						}
					}
				}
			}
			catch
			{
			}
			MorphHudHide[key] = list;
		}

