		internal static void KeepMorphDisguise(Transform who)
		{
			if (who == null)
			{
				return;
			}
			Transform transform = who;
			try
			{
				NetworkIdentity componentInParent = who.GetComponentInParent<NetworkIdentity>();
				if (componentInParent != null && componentInParent.transform != null)
				{
					transform = componentInParent.transform;
				}
			}
			catch
			{
			}
			try
			{
				Renderer[] componentsInChildren = transform.GetComponentsInChildren<Renderer>(true);
				if (componentsInChildren != null)
				{
					Renderer[] array = componentsInChildren;
					foreach (Renderer renderer in array)
					{
						if (!(renderer == null) && !RendererIsFirstPerson(renderer, false))
						{
							if (RendererIsHeldItem(renderer))
							{
								renderer.enabled = true;
							}
							else
							{
								renderer.enabled = false;
							}
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				PlayerProfile playerProfile = who.GetComponent<PlayerProfile>() ?? who.GetComponentInParent<PlayerProfile>() ?? who.GetComponentInChildren<PlayerProfile>();
				if (playerProfile != null)
				{
					string text = Key(playerProfile);
					string value;
					if (!string.IsNullOrEmpty(text) && MorphFakeName.TryGetValue(text, out value) && !string.IsNullOrEmpty(value))
					{
						SetDisguiseName(playerProfile, text, value);
					}
					else if (!string.IsNullOrEmpty(text))
					{
						HidePlayerName(playerProfile, text, true);
					}
				}
			}
			catch
			{
			}
		}

		private static void SilenceCloneNet(GameObject go)
		{
			if (go == null)
			{
				return;
			}
			try
			{
				NetworkBehaviour[] componentsInChildren = go.GetComponentsInChildren<NetworkBehaviour>(true);
				if (componentsInChildren != null)
				{
					for (int i = 0; i < componentsInChildren.Length; i++)
					{
						if (componentsInChildren[i] != null)
						{
							componentsInChildren[i].enabled = false;
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				NetworkIdentity[] componentsInChildren2 = go.GetComponentsInChildren<NetworkIdentity>(true);
				if (componentsInChildren2 != null)
				{
					for (int j = 0; j < componentsInChildren2.Length; j++)
					{
						if (componentsInChildren2[j] != null)
						{
							componentsInChildren2[j].enabled = false;
						}
					}
				}
			}
			catch
			{
			}
			Component[] componentsInChildren3 = go.GetComponentsInChildren<Component>(true);
			if (componentsInChildren3 == null)
			{
				return;
			}
			Component[] array = componentsInChildren3;
			foreach (Component component in array)
			{
				if (component == null)
				{
					continue;
				}
				string text = component.GetType().Name;
				switch (text)
				{
				case "NavMeshAgent":
				case "AudioSource":
				case "AudioListener":
					try
					{
						Behaviour behaviour = component as Behaviour;
						if (behaviour != null)
						{
							behaviour.enabled = false;
						}
					}
					catch
					{
					}
					break;
				}
				if (!(text == "Rigidbody"))
				{
					continue;
				}
				try
				{
					Rigidbody rigidbody = component as Rigidbody;
					if (rigidbody != null)
					{
						rigidbody.isKinematic = true;
						rigidbody.detectCollisions = true;
					}
				}
				catch
				{
				}
			}
		}

		private static void SetLayerRec(GameObject go, int layer)
		{
			if (!(go == null))
