		private static void StripMorphClone(GameObject go)
		{
			if (go == null)
			{
				return;
			}
			List<Component> list = new List<Component>();
			Component[] componentsInChildren = go.GetComponentsInChildren<Component>(true);
			if (componentsInChildren == null)
			{
				return;
			}
			Component[] array = componentsInChildren;
			foreach (Component component in array)
			{
				if (!(component == null) && !(component is Transform) && !(component is Renderer) && !(component is MeshFilter) && !(component is Animator))
				{
					string text = component.GetType().Name;
					if (!(text == "SkinnedMeshRenderer"))
					{
						list.Add(component);
					}
				}
			}
			for (int j = 0; j < list.Count; j++)
			{
				if (!(list[j] == null))
				{
					try
					{
						UnityEngine.Object.Destroy(list[j]);
					}
					catch
					{
					}
				}
			}
			try
			{
				Animator[] componentsInChildren2 = go.GetComponentsInChildren<Animator>(true);
				if (componentsInChildren2 != null)
				{
					for (int k = 0; k < componentsInChildren2.Length; k++)
					{
						if (!(componentsInChildren2[k] == null))
						{
							componentsInChildren2[k].enabled = true;
							componentsInChildren2[k].cullingMode = AnimatorCullingMode.AlwaysAnimate;
						}
					}
				}
			}
			catch
			{
			}
			SetLayerRec(go, 0);
		}

		private static bool RendererOnThisNpc(Renderer r, NPC npc, Transform vis)
		{
			if (r == null || npc == null)
			{
				return false;
			}
			try
			{
				if (!r.gameObject.activeInHierarchy)
				{
					return false;
				}
			}
			catch
			{
				return false;
			}
			try
			{
				if (vis != null && !r.transform.IsChildOf(vis) && r.transform != vis)
				{
					return false;
				}
			}
			catch
			{
			}
			try
			{
				NPC componentInParent = r.GetComponentInParent<NPC>();
				if (componentInParent != null && componentInParent != npc)
				{
					return false;
				}
			}
			catch
			{
			}
			try
			{
				Vector3 size = r.bounds.size;
				if (size.x > 20f || size.y > 20f || size.z > 20f)
				{
					return false;
				}
			}
			catch
			{
			}
			return true;
		}

		private static GameObject CopyNpcVisual(NPC npc)
		{
			if (npc == null)
			{
				return null;
			}
			Transform transform = NpcVisRoot(npc);
			if (transform == null)
			{
				return null;
			}
			GameObject gameObject = new GameObject("MorphVis");
			Quaternion rotation = Quaternion.Euler(0f, transform.eulerAngles.y, 0f);
			gameObject.transform.position = transform.position;
			gameObject.transform.rotation = rotation;
			gameObject.transform.localScale = Vector3.one;
			SetLayerRec(gameObject, 0);
			Vector3 lossyScale = transform.lossyScale;
			if (Mathf.Abs(lossyScale.x) < 0.001f)
			{
				lossyScale.x = 1f;
			}
			if (Mathf.Abs(lossyScale.y) < 0.001f)
			{
				lossyScale.y = 1f;
			}
			if (Mathf.Abs(lossyScale.z) < 0.001f)
			{
				lossyScale.z = 1f;
			}
			Renderer[] componentsInChildren = transform.GetComponentsInChildren<Renderer>(false);
			int num = 0;
			if (componentsInChildren != null)
			{
				Renderer[] array = componentsInChildren;
				foreach (Renderer renderer in array)
				{
					if (renderer == null || !renderer.enabled || !renderer.gameObject.activeInHierarchy || !RendererOnThisNpc(renderer, npc, transform))
					{
						continue;
					}
					string text = renderer.GetType().Name;
					switch (text)
					{
					case "ParticleSystemRenderer":
					case "TrailRenderer":
					case "LineRenderer":
						continue;
					}
					if (text.IndexOf("Text", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						continue;
					}
					try
					{
						Component[] componentsInParent = renderer.GetComponentsInParent<Component>(true);
						bool flag = false;
						if (componentsInParent != null)
						{
							for (int j = 0; j < componentsInParent.Length; j++)
							{
								if (!(componentsInParent[j] == null) && componentsInParent[j].GetType().Name == "Canvas")
								{
									flag = true;
									break;
								}
							}
						}
						if (flag)
						{
							continue;
						}
					}
					catch
					{
					}
					Mesh mesh = null;
					bool flag2 = false;
					try
					{
						SkinnedMeshRenderer skinnedMeshRenderer = renderer as SkinnedMeshRenderer;
						if (skinnedMeshRenderer != null && skinnedMeshRenderer.sharedMesh != null)
						{
							mesh = new Mesh();
							mesh.name = "MorphBake";
							skinnedMeshRenderer.BakeMesh(mesh);
							flag2 = true;
						}
						else
						{
							MeshFilter component = renderer.GetComponent<MeshFilter>();
							if (component != null)
							{
								mesh = component.sharedMesh;
							}
						}
					}
					catch
					{
						mesh = null;
					}
					if (mesh == null)
					{
						continue;
					}
					try
					{
						if (mesh.vertexCount < 3)
						{
							continue;
						}
					}
					catch
					{
					}
					try
					{
						GameObject gameObject2 = new GameObject(renderer.gameObject.name);
						gameObject2.layer = 0;
						gameObject2.transform.SetParent(gameObject.transform, false);
						gameObject2.transform.localPosition = Quaternion.Inverse(rotation) * (renderer.transform.position - transform.position);
						gameObject2.transform.localRotation = Quaternion.Inverse(rotation) * renderer.transform.rotation;
						if (flag2)
						{
							gameObject2.transform.localScale = Vector3.one;
						}
						else
						{
							Vector3 lossyScale2 = renderer.transform.lossyScale;
							gameObject2.transform.localScale = new Vector3(lossyScale2.x / lossyScale.x, lossyScale2.y / lossyScale.y, lossyScale2.z / lossyScale.z);
						}
						MeshFilter meshFilter = gameObject2.AddComponent<MeshFilter>();
						meshFilter.sharedMesh = mesh;
						MeshRenderer meshRenderer = gameObject2.AddComponent<MeshRenderer>();
						meshRenderer.sharedMaterials = renderer.sharedMaterials;
						meshRenderer.shadowCastingMode = renderer.shadowCastingMode;
						meshRenderer.receiveShadows = renderer.receiveShadows;
						meshRenderer.enabled = true;
						num++;
					}
					catch
					{
					}
				}
			}
			if (num <= 0)
			{
				UnityEngine.Object.Destroy(gameObject);
				return null;
			}
			SnapMorphLocalFeet(gameObject);
			return gameObject;
		}

