		private static void SnapMorphLocalFeet(GameObject root)
		{
			if (root == null)
			{
				return;
			}
			try
			{
				Renderer[] componentsInChildren = root.GetComponentsInChildren<Renderer>();
				if (componentsInChildren == null || componentsInChildren.Length == 0)
				{
					return;
				}
				Bounds bounds = componentsInChildren[0].bounds;
				bool flag = componentsInChildren[0] != null;
				for (int i = 1; i < componentsInChildren.Length; i++)
				{
					if (!(componentsInChildren[i] == null) && componentsInChildren[i].enabled)
					{
						if (!flag)
						{
							bounds = componentsInChildren[i].bounds;
							flag = true;
						}
						else
						{
							bounds.Encapsulate(componentsInChildren[i].bounds);
						}
					}
				}
				if (!flag)
				{
					return;
				}
				float num = root.transform.position.y - bounds.min.y;
				if (!(Mathf.Abs(num) < 0.001f))
				{
					Transform transform = root.transform;
					for (int j = 0; j < transform.childCount; j++)
					{
						Transform child = transform.GetChild(j);
						Vector3 localPosition = child.localPosition;
						localPosition.y += num;
						child.localPosition = localPosition;
					}
				}
			}
			catch
			{
			}
		}

		private static void SweepOrphanMorphVis()
		{
			try
			{
				MorphFollow[] array = UnityEngine.Object.FindObjectsByType<MorphFollow>(FindObjectsSortMode.None);
				if (array == null)
				{
					return;
				}
				MorphFollow[] array2 = array;
				foreach (MorphFollow morphFollow in array2)
				{
					if (morphFollow == null || morphFollow.gameObject == null)
					{
						continue;
					}
					bool flag = false;
					foreach (KeyValuePair<string, GameObject> item in MorphClone)
					{
						if (item.Value == morphFollow.gameObject)
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						UnityEngine.Object.Destroy(morphFollow.gameObject);
					}
				}
			}
			catch
			{
			}
		}

		private static void AttachMorphVisual(PlayerProfile p, uint npcNet)
		{
			if (p == null)
			{
				return;
			}
			string text = Key(p);
			if (string.IsNullOrEmpty(text))
			{
				Acc acc = Ensure(p);
				if (acc != null)
				{
					text = acc.id;
				}
			}
			if (string.IsNullOrEmpty(text))
			{
				return;
			}
			DetachMorphVisual(p, text, false);
			NPC nPC = NpcFromNetId(npcNet);
			if (nPC == null || nPC.gameObject == null)
			{
				return;
			}
			bool flag = p == LocalProfile();
			HidePlayerName(p, text, true);
			if (flag)
			{
				return;
			}
			GameObject gameObject = CopyNpcVisual(nPC);
			if (gameObject == null)
			{
				return;
			}
			Transform target = p.transform;
			Transform transform = p.transform;
			try
			{
				PlayerController playerController = p.GetComponent<PlayerController>();
				if (playerController == null)
				{
					playerController = p.GetComponentInParent<PlayerController>();
				}
				if (playerController == null)
				{
					playerController = p.GetComponentInChildren<PlayerController>();
				}
				if (playerController != null && playerController.transform != null)
				{
					transform = playerController.transform;
				}
			}
			catch
			{
			}
			try
			{
				CharacterController characterController = transform.GetComponent<CharacterController>();
				if (characterController == null)
				{
					characterController = transform.GetComponentInChildren<CharacterController>();
				}
				if (characterController != null && characterController.transform != null)
				{
					target = characterController.transform;
				}
			}
			catch
			{
			}
			List<Renderer> list = new List<Renderer>();
			KeepMorphDisguise(transform);
			try
			{
				Renderer[] componentsInChildren = transform.GetComponentsInChildren<Renderer>(true);
				if (componentsInChildren != null)
				{
					Renderer[] array = componentsInChildren;
					foreach (Renderer renderer in array)
					{
						if (!(renderer == null) && !RendererIsFirstPerson(renderer, false) && !RendererIsHeldItem(renderer))
						{
							renderer.enabled = false;
							list.Add(renderer);
						}
					}
				}
			}
			catch
			{
			}
			MorphHid[text] = list;
			MorphFollow morphFollow = gameObject.AddComponent<MorphFollow>();
			morphFollow.target = target;
			morphFollow.who = transform;
			morphFollow.hide = list;
			try
			{
				CapsuleCollider capsuleCollider = gameObject.GetComponent<CapsuleCollider>();
				if (capsuleCollider == null)
				{
					capsuleCollider = gameObject.AddComponent<CapsuleCollider>();
				}
				Renderer[] componentsInChildren2 = gameObject.GetComponentsInChildren<Renderer>();
				float height = 1.6f;
				float radius = 0.35f;
				Vector3 center = Vector3.up * 0.8f;
				if (componentsInChildren2 != null && componentsInChildren2.Length > 0)
				{
					Bounds bounds = componentsInChildren2[0].bounds;
					bool flag2 = componentsInChildren2[0] != null;
					for (int j = 1; j < componentsInChildren2.Length; j++)
					{
						if (!(componentsInChildren2[j] == null))
						{
							if (!flag2)
							{
								bounds = componentsInChildren2[j].bounds;
								flag2 = true;
							}
							else
							{
								bounds.Encapsulate(componentsInChildren2[j].bounds);
							}
						}
					}
					if (flag2)
					{
						height = Mathf.Max(0.8f, bounds.size.y);
						radius = Mathf.Max(0.22f, Mathf.Max(bounds.extents.x, bounds.extents.z));
						center = gameObject.transform.InverseTransformPoint(bounds.center);
					}
				}
				capsuleCollider.height = height;
				capsuleCollider.radius = radius;
				capsuleCollider.center = center;
				capsuleCollider.isTrigger = true;
			}
			catch
			{
			}
			MorphClone[text] = gameObject;
		}

		private static void AttachPlayerMorphVisual(PlayerProfile p, PlayerProfile vic, string fakeName, string look)
		{
			if (p == null)
			{
				return;
			}
			string text = Key(p);
			if (string.IsNullOrEmpty(text))
			{
				Acc acc = Ensure(p);
				if (acc != null)
				{
					text = acc.id;
				}
			}
			if (string.IsNullOrEmpty(text))
			{
				return;
			}
			GameObject value;
			if (MorphClone.TryGetValue(text, out value))
			{
				MorphClone.Remove(text);
				if (value != null)
				{
					UnityEngine.Object.Destroy(value);
				}
			}
			List<Renderer> value2;
			if (MorphHid.TryGetValue(text, out value2) && value2 != null)
			{
				for (int i = 0; i < value2.Count; i++)
				{
					if (value2[i] != null)
					{
						value2[i].enabled = true;
					}
				}
				MorphHid.Remove(text);
			}
			SnapshotLookMeshes(p, text);
			if (string.IsNullOrEmpty(look) && vic != null)
			{
				look = CaptureLook(vic);
			}
			if (string.IsNullOrEmpty(look) && vic != null)
			{
				string text2 = Key(vic);
				if (!string.IsNullOrEmpty(text2))
				{
					LookBook.TryGetValue(text2, out look);
				}
			}
			ApplyLook(p, look, vic);
			if (!string.IsNullOrEmpty(fakeName))
			{
				SetDisguiseName(p, text, LookalikeName(fakeName));
			}
		}

		private static void DetachMorphVisual(PlayerProfile p, string key, bool smoke)
		{
			List<string> list = new List<string>();
			if (!string.IsNullOrEmpty(key))
			{
				list.Add(key);
			}
			if (p != null)
			{
				string text = Key(p);
				if (!string.IsNullOrEmpty(text))
				{
					list.Add(text);
				}
				Acc acc = Ensure(p);
				if (acc != null && !string.IsNullOrEmpty(acc.id))
				{
					list.Add(acc.id);
				}
			}
			try
			{
				List<string> list2 = new List<string>();
				foreach (KeyValuePair<string, GameObject> item in MorphClone)
				{
					if (!(item.Value == null))
					{
						MorphFollow component = item.Value.GetComponent<MorphFollow>();
						if (!(component == null) && !(component.who == null) && !(p == null) && !(p.transform == null) && (component.who == p.transform || component.who.IsChildOf(p.transform) || p.transform.IsChildOf(component.who)))
						{
							list2.Add(item.Key);
						}
					}
				}
				for (int i = 0; i < list2.Count; i++)
				{
					list.Add(list2[i]);
				}
			}
			catch
			{
			}
			bool flag = false;
			for (int j = 0; j < list.Count; j++)
			{
				string text2 = list[j];
				if (string.IsNullOrEmpty(text2))
				{
					continue;
				}
				GameObject value;
				if (MorphClone.TryGetValue(text2, out value))
				{
					MorphClone.Remove(text2);
					if (value != null)
					{
						UnityEngine.Object.Destroy(value);
					}
				}
				List<Renderer> value2;
				if (MorphHid.TryGetValue(text2, out value2) && value2 != null)
				{
					for (int k = 0; k < value2.Count; k++)
					{
						if (value2[k] != null)
						{
							value2[k].enabled = true;
						}
					}
					MorphHid.Remove(text2);
				}
				RestoreDisguiseName(p, text2);
				HidePlayerName(p, text2, false);
				RestoreLookMeshes(p, text2);
			}
			if (smoke && p != null && p.transform != null && !flag)
			{
				SpawnMorphSmoke(p.transform);
			}
		}

		private static void ApplyMorphView(string key, uint nid, float sec)
		{
			ApplyMorphView(key, nid, sec, "", "", "");
		}

		private static void ApplyMorphView(string key, uint nid, float sec, string faceKey, string faceName)
		{
			ApplyMorphView(key, nid, sec, faceKey, faceName, "");
		}

		private static void ApplyMorphView(string key, uint nid, float sec, string faceKey, string faceName, string look)
		{
			if (string.IsNullOrEmpty(key))
			{
				return;
			}
			PlayerProfile playerProfile = ResolveMorphProfile(key);
			Acc a = FindAccByKey(key);
			bool flag = MorphKeyIsLocal(key) || AccIsPlayer(a, LocalProfile()) || (playerProfile != null && playerProfile == LocalProfile()) || ProfileMatchesKey(LocalProfile(), key);
			if (playerProfile == null && flag)
			{
				playerProfile = LocalProfile();
			}
			bool flag2 = !string.IsNullOrEmpty(faceKey);
			if (sec <= 0.01f || (nid == 0 && !flag2))
			{
				bool flag3 = flag && (LocalMorphUntil > Time.unscaledTime || LocalMorphed());
				ViewMorphUntil.Remove(key);
				ViewMorphNpc.Remove(key);
				MorphFaceOf.Remove(key);
				if (flag)
				{
					LocalMorphUntil = 0f;
				}
				if (flag)
				{
					LocalMorphSpeed = 0f;
				}
				if (flag)
				{
					LocalMorphPlayer = false;
				}
				if (flag3 && LocalMorphCoolUntil < Time.unscaledTime + 4.5f)
				{
					LocalMorphCoolUntil = Time.unscaledTime + 5f;
				}
				DetachMorphVisual(playerProfile, key, true);
				return;
			}
			ViewMorphUntil[key] = Time.unscaledTime + sec;
			ViewMorphNpc[key] = nid;
			if (flag2)
			{
				MorphFaceOf[key] = faceKey;
			}
			else
			{
				MorphFaceOf.Remove(key);
			}
			if (flag)
			{
				LocalMorphUntil = Time.unscaledTime + sec;
				LocalMorphPlayer = flag2;
				if (!flag2)
				{
					NPC npc = NpcFromNetId(nid);
					float num = SampleNpcWalkSpeed(npc);
					if (num < 0.4f)
					{
						num = MorphWalkSpeed((playerProfile != null) ? playerProfile : LocalProfile());
					}
					LocalMorphSpeed = num;
				}
				else
				{
					LocalMorphSpeed = 0f;
				}
			}
			if (flag2)
			{
				PlayerProfile playerProfile2 = ResolveMorphProfile(faceKey);
				if (playerProfile2 == null)
				{
					playerProfile2 = FindProfileByKey(faceKey);
				}
				if (playerProfile2 == null && nid != 0)
				{
					playerProfile2 = ProfileFromNetId(nid);
				}
				if (string.IsNullOrEmpty(look) && !string.IsNullOrEmpty(faceKey))
				{
					LookBook.TryGetValue(faceKey, out look);
				}
				AttachPlayerMorphVisual(playerProfile, playerProfile2, faceName, look);
			}
			else
			{
				AttachMorphVisual(playerProfile, nid);
			}
			if (playerProfile != null && playerProfile.transform != null)
			{
				SpawnMorphSmoke(playerProfile.transform);
			}
		}

		private static void BroadcastMorph(string key, uint nid, float sec)
		{
			BroadcastMorph(key, nid, sec, "", "", "");
		}

		private static void BroadcastMorph(string key, uint nid, float sec, string faceKey, string faceName)
