			BroadcastMorph(key, nid, sec, faceKey, faceName, "");
		}

		private static void BroadcastMorph(string key, uint nid, float sec, string faceKey, string faceName, string look)
		{
			ApplyMorphView(key, nid, sec, faceKey, faceName, look);
			if (!NetworkServer.active)
			{
				return;
			}
			string json = "MORPH\t" + (key ?? "") + "\t" + nid.ToString(CultureInfo.InvariantCulture) + "\t" + sec.ToString("R", CultureInfo.InvariantCulture) + "\t" + (faceKey ?? "") + "\t" + (faceName ?? "") + "\t" + (look ?? "");
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value != null && (!(value.identity != null) || !value.identity.isLocalPlayer))
					{
						value.Send(new SoloMsg
						{
							json = json
						});
					}
				}
			}
			catch
			{
			}
		}

		private static void SendMorphCool(PlayerProfile p, float sec)
		{
			if (p == null)
			{
				return;
			}
			Acc a = Ensure(p);
			if (AccIsPlayer(a, LocalProfile()))
			{
				LocalMorphCoolUntil = Time.unscaledTime + sec;
			}
			string json = "MCD\t" + sec.ToString("R", CultureInfo.InvariantCulture);
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value != null && !(value.identity == null))
					{
						PlayerProfile p2 = ProfileFromIdentity(value.identity);
						if (AccIsPlayer(a, p2) && !value.identity.isLocalPlayer)
						{
							value.Send(new SoloMsg
							{
								json = json
							});
						}
					}
				}
			}
			catch
			{
			}
		}

		private static void UnmorphThief(Acc ta, PlayerProfile thief, bool startCool)
		{
			if (ta == null && thief != null)
			{
				ta = Ensure(thief);
			}
			List<string> list = new List<string>();
			if (ta != null && !string.IsNullOrEmpty(ta.id))
			{
				list.Add(ta.id);
			}
			if (thief != null)
			{
				string text = Key(thief);
				if (!string.IsNullOrEmpty(text))
				{
					bool flag = false;
					for (int i = 0; i < list.Count; i++)
					{
						if (list[i] == text)
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						list.Add(text);
					}
				}
			}
			bool flag2 = false;
			for (int j = 0; j < list.Count; j++)
			{
				string text2 = list[j];
				if (MorphUntil.ContainsKey(text2) || ViewMorphUntil.ContainsKey(text2) || ServerMorphed(text2))
				{
					flag2 = true;
				}
			}
			if (!flag2 && thief != null)
			{
				string text3 = Key(thief);
				GameObject value;
				if (!string.IsNullOrEmpty(text3) && MorphClone.TryGetValue(text3, out value) && value != null)
				{
					flag2 = true;
				}
				if (ta != null && !string.IsNullOrEmpty(ta.id) && MorphClone.TryGetValue(ta.id, out value) && value != null)
				{
					flag2 = true;
				}
			}
			string text4 = ((list.Count > 0) ? list[0] : "");
			if (string.IsNullOrEmpty(text4) && ta != null)
			{
				text4 = ta.id;
			}
			if (flag2)
			{
				for (int k = 0; k < list.Count; k++)
				{
					MorphUntil.Remove(list[k]);
					MorphNpc.Remove(list[k]);
					MorphFaceOf.Remove(list[k]);
				}
				if (!string.IsNullOrEmpty(text4))
				{
					BroadcastMorph(text4, 0u, 0f);
				}
				if (startCool && !string.IsNullOrEmpty(text4))
				{
					MorphCool[text4] = Time.unscaledTime + 5f;
					SendMorphCool(thief, 5f);
				}
			}
		}

		internal static void UnmorphFromKnock(PlayerController pc)
		{
			if (pc == null)
			{
				return;
			}
			PlayerProfile playerProfile = PcProfile(pc);
			string text = ((playerProfile != null) ? Key(playerProfile) : "");
			if (!NetworkServer.active)
			{
				uint num = 0u;
				try
				{
					num = pc.netId;
				}
				catch
				{
				}
				try
				{
					NetworkClient.Send(new SideMsg
					{
						json = "MK\t" + num + "\t" + (text ?? "")
					});
				}
				catch
				{
				}
				bool flag = false;
				if (playerProfile != null && playerProfile == LocalProfile() && LocalMorphed())
				{
					flag = true;
				}
				float value;
				if (!flag && !string.IsNullOrEmpty(text) && ViewMorphUntil.TryGetValue(text, out value) && value > Time.unscaledTime)
				{
					flag = true;
				}
				GameObject value2;
				if (!flag && !string.IsNullOrEmpty(text) && MorphClone.TryGetValue(text, out value2) && value2 != null)
				{
					flag = true;
				}
				if (flag && !string.IsNullOrEmpty(text))
				{
					ApplyMorphView(text, 0u, 0f);
				}
			}
			else if (!(playerProfile == null))
			{
				UnmorphThief(Ensure(playerProfile), playerProfile, true);
			}
		}

