		private static void FireBatHitOnce(Bat bat, PlayerController pc)
		{
			if (bat == null || pc == null)
			{
				return;
			}
			int num = 0;
			try
			{
				num = pc.GetInstanceID();
			}
			catch
			{
			}
			if (num != 0 && num == _batHitWho && Time.unscaledTime < _batHitAt + 0.28f)
			{
				return;
			}
			_batHitWho = num;
			_batHitAt = Time.unscaledTime;
			try
			{
				if (_batCmdHit == null)
				{
					_batCmdHit = AccessTools.Method(typeof(Bat), "CmdHitPlayer");
				}
				if (_batCmdHit != null)
				{
					_batCmdHit.Invoke(bat, new object[2] { pc, 1f });
				}
			}
			catch
			{
			}
		}

		internal static bool SwallowBatHit(Bat bat, Collider other)
		{
			if (bat == null || other == null)
			{
				return false;
