			MorphFollow morphFollow = null;
			try
			{
				morphFollow = other.GetComponentInParent<MorphFollow>();
			}
			catch
			{
			}
			if (morphFollow != null && morphFollow.who != null)
			{
				PlayerController pc = PcFromWho(morphFollow.who);
				FireBatHitOnce(bat, pc);
				return true;
			}
			PlayerController playerController = null;
			try
			{
				playerController = other.GetComponentInParent<PlayerController>();
			}
			catch
			{
			}
			if (playerController == null)
			{
				return false;
			}
			if (!PlayerIsMorphed(playerController))
			{
				return false;
			}
			int num = 0;
			try
			{
				num = playerController.GetInstanceID();
			}
			catch
			{
			}
			if (num != 0 && num == _batHitWho && Time.unscaledTime < _batHitAt + 0.28f)
			{
				return true;
			}
			return false;
		}

