		private static MorphFollow MorphOnRay(Vector3 origin, Vector3 dir, float maxDist)
		{
			if (dir.sqrMagnitude < 0.0001f)
			{
				return null;
			}
			dir.Normalize();
			Ray ray = new Ray(origin, dir);
			MorphFollow result = null;
			float num = maxDist;
			try
			{
				MorphFollow[] array = UnityEngine.Object.FindObjectsByType<MorphFollow>(FindObjectsSortMode.None);
				if (array == null)
				{
					return null;
				}
				MorphFollow[] array2 = array;
				foreach (MorphFollow morphFollow in array2)
				{
					if (morphFollow == null)
					{
						continue;
					}
					Collider[] componentsInChildren = morphFollow.GetComponentsInChildren<Collider>();
					if (componentsInChildren != null)
					{
						for (int j = 0; j < componentsInChildren.Length; j++)
						{
							RaycastHit hitInfo;
							if (!(componentsInChildren[j] == null) && componentsInChildren[j].Raycast(ray, out hitInfo, maxDist) && !(hitInfo.distance >= num))
							{
								num = hitInfo.distance;
								result = morphFollow;
							}
						}
					}
					Renderer[] componentsInChildren2 = morphFollow.GetComponentsInChildren<Renderer>();
					if (componentsInChildren2 == null || componentsInChildren2.Length == 0)
					{
						continue;
					}
					Bounds bounds = default(Bounds);
					bool flag = false;
					for (int k = 0; k < componentsInChildren2.Length; k++)
					{
						if (!(componentsInChildren2[k] == null) && componentsInChildren2[k].enabled)
						{
							if (!flag)
							{
								bounds = componentsInChildren2[k].bounds;
								flag = true;
							}
							else
							{
								bounds.Encapsulate(componentsInChildren2[k].bounds);
							}
						}
					}
					float distance;
					if (flag && bounds.IntersectRay(ray, out distance) && !(distance < 0f) && !(distance >= num) && !(distance > maxDist))
					{
						num = distance;
						result = morphFollow;
					}
				}
			}
			catch
			{
			}
			return result;
		}

		internal static void TryGunHitMorph(QuotaGun gun)
		{
			if (gun == null)
			{
				return;
			}
			Transform transform = GunAim(gun);
			if (transform == null)
			{
				return;
			}
			try
			{
				RaycastHit hitInfo;
				if (Physics.Raycast(transform.position, transform.forward, out hitInfo, 40f, -5, QueryTriggerInteraction.Ignore))
				{
					PlayerController playerController = null;
					try
					{
						playerController = hitInfo.collider.GetComponentInParent<PlayerController>();
					}
					catch
					{
					}
					if (playerController != null)
					{
						return;
					}
				}
			}
			catch
			{
			}
			MorphFollow morphFollow = MorphOnRay(transform.position, transform.forward, 40f);
			Vector3 vector = transform.position + transform.forward * 2f;
			if (morphFollow == null || morphFollow.who == null)
			{
				return;
			}
			try
			{
				vector = morphFollow.transform.position + Vector3.up * 0.9f;
			}
			catch
			{
			}
			PlayerController playerController2 = PcFromWho(morphFollow.who);
			if (playerController2 == null)
			{
				return;
			}
			try
			{
				if (_gunCmdShoot == null)
				{
					_gunCmdShoot = AccessTools.Method(typeof(QuotaGun), "CmdShootPlayer");
				}
				if (_gunCmdShoot != null)
				{
					_gunCmdShoot.Invoke(gun, new object[3] { playerController2, transform.forward, vector });
				}
			}
			catch
			{
			}
		}

		internal static bool AllowKnock(PlayerController pc)
		{
			bool flag = PlayerIsMorphed(pc);
			uint num = 0u;
			try
			{
				if (pc != null)
				{
					num = pc.netId;
				}
			}
			catch
			{
			}
			if (flag)
			{
				UnmorphFromKnock(pc);
				_knockGraceNet = num;
				_knockGraceUntil = Time.unscaledTime + 2f;
				return true;
			}
			if (Time.unscaledTime < _knockGraceUntil && (num == 0 || _knockGraceNet == 0 || num == _knockGraceNet))
			{
				return true;
			}
			UnmorphFromKnock(pc);
			return true;
		}

		internal static bool PlayerIsMorphed(PlayerController pc)
		{
			PlayerProfile playerProfile = PcProfile(pc);
			if (playerProfile == null)
			{
				return false;
			}
			if (playerProfile == LocalProfile() && LocalMorphed())
			{
				return true;
			}
			string text = Key(playerProfile);
			Acc acc = Ensure(playerProfile);
			if (acc != null && ServerMorphed(acc.id))
			{
				return true;
			}
			float value;
			if (!string.IsNullOrEmpty(text) && ViewMorphUntil.TryGetValue(text, out value) && value > Time.unscaledTime)
			{
				return true;
			}
			GameObject value2;
			if (!string.IsNullOrEmpty(text) && MorphClone.TryGetValue(text, out value2) && value2 != null)
			{
				return true;
			}
			return false;
		}

		internal static void TryMorphNpc(PlayerProfile thief, uint npcNet)
		{
			if (!NetworkServer.active || thief == null)
			{
				return;
			}
			Acc acc = Ensure(thief);
			if (!IsThief(acc))
			{
				NotifyMoney(acc, "只有小偷能伪装", 2);
				return;
			}
			if (ServerMorphed(acc.id))
			{
				NotifyMoney(acc, "已经在伪装中", 2);
				return;
			}
			float value;
			if (MorphCool.TryGetValue(acc.id, out value) && Time.unscaledTime < value)
			{
				NotifyMoney(acc, "伪装冷却中", 2);
				return;
			}
			NPC nPC = NpcFromNetId(npcNet);
			if (nPC == null || nPC.transform == null)
			{
				NotifyMoney(acc, "找不到NPC", 2);
			}
			else if (!(thief.transform == null))
			{
				if (Vector3.Distance(thief.transform.position, nPC.transform.position) > 5.5f)
				{
					NotifyMoney(acc, "离得太远", 2);
					return;
				}
				MorphUntil[acc.id] = Time.unscaledTime + 45f;
				MorphNpc[acc.id] = npcNet;
				BroadcastMorph(acc.id, npcNet, 45f);
			}
		}

		private static bool FaceLookServer(PlayerProfile me, PlayerProfile vic)
		{
			if (me == null || vic == null || me == vic)
			{
				return false;
			}
			Acc acc = Ensure(me);
			if (!IsThief(acc))
			{
				return false;
			}
			if (ServerMorphed(acc.id) && MorphIsPlayerForm(acc.id))
			{
				return false;
			}
			if (me.transform == null || vic.transform == null)
			{
				return false;
			}
			if (!StealZoneOk(me.transform.position) || !StealZoneOk(vic.transform.position))
			{
				return false;
			}
			if (Vector3.Distance(me.transform.position, vic.transform.position) > 5.5f)
			{
				return false;
			}
			if (JobBehind(me, vic))
			{
				return false;
			}
			return JobInFront(me, vic);
		}

		private static void ClearFaceMemAll()
		{
			FaceMem.Clear();
			FaceMemName.Clear();
			FaceMemLook.Clear();
			LocalFaceKey = "";
			LocalFaceName = "";
			if (!NetworkServer.active)
			{
				return;
			}
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value != null && (!(value.identity != null) || !value.identity.isLocalPlayer))
					{
						value.Send(new SoloMsg
						{
							json = "FACE\t\t"
						});
					}
				}
			}
			catch
			{
			}
		}

		private static void SendFaceTo(PlayerProfile p, string name, string key, string look)
		{
			if (!(p == null))
			{
				SendSoloTo(p, "FACE\t" + (name ?? "") + "\t" + (key ?? "") + "\t" + (look ?? ""));
			}
		}

		private static void WriteThiefFace(Acc ta, PlayerProfile thief, string vk, string nm, string look)
		{
			if (ta == null)
			{
				return;
			}
			List<string> list = new List<string>();
			if (!string.IsNullOrEmpty(ta.id))
			{
				list.Add(ta.id);
			}
			if (thief != null)
			{
				string text = Key(thief);
				if (!string.IsNullOrEmpty(text))
				{
					bool flag = false;
					for (int i = 0; i < list.Count; i++)
					{
						if (list[i] == text)
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						list.Add(text);
					}
				}
			}
			for (int j = 0; j < list.Count; j++)
			{
				string key = list[j];
				FaceMem[key] = vk ?? "";
				FaceMemName[key] = nm ?? "";
				FaceMemLook[key] = look ?? "";
			}
			if (!string.IsNullOrEmpty(vk) && !string.IsNullOrEmpty(look))
			{
				LookBook[vk] = look;
			}
			if (thief != null && (AccIsPlayer(ta, LocalProfile()) || thief == LocalProfile()))
			{
				LocalFaceKey = vk ?? "";
				LocalFaceName = nm ?? "";
			}
			SendFaceTo(thief, nm, vk, look);
		}

		internal static void TryRememberFace(PlayerProfile thief, uint victimNet, string victimKey)
		{
			if (!NetworkServer.active || thief == null)
			{
				return;
			}
			Acc acc = Ensure(thief);
			if (!IsThief(acc))
			{
				NotifyMoney(acc, "只有小偷能记住长相", 2);
				return;
			}
			if (ServerMorphed(acc.id) && MorphIsPlayerForm(acc.id))
			{
				NotifyMoney(acc, "伪装中不能记住长相", 2);
				return;
			}
			PlayerProfile playerProfile = ProfileFromNetId(victimNet);
			if (playerProfile == null && !string.IsNullOrEmpty(victimKey))
			{
				playerProfile = FindProfileByKey(victimKey);
			}
			if (playerProfile == null || playerProfile == thief)
			{
				NotifyMoney(acc, "找不到目标", 2);
				return;
			}
			if (!FaceLookServer(thief, playerProfile))
			{
				NotifyMoney(acc, "只能在赌场里、从对方前面记住长相", 2);
				return;
			}
			string text = Key(playerProfile);
			string text2 = playerProfile.playerName ?? "";
			if (string.IsNullOrEmpty(text2))
			{
				Acc acc2 = Ensure(playerProfile);
				if (acc2 != null)
				{
					text2 = acc2.name ?? "";
				}
			}
			if (string.IsNullOrEmpty(text) || string.IsNullOrEmpty(text2))
			{
				NotifyMoney(acc, "找不到目标", 2);
				return;
			}
			string look = CaptureLook(playerProfile);
			WriteThiefFace(acc, thief, text, text2, look);
		}

		internal static void TryMorphRemembered(PlayerProfile thief)
		{
			TryMorphRemembered(thief, "", "");
		}

		internal static void TryMorphRemembered(PlayerProfile thief, string extraK, string extraL)
		{
			if (!NetworkServer.active || thief == null || DayStatsOpen || EconomyFrozen())
			{
				return;
			}
			Acc acc = Ensure(thief);
			if (!IsThief(acc) && GetJob(thief) != 3)
			{
				NotifyMoney(acc, "只有小偷能伪装", 2);
				return;
			}
			if (ServerMorphed(acc.id))
			{
				NotifyMoney(acc, "已经在伪装中", 2);
				return;
			}
			float value;
			if (MorphCool.TryGetValue(acc.id, out value) && Time.unscaledTime < value)
			{
				NotifyMoney(acc, "伪装冷却中", 2);
				return;
			}
			string value2 = "";
			string value3 = "";
			if (!FaceMem.TryGetValue(acc.id, out value2) || string.IsNullOrEmpty(value2))
			{
				string text = Key(thief);
				if (!string.IsNullOrEmpty(text))
				{
					FaceMem.TryGetValue(text, out value2);
				}
			}
			if (!FaceMemName.TryGetValue(acc.id, out value3) || string.IsNullOrEmpty(value3))
			{
				string text2 = Key(thief);
				if (!string.IsNullOrEmpty(text2))
				{
					FaceMemName.TryGetValue(text2, out value3);
				}
			}
			if ((string.IsNullOrEmpty(value2) || string.IsNullOrEmpty(value3)) && !string.IsNullOrEmpty(extraK))
			{
				value2 = extraK;
				PlayerProfile playerProfile = ResolveMorphProfile(extraK);
				if (playerProfile == null)
				{
					playerProfile = FindProfileByKey(extraK);
				}
				if (playerProfile != null && string.IsNullOrEmpty(value3))
				{
					value3 = playerProfile.playerName ?? "";
				}
			}
			if (string.IsNullOrEmpty(value2) || string.IsNullOrEmpty(value3))
			{
				NotifyMoney(acc, "还没有记住长相", 2);
				return;
			}
			PlayerProfile playerProfile2 = ResolveMorphProfile(value2);
			if (playerProfile2 == null)
			{
				playerProfile2 = FindProfileByKey(value2);
			}
			string value4 = "";
			FaceMemLook.TryGetValue(acc.id, out value4);
			if (string.IsNullOrEmpty(value4))
			{
				string text3 = Key(thief);
				if (!string.IsNullOrEmpty(text3))
				{
					FaceMemLook.TryGetValue(text3, out value4);
				}
			}
			if (string.IsNullOrEmpty(value4) && !string.IsNullOrEmpty(extraL))
			{
				value4 = extraL;
			}
			if (playerProfile2 != null)
			{
				string text4 = CaptureLook(playerProfile2);
				if (!string.IsNullOrEmpty(text4))
				{
					value4 = text4;
				}
			}
			if (string.IsNullOrEmpty(value4) && !string.IsNullOrEmpty(value2))
			{
				LookBook.TryGetValue(value2, out value4);
			}
			if (string.IsNullOrEmpty(value4))
			{
				NotifyMoney(acc, "找不到目标", 2);
				return;
			}
			uint num = ((playerProfile2 != null) ? NetIdOf(playerProfile2) : 0u);
			MorphUntil[acc.id] = Time.unscaledTime + 45f;
			MorphNpc[acc.id] = num;
			MorphFaceOf[acc.id] = value2;
			FaceMemLook[acc.id] = value4;
			BroadcastMorph(acc.id, num, 45f, value2, value3, value4);
		}

		internal static void OnDayStatsShown()
		{
			DayStatsOpen = true;
			StripPlayerMorphs();
		}

		internal static void OnDayStarted()
		{
			DayStatsOpen = false;
			try
			{
				string selfKey = Key(LocalProfile());
				if (!string.IsNullOrEmpty(selfKey))
				{
					ApplyMorphView(selfKey, 0u, 0f);
				}
			}
			catch
			{
			}
			LocalMorphUntil = 0f;
			LocalMorphSpeed = 0f;
			LocalMorphPlayer = false;
			ForceRestoreLocalMove();
		}

		private static void StripPlayerMorphs()
		{
			if (LocalMorphPlayer)
			{
				string text = Key(LocalProfile());
				if (string.IsNullOrEmpty(text))
				{
					Acc acc = LocalAccRow();
					if (acc != null)
					{
						text = acc.id;
					}
				}
				if (!string.IsNullOrEmpty(text))
				{
					ApplyMorphView(text, 0u, 0f);
				}
				else
				{
					LocalMorphUntil = 0f;
					LocalMorphSpeed = 0f;
					LocalMorphPlayer = false;
				}
			}
			if (!NetworkServer.active)
			{
				return;
			}
			List<string> list = new List<string>();
			foreach (KeyValuePair<string, string> item in MorphFaceOf)
			{
				if (item.Value != null && item.Value.Length != 0)
				{
					list.Add(item.Key);
				}
			}
			for (int i = 0; i < list.Count; i++)
			{
				string k = list[i];
				Acc ta = FindAccByKey(k);
				PlayerProfile thief = FindProfileByKey(k);
				UnmorphThief(ta, thief, false);
			}
		}

		internal static void TickMorphWindow()
		{
			if (DayStatsOpen || EconomyFrozen())
			{
				if (LocalMorphPlayer && (LocalMorphed() || LocalMorphUntil > Time.unscaledTime))
				{
					StripPlayerMorphs();
				}
				else if (NetworkServer.active && Time.frameCount % 20 == 0)
				{
					StripPlayerMorphs();
				}
			}
			float unscaledTime = Time.unscaledTime;
			if (NetworkServer.active)
			{
				List<string> list = null;
				foreach (KeyValuePair<string, float> item in MorphUntil)
				{
					if (!(item.Value > unscaledTime))
					{
						if (list == null)
						{
							list = new List<string>();
						}
						list.Add(item.Key);
					}
				}
				if (list != null)
				{
					for (int i = 0; i < list.Count; i++)
					{
						Acc ta = FindAccByKey(list[i]);
						PlayerProfile thief = FindProfileByKey(list[i]);
						UnmorphThief(ta, thief, true);
					}
				}
			}
			if (unscaledTime >= _morphRagAt)
			{
				_morphRagAt = unscaledTime + 0.2f;
				TickMorphRagdoll();
			}
		}

		private static void TickMorphRagdoll()
		{
			List<string> list = new List<string>();
			foreach (KeyValuePair<string, float> item in MorphUntil)
			{
				list.Add(item.Key);
			}
			foreach (KeyValuePair<string, float> item2 in ViewMorphUntil)
			{
				list.Add(item2.Key);
			}
			foreach (KeyValuePair<string, GameObject> item3 in MorphClone)
			{
				list.Add(item3.Key);
			}
			if (LocalMorphed())
			{
				string text = Key(LocalProfile());
				if (!string.IsNullOrEmpty(text))
				{
					list.Add(text);
				}
			}
			for (int i = 0; i < list.Count; i++)
			{
				string text2 = list[i];
				if (string.IsNullOrEmpty(text2))
				{
					continue;
				}
				bool flag = false;
				for (int j = 0; j < i; j++)
				{
					if (list[j] == text2)
					{
						flag = true;
						break;
					}
				}
				if (flag)
				{
					continue;
				}
				PlayerProfile playerProfile = FindProfileByKey(text2);
				if (playerProfile == null)
				{
					continue;
				}
				PlayerController playerController = null;
				try
				{
					playerController = playerProfile.GetComponent<PlayerController>();
				}
				catch
				{
				}
				if (playerController == null)
				{
					try
					{
						playerController = playerProfile.GetComponentInParent<PlayerController>();
					}
					catch
					{
					}
				}
				if (playerController == null)
				{
					try
					{
						playerController = playerProfile.GetComponentInChildren<PlayerController>();
					}
					catch
					{
					}
				}
				if (!(playerController == null))
				{
					PlayerController.PlayerState state;
					try
					{
						state = playerController.State;
					}
					catch
					{
						continue;
					}
					if (state == PlayerController.PlayerState.Ragdoll)
					{
						UnmorphFromKnock(playerController);
					}
				}
			}
		}

