		private static PlayerInventory InvOf(PlayerProfile p)
		{
			if (p == null)
			{
				return null;
			}
			PlayerInventory playerInventory = p.GetComponent<PlayerInventory>();
			if (playerInventory == null)
			{
				playerInventory = p.GetComponentInChildren<PlayerInventory>();
			}
			if (playerInventory == null)
			{
				playerInventory = p.GetComponentInParent<PlayerInventory>();
			}
			if (playerInventory != null)
			{
				return playerInventory;
			}
			PlayerController playerController = p.GetComponent<PlayerController>();
			if (playerController == null)
			{
				playerController = p.GetComponentInChildren<PlayerController>();
			}
			if (playerController == null)
			{
				playerController = p.GetComponentInParent<PlayerController>();
			}
			if (playerController == null)
			{
				return null;
			}
			return playerController.GetComponent<PlayerInventory>() ?? playerController.GetComponentInChildren<PlayerInventory>();
		}

		private static PlayerProfile CarriedBy(PlayerProfile holder)
		{
			PlayerInventory playerInventory = InvOf(holder);
			if (playerInventory == null)
			{
				return null;
			}
			Item item = playerInventory.holdingItem;
			if (item == null)
			{
				item = playerInventory.NetworkholdingItem;
			}
			if (item == null)
			{
				return null;
			}
			PlayerCarry playerCarry = item as PlayerCarry;
			if (playerCarry == null)
			{
				playerCarry = item.GetComponent<PlayerCarry>();
			}
			if (playerCarry == null)
			{
				return null;
			}
			if (_carryPcF == null)
			{
				_carryPcF = AccessTools.Field(typeof(PlayerCarry), "_pc");
			}
			PlayerController playerController = null;
			try
			{
				if (_carryPcF != null)
				{
					playerController = _carryPcF.GetValue(playerCarry) as PlayerController;
				}
			}
			catch
			{
			}
			if (playerController == null)
			{
				try
				{
					playerController = playerCarry.GetComponent<PlayerController>();
				}
				catch
				{
				}
				if (playerController == null)
				{
					try
					{
						playerController = playerCarry.GetComponentInChildren<PlayerController>(true);
					}
					catch
					{
					}
				}
				if (playerController == null)
				{
					try
					{
						playerController = playerCarry.GetComponentInParent<PlayerController>();
					}
					catch
					{
					}
				}
			}
			if (playerController != null)
			{
				return playerController.GetComponent<PlayerProfile>() ?? playerController.GetComponentInParent<PlayerProfile>() ?? playerController.GetComponentInChildren<PlayerProfile>();
			}
			try
			{
				return playerCarry.GetComponentInParent<PlayerProfile>() ?? playerCarry.GetComponentInChildren<PlayerProfile>(true);
			}
			catch
			{
			}
			return null;
		}

		private static bool IsChaseThief(PlayerProfile thief)
		{
			if (thief == null)
			{
				return false;
			}
			RefreshChaseView();
			string text = Key(thief);
			Acc acc = Ensure(thief);
			if (acc != null && !string.IsNullOrEmpty(acc.id) && ViewChaseUntil.ContainsKey(acc.id))
			{
				return true;
			}
			if (!string.IsNullOrEmpty(text) && ViewChaseUntil.ContainsKey(text))
			{
				return true;
			}
			if (!string.IsNullOrEmpty(_stealCdKey) && text == _stealCdKey)
			{
				return true;
			}
			if (!string.IsNullOrEmpty(StealChaseKey) && text == StealChaseKey)
			{
				return true;
			}
			if (acc != null && !string.IsNullOrEmpty(acc.name) && ViewChaseName.ContainsValue(acc.name))
			{
				return true;
			}
			if (!string.IsNullOrEmpty(_stealCdName) && thief.playerName == _stealCdName)
			{
				return true;
			}
			if (!string.IsNullOrEmpty(StealChaseName) && thief.playerName == StealChaseName)
			{
				return true;
			}
			return false;
		}

		public static bool RecoverPromptOk(PlayerProfile me, PlayerProfile thief)
		{
			if (me == null || thief == null || me == thief)
			{
				return false;
			}
			if (ProfileLooksMorphed(thief))
			{
				return false;
			}
			if (me.transform == null || thief.transform == null)
			{
				return false;
			}
			if (Vector3.Distance(me.transform.position, thief.transform.position) > 6f)
			{
				return false;
			}
			if (LocalJob == 3 || GetJob(me) == 3)
			{
				return false;
			}
			if (IsGuard(thief))
			{
				return false;
			}
			if (IsStealVictimLook(thief))
			{
				return false;
			}
			if (!IsChaseThief(thief))
			{
				return false;
			}
			if (_stealCdRole == 2 && Time.unscaledTime < _stealCdUntil)
			{
				Acc acc = Ensure(thief);
				if (acc != null && !string.IsNullOrEmpty(_stealCdKey) && acc.id == _stealCdKey)
				{
					return true;
				}
				if (!string.IsNullOrEmpty(_stealCdName) && thief.playerName == _stealCdName)
				{
					return true;
				}
			}
			if (LocalJob == 4 && me == LocalProfile())
			{
				return true;
			}
			if (GetJob(me) == 4)
			{
				return true;
			}
			return false;
		}

