		private static void NoteStealCoolHint()
		{
			float num = StealSkillCoolLeft();
			if (num <= 0.02f)
			{
				return;
			}
			float unscaledTime = Time.unscaledTime;
			if (!(unscaledTime < _stealCoolHintAt + 0.4f) || !_stealCoolDinged)
			{
				_stealCoolHintAt = unscaledTime;
				int num2 = Mathf.CeilToInt(num);
				if (num2 < 1)
				{
					num2 = 1;
				}
				bool ding = !_stealCoolDinged;
				_stealCoolDinged = true;
				ShowPayToast("技能冷却中 " + num2 + "秒", 2, ding);
			}
		}

		public static float DayTimeLeft()
		{
			try
			{
				GameManager instance = NetworkSingleton<GameManager>.Instance;
				if (instance == null)
				{
					return 999f;
				}
				float num = 0f;
				try
				{
					num = instance.RoundTimerRemaining;
				}
				catch
				{
				}
				if (num <= 0.01f)
				{
					try
					{
						num = instance.Network_timer;
					}
					catch
					{
					}
				}
				if (num <= 0.01f)
				{
					return 999f;
				}
				return num;
			}
			catch
			{
				return 0f;
			}
		}

		internal static PlayerProfile ProfileFromNetId(uint nid)
		{
			if (nid == 0)
			{
				return null;
			}
			try
			{
				NetworkIdentity value;
				if (NetworkServer.spawned != null && NetworkServer.spawned.TryGetValue(nid, out value) && value != null)
				{
					PlayerProfile playerProfile = ProfileFromIdentity(value);
					if (playerProfile != null)
					{
						return playerProfile;
					}
					playerProfile = value.GetComponent<PlayerProfile>() ?? value.GetComponentInChildren<PlayerProfile>();
					if (playerProfile != null)
					{
						return playerProfile;
					}
				}
			}
			catch
			{
			}
			try
			{
				PlayerProfile[] array = UnityEngine.Object.FindObjectsByType<PlayerProfile>(FindObjectsSortMode.None);
				if (array == null)
				{
					return null;
				}
				PlayerProfile[] array2 = array;
				foreach (PlayerProfile playerProfile2 in array2)
				{
					if (!(playerProfile2 == null))
					{
						NetworkIdentity networkIdentity = playerProfile2.netIdentity;
						if (networkIdentity == null)
						{
							networkIdentity = playerProfile2.GetComponent<NetworkIdentity>();
						}
						if (networkIdentity == null)
						{
							networkIdentity = playerProfile2.GetComponentInParent<NetworkIdentity>();
						}
						if (networkIdentity != null && networkIdentity.netId == nid)
						{
							return playerProfile2;
						}
					}
				}
			}
			catch
			{
			}
			return null;
		}

		internal static void SendJobCd(PlayerProfile p, int role, float sec, string other, string otherKey)
		{
			if (p == null)
			{
				return;
			}
			Acc a = Ensure(p);
			string json = "SCD\t" + role + "\t" + sec.ToString("R", CultureInfo.InvariantCulture) + "\t" + (other ?? "").Replace('\t', ' ') + "\t" + (otherKey ?? "").Replace('\t', ' ');
			if (AccIsPlayer(a, LocalProfile()))
			{
				_stealCdRole = role;
				_stealCdName = other ?? "";
				_stealCdKey = otherKey ?? "";
				_stealCdUntil = ((role <= 0 || sec <= 0.01f) ? 0f : (Time.unscaledTime + sec));
				_stealTickSec = -1;
			}
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value != null && !(value.identity == null))
					{
						PlayerProfile p2 = ProfileFromIdentity(value.identity);
						if (AccIsPlayer(a, p2) && !value.identity.isLocalPlayer)
						{
							value.Send(new SoloMsg
							{
								json = json
							});
						}
					}
				}
			}
			catch
			{
			}
		}

