		internal static void TryJobSteal(PlayerProfile thief, uint victimNet, string victimKey)
		{
			if (!NetworkServer.active || thief == null)
			{
				return;
			}
			Acc acc = Ensure(thief);
			if (!IsThief(acc))
			{
				NotifyMoney(acc, "只有小偷能偷钱", 2);
				return;
			}
			float value = 0f;
			if (StealCool.TryGetValue(acc.id, out value) && Time.unscaledTime < value)
			{
				NotifyMoney(acc, "技能冷却中 " + Mathf.CeilToInt(value - Time.unscaledTime) + "秒", 2);
			}
			else if (FindStealRun(acc, thief) != null)
			{
				NotifyMoney(acc, "追捕还没结束", 2);
			}
			else if (DayTimeLeft() <= 33.01f)
			{
				NotifyMoney(acc, "白天剩余时间不足，不能偷", 2);
			}
			else
			{
				if (thief.transform == null)
				{
					return;
				}
				if (!StealZoneOk(thief.transform.position))
				{
					NotifyMoney(acc, "只能在赌场里偷", 2);
					return;
				}
				PlayerProfile playerProfile = ProfileFromNetId(victimNet);
				if (playerProfile == null && !string.IsNullOrEmpty(victimKey))
				{
					playerProfile = FindProfileByKey(victimKey);
				}
				if (playerProfile == null || playerProfile == thief)
				{
					NotifyMoney(acc, "找不到目标", 2);
					return;
				}
				Acc acc2 = Ensure(playerProfile);
				if (acc2 == null || acc == null || playerProfile.transform == null)
				{
					return;
				}
				if (!StealZoneOk(playerProfile.transform.position))
				{
					NotifyMoney(acc, "对方不在赌场", 2);
					return;
				}
				float num = Vector3.Distance(thief.transform.position, playerProfile.transform.position);
				if (num > 5.5f)
				{
					NotifyMoney(acc, "离得太远", 2);
					return;
				}
				if (!JobBehind(thief, playerProfile))
				{
					NotifyMoney(acc, "必须从背后偷", 2);
					return;
				}
				if (acc2.money < 1.0)
				{
					NotifyMoney(acc, "对方没有现金", 2);
					return;
				}
				int num2 = UnityEngine.Random.Range(5, 31);
				double num3 = acc2.money * (double)num2 / 100.0;
				if (!(num3 < 0.01))
				{
					if (num3 > acc2.money)
					{
						num3 = acc2.money;
					}
					StealRun stealRun = new StealRun();
					stealRun.thief = acc.id;
					stealRun.victim = acc2.id;
					stealRun.thiefName = (string.IsNullOrEmpty(acc.name) ? "玩家" : acc.name);
					stealRun.amt = num3;
					stealRun.pct = num2;
					stealRun.warnAt = Time.unscaledTime + 3f;
					stealRun.until = Time.unscaledTime + 33f;
					stealRun.warned = false;
					stealRun.npc = false;
					stealRun.boss = IsBoss(acc2);
					stealRun.cool = 60f;
					StealRuns[acc.id] = stealRun;
					string text = (string.IsNullOrEmpty(acc2.name) ? "玩家" : acc2.name);
					string text2 = MoneyDollar(num3);
					NotifyMoney(acc, "你偷走了" + text + text2 + "的现金", 1);
					if (stealRun.boss)
					{
						_bossRobber = acc.id ?? "";
					}
				}
			}
		}

		internal static void TryJobStealNpc(PlayerProfile thief, uint npcNet)
		{
			if (!NetworkServer.active || thief == null)
			{
				return;
			}
			Acc acc = Ensure(thief);
			if (!IsThief(acc))
			{
				NotifyMoney(acc, "只有小偷能偷钱", 2);
				return;
			}
			float value = 0f;
			if (StealCool.TryGetValue(acc.id, out value) && Time.unscaledTime < value)
			{
				NotifyMoney(acc, "技能冷却中 " + Mathf.CeilToInt(value - Time.unscaledTime) + "秒", 2);
			}
			else if (FindStealRun(acc, thief) != null)
			{
				NotifyMoney(acc, "追捕还没结束", 2);
			}
			else if (EconomyFrozen())
			{
				NotifyMoney(acc, "结算日不能偷", 2);
			}
			else if (DayTimeLeft() <= 30.01f)
			{
				NotifyMoney(acc, "白天剩余时间不足，不能偷", 2);
			}
			else
			{
				if (thief.transform == null)
				{
					return;
				}
				if (!StealZoneOk(thief.transform.position))
				{
					NotifyMoney(acc, "只能在赌场里偷", 2);
					return;
				}
				NPC nPC = NpcFromNetId(npcNet);
				if (nPC == null || nPC.transform == null)
				{
					NotifyMoney(acc, "找不到NPC", 2);
					return;
				}
				if (!StealZoneOk(nPC.transform.position))
				{
					NotifyMoney(acc, "NPC不在赌场", 2);
					return;
				}
				float num = Vector3.Distance(thief.transform.position, nPC.transform.position);
				if (num > 5.5f)
				{
					NotifyMoney(acc, "离得太远", 2);
					return;
				}
				if (!JobBehindNpc(thief, nPC))
				{
					NotifyMoney(acc, "必须从背后偷", 2);
					return;
				}
				double num2 = NpcStealRoll();
				if (!(num2 < 0.01))
				{
					StealRun stealRun = new StealRun();
					stealRun.thief = acc.id;
					stealRun.victim = "npc";
					stealRun.thiefName = (string.IsNullOrEmpty(acc.name) ? "玩家" : acc.name);
					stealRun.amt = num2;
					stealRun.pct = 0;
					stealRun.until = Time.unscaledTime + 30f;
					stealRun.warnAt = 0f;
					stealRun.warned = true;
					stealRun.npc = true;
					stealRun.boss = false;
					stealRun.cool = 30f;
					stealRun.npcNet = npcNet;
					StealRuns[acc.id] = stealRun;
					string thiefName = stealRun.thiefName;
					NotifyMoney(acc, "从NPC偷到" + MoneyDollar(num2) + "，跑完倒计时才到账", 1);
					SendJobCd(thief, 1, 30f, "NPC", "npc");
					BroadcastGuardCatchMark(acc.id, thiefName, 30f);
					BroadcastNpcMark(npcNet, 2f, 30f);
					Broadcast();
				}
			}
		}

		private static void StartStealCool(string thiefId, PlayerProfile thief, float sec)
		{
			if (sec < 1f)
			{
				sec = 30f;
			}
			if (thief == null && !string.IsNullOrEmpty(thiefId))
			{
				thief = FindProfileByKey(thiefId);
			}
			if (thief == null && !string.IsNullOrEmpty(thiefId))
			{
				try
				{
					List<PlayerProfile> list = PresentProfiles();
					if (list != null)
					{
						for (int i = 0; i < list.Count; i++)
						{
							Acc acc = Ensure(list[i]);
							if (acc != null && acc.id == thiefId)
							{
								thief = list[i];
								break;
							}
						}
					}
				}
				catch
				{
				}
			}
			Acc acc2 = ((thief != null) ? Ensure(thief) : null);
			if (string.IsNullOrEmpty(thiefId) && acc2 != null)
			{
				thiefId = acc2.id;
			}
			if (!string.IsNullOrEmpty(thiefId))
			{
				StealCool[thiefId] = Time.unscaledTime + sec;
			}
			if (acc2 != null && !string.IsNullOrEmpty(acc2.id) && acc2.id != thiefId)
			{
				StealCool[acc2.id] = Time.unscaledTime + sec;
			}
			if (thief != null)
			{
				string text = Key(thief);
				if (!string.IsNullOrEmpty(text))
				{
					StealCool[text] = Time.unscaledTime + sec;
				}
				if (thief.steamId != 0)
				{
					StealCool["s" + thief.steamId] = Time.unscaledTime + sec;
				}
			}
			if (thief != null)
			{
				SendThiefCool(thief, sec);
			}
		}

		private static float StealCoolLeft(PlayerProfile p)
		{
			if (p == null)
			{
				return 0f;
			}
			Acc acc = Ensure(p);
			float num = 0f;
			float unscaledTime = Time.unscaledTime;
			float value;
			if (acc != null && !string.IsNullOrEmpty(acc.id) && StealCool.TryGetValue(acc.id, out value) && value > num)
			{
				num = value;
			}
			string text = Key(p);
			if (!string.IsNullOrEmpty(text) && StealCool.TryGetValue(text, out value) && value > num)
			{
				num = value;
			}
			if (num <= unscaledTime)
			{
				return 0f;
			}
			return num - unscaledTime;
		}

		private static void EndStealChase(StealRun run, bool startCool)
		{
			if (run == null)
			{
				return;
			}
			string thief = run.thief;
			string victim = run.victim;
			float sec = (run.npc ? 30f : 60f);
			if (run.cool > 1f)
			{
				sec = run.cool;
			}
			if (!string.IsNullOrEmpty(thief))
			{
				StealRuns.Remove(thief);
			}
			PlayerProfile playerProfile = FindProfileByKey(thief);
			PlayerProfile playerProfile2 = ((victim == "npc") ? null : FindProfileByKey(victim));
			try
			{
				List<PlayerProfile> list = PresentProfiles();
				if (list != null)
				{
					for (int i = 0; i < list.Count; i++)
					{
						Acc acc = Ensure(list[i]);
						if (acc != null)
						{
							if (playerProfile == null && acc.id == thief)
							{
								playerProfile = list[i];
							}
							if (playerProfile2 == null && acc.id == victim)
							{
								playerProfile2 = list[i];
							}
						}
					}
				}
			}
			catch
			{
			}
			if (run.npc)
			{
				BroadcastGuardCatchMark(thief, "", 0f);
			}
			else
			{
				BroadcastChase(thief, "", 0f);
			}
			if (run.npc && run.npcNet != 0)
			{
				BroadcastNpcMark(run.npcNet, 0f, 0f);
			}
			if (playerProfile != null)
			{
				SendJobCd(playerProfile, 0, 0f, "", "");
			}
			if (playerProfile2 != null)
			{
				StealRun stealRun = FindStealRunByVictim(victim);
				if (stealRun != null)
				{
					float num = stealRun.until - Time.unscaledTime;
					if (num < 0.05f)
					{
						num = 0.05f;
					}
					SendJobCd(playerProfile2, 2, num, stealRun.thiefName, stealRun.thief);
				}
				else
				{
					SendJobCd(playerProfile2, 0, 0f, "", "");
				}
			}
			if (startCool)
			{
				StartStealCool(thief, playerProfile, sec);
			}
		}

		private static void WarnVictimSteal(StealRun run)
		{
			if (run == null || run.npc || run.warned)
			{
				return;
			}
			Acc acc = FindAccByKey(run.victim);
			if (acc == null && !string.IsNullOrEmpty(run.victim) && Accs.ContainsKey(run.victim))
			{
				acc = Accs[run.victim];
			}
			if (acc == null)
			{
				run.warned = true;
				return;
			}
			double num = run.amt;
			if (num > acc.money)
			{
				num = acc.money;
			}
			if (num < 0.0)
			{
				num = 0.0;
			}
			run.amt = num;
			acc.money -= num;
			if (acc.money < 0.0)
			{
				acc.money = 0.0;
			}
			run.warned = true;
			run.until = Time.unscaledTime + 30f;
			NotifyMoney(acc, "你的钱被偷了-" + MoneyDollar(num) + "！！！", 0);
			PlayerProfile playerProfile = FindProfileByKey(run.thief);
			PlayerProfile playerProfile2 = FindProfileByKey(run.victim);
			string thiefName = run.thiefName;
			string other = (string.IsNullOrEmpty(acc.name) ? "玩家" : acc.name);
			if (playerProfile2 != null)
			{
				SendAlarm(playerProfile2);
			}
			if (playerProfile != null)
			{
				SendJobCd(playerProfile, 1, 30f, other, acc.id);
			}
			if (playerProfile2 != null)
			{
				SendJobCd(playerProfile2, 2, 30f, thiefName, run.thief);
			}
			BroadcastChase(run.thief, thiefName, 30f);
			Broadcast();
		}

		private static void CommitStealEscape(StealRun run)
		{
			if (run == null)
			{
				return;
			}
			Acc acc = FindAccByKey(run.thief);
			if (acc == null && !string.IsNullOrEmpty(run.thief) && Accs.ContainsKey(run.thief))
			{
				acc = Accs[run.thief];
			}
			if (acc != null && run.amt > 0.01 && !run.npc && run.warned)
			{
				acc.money += run.amt;
				NotifyMoney(acc, "逃脱成功，赃款 " + MoneyDollar(run.amt) + " 已到账", 1);
			}
			if (acc != null && run.npc && run.amt > 0.01)
			{
				acc.money += run.amt;
				string text = acc.id;
				PlayerProfile playerProfile = FindProfileByKey(text);
				if (playerProfile != null)
				{
					text = Key(playerProfile);
				}
				if (!string.IsNullOrEmpty(text) && _betMoney.ContainsKey(text))
				{
					_betMoney[text] += run.amt;
				}
				NotifyMoney(acc, "逃脱成功，NPC赃款 " + MoneyDollar(run.amt) + " 已到账", 1);
			}
			if (acc != null && run.pct > 0 && !run.npc)
			{
				RefreshGoalDay(acc);
				acc.stealPct += run.pct;
				TouchGoalHud(acc);
			}
			if (run.boss)
			{
				_bossRobbed = true;
				if (string.IsNullOrEmpty(_bossRobber) && acc != null)
				{
					_bossRobber = acc.id ?? "";
				}
				Acc acc2 = FindAccByKey(run.victim);
				if (acc2 == null && !string.IsNullOrEmpty(run.victim) && Accs.ContainsKey(run.victim))
				{
					acc2 = Accs[run.victim];
				}
				if (acc2 != null)
				{
					acc2.robbedDay = SharedDay;
				}
			}
		}

		internal static void TickStealWindow()
		{
			if (!NetworkServer.active)
			{
				return;
			}
			List<StealRun> list = null;
			List<StealRun> list2 = null;
			float unscaledTime = Time.unscaledTime;
			foreach (KeyValuePair<string, StealRun> stealRun in StealRuns)
			{
				StealRun value = stealRun.Value;
				if (value != null && !value.npc && !value.warned && unscaledTime >= value.warnAt)
				{
					if (list == null)
					{
						list = new List<StealRun>();
					}
					list.Add(value);
				}
			}
			if (list != null)
			{
				for (int i = 0; i < list.Count; i++)
				{
					WarnVictimSteal(list[i]);
				}
			}
			foreach (KeyValuePair<string, StealRun> stealRun2 in StealRuns)
			{
				StealRun value2 = stealRun2.Value;
				if (value2 != null && !(unscaledTime < value2.until) && (value2.npc || value2.warned))
				{
					if (list2 == null)
					{
						list2 = new List<StealRun>();
					}
					list2.Add(value2);
				}
			}
			if (list2 != null)
			{
				for (int j = 0; j < list2.Count; j++)
				{
					CommitStealEscape(list2[j]);
					EndStealChase(list2[j], true);
				}
				Broadcast();
			}
		}

