		private static float SampleNpcWalkSpeed(NPC npc)
		{
			if (npc == null)
			{
				return 0f;
			}
			float num = 0f;
			try
			{
				object obj = null;
				try
				{
					PropertyInfo property = typeof(NPC).GetProperty("Agent");
					if (property != null)
					{
						obj = property.GetValue(npc, null);
					}
				}
				catch
				{
				}
				if (obj == null)
				{
					Component[] components = npc.GetComponents<Component>();
					if (components != null)
					{
						for (int i = 0; i < components.Length; i++)
						{
							if (!(components[i] == null) && components[i].GetType().Name == "NavMeshAgent")
							{
								obj = components[i];
								break;
							}
						}
					}
				}
				if (obj != null)
				{
					PropertyInfo property2 = obj.GetType().GetProperty("speed");
					if (property2 != null)
					{
						num = (float)property2.GetValue(obj, null);
					}
					if (num < 0.2f)
					{
						PropertyInfo property3 = obj.GetType().GetProperty("desiredVelocity");
						if (property3 != null)
						{
							float magnitude = ((Vector3)property3.GetValue(obj, null)).magnitude;
							if (magnitude > num)
							{
								num = magnitude;
							}
						}
					}
					if (num < 0.2f)
					{
						PropertyInfo property4 = obj.GetType().GetProperty("velocity");
						if (property4 != null)
						{
							float magnitude2 = ((Vector3)property4.GetValue(obj, null)).magnitude;
							if (magnitude2 > num)
							{
								num = magnitude2;
							}
						}
					}
				}
			}
			catch
			{
			}
			if (num > 6.5f)
			{
				num = 0f;
			}
			return num;
		}

		private static float MorphWalkSpeed(PlayerProfile me)
		{
			uint value = 0u;
			string text = Key(me);
			if (!string.IsNullOrEmpty(text))
			{
				ViewMorphNpc.TryGetValue(text, out value);
				if (value == 0)
				{
					MorphNpc.TryGetValue(text, out value);
				}
			}
			NPC npc = ((value != 0) ? NpcFromNetId(value) : null);
			float num = SampleNpcWalkSpeed(npc);
			if (num >= 0.4f && num <= 6.5f)
			{
				return num;
			}
			if (_npcWalkAvg >= 0.4f && Time.unscaledTime < _npcWalkAvgAt + 8f)
			{
				return _npcWalkAvg;
			}
			try
			{
				NPC[] array = UnityEngine.Object.FindObjectsByType<NPC>(FindObjectsSortMode.None);
				if (array != null)
				{
					float num2 = 0f;
					int num3 = 0;
					for (int i = 0; i < array.Length; i++)
					{
						float num4 = SampleNpcWalkSpeed(array[i]);
						if (!(num4 < 0.4f) && !(num4 > 6.5f))
						{
							num2 += num4;
							num3++;
							if (num3 >= 12)
							{
								break;
							}
						}
					}
					if (num3 > 0)
					{
						_npcWalkAvg = num2 / (float)num3;
						_npcWalkAvgAt = Time.unscaledTime;
						return _npcWalkAvg;
					}
				}
			}
			catch
			{
			}
			return 3.2f;
		}

