		private static void CapMorphVelocity(PlayerController pc, float cap)
		{
			if (pc == null || cap < 0.2f)
			{
				return;
			}
			try
			{
				if (_pcRbF == null)
				{
					_pcRbF = AccessTools.Field(typeof(PlayerController), "_rb");
				}
				Rigidbody rigidbody = ((_pcRbF != null) ? (_pcRbF.GetValue(pc) as Rigidbody) : null);
				if (rigidbody == null)
				{
					return;
				}
				Vector3 vector = Vector3.zero;
				PropertyInfo property = rigidbody.GetType().GetProperty("linearVelocity");
				if (property != null)
				{
					vector = (Vector3)property.GetValue(rigidbody, null);
				}
				else
				{
					PropertyInfo property2 = rigidbody.GetType().GetProperty("velocity");
					if (property2 != null)
					{
						vector = (Vector3)property2.GetValue(rigidbody, null);
					}
				}
				Vector3 vector2 = new Vector3(vector.x, 0f, vector.z);
				if (vector2.magnitude <= cap + 0.02f)
				{
					return;
				}
				vector2 = vector2.normalized * cap;
				vector.x = vector2.x;
				vector.z = vector2.z;
				if (property != null)
				{
					property.SetValue(rigidbody, vector, null);
					return;
				}
				PropertyInfo property3 = rigidbody.GetType().GetProperty("velocity");
				if (property3 != null)
				{
					property3.SetValue(rigidbody, vector, null);
				}
			}
			catch
			{
			}
		}

		internal static void StampMorphPs(PlayerController pc)
		{
			if (pc == null)
			{
				return;
			}
			PlayerProfile playerProfile = PcProfile(pc);
			if (playerProfile == null || playerProfile != LocalProfile())
			{
				return;
			}
			if (_pcSettingsF == null)
			{
				_pcSettingsF = AccessTools.Field(typeof(PlayerController), "_ps");
			}
			if (_pcSettingsF == null)
			{
				return;
			}
			PlayerSettings playerSettings = null;
			try
			{
				playerSettings = _pcSettingsF.GetValue(pc) as PlayerSettings;
			}
			catch
			{
			}
			if (playerSettings == null)
			{
				return;
			}
			if (LocalMorphed() && !LocalMorphPlayer)
			{
				if (_psSavedMax < 0f || _psSavedOn != playerSettings)
				{
					_psSavedOn = playerSettings;
					_psSavedMax = playerSettings.maxSpeed;
					_psSavedSprint = playerSettings.sprintMaxSpeed;
					_psSavedCrouch = playerSettings.crouchMaxSpeed;
					_psSavedRoll = playerSettings.rollMaxSpeed;
					_psSavedAcc = playerSettings.acceleration;
					_psSavedJump = playerSettings.jumpForce;
				}
				float num = LocalMorphSpeed;
				if (num < 0.4f)
				{
					num = MorphWalkSpeed(playerProfile);
				}
				if (num < 0.4f)
				{
					num = 3.2f;
				}
				float num2 = num * 1.14f;
				float num3 = num * 2f;
				bool flag = false;
				try
				{
					flag = pc.State == PlayerController.PlayerState.Ragdoll;
				}
				catch
				{
				}
				if (!flag)
				{
					playerSettings.maxSpeed = num2;
					playerSettings.sprintMaxSpeed = num3;
					playerSettings.crouchMaxSpeed = num2;
					playerSettings.rollMaxSpeed = num2;
					float num4 = _psSavedMax;
					if (num4 < 0.5f)
					{
						num4 = 5f;
					}
					playerSettings.acceleration = _psSavedAcc * (num3 / num4);
					if (playerSettings.acceleration < 6f)
					{
						playerSettings.acceleration = 6f;
					}
					playerSettings.jumpForce = 0f;
					CapMorphVelocity(pc, num3);
				}
			}
			else if (_psSavedMax >= 0f && _psSavedOn == playerSettings)
			{
				playerSettings.maxSpeed = _psSavedMax;
				playerSettings.sprintMaxSpeed = _psSavedSprint;
				playerSettings.crouchMaxSpeed = _psSavedCrouch;
				playerSettings.rollMaxSpeed = _psSavedRoll;
				playerSettings.acceleration = _psSavedAcc;
				playerSettings.jumpForce = _psSavedJump;
				_psSavedMax = -1f;
				_psSavedOn = null;
			}
		}

