		internal static void TryRefundSteal(PlayerProfile shooter, PlayerProfile hit)
		{
			if (!NetworkServer.active || shooter == null || hit == null)
			{
				return;
			}
			Acc acc = Ensure(shooter);
			Acc acc2 = Ensure(hit);
			if (acc == null || acc2 == null)
			{
				return;
			}
			StealRun stealRun = FindStealRun(acc2, hit);
			if (stealRun == null || stealRun.npc || stealRun.until <= Time.unscaledTime || acc.id != stealRun.victim)
			{
				return;
			}
			Acc acc3 = null;
			Acc acc4 = acc;
			if (Accs.ContainsKey(stealRun.thief))
			{
				acc3 = Accs[stealRun.thief];
			}
			if (acc3 != null)
			{
				double num = stealRun.amt;
				if (num > acc3.money)
				{
					num = acc3.money;
				}
				acc3.money -= num;
				acc4.money += num;
				string text = (string.IsNullOrEmpty(acc3.name) ? "玩家" : acc3.name);
				NotifyMoney(acc4, "手枪打中了" + text + "，现金已追回", 1);
				NotifyMoney(acc3, "被手枪打中，赃款已退回", 0);
				EndStealChase(stealRun, true);
				Broadcast();
			}
		}

		internal static void TryGrabSteal(PlayerProfile grabber, uint thiefNet, string thiefKey)
		{
			if (!NetworkServer.active || grabber == null)
			{
				return;
			}
			PlayerProfile playerProfile = ProfileFromNetId(thiefNet);
			if (playerProfile == null && !string.IsNullOrEmpty(thiefKey))
			{
				playerProfile = FindProfileByKey(thiefKey);
			}
			if (playerProfile == null || playerProfile == grabber)
			{
				NotifyMoney(Ensure(grabber), "找不到小偷", 2);
				return;
			}
			Acc acc = Ensure(grabber);
			Acc acc2 = Ensure(playerProfile);
			if (acc == null || acc2 == null)
			{
				return;
			}
			StealRun stealRun = FindStealRun(acc2, playerProfile);
			if (stealRun == null || Time.unscaledTime >= stealRun.until)
			{
				NotifyMoney(acc, "已经超过30秒，不能拿回了", 2);
			}
			else
			{
				if (grabber.transform == null || playerProfile.transform == null)
				{
					return;
				}
				PlayerProfile playerProfile2 = CarriedBy(grabber);
				if ((!(playerProfile2 != null) || (!(playerProfile2 == playerProfile) && (string.IsNullOrEmpty(Key(playerProfile)) || !(Key(playerProfile2) == Key(playerProfile))) && (string.IsNullOrEmpty(playerProfile.playerName) || !(playerProfile2.playerName == playerProfile.playerName)))) && Vector3.Distance(grabber.transform.position, playerProfile.transform.position) > 2.75f)
				{
					NotifyMoney(acc, "离得太远", 2);
					return;
				}
				if (stealRun.npc)
				{
					if (!IsGuard(acc) && GetJob(grabber) != 4)
					{
						NotifyMoney(acc, "只有保安能抓住", 2);
						return;
					}
					Acc a = (Accs.ContainsKey(stealRun.thief) ? Accs[stealRun.thief] : acc2);
					double num = stealRun.amt;
					if (num < 0.0)
					{
						num = 0.0;
					}
					acc.money += num;
					acc.catches++;
					if (AccIsPlayer(acc, LocalProfile()))
					{
						LocalCatches = acc.catches;
					}
					SendCatchCount(acc);
					NotifyMoney(acc, "抓住小偷，NPC赃款 " + MoneyDollar(num), 1);
					NotifyMoney(a, "被保安抓住，NPC赃款没有到账", 0);
					EndStealChase(stealRun, true);
					Broadcast();
					return;
				}
				Acc value = null;
				Acc value2 = null;
				if (!string.IsNullOrEmpty(stealRun.victim))
				{
					Accs.TryGetValue(stealRun.victim, out value);
				}
				if (!string.IsNullOrEmpty(stealRun.thief))
				{
					Accs.TryGetValue(stealRun.thief, out value2);
				}
				if (acc.id != stealRun.victim && !AccIsPlayer(value, grabber) && !IsGuard(acc))
				{
					NotifyMoney(acc, "你不是被偷的人", 2);
					return;
				}
				if (acc2.id != stealRun.thief && !AccIsPlayer(value2, playerProfile))
				{
					NotifyMoney(acc, "这不是偷你的人", 2);
					return;
				}
				Acc a2 = (Accs.ContainsKey(stealRun.thief) ? Accs[stealRun.thief] : acc2);
				Acc acc3 = ((value != null) ? value : acc);
				if (!IsGuard(acc) && acc3 != acc)
				{
					acc3 = acc;
				}
				if (IsGuard(acc) && value != null)
				{
					acc3 = value;
				}
				if (!stealRun.warned)
				{
					NotifyMoney(a2, "被抓住，这次没偷到", 0);
					EndStealChase(stealRun, true);
					Broadcast();
					return;
				}
				double num2 = stealRun.amt;
				if (num2 < 0.0)
				{
					num2 = 0.0;
				}
				if (IsGuard(acc) && acc3 != null && acc3 != acc)
				{
					double num3 = num2 * 0.1;
					if (num3 < 0.0)
					{
						num3 = 0.0;
					}
					if (num3 > num2)
					{
						num3 = num2;
					}
					double num4 = num2 - num3;
					acc.money += num3;
					acc3.money += num4;
					acc.catches++;
					if (AccIsPlayer(acc, LocalProfile()))
					{
						LocalCatches = acc.catches;
					}
					SendCatchCount(acc);
					NotifyMoney(acc, "恭喜你抓住了小偷 失主奖励了你" + MoneyDollar(num3), 1);
					NotifyMoney(acc3, "保安追回了你被偷走的钱 并要求你给小费-" + MoneyDollar(num3), 3);
					NotifyMoney(a2, "被保安抓住，赃款没有到账", 0);
				}
				else
				{
					if (acc3 != null)
					{
						acc3.money += num2;
					}
					NotifyMoney(acc3, "拿回了被偷走的现金", 1);
					NotifyMoney(a2, "赃款被拿回了", 0);
				}
				EndStealChase(stealRun, true);
				Broadcast();
			}
		}

