		private static void RefreshZoneCache()
		{
			if (Time.unscaledTime - _zoneAt < 0.25f)
			{
				return;
			}
			_zoneAt = Time.unscaledTime;
			try
			{
				NetworkIdentity localPlayer = NetworkClient.localPlayer;
				if (localPlayer == null)
				{
					_zoneElev = false;
					_zoneCasino = false;
				}
				else
				{
					Vector3 position = localPlayer.transform.position;
					_zoneElev = PlayerInElevator(position);
					_zoneCasino = PlayerOnCasinoFloor(position);
				}
			}
			catch
			{
				_zoneElev = false;
				_zoneCasino = false;
			}
		}

		private static void EnsureShopCache(bool force)
		{
			int num = 0;
			if (_toolLines != null)
			{
				num += _toolLines.Length;
			}
			if (_machLines != null)
			{
				num += _machLines.Length;
			}
			float num2 = ((num > 0) ? 30f : 2f);
			if (force || _shopCacheDay != SharedDay || !(Time.unscaledTime - _shopCacheAt < num2))
			{
				_shopCacheAt = Time.unscaledTime;
				_shopCacheDay = SharedDay;
				if (_zhMap != null)
				{
					_zhMap.Clear();
				}
				_cacheTools = ListByKind(false);
				_cacheMach = ListByKind(true);
				_cacheGames = ListGamePrefabs();
				_toolLines = MakeToolLines(_cacheTools);
				_machLines = MakeMachLines(_cacheMach, _cacheGames);
			}
		}

		private static ShopLine[] MakeToolLines(SpawnableSO[] tools)
		{
			if (tools == null)
			{
				return new ShopLine[0];
			}
			List<ShopLine> list = new List<ShopLine>();
			int num = Math.Min(tools.Length, 48);
			for (int i = 0; i < num; i++)
			{
				SpawnableSO spawnableSO = tools[i];
				if (!(spawnableSO == null) && !ShopHidden(spawnableSO.spawnableName))
				{
					list.Add(new ShopLine
					{
						src = spawnableSO.spawnableName,
						cmd = "I" + spawnableSO.spawnableID,
						cost = BaseToolCost(spawnableSO)
					});
				}
			}
			return list.ToArray();
		}

		private static ShopLine[] MakeMachLines(SpawnableSO[] mach, GameBase[] gpref)
		{
			List<ShopLine> list = new List<ShopLine>();
			List<string> list2 = new List<string>();
			if (mach != null)
			{
				int num = Math.Min(mach.Length, 24);
				for (int i = 0; i < num; i++)
				{
					SpawnableSO spawnableSO = mach[i];
					if (!(spawnableSO == null) && !ShopHidden(spawnableSO.spawnableName))
					{
						string text = Zh(spawnableSO.spawnableName);
						if (!HasName(list2, text))
						{
							list2.Add(text);
							list.Add(new ShopLine
							{
								src = spawnableSO.spawnableName,
								cmd = "G" + spawnableSO.spawnableID,
								cost = MachineCost(spawnableSO, null)
							});
						}
					}
				}
			}
			if (gpref != null)
			{
				int num2 = Math.Min(gpref.Length, 16);
				for (int j = 0; j < num2; j++)
				{
					GameBase gameBase = gpref[j];
					if (gameBase == null)
					{
						continue;
					}
					string text2 = DispGame(gameBase);
					if (ShopHidden(text2))
					{
						continue;
					}
					string text3 = Zh(text2);
					if (!HasName(list2, text3))
					{
						list2.Add(text3);
						int num3 = ShopPriceOverride(text2);
						if (num3 <= 0)
						{
							num3 = 8;
						}
						list.Add(new ShopLine
						{
							src = text2,
							cmd = "P" + text2,
							cost = num3
						});
					}
				}
			}
			return list.ToArray();
		}

		private static bool HasName(List<string> seen, string s)
		{
			for (int i = 0; i < seen.Count; i++)
			{
				if (seen[i] == s)
				{
					return true;
				}
			}
			return false;
		}

		private static string ZhCached(string s)
		{
			if (s == null)
			{
				s = "";
			}
			if (_zhMap == null)
			{
				_zhMap = new Dictionary<string, string>();
			}
			string value;
			if (_zhMap.TryGetValue(s, out value))
			{
				return value;
			}
			value = Zh(s);
			_zhMap[s] = value;
			return value;
		}

		private static T[] ScanTypes<T>() where T : UnityEngine.Object
		{
			try
			{
				T[] array = UnityEngine.Object.FindObjectsByType<T>(FindObjectsSortMode.None);
				return array ?? new T[0];
			}
			catch
			{
				return new T[0];
			}
		}

		private static T[] AppendScan<T>(T[] arr, T item) where T : UnityEngine.Object
		{
			if (item == null)
			{
				return arr ?? new T[0];
			}
			if (arr == null)
			{
				arr = new T[0];
			}
			for (int i = 0; i < arr.Length; i++)
			{
				if (object.ReferenceEquals(arr[i], item))
				{
					return arr;
				}
			}
			T[] array = new T[arr.Length + 1];
			for (int j = 0; j < arr.Length; j++)
			{
				array[j] = arr[j];
			}
			array[arr.Length] = item;
			return array;
		}

		private static void RunBootScanPiece(int step)
		{
			switch (step)
			{
			case 0:
				_scanBats = ScanTypes<Bat>();
				break;
			case 1:
				_scanHolders = ScanTypes<BatHolder>();
				break;
			case 2:
				_scanGames = ScanTypes<GameBase>();
				NoteBlackjackTables(_scanGames);
				break;
			case 3:
				_scanGachas = ScanTypes<GachaMachine>();
				break;
			case 4:
				_scanShreds = ScanTypes<BodyShreddingMachine>();
				break;
			case 5:
				_scanElev = ScanTypes<ElevatorManager>();
				break;
			case 6:
				_scanFloors = ScanTypes<CasinoFloor>();
				break;
			}
		}

		private static bool ScanGone(UnityEngine.Object[] a)
		{
			if (a == null || a.Length == 0)
			{
				return true;
			}
			for (int i = 0; i < a.Length; i++)
			{
				if (a[i] != null)
				{
					return false;
				}
			}
			return true;
		}

		private static void EnsureElevFloors()
		{
			if (ScanGone(_scanElev))
			{
				_scanElev = ScanTypes<ElevatorManager>();
			}
			if (ScanGone(_scanFloors))
			{
				_scanFloors = ScanTypes<CasinoFloor>();
			}
		}

		private static void EnsureLabelObjects()
		{
			if (!(Time.unscaledTime - _labelScanAt < 1.5f) && (ScanGone(_scanBats) || ScanGone(_scanHolders) || ScanGone(_scanGames) || ScanGone(_scanGachas) || ScanGone(_scanShreds)))
			{
				_labelScanAt = Time.unscaledTime;
				if (ScanGone(_scanBats))
				{
					_scanBats = ScanTypes<Bat>();
				}
				else if (ScanGone(_scanHolders))
				{
					_scanHolders = ScanTypes<BatHolder>();
				}
				else if (ScanGone(_scanGames))
				{
					_scanGames = ScanTypes<GameBase>();
					NoteBlackjackTables(_scanGames);
				}
				else if (ScanGone(_scanGachas))
				{
					_scanGachas = ScanTypes<GachaMachine>();
				}
				else if (ScanGone(_scanShreds))
				{
					_scanShreds = ScanTypes<BodyShreddingMachine>();
				}
			}
		}

		private static void EnsureWorldScan()
		{
			EnsureElevFloors();
			EnsureLabelObjects();
			if (!_bootScanDone && _bootScanStep < 0)
			{
				_bootScanStep = 0;
			}
		}

