		private static void NoteBlackjackTables(GameBase[] games)
		{
			if (_sawBlackjack || games == null)
			{
				return;
			}
			foreach (GameBase gameBase in games)
			{
				if (gameBase == null)
				{
					continue;
				}
				try
				{
					if (gameBase.GameType == CasinoGameType.Blackjack)
					{
						_sawBlackjack = true;
						break;
					}
				}
				catch
				{
				}
				try
				{
					string text = (gameBase.GameName ?? "") + " " + gameBase.name;
					if (text.IndexOf("blackjack", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("二十一点") >= 0)
					{
						_sawBlackjack = true;
						break;
					}
				}
				catch
				{
				}
			}
		}

