		internal static string NextLoadingQuote()
		{
			LoadQuoteFlags();
			if (!string.IsNullOrEmpty(_quoteCache) && Time.unscaledTime - _quoteCacheAt < 4f)
			{
				return _quoteCache;
			}
			string text;
			if (_forceMissQuote)
			{
				_forceMissQuote = false;
				SaveQuoteFlags();
				text = FormatLoadingQuote(QuoteBodies()[8], QuoteWhos()[8]);
			}
			else
			{
				int n = (_sawBlackjack ? 9 : 8);
				int num = DrawPoolQuote(n);
				if (num == 8)
				{
					num = 9;
				}
				text = FormatLoadingQuote(QuoteBodies()[num], QuoteWhos()[num]);
			}
			_quoteCache = text;
			_quoteCacheAt = Time.unscaledTime;
			return text;
		}

