		private static int DrawPoolQuote(int n)
		{
			if (n < 1)
			{
				n = 1;
			}
			if (_quoteBagSize != n)
			{
				_quoteBag.Clear();
				_quoteBagSize = n;
			}
			if (_quoteBag.Count == 0)
			{
				for (int i = 0; i < n; i++)
				{
					_quoteBag.Add(i);
				}
				for (int num = _quoteBag.Count - 1; num > 0; num--)
				{
					int index = UnityEngine.Random.Range(0, num + 1);
					int value = _quoteBag[num];
					_quoteBag[num] = _quoteBag[index];
					_quoteBag[index] = value;
				}
				if (_quoteBag.Count > 1 && _quoteBag[_quoteBag.Count - 1] == _lastPoolQuote)
				{
					int value2 = _quoteBag[_quoteBag.Count - 1];
					_quoteBag[_quoteBag.Count - 1] = _quoteBag[0];
					_quoteBag[0] = value2;
				}
			}
			int num2 = _quoteBag[_quoteBag.Count - 1];
			_quoteBag.RemoveAt(_quoteBag.Count - 1);
			_lastPoolQuote = num2;
			return num2;
		}

