		internal static bool FloorUnlocked(int floorIndex)
		{
			return FloorOpenOnDay(NormalizeFloorNum(floorIndex));
		}

		private static int NormalizeFloorNum(int floorIndex)
		{
			if (floorIndex <= 0)
			{
				return 1;
			}
			return floorIndex;
		}

		private static bool FloorOpenOnDay(int floorNum)
		{
			int num = SharedDay;
			if (num < 1)
			{
				num = 1;
			}
			if (floorNum <= 1)
			{
				return true;
			}
			switch (floorNum)
			{
			case 2:
				return num >= 3;
			case 3:
				return num >= 5;
			default:
				return num >= 7;
			}
		}

		private static void FloorIndexRange(ElevatorManager em, out int min, out int max)
		{
			min = 1;
			max = 4;
			try
			{
				List<CasinoFloor> list = AccessTools.Field(typeof(ElevatorManager), "allFloors").GetValue(em) as List<CasinoFloor>;
				if (list == null)
				{
					return;
				}
				int num = int.MaxValue;
				int num2 = int.MinValue;
				for (int i = 0; i < list.Count; i++)
				{
					if (!(list[i] == null))
					{
						int floorIndex = list[i].floorIndex;
						if (floorIndex < num)
						{
							num = floorIndex;
						}
						if (floorIndex > num2)
						{
							num2 = floorIndex;
						}
					}
				}
				if (num != int.MaxValue)
				{
					min = num;
					max = num2;
				}
			}
			catch
			{
			}
		}

		private static int CasinoFloorNum(ElevatorManager em, int floorIndex)
		{
			int min;
			int max;
			FloorIndexRange(em, out min, out max);
			if (min <= 0 && max >= 4)
			{
				if (floorIndex > 0)
				{
					return floorIndex;
				}
				return 1;
			}
			if (min == 0 && max <= 3)
			{
				return floorIndex + 1;
			}
			return NormalizeFloorNum(floorIndex);
		}

		internal static int ElevatorTargetFloor(ElevatorManager em, int toIndex)
		{
			try
			{
				List<CasinoFloor> list = AccessTools.Field(typeof(ElevatorManager), "allFloors").GetValue(em) as List<CasinoFloor>;
				if (list != null && toIndex >= 0 && toIndex < list.Count && list[toIndex] != null)
				{
					return CasinoFloorNum(em, list[toIndex].floorIndex);
				}
			}
			catch
			{
			}
			if (toIndex <= 0)
			{
				return 1;
			}
			return CasinoFloorNum(em, toIndex);
		}

		private static int FloorIndexFromName(string n)
		{
			if (string.IsNullOrEmpty(n))
			{
				return -1;
			}
			string text = n.ToLowerInvariant();
			if (text.IndexOf("4") >= 0 || text.IndexOf("four") >= 0)
			{
				return 4;
			}
			if (text.IndexOf("3") >= 0 || text.IndexOf("three") >= 0)
			{
				return 3;
			}
			if (text.IndexOf("2") >= 0 || text.IndexOf("two") >= 0)
			{
				return 2;
			}
			if (text.IndexOf("1") >= 0 || text.IndexOf("one") >= 0)
			{
				return 1;
			}
			return -1;
		}

