					{
						Transform transform = list2[i];
						if (!(transform == null) && (!(transform != btn) || (!(btn == null) && btn.IsChildOf(transform))))
						{
							if (list != null && i < list.Count && list[i] != null)
							{
								return list[i].floorIndex;
							}
							int num = FloorIndexFromName(transform.name);
							if (num >= 0)
							{
								return num;
							}
							return -1;
						}
					}
				}
			}
			catch
			{
			}
			return FloorIndexFromName(btn.name);
		}

		internal static bool ElevatorButtonAllowed(Component c)
		{
			if (c == null)
			{
				return true;
			}
			ElevatorManager elevatorManager = null;
			try
			{
				elevatorManager = c.GetComponentInParent<ElevatorManager>();
			}
			catch
			{
			}
			if (elevatorManager == null)
			{
				return true;
			}
			Transform btn = c.transform;
			int num = ElevatorButtonFloor(elevatorManager, btn);
			if (num < 0)
			{
				return true;
			}
			return FloorUnlocked(CasinoFloorNum(elevatorManager, num));
		}

		internal static void ApplyElevatorLocks(ElevatorManager em)
		{
			if (em == null)
			{
				return;
			}
			try
			{
				List<Transform> list = AccessTools.Field(typeof(ElevatorManager), "buttonList").GetValue(em) as List<Transform>;
				if (list == null)
				{
					return;
				}
				for (int i = 0; i < list.Count; i++)
				{
					Transform transform = list[i];
					if (transform == null)
					{
						continue;
					}
					int num = ElevatorButtonFloor(em, transform);
					num = ((num >= 0) ? CasinoFloorNum(em, num) : (i + 1));
					bool isInteractable = FloorUnlocked(num);
					InteractableBase[] componentsInChildren = transform.GetComponentsInChildren<InteractableBase>(true);
					if (componentsInChildren == null)
					{
						continue;
					}
					for (int j = 0; j < componentsInChildren.Length; j++)
					{
						if (!(componentsInChildren[j] == null))
						{
							try
							{
								componentsInChildren[j].IsInteractable = isInteractable;
							}
							catch
							{
							}
						}
					}
				}
			}
			catch
			{
			}
		}

		internal static void ApplyAllElevatorLocks()
		{
			try
			{
				EnsureWorldScan();
				ElevatorManager[] scanElev = _scanElev;
				if (scanElev != null)
				{
					for (int i = 0; i < scanElev.Length; i++)
					{
						ApplyElevatorLocks(scanElev[i]);
					}
				}
			}
			catch
			{
			}
		}

		internal static void SendShop(string cmd)
		{
			if (string.IsNullOrEmpty(cmd))
			{
				return;
			}
			if (EconomyFrozen())
			{
				_shopNote = "第11天金钱和票已锁定。";
				return;
			}
			bool flag = LocalInElevator();
			bool flag2 = LocalOnCasinoFloor();
			if (!flag && !flag2)
			{
				_shopNote = "工具请在电梯买，机器请在赌场1-4楼（电梯外）买。";
				return;
			}
			if (cmd.Length > 0 && cmd[0] == 'I' && !flag)
			{
				_shopNote = "工具只能在电梯里购买。";
				return;
			}
			if (cmd.Length > 0 && (cmd[0] == 'G' || cmd[0] == 'P') && !flag2)
			{
				_shopNote = "机器只能在赌场1-4楼、电梯外购买。";
				return;
			}
			if (NetworkServer.active)
			{
				DoShop(LocalProfile(), cmd);
				return;
			}
			try
			{
				NetworkClient.Send(new ShopMsg
				{
					json = cmd
				});
				_shopNote = "已发送。";
			}
			catch
			{
				_shopNote = "商店发送失败。";
			}
		}

		private static void OnShopCmd(NetworkConnectionToClient conn, ShopMsg msg)
		{
			if (!NetworkServer.active || conn == null)
			{
				return;
			}
			PlayerProfile playerProfile = ProfileFromIdentity(conn.identity);
			if (playerProfile == null)
			{
				return;
			}
			Vector3 pos = Vector3.zero;
			try
			{
				if (conn.identity != null)
				{
					pos = conn.identity.transform.position;
				}
			}
			catch
			{
			}
			string json = msg.json;
			if (!string.IsNullOrEmpty(json))
			{
				bool flag = PlayerInElevator(pos);
				bool flag2 = PlayerOnCasinoFloor(pos);
				if ((flag || flag2) && (json[0] != 'I' || flag) && ((json[0] != 'G' && json[0] != 'P') || flag2))
				{
					DoShop(playerProfile, json);
				}
			}
		}

		private static void DoShop(PlayerProfile who, string cmd)
		{
			if (who == null || string.IsNullOrEmpty(cmd))
			{
				return;
			}
			Acc acc = Ensure(who);
			if (acc == null)
			{
				return;
			}
			if (EconomyFrozen())
			{
				_shopNote = "第11天金钱和票已锁定。";
				return;
			}
			RefreshShopDay(acc);
			if (cmd == "T")
			{
				if (acc.shopBuyT >= 10)
				{
					_shopNote = "今日用现金买票已达上限（10）。";
					Broadcast();
					return;
				}
				double num = NextTicketBuyCost(acc);
				if (acc.money + 0.0001 < num)
				{
					_shopNote = "需要 " + MoneyDollar(num) + " 才能买 1 张票。";
					Broadcast();
					return;
				}
				acc.money -= num;
				acc.tickets++;
				acc.shopBuyT++;
				_shopNote = "已用 " + MoneyDollar(num) + " 购买 1 张票。下一张 " + MoneyDollar(NextTicketBuyCost(acc)) + "。";
				Broadcast();
			}
			else if (cmd == "M")
			{
				if (acc.shopSellT >= 5)
				{
					_shopNote = "今日换现金已达上限（5）。";
					Broadcast();
					return;
				}
				if (acc.tickets < 1)
				{
					_shopNote = "需要 1 张票。";
					Broadcast();
					return;
				}
				acc.tickets--;
				acc.money += 700.0;
				acc.shopSellT++;
				_shopNote = "已用 1 张票换得 $700。";
				Broadcast();
			}
			else if (cmd.Length > 1 && cmd[0] == 'P')
			{
				string s = cmd.Substring(1);
				if (ShopHidden(s))
				{
					_shopNote = "无法购买。";
					Broadcast();
					return;
				}
				GameBase gameBase = FindGamePrefab(s);
				if (gameBase == null)
				{
					_shopNote = "未知机器。";
					Broadcast();
					return;
				}
				int num2 = ShopPriceOverride(s);
				if (num2 <= 0)
				{
					num2 = 8;
				}
				num2 = ShopHalfInt(acc, num2);
				if (acc.tickets < num2)
				{
					_shopNote = "需要 " + num2 + " 张票。";
					Broadcast();
					return;
				}
				acc.tickets -= num2;
				GiveGame(who, gameBase);
				_shopNote = "已购买 " + Zh(s) + "。";
				Broadcast();
			}
			else
			{
				int result;
				if (cmd.Length <= 1 || (cmd[0] != 'I' && cmd[0] != 'G') || !int.TryParse(cmd.Substring(1), out result))
				{
					return;
				}
				SpawnableSO spawnableSO = FindSpawnable(result);
				bool flag = cmd[0] == 'G';
				if (spawnableSO == null || IsMachine(spawnableSO) != flag || ShopHidden(spawnableSO.spawnableName))
				{
					_shopNote = (flag ? "未知机器。" : "未知工具。");
					Broadcast();
					return;
				}
				int num3 = (flag ? MachineCost(spawnableSO, acc) : ToolCost(spawnableSO, acc));
				if (num3 < 0)
				{
					_shopNote = "无法定价。";
					Broadcast();
					return;
				}
				if (!flag && SpawnIsBat(spawnableSO) && PlayerOwnsKind(acc, who, false))
				{
					_shopNote = "每人只能买 1 根球棒。";
					Broadcast();
					return;
				}
				if (!flag && SpawnIsGun(spawnableSO) && PlayerOwnsKind(acc, who, true))
				{
					_shopNote = "每人只能买 1 把手枪。";
					Broadcast();
					return;
				}
				if (acc.tickets < num3)
				{
					_shopNote = "需要 " + num3 + " 张票。";
					Broadcast();
					return;
				}
				acc.tickets -= num3;
				if (IsBonusDrawItem(spawnableSO.spawnableName))
				{
					acc.bonusDraw = 1;
				}
				if (!flag && SpawnIsBatOrGun(spawnableSO))
				{
					StashAdd(acc, spawnableSO.spawnableID, 1);
				}
				GiveTool(who, spawnableSO);
				_shopNote = "已购买 " + Zh(spawnableSO.spawnableName) + "。";
				Broadcast();
			}
		}

		private static bool IsBonusDrawItem(string name)
		{
			if (string.IsNullOrEmpty(name))
			{
				return false;
			}
			string s = name.ToLowerInvariant();
			if (HasTxt(name, "赚钱时加金票") || HasTxt(name, "额外抽奖"))
			{
				return true;
			}
			if ((!HasTxt(s, "upgrade") || !HasTxt(s, "bonus")) && !HasTxt(s, "bonusdraw"))
			{
				return HasTxt(s, "bonus draw");
			}
			return true;
		}

		private static bool ShopHidden(string name)
		{
			if (string.IsNullOrEmpty(name))
			{
				return true;
			}
			string s = name.ToLowerInvariant();
			if (HasTxt(s, "maxwell") || HasTxt(name, "麦克斯韦"))
			{
				return true;
			}
			if (HasTxt(s, "ratto") || HasTxt(name, "拉托"))
			{
				return true;
			}
			if (HasTxt(s, "voice") || HasTxt(s, "manipulator") || HasTxt(name, "变声器"))
			{
				return true;
			}
			if (HasTxt(s, "cosmetic") || HasTxt(name, "装饰品"))
			{
				return true;
			}
			return false;
		}

		private static int ShopPriceOverride(string name)
		{
			if (string.IsNullOrEmpty(name))
			{
				return 0;
			}
			string s = name.ToLowerInvariant();
			if ((HasTxt(s, "cross") && !HasTxt(s, "crossy")) || HasTxt(name, "圣像") || HasTxt(name, "十字架"))
			{
				return 15;
			}
			if ((HasTxt(s, "bat") && !HasTxt(s, "combat")) || HasTxt(name, "球棒"))
			{
				return 5;
			}
			if (HasTxt(s, "quota") || HasTxt(name, "额度枪") || HasTxt(name, "手枪"))
			{
				return 7;
			}
			if (HasTxt(s, "stun") || HasTxt(s, "taser") || HasTxt(name, "电击") || HasTxt(name, "增加投注"))
			{
				return 5;
			}
			if ((HasTxt(s, "upgrade") && HasTxt(s, "bonus")) || HasTxt(name, "赚钱时加金票") || HasTxt(name, "额外抽奖"))
			{
				return 5;
			}
			if ((HasTxt(s, "upgrade") && (HasTxt(s, "gambler") || HasTxt(s, "confidence"))) || HasTxt(name, "赚更多钱") || HasTxt(name, "赌徒信心"))
			{
				return 7;
			}
			if ((HasTxt(s, "upgrade") && HasTxt(s, "insurance")) || HasTxt(name, "输少点钱") || HasTxt(name, "保险"))
			{
				return 7;
			}
			if ((HasTxt(s, "upgrade") && HasTxt(s, "stake")) || HasTxt(name, "增加道具效果") || HasTxt(name, "股东"))
			{
				return 5;
			}
			if (HasTxt(s, "mystery") || HasTxt(name, "神秘箱"))
			{
				return 3;
			}
			if (HasTxt(s, "shred") || HasTxt(name, "碎尸"))
			{
				return 5;
			}
			return 0;
		}

		private static int ToolDayExtra()
		{
			int num = SharedDay - 1;
			if (num < 0)
			{
				num = 0;
			}
			return num;
		}

		private static int BaseToolCost(SpawnableSO so)
		{
			if (so == null)
			{
				return 0;
			}
			int num = ShopPriceOverride(so.spawnableName);
			int num2;
			if (num > 0)
			{
				num2 = num;
			}
			else
			{
				num2 = 3 + Math.Abs(so.spawnableID) % 5;
				if (num2 < 2)
				{
					num2 = 2;
				}
			}
			if (num2 < 1)
			{
				num2 = 1;
			}
			return num2;
		}

		private static int ToolCost(SpawnableSO so)
		{
			return ToolCost(so, null);
		}

		private static bool GuardFreeTool(string name)
		{
			if (string.IsNullOrEmpty(name))
			{
				return false;
			}
			string s = name.ToLowerInvariant();
			if ((HasTxt(s, "bat") && !HasTxt(s, "combat")) || HasTxt(name, "球棒"))
			{
				return true;
			}
			if (HasTxt(s, "quota") || HasTxt(name, "额度枪") || HasTxt(name, "手枪") || (HasTxt(s, "gun") && HasTxt(s, "quota")))
			{
				return true;
			}
			return false;
		}

		private static int ToolCost(SpawnableSO so, Acc buyer)
		{
			if (IsGuard(buyer) && so != null && GuardFreeTool(so.spawnableName))
			{
				return 0;
			}
			int num = BaseToolCost(so);
			if (!IsBoss(buyer))
			{
				num += ToolDayExtra();
			}
			if (num < 1)
			{
				num = 1;
			}
			return ShopHalfInt(buyer, num);
		}

		private static int MachineCost(SpawnableSO so)
		{
			return MachineCost(so, null);
		}

		private static int MachineCost(SpawnableSO so, Acc buyer)
		{
			if (so == null)
			{
				return 0;
			}
			string text = (so.spawnableName ?? "") + " " + ((so.prefab != null) ? so.prefab.name : "");
			int num = ShopPriceOverride(text);
			int cost = ((num <= 0) ? (8 + Math.Abs(so.spawnableID) % 6) : num);
			return ShopHalfInt(buyer, cost);
		}

		private static bool IsMachine(SpawnableSO s)
		{
			if (s == null || s.prefab == null)
			{
				return false;
			}
			try
			{
				if (s.prefab.GetComponent<GameBase>() != null)
				{
					return true;
				}
				if (s.prefab.GetComponent<ClawMachine>() != null)
				{
					return true;
				}
				if (s.prefab.GetComponent<GachaMachine>() != null)
				{
					return true;
				}
				if (s.prefab.GetComponent<BodyShreddingMachine>() != null)
				{
					return true;
				}
			}
			catch
			{
			}
			string text = ((s.spawnableName ?? "") + " " + s.prefab.name).ToLowerInvariant();
			if (text.IndexOf("poker") < 0 && text.IndexOf("blackjack") < 0 && text.IndexOf("slot") < 0 && text.IndexOf("roulette") < 0 && text.IndexOf("craps") < 0 && text.IndexOf("plinko") < 0 && text.IndexOf("keno") < 0 && text.IndexOf("wheel") < 0 && text.IndexOf("baccarat") < 0 && text.IndexOf("crash") < 0 && text.IndexOf("claw") < 0 && text.IndexOf("gacha") < 0 && text.IndexOf("shred") < 0 && text.IndexOf("hilo") < 0 && text.IndexOf("hi-lo") < 0 && text.IndexOf("dragon") < 0 && text.IndexOf("minesweeper") < 0 && text.IndexOf("fortune") < 0 && text.IndexOf("coinflip") < 0 && text.IndexOf("coin flip") < 0)
			{
				return text.IndexOf("crossy") >= 0;
			}
			return true;
		}

		private static bool HasTxt(string s, string a)
		{
			if (string.IsNullOrEmpty(s) || string.IsNullOrEmpty(a))
			{
				return false;
			}
			return s.IndexOf(a, StringComparison.OrdinalIgnoreCase) >= 0;
		}

		private static string Zh(string s)
		{
			if (string.IsNullOrEmpty(s))
			{
				return s;
			}
			string text = s.Trim();
			if (text.EndsWith("(Clone)", StringComparison.OrdinalIgnoreCase))
			{
				text = text.Substring(0, text.Length - 7).Trim();
			}
			string s2 = text.ToLowerInvariant();
			if ((HasTxt(s2, "time") && HasTxt(s2, "machine")) || HasTxt(text, "时光机"))
			{
				return "时光机";
			}
			if ((HasTxt(s2, "fortune") || (HasTxt(text, "命运") && (HasTxt(s2, "of") || HasTxt(s2, "wheel") || HasTxt(text, "转盘")))) && (HasTxt(s2, "wheel") || HasTxt(text, "转盘") || HasTxt(s2, "fortune") || HasTxt(s2, "of")))
			{
				return "命运转盘";
