				return "挖钻石";
			}
			if (HasTxt(s2, "hilo") || HasTxt(s2, "hi-lo") || HasTxt(s2, "hi lo"))
			{
				return "大小";
			}
			if (HasTxt(s2, "coin") && HasTxt(s2, "flip"))
			{
				return "抛硬币";
			}
			if (HasTxt(s2, "shred") || HasTxt(text, "碎尸"))
			{
				return "碎尸机";
			}
			if (HasTxt(s2, "stun") || HasTxt(s2, "taser") || HasTxt(text, "电击"))
			{
				return "增加投注金额";
			}
			if (HasTxt(s2, "upgrade") && HasTxt(s2, "bonus"))
			{
				return "升级：赚钱时加金票";
			}
			if (HasTxt(s2, "upgrade") && (HasTxt(s2, "gambler") || HasTxt(s2, "confidence")))
			{
				return "升级：赚更多钱";
			}
			if (HasTxt(s2, "upgrade") && HasTxt(s2, "insurance"))
			{
				return "升级：输少点钱";
			}
			if (HasTxt(s2, "upgrade") && HasTxt(s2, "stake"))
			{
				return "升级：增加道具效果";
			}
			if (HasTxt(s2, "dice") || (HasTxt(text, "骰子") && !HasTxt(text, "骰宝")))
			{
				return "骰子";
			}
			string text2 = NormKey(text);
			string text3 = ZhLookup(text2);
			if (text3 != null)
			{
				return text3;
			}
			if (text2.StartsWith("upgrade"))
			{
				string text4 = ZhLookup(text2.Substring(7));
				if (text4 != null)
				{
					return "升级：" + text4;
				}
				return "升级";
			}
			string[] array = ZhKeys();
			string[] array2 = ZhVals();
			int num = -1;
			int num2 = 0;
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].Length > num2 && text2.IndexOf(array[i]) >= 0)
				{
					num = i;
					num2 = array[i].Length;
				}
			}
			if (num >= 0)
			{
				return array2[num];
			}
			return text;
		}

		private static string NormKey(string s)
		{
			if (string.IsNullOrEmpty(s))
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder(s.Length);
			for (int i = 0; i < s.Length; i++)
			{
				char c = s[i];
				if (c >= 'A' && c <= 'Z')
				{
					c = (char)(c + 32);
				}
				if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
				{
					stringBuilder.Append(c);
				}
			}
			string text = stringBuilder.ToString();
			if (text.StartsWith("the"))
			{
				text = text.Substring(3);
			}
			return text;
		}

		private static string ZhLookup(string key)
		{
			if (string.IsNullOrEmpty(key))
			{
				return null;
			}
			string[] array = ZhKeys();
			string[] array2 = ZhVals();
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] == key)
				{
					return array2[i];
				}
			}
			return null;
		}

