		private static SpawnableSO FindSpawnable(int id)
		{
			SpawnableSO spawnableSO = FindIn(_cacheTools, id);
			if (spawnableSO != null)
			{
				return spawnableSO;
			}
			spawnableSO = FindIn(_cacheMach, id);
			if (spawnableSO != null)
			{
				return spawnableSO;
			}
			return FindIn(ListCatalog(), id);
		}

		private static SpawnableSO FindIn(SpawnableSO[] all, int id)
		{
			if (all == null)
			{
				return null;
			}
			for (int i = 0; i < all.Length; i++)
			{
				if (all[i] != null && all[i].spawnableID == id)
				{
					return all[i];
				}
			}
			return null;
		}

		private static SpawnableSO[] ListCatalog()
		{
			try
			{
				SpawnableSO[] array = Resources.FindObjectsOfTypeAll<SpawnableSO>();
				if (array == null)
				{
					return new SpawnableSO[0];
				}
				List<SpawnableSO> list = new List<SpawnableSO>();
				List<string> list2 = new List<string>();
				SpawnableSO[] array2 = array;
				foreach (SpawnableSO spawnableSO in array2)
				{
					if (spawnableSO == null || string.IsNullOrEmpty(spawnableSO.spawnableName) || spawnableSO.prefab == null)
					{
						continue;
					}
					bool flag = false;
					for (int j = 0; j < list2.Count; j++)
					{
						if (list2[j] == spawnableSO.spawnableName)
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						list2.Add(spawnableSO.spawnableName);
						list.Add(spawnableSO);
					}
				}
				list.Sort((SpawnableSO x, SpawnableSO y) => string.Compare(x.spawnableName, y.spawnableName, StringComparison.OrdinalIgnoreCase));
				return list.ToArray();
			}
			catch
			{
				return new SpawnableSO[0];
			}
		}

		private static SpawnableSO[] ListByKind(bool machines)
		{
			SpawnableSO[] array = ListCatalog();
			List<SpawnableSO> list = new List<SpawnableSO>();
			for (int i = 0; i < array.Length; i++)
			{
				if (!(array[i] == null) && IsMachine(array[i]) == machines)
				{
					list.Add(array[i]);
				}
			}
			return list.ToArray();
		}

		private static GameBase[] ListGamePrefabs()
		{
			try
			{
				GameBase[] array = Resources.FindObjectsOfTypeAll<GameBase>();
				if (array == null)
				{
					return new GameBase[0];
				}
				List<GameBase> list = new List<GameBase>();
				List<string> list2 = new List<string>();
				GameBase[] array2 = array;
				foreach (GameBase gameBase in array2)
				{
					if (gameBase == null)
					{
						continue;
					}
					try
					{
						if (gameBase.gameObject.scene.IsValid() && !string.IsNullOrEmpty(gameBase.gameObject.scene.name))
						{
							continue;
						}
					}
					catch
					{
					}
					if (list.Count >= 16)
					{
						break;
					}
					string gameName = gameBase.GameName;
					if (string.IsNullOrEmpty(gameName))
					{
						gameName = gameBase.gameObject.name;
					}
					if (gameName.IndexOf("(Clone)", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						continue;
					}
					bool flag = false;
					for (int j = 0; j < list2.Count; j++)
					{
						if (list2[j] == gameName)
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						list2.Add(gameName);
						list.Add(gameBase);
					}
				}
				list.Sort((GameBase x, GameBase y) => string.Compare(DispGame(x), DispGame(y), StringComparison.OrdinalIgnoreCase));
				return list.ToArray();
			}
			catch
			{
				return new GameBase[0];
			}
		}

		private static string DispGame(GameBase g)
		{
			if (g == null)
			{
				return "?";
			}
			if (!string.IsNullOrEmpty(g.GameName))
			{
				return g.GameName;
			}
			if (!(g.gameObject != null))
			{
				return "?";
			}
			return g.gameObject.name;
		}

		private static GameBase FindGamePrefab(string name)
		{
			if (string.IsNullOrEmpty(name))
			{
				return null;
			}
			if (_cacheGames != null)
			{
				for (int i = 0; i < _cacheGames.Length; i++)
				{
					if (_cacheGames[i] != null && DispGame(_cacheGames[i]) == name)
					{
						return _cacheGames[i];
					}
				}
			}
			GameBase[] array = ListGamePrefabs();
			for (int j = 0; j < array.Length; j++)
			{
				if (array[j] != null && DispGame(array[j]) == name)
				{
					return array[j];
				}
			}
			return null;
		}

		private static Vector3 FlatForward(PlayerProfile who)
		{
			Vector3 vector = Vector3.forward;
			try
			{
				Transform transform = null;
				if (who != null)
				{
					Camera[] componentsInChildren = who.GetComponentsInChildren<Camera>(true);
					if (componentsInChildren != null)
					{
						Camera[] array = componentsInChildren;
						foreach (Camera camera in array)
						{
							if (!(camera == null) && camera.enabled)
							{
								transform = camera.transform;
								break;
							}
						}
						if (transform == null && componentsInChildren.Length > 0 && componentsInChildren[0] != null)
						{
							transform = componentsInChildren[0].transform;
						}
					}
					try
					{
						if (transform == null && who.isLocalPlayer && Camera.main != null)
						{
							transform = Camera.main.transform;
						}
					}
					catch
					{
					}
				}
				if (transform != null)
				{
					vector = transform.forward;
				}
				else if (who != null)
				{
					vector = -who.transform.forward;
				}
			}
			catch
			{
			}
			vector.y = 0f;
			if (vector.sqrMagnitude < 0.0001f)
			{
				vector = Vector3.forward;
			}
			return vector.normalized;
		}

		private static Vector3 PlaceInFrontOnFloor(PlayerProfile who, float dist)
		{
			Vector3 position = who.transform.position;
			Vector3 vector = FlatForward(who);
			Vector3 origin = position + vector * dist + Vector3.up * 3.5f;
			RaycastHit hitInfo;
			if (Physics.Raycast(origin, Vector3.down, out hitInfo, 24f, -5, QueryTriggerInteraction.Ignore))
			{
				return hitInfo.point;
			}
			if (Physics.Raycast(position + Vector3.up * 0.4f, vector, out hitInfo, dist + 0.5f, -5, QueryTriggerInteraction.Ignore))
			{
				Vector3 vector2 = hitInfo.point - vector * 0.6f;
				if (Physics.Raycast(vector2 + Vector3.up * 3.5f, Vector3.down, out hitInfo, 24f, -5, QueryTriggerInteraction.Ignore))
				{
					return hitInfo.point;
				}
			}
			return position + vector * dist;
		}

		private static void SnapToFloor(GameObject go, Vector3 floor)
		{
			if (go == null)
			{
				return;
			}
			Vector3 position = go.transform.position;
			position.x = floor.x;
			position.z = floor.z;
			go.transform.position = position;
			float y = position.y;
			bool flag = false;
			try
			{
				Renderer[] componentsInChildren = go.GetComponentsInChildren<Renderer>(true);
				if (componentsInChildren != null)
				{
					Renderer[] array = componentsInChildren;
					foreach (Renderer renderer in array)
					{
						if (renderer == null || !renderer.enabled)
						{
							continue;
						}
						Bounds bounds = renderer.bounds;
						if (!(bounds.size.x > 8f) && !(bounds.size.y > 8f) && !(bounds.size.z > 8f))
						{
							if (!flag)
							{
								y = bounds.min.y;
								flag = true;
							}
							else if (bounds.min.y < y)
							{
								y = bounds.min.y;
							}
						}
					}
				}
			}
			catch
			{
			}
			if (!flag)
			{
				try
				{
					Collider[] componentsInChildren2 = go.GetComponentsInChildren<Collider>(true);
					if (componentsInChildren2 != null)
					{
						Collider[] array2 = componentsInChildren2;
						foreach (Collider collider in array2)
						{
							if (collider == null || !collider.enabled)
							{
								continue;
							}
							Bounds bounds2 = collider.bounds;
							if (!(bounds2.size.x > 8f) && !(bounds2.size.y > 8f) && !(bounds2.size.z > 8f))
							{
								if (!flag)
								{
									y = bounds2.min.y;
									flag = true;
								}
								else if (bounds2.min.y < y)
								{
									y = bounds2.min.y;
								}
							}
						}
					}
				}
				catch
				{
				}
			}
			if (flag)
			{
				go.transform.position += new Vector3(0f, floor.y - y, 0f);
			}
			else
			{
				position = go.transform.position;
				position.y = floor.y;
				go.transform.position = position;
			}
			try
			{
				Rigidbody rigidbody = go.GetComponent<Rigidbody>();
				if (rigidbody == null)
				{
					rigidbody = go.GetComponentInChildren<Rigidbody>();
				}
				if (rigidbody != null)
				{
					rigidbody.linearVelocity = Vector3.zero;
					rigidbody.angularVelocity = Vector3.zero;
				}
			}
			catch
			{
			}
		}

		private static IEnumerator FinishOwnedClaim(GameObject go, PlayerProfile who, Vector3 floor)
		{
			yield return null;
			if (go == null)
			{
				yield break;
			}
			try
			{
				go.transform.position = floor + Vector3.up * 0.02f;
			}
			catch
			{
			}
			NetTeleport(go);
			yield return null;
			if (!(go == null))
			{
				try
				{
					go.transform.position = floor + Vector3.up * 0.02f;
				}
				catch
				{
				}
				NetTeleport(go);
				ClaimSpawnedOwned(go, who);
				Broadcast();
			}
		}

		private static void PlaceOwnedWorld(PlayerProfile who, GameObject prefab, float dist)
		{
			if (!(prefab == null) && !(who == null))
			{
				PlaceOwnedWorld(who, prefab, dist, Vector3.zero);
			}
		}

		private static void PlaceOwnedWorld(PlayerProfile who, GameObject prefab, float dist, Vector3 shift)
		{
			if (prefab == null || who == null)
			{
				return;
			}
			Vector3 vector = PlaceInFrontOnFloor(who, dist) + shift;
			Vector3 vector2 = FlatForward(who);
			Quaternion rotation = Quaternion.LookRotation(-vector2, Vector3.up);
			Vector3 position = vector + Vector3.up * 0.02f;
			GameObject gameObject = UnityEngine.Object.Instantiate(prefab, position, rotation);
			try
			{
				Rigidbody[] componentsInChildren = gameObject.GetComponentsInChildren<Rigidbody>(true);
				if (componentsInChildren != null)
				{
					for (int i = 0; i < componentsInChildren.Length; i++)
					{
						if (!(componentsInChildren[i] == null))
						{
							componentsInChildren[i].isKinematic = true;
							componentsInChildren[i].linearVelocity = Vector3.zero;
							componentsInChildren[i].angularVelocity = Vector3.zero;
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				gameObject.transform.position = position;
			}
			catch
			{
			}
			NetworkServer.Spawn(gameObject);
			try
			{
				gameObject.transform.position = position;
			}
			catch
			{
			}
			NetTeleport(gameObject);
			ClaimSpawnedOwned(gameObject, who);
			if (_inst != null)
			{
				_inst.StartCoroutine(FinishOwnedClaim(gameObject, who, vector));
			}
			Broadcast();
		}

		private static void NetTeleport(GameObject go)
		{
			if (go == null)
			{
				return;
			}
			Vector3 position = go.transform.position;
			Quaternion rotation = go.transform.rotation;
			try
			{
				Component[] componentsInChildren = go.GetComponentsInChildren<Component>(true);
				if (componentsInChildren == null)
				{
					return;
				}
				Component[] array = componentsInChildren;
				foreach (Component component in array)
				{
					if (component == null)
					{
						continue;
					}
					string text = component.GetType().Name;
					if (text.IndexOf("NetworkTransform", StringComparison.Ordinal) < 0 && text != "NetworkIdentity")
					{
						continue;
					}
					MethodInfo[] methods = component.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if (methods == null)
					{
						continue;
					}
					MethodInfo[] array2 = methods;
					foreach (MethodInfo methodInfo in array2)
					{
						if (methodInfo == null)
						{
							continue;
						}
						string text2 = methodInfo.Name;
						if (text2.IndexOf("Teleport", StringComparison.OrdinalIgnoreCase) < 0)
						{
							continue;
						}
						ParameterInfo[] parameters = methodInfo.GetParameters();
						try
						{
							if (parameters.Length == 2 && parameters[0].ParameterType == typeof(Vector3) && parameters[1].ParameterType == typeof(Quaternion))
							{
								methodInfo.Invoke(component, new object[2] { position, rotation });
								return;
							}
							if (parameters.Length == 1 && parameters[0].ParameterType == typeof(Vector3))
							{
								methodInfo.Invoke(component, new object[1] { position });
								return;
							}
						}
						catch
						{
						}
					}
				}
			}
			catch
			{
			}
		}

		private static void GiveGame(PlayerProfile who, GameBase pref)
		{
			try
			{
				if (!(pref == null) && !(who == null))
				{
					PlaceOwnedWorld(who, pref.gameObject, 2.4f);
				}
			}
			catch
			{
			}
		}

