		{
			try
			{
				if (so != null && IsMachine(so) && so.prefab != null)
				{
					PlaceOwnedWorld(who, so.prefab, 2.4f);
					return;
				}
			}
			catch
			{
			}
			try
			{
				if (!(so == null) && !(so.prefab == null) && !(who == null))
				{
					PlaceOwnedWorld(who, so.prefab, 1.6f);
				}
			}
			catch
			{
			}
		}

		private static Dictionary<int, int> ParseStash(string raw)
		{
			Dictionary<int, int> dictionary = new Dictionary<int, int>();
			if (string.IsNullOrEmpty(raw))
			{
				return dictionary;
			}
			string[] array = raw.Split(new char[1] { ',' });
			string[] array2 = array;
			foreach (string text in array2)
			{
				if (string.IsNullOrEmpty(text))
				{
					continue;
				}
				int num = text.IndexOf(':');
				int result;
				int result2;
				if (num > 0 && int.TryParse(text.Substring(0, num), out result) && int.TryParse(text.Substring(num + 1), out result2) && result != 0 && result2 != 0)
				{
					int value = 0;
					dictionary.TryGetValue(result, out value);
					value += result2;
					if (value <= 0)
					{
						dictionary.Remove(result);
					}
					else
					{
						dictionary[result] = value;
					}
				}
			}
			return dictionary;
		}

		private static string FormatStash(Dictionary<int, int> map)
		{
			if (map == null || map.Count == 0)
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder();
			foreach (KeyValuePair<int, int> item in map)
			{
				if (item.Key != 0 && item.Value > 0)
				{
					if (stringBuilder.Length > 0)
					{
						stringBuilder.Append(',');
					}
					stringBuilder.Append(item.Key.ToString(CultureInfo.InvariantCulture));
					stringBuilder.Append(':');
					stringBuilder.Append(item.Value.ToString(CultureInfo.InvariantCulture));
				}
			}
			return stringBuilder.ToString();
		}

		private static void StashAdd(Acc a, int sid, int n)
		{
			if (a != null && sid != 0 && n != 0)
			{
				Dictionary<int, int> dictionary = ParseStash(a.stash);
				int value = 0;
				dictionary.TryGetValue(sid, out value);
				value += n;
				if (value <= 0)
				{
					dictionary.Remove(sid);
				}
				else
				{
					dictionary[sid] = value;
				}
				a.stash = FormatStash(dictionary);
			}
		}

