		private static bool IsRetrieveNpc(Component c)
		{
			if (c == null)
			{
				return false;
			}
			string text = "";
			try
			{
				InteractableBase interactableBase = c as InteractableBase;
				if (interactableBase == null)
				{
					interactableBase = c.GetComponent<InteractableBase>();
				}
				if (interactableBase == null)
				{
					interactableBase = c.GetComponentInParent<InteractableBase>();
				}
				if (interactableBase != null)
				{
					try
					{
						text = text + " " + interactableBase.InteractableName;
					}
					catch
					{
					}
					try
					{
						text = text + " " + interactableBase.TooltipMessage;
					}
					catch
					{
					}
					try
					{
						FieldInfo fieldInfo = AccessTools.Field(typeof(InteractableBase), "interactableName");
						if (fieldInfo != null)
						{
							text = text + " " + (fieldInfo.GetValue(interactableBase) as string);
						}
					}
					catch
					{
					}
				}
			}
			catch
			{
			}
			try
			{
				if (c.gameObject != null)
				{
					text = text + " " + c.gameObject.name;
				}
				if (c.transform != null && c.transform.parent != null)
				{
					text = text + " " + c.transform.parent.name;
				}
			}
			catch
			{
			}
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			if (HasTxt(text, "篮球") || HasTxt(text, "找回按钮") || HasTxt(text, "找回篮球"))
			{
				return false;
			}
			string s = text.ToLowerInvariant();
			if (HasTxt(s, "basket") || HasTxt(s, "hoop"))
			{
				return false;
			}
			if (HasTxt(text, "找回"))
			{
				return true;
			}
			if (HasTxt(s, "retrieve"))
			{
				return true;
			}
			if (HasTxt(s, "return item"))
			{
				return true;
			}
			if (HasTxt(s, "recover item"))
			{
				return true;
			}
			return false;
		}

		internal static bool TryRetrieveNpc(Component c, PlayerProfile who)
		{
			if (!NetworkServer.active)
			{
				return false;
