		}

		private static void RetrieveOwnedTools(PlayerProfile who, Transform at)
		{
			if (!NetworkServer.active || who == null || _doingRetrieve)
			{
				return;
			}
			Acc acc = Ensure(who);
			if (acc == null)
			{
				return;
			}
			string text = (string.IsNullOrEmpty(acc.id) ? Key(who) : acc.id);
			if (text == _retrieveWho && Time.unscaledTime - _retrieveAt < 1.4f)
			{
				return;
			}
			_retrieveWho = text ?? "";
			_retrieveAt = Time.unscaledTime;
			Dictionary<int, int> dictionary = ParseStash(acc.stash);
			GunLog("retrieve by acc=" + acc.id + " name=" + acc.name + " rawStash=[" + acc.stash + "] parsed=" + dictionary.Count);
			List<int> list = new List<int>();
			foreach (KeyValuePair<int, int> item2 in dictionary)
			{
				if (!SpawnIsBatOrGun(FindSpawnable(item2.Key)))
				{
					list.Add(item2.Key);
				}
			}
			for (int i = 0; i < list.Count; i++)
			{
				dictionary.Remove(list[i]);
			}
			if (dictionary.Count == 0)
			{
				GunLog("nothing in stash to retrieve; scanning world for owned bats/guns...");
				try
				{
					Item[] all = UnityEngine.Object.FindObjectsByType<Item>(FindObjectsSortMode.None);
					if (all != null)
					{
						foreach (Item it in all)
						{
							if (it == null)
							{
								continue;
							}
							int sid = ItemSpawnId(it);
							if (!SpawnIsBatOrGun(FindSpawnable(sid)))
							{
								continue;
							}
							uint nid = NetIdOf(it);
							string ownerKey = null;
							if (nid != 0)
							{
								BatOwnerKey.TryGetValue(nid, out ownerKey);
							}
							GunLog("world gun/bat sid=" + sid + " netId=" + nid + " ownerKey=[" + (ownerKey ?? "null") + "] isOwnerOfWho=" + IsOwner(it, who) + " held=" + ItemIsHeld(it));
						}
					}
				}
				catch (Exception exg)
				{
					GunLog("world scan error: " + exg.Message);
				}
				NotifyMoney(acc, "没有可找回的球棒或手枪", 2);
				return;
			}
			_doingRetrieve = true;
			try
			{
				Vector3 vector = FlatForward(who);
				Vector3 vector2 = Vector3.Cross(Vector3.up, vector);
				if (vector2.sqrMagnitude < 0.2f)
				{
					vector2 = Vector3.right;
				}
				vector2.Normalize();
				int num = 0;
				int num2 = 0;
				int num3 = 0;
				Item[] array = null;
				try
				{
					array = UnityEngine.Object.FindObjectsByType<Item>(FindObjectsSortMode.None);
				}
				catch
				{
				}
				foreach (KeyValuePair<int, int> item3 in dictionary)
				{
					int key = item3.Key;
					int value = item3.Value;
					if (key == 0 || value <= 0)
					{
						continue;
					}
					int num4 = 0;
					if (array != null)
					{
						for (int j = 0; j < array.Length; j++)
						{
							if (num4 >= value)
							{
								break;
							}
							Item item = array[j];
							if (item == null || ItemSpawnId(item) != key)
							{
								continue;
							}
							bool flag = IsOwner(item, who);
							if (!flag)
							{
								try
								{
									NetworkIdentity netIdentity = item.netIdentity;
									if (netIdentity != null)
									{
										flag = IsOwner(netIdentity, who);
									}
								}
								catch
								{
								}
							}
							if (!flag)
							{
								continue;
							}
							if (ItemIsHeld(item))
							{
								num4++;
								continue;
							}
							Vector3 vector3 = PlaceInFrontOnFloor(who, 1.5f) + vector2 * (num % 5 - 2) * 0.42f + vector * (num / 5) * 0.42f;
							num++;
							try
							{
								item.transform.position = vector3 + Vector3.up * 0.04f;
							}
							catch
							{
							}
							NetTeleport(item.gameObject);
							if (_inst != null)
							{
								_inst.StartCoroutine(FinishOwnedClaim(item.gameObject, who, vector3));
							}
							num4++;
							num2++;
						}
					}
					int num5 = value - num4;
					SpawnableSO spawnableSO = FindSpawnable(key);
					if (!(spawnableSO == null) && !(spawnableSO.prefab == null))
					{
						for (int k = 0; k < num5; k++)
						{
							Vector3 shift = vector2 * (num % 5 - 2) * 0.42f + vector * (num / 5) * 0.42f;
							num++;
							PlaceOwnedWorld(who, spawnableSO.prefab, 1.5f, shift);
							num3++;
						}
					}
				}
				GunLog("retrieve result: moved=" + num2 + " spawned=" + num3);
				if (num3 + num2 <= 0)
				{
					NotifyMoney(acc, "道具都在", 2);
				}
				else
				{
					NotifyMoney(acc, "已找回 " + (num3 + num2) + " 件道具", 1);
				}
				Broadcast();
			}
			finally
			{
				_doingRetrieve = false;
			}
		}

