		internal static string AccLine(Acc a)
		{
			return a.name.Replace('\t', ' ').Replace('\n', ' ') + "\t" + a.money.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.tickets + "\t" + a.day + "\t" + a.quota.ToString("R", CultureInfo.InvariantCulture) + "\t" + (a.id ?? "") + "\t" + a.loanExtra.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.shopBuyT + "\t" + a.shopSellT + "\t" + a.shopDay + "\t" + a.loanUsed.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.loanDay + "\t" + a.bonusDraw + "\t" + a.hoopDay + "\t" + a.hoopBonus.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.payStreak + "\t" + a.allowBet + "\t" + a.rentDay + "\t" + (a.rentPass ?? "").Replace('\t', ' ').Replace('\n', ' ') + "\t" + a.confStacks + "\t" + a.insStacks + "\t" + a.stakeStacks + "\t" + (a.stash ?? "").Replace('\t', ' ').Replace('\n', ' ') + "\t" + a.catches + "\t" + a.kit + "\t" + a.goalTier + "\t" + a.goalOk + "\t" + a.goalDay + "\t" + a.stealPct.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.winDay.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.protectStreak + "\t" + (a.betLock ?? "").Replace('\t', ' ') + "\t" + a.betCost.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.betCash.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.robbedDay + "\t" + a.job + "\t" + a.usuryDue.ToString("R", CultureInfo.InvariantCulture) + "\t" + (a.usuryFrom ?? "").Replace('\t', ' ').Replace('\n', ' ') + "\t" + (a.duelPeer ?? "").Replace('\t', ' ') + "\t" + a.duelCash0.ToString("R", CultureInfo.InvariantCulture) + "\t" + a.duelDay;
		}

		internal static string BuildPayload(List<Acc> list)
		{
			if (list == null)
			{
				list = new List<Acc>();
			}
			int value = ((!RankBoardVisible()) ? 1 : 0);
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("SB2\n").Append(SharedDay).Append('\n')
				.Append(value)
				.Append('\n')
				.Append("0\n");
			for (int i = 0; i < list.Count; i++)
			{
				Acc acc = list[i];
				if (acc != null && !string.IsNullOrEmpty(acc.name))
				{
					stringBuilder.Append(AccLine(acc)).Append('\n');
				}
			}
			return stringBuilder.ToString();
		}

		internal static string BuildSavePayload(List<Acc> list)
		{
			if (list == null)
			{
				list = new List<Acc>();
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("SB1\n").Append(SharedDay).Append('\n');
			for (int i = 0; i < list.Count; i++)
			{
				Acc acc = list[i];
				if (acc != null && !string.IsNullOrEmpty(acc.name))
				{
					stringBuilder.Append(AccLine(acc)).Append('\n');
				}
			}
			return stringBuilder.ToString();
		}

		internal static void SaveToDisk()
		{
			if (NetworkServer.active)
			{
				EnsureAll();
				File.WriteAllText(SavePath(), BuildSavePayload(NamedAccs()), Encoding.UTF8);
				_saveMsg = "已保存 " + DateTime.Now.ToString("HH:mm:ss");
				Broadcast();
			}
		}

		internal static void LoadFromDisk()
		{
			string path = SavePath();
			if (!File.Exists(path))
			{
				return;
			}
			string raw = File.ReadAllText(path, Encoding.UTF8);
			ApplyPayload(raw);
			Accs.Clear();
			Acc[] view = View;
			if (view == null)
			{
				return;
			}
			Acc[] array = view;
			foreach (Acc acc in array)
			{
				if (acc != null && !string.IsNullOrEmpty(acc.name))
				{
					string key = (acc.id = (string.IsNullOrEmpty(acc.id) ? ("p" + acc.name) : acc.id));
					Accs[key] = acc;
				}
			}
			foreach (Acc value in Accs.Values)
			{
				FixMissingQuota(value);
			}
			foreach (Acc value2 in Accs.Values)
			{
				ulong result;
				if (value2 != null && !string.IsNullOrEmpty(value2.id) && value2.id.Length >= 2 && value2.id[0] == 's' && ulong.TryParse(value2.id.Substring(1), out result))
				{
					SyncUpgradePanel(result);
				}
			}
		}

		internal static void Broadcast()
		{
			if (!NetworkServer.active)
			{
				return;
			}
			EnsureAll();
			foreach (Acc value7 in Accs.Values)
			{
				if (value7 != null)
				{
					RefreshShopDay(value7);
				}
				RefreshGoalDay(value7);
				FixMissingQuota(value7);
			}
			List<Acc> list = PresentAccs();
			View = list.ToArray();
			ApplyAllElevatorLocks();
			string text = BuildPayload(list);
			if (ThisPcCanHost())
			{
				text = "HOK\n" + text;
			}
			try
			{
				foreach (KeyValuePair<int, NetworkConnectionToClient> connection in NetworkServer.connections)
				{
					NetworkConnectionToClient value = connection.Value;
					if (value == null)
					{
						continue;
					}
					PlayerProfile playerProfile = ProfileFromIdentity(value.identity);
					SoloMsg message = new SoloMsg
					{
						json = text + BuildBatOwnerLines() + BuildChalProgLines(playerProfile) + BuildSideLines()
					};
					value.Send(message);
					if (!(playerProfile != null))
					{
						continue;
					}
					int job = GetJob(playerProfile);
					float num = StealCoolLeft(playerProfile);
					Acc acc = Ensure(playerProfile);
					if (value.identity != null && value.identity.isLocalPlayer)
					{
						LocalJob = job;
						if (num > 0.05f)
						{
							StealCoolUntil = Time.unscaledTime + num;
						}
						if (acc != null && GetJob(acc) == 4)
						{
							LocalCatches = acc.catches;
						}
						string value2;
						string value3;
						if (acc != null && FaceMem.TryGetValue(acc.id, out value2) && FaceMemName.TryGetValue(acc.id, out value3))
						{
							LocalFaceKey = value2;
							LocalFaceName = value3;
						}
						continue;
					}
					value.Send(new SoloMsg
					{
						json = "JOB\t" + job
					});
					if (num > 0.05f)
					{
						value.Send(new SoloMsg
						{
							json = "THCD\t" + num.ToString("R", CultureInfo.InvariantCulture)
						});
					}
					if (acc != null && GetJob(acc) == 4)
					{
						value.Send(new SoloMsg
						{
							json = "CATCH\t" + acc.catches.ToString(CultureInfo.InvariantCulture)
						});
					}
					string value4;
					string value5;
					if (acc != null && FaceMem.TryGetValue(acc.id, out value4) && FaceMemName.TryGetValue(acc.id, out value5))
					{
						string value6;
						FaceMemLook.TryGetValue(acc.id, out value6);
						value.Send(new SoloMsg
						{
							json = "FACE\t" + value5 + "\t" + value4 + "\t" + (value6 ?? "")
						});
					}
				}
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[SoloBank] sync: " + ex.Message);
			}
			BroadcastSeats();
		}

		internal static void SettleDay()
		{
			if (!NetworkServer.active || EconomyFrozen() || Time.unscaledTime < _settleLockUntil)
			{
				return;
			}
			_settleLockUntil = Time.unscaledTime + 20f;
			EnsureAll();
			if (!string.IsNullOrEmpty(_usuryPendTgt))
			{
				PlayerProfile playerProfile = FindProfileByKey(_usuryPendBoss);
				PlayerProfile playerProfile2 = FindProfileByKey(_usuryPendTgt);
				if (playerProfile != null)
				{
					SendSoloTo(playerProfile, "UEND");
				}
				if (playerProfile2 != null)
				{
					SendSoloTo(playerProfile2, "UEND");
				}
				ClearUsuryPend();
			}
			ReturnParkedBets();
			PayGuardPayroll();
			EvaluateClassGoals();
			List<Acc> list = PresentAccs();
			bool flag = SharedDay == 10;
			for (int i = 0; i < list.Count; i++)
			{
				SettleUsuryOne(list[i]);
			}
			SettleDuels(list);
			ClearAllDuels();
			QueueRestoreGamblerUi();
			List<Acc> list2 = new List<Acc>();
			List<Acc> list3 = new List<Acc>();
			Acc guardAcc = null;
			for (int g = 0; g < list.Count; g++)
			{
				if (list[g] != null && GetJob(list[g]) == 4)
				{
					guardAcc = list[g];
					break;
				}
			}
			double guardTake = 0.0;
			for (int j = 0; j < list.Count; j++)
			{
				Acc acc = list[j];
				if (guardAcc != null && acc != null && acc != guardAcc && (IsGambler(acc) || IsThief(acc)) && acc.money + 0.001 >= acc.quota)
				{
					double quotaCut = acc.quota - acc.loanExtra;
					if (quotaCut > 0.0001)
					{
						guardTake += quotaCut;
					}
				}
				if (flag)
				{
					double num = acc.money - acc.quota;
					if (num < 0.0)
					{
						num = 0.0;
					}
					acc.money = num;
					acc.loanExtra = 0.0;
					acc.hoopBonus = 0.0;
					acc.quota = 0.0;
					acc.payStreak = 0;
					continue;
				}
				if (GetJob(acc) == 1 || GetJob(acc) == 4)
				{
					acc.loanExtra = 0.0;
					acc.day++;
					acc.payStreak++;
					acc.quota = 0.0;
					list2.Add(acc);
					continue;
				}
				if (acc.money + 0.001 < acc.quota)
				{
					ResetToClassStart(acc);
					list3.Add(acc);
					continue;
				}
				double num2 = acc.money - acc.quota;
				if (num2 < 0.0)
				{
					num2 = 0.0;
				}
				acc.money = num2;
				acc.loanExtra = 0.0;
				acc.day++;
				acc.payStreak++;
				acc.quota = Acc.QuotaFromLeftover(acc.day, acc.payStreak, num2, 0.0, acc.hoopBonus);
				list2.Add(acc);
			}
			if (guardAcc != null && guardTake > 0.0001)
			{
				guardAcc.notePay += guardTake;
				QueueNote(guardAcc, "赌徒和小偷上交的指标 +" + MoneyDollar(guardTake), 1);
			}
			SharedDay++;
			ClearFaceMemAll();
			_quotaFreezeDay = 0;
			_blockVanillaTixUntil = Time.unscaledTime + 180f;
			foreach (Acc value in Accs.Values)
			{
				if (value != null)
				{
					value.loanDay = SharedDay;
					value.loanUsed = 0.0;
				}
			}
			FreezeQuotasForDay();
			KeepUpgradeKeys.Clear();
			KeepUpgradeAccs.Clear();
			for (int k = 0; k < list2.Count; k++)
			{
				Acc acc2 = list2[k];
				if (acc2 != null && (GetJob(acc2) == 2 || acc2.job == 2 || IsGambler(acc2)))
				{
					KeepUpgradeAccs.Add(acc2);
					string text = AccKeepKey(acc2);
					if (!string.IsNullOrEmpty(text))
					{
						KeepUpgradeKeys[text] = 1;
					}
					if (!string.IsNullOrEmpty(acc2.name))
					{
						KeepUpgradeKeys[acc2.name] = 1;
					}
					if (!string.IsNullOrEmpty(acc2.id))
					{
						KeepUpgradeKeys[acc2.id] = 1;
					}
				}
			}
			ClearAllUpgrades();
			ClearPlayerChallengeProgress();
			List<Acc> list4 = PresentAccs();
			for (int l = 0; l < list4.Count; l++)
			{
				Acc acc3 = list4[l];
				if (acc3 != null && GetJob(acc3) >= 1 && (acc3.goalTier <= 2 || !(acc3.goalPayCash <= 0.0001) || acc3.goalPayTix > 0))
				{
					SendGoalFx(acc3, acc3.goalOk != 0, acc3.goalPayCash, acc3.goalPayTix);
				}
			}
			Broadcast();
		}

		private static void ReturnParkedBets()
		{
			if (!NetworkServer.active)
			{
				return;
			}
			Dictionary<string, double> dictionary = new Dictionary<string, double>();
			for (int i = 0; i < SideBets.Count; i++)
			{
				SideWager sideWager = SideBets[i];
				if (sideWager != null && !string.IsNullOrEmpty(sideWager.from))
				{
					double num = sideWager.amt;
					if (num < 0.0)
					{
						num = 0.0;
					}
					double value = 0.0;
					dictionary.TryGetValue(sideWager.from, out value);
					dictionary[sideWager.from] = value + num;
				}
			}
			SideBets.Clear();
			foreach (KeyValuePair<string, double> item in dictionary)
			{
				Acc acc = FindAccByKey(item.Key);
				if (acc != null)
				{
					acc.money += item.Value;
					QueueNote(acc, "你押在其他玩家身上的" + MoneyDollar(item.Value) + "已全部返回", 1);
				}
			}
		}

		private static void PayGuardPayroll()
		{
			Acc acc = null;
			Acc acc2 = null;
			List<Acc> list = PresentAccs();
			if (list == null)
			{
				return;
			}
			for (int i = 0; i < list.Count; i++)
			{
				Acc acc3 = list[i];
				if (acc3 != null)
				{
					if (acc == null && GetJob(acc3) == 1)
					{
						acc = acc3;
					}
					if (acc2 == null && GetJob(acc3) == 4)
					{
						acc2 = acc3;
					}
				}
			}
			if (acc == null || acc2 == null)
			{
				_bossRobbed = false;
				_bossRobber = "";
				return;
			}
			int num = acc2.catches;
			if (num < 0)
			{
				num = 0;
			}
			double num2 = 0.1 + 0.02 * (double)num;
			double num3 = acc.money * num2;
			if (num3 < 0.0)
			{
				num3 = 0.0;
			}
			if (num3 > acc.money)
			{
				num3 = acc.money;
			}
			string text = (string.IsNullOrEmpty(acc2.name) ? "玩家" : acc2.name);
			string text2 = MoneyDollar(num3);
			if (_bossRobbed)
			{
				Acc acc4 = FindAccByKey(_bossRobber);
				acc.notePay -= num3;
				if (acc4 != null)
				{
					acc4.notePay += num3;
				}
				QueueNote(acc2, "因为你的疏忽你老板的钱被小偷偷走了~所以老板决定今天不给你工资", 0);
				if (acc4 != null)
				{
					QueueNote(acc4, "劫富济穷+" + text2, 1);
				}
				QueueNote(acc, "你的保安有什么用~ -" + text2, 0);
			}
			else if (num3 > 0.0001)
			{
				acc.notePay -= num3;
				acc2.notePay += num3;
				QueueNote(acc, "已付" + text + "工资" + text2, 0);
				QueueNote(acc2, text2 + "工资已入账", 1);
			}
			_bossRobbed = false;
			_bossRobber = "";
		}

		internal static void FreezeQuotasForDay()
		{
			if (!NetworkServer.active)
			{
				return;
			}
			if (SharedDay > 10)
			{
				foreach (Acc value in Accs.Values)
				{
					if (value != null)
					{
						value.quota = 0.0;
					}
				}
				_quotaFreezeDay = SharedDay;
				return;
			}
			if (_quotaFreezeDay == SharedDay)
			{
				foreach (Acc value2 in Accs.Values)
				{
					FixMissingQuota(value2);
				}
				return;
			}
			_quotaFreezeDay = SharedDay;
			EnsureAll();
			foreach (Acc value3 in Accs.Values)
			{
				FixMissingQuota(value3);
			}
		}

