		internal static void NoteBetStart(GameBase game, PlayerProfile p)
		{
			if (game == null || p == null)
			{
				return;
			}
			Acc acc = Ensure(p);
			if (acc != null)
			{
				string key = Key(p);
				double num = GameStakeAmount(game);
				if (num < 0.0)
				{
					num = 0.0;
				}
				_betAmt[key] = num;
				if (UsesChipBets(game))
				{
					_betMoney[key] = acc.money + num;
				}
				else if (acc.money + 0.0001 >= num)
				{
					_betMoney[key] = acc.money;
				}
				else
				{
					_betMoney[key] = acc.money + num;
				}
			}
		}

		internal static double StakePct(Acc a)
		{
			if (a == null || a.stakeStacks < 1)
			{
				return 0.0;
			}
			int stakeStacks = a.stakeStacks;
			if (IsGambler(a))
			{
				double num = 0.25 * (double)stakeStacks;
				if (num > 1.0)
				{
					num = 1.0;
				}
				return num;
			}
			return 0.5 * (double)stakeStacks;
		}

		internal static double StakeFactor(Acc a)
		{
			if (a == null || a.stakeStacks < 1)
			{
				return 1.0;
			}
			if (AccDuelNoBuffs(a))
			{
				return 1.0;
			}
			return 1.0 + StakePct(a);
		}

		internal static double StakeFactorRaw(Acc a)
		{
			if (a == null || a.stakeStacks < 1)
			{
				return 1.0;
			}
			return 1.0 + StakePct(a);
		}

		internal static double ConfBasePct(Acc a)
		{
			if (a == null || a.confStacks < 1)
			{
				return 0.0;
			}
			if (IsGambler(a))
			{
				double num = (double)a.confStacks * 0.5;
				if (num > 2.5)
				{
					num = 2.5;
				}
				return num;
			}
			return (double)a.confStacks * 1.0;
		}

		internal static double ConfMorePct(Acc a)
		{
			if (a == null || a.confStacks < 1)
			{
				return 0.0;
			}
			if (AccDuelNoBuffs(a))
			{
				return 0.0;
			}
			return ConfMorePctRaw(a);
		}

		internal static double ConfMorePctRaw(Acc a)
		{
			if (a == null || a.confStacks < 1)
			{
				return 0.0;
			}
			double num = ConfBasePct(a) * StakeFactorRaw(a);
			if (IsGambler(a) && num > 5.0)
			{
				num = 5.0;
			}
			return num;
		}

		internal static double InsBasePct(Acc a)
		{
			if (a == null)
			{
				return 0.0;
			}
			int num = a.insStacks;
			if (num <= 0)
			{
				return 0.0;
			}
			if (IsGambler(a))
			{
				if (num > 6)
				{
					num = 6;
				}
				return 0.125 + 0.025 * (double)(num - 1);
			}
			switch (num)
			{
			case 1:
				return 0.25;
			case 2:
				return 0.45;
			case 3:
				return 0.6;
			case 4:
				return 0.7;
			default:
				return 0.75;
			}
		}

		internal static double InsEffective(Acc a)
		{
			if (AccDuelNoBuffs(a))
			{
				return 0.0;
			}
			return InsEffectiveRaw(a);
		}

		internal static double InsEffectiveRaw(Acc a)
		{
			double num = InsBasePct(a) * StakeFactorRaw(a);
			if (IsGambler(a))
			{
				if (num > 0.5)
				{
					num = 0.5;
				}
			}
			else if (num > 0.75)
			{
				num = 0.75;
			}
			return num;
		}

		internal static PlayerProfile ProfileFromSteam(ulong steamId)
		{
			if (steamId == 0)
			{
				return null;
			}
			try
			{
				PlayerProfile[] array = UnityEngine.Object.FindObjectsByType<PlayerProfile>(FindObjectsSortMode.None);
				if (array == null)
				{
					return null;
				}
				PlayerProfile[] array2 = array;
				foreach (PlayerProfile playerProfile in array2)
				{
					if (playerProfile != null && playerProfile.steamId == steamId)
					{
						return playerProfile;
					}
				}
			}
			catch
			{
			}
			return null;
		}

		internal static Acc AccFromSteam(ulong steamId)
		{
			PlayerProfile playerProfile = ProfileFromSteam(steamId);
			if (playerProfile != null)
			{
				return Ensure(playerProfile);
			}
			string key = "s" + steamId;
			Acc value;
			if (Accs.TryGetValue(key, out value))
			{
				return value;
			}
			return null;
		}

		internal static Acc LocalViewAcc()
		{
			PlayerProfile playerProfile = LocalProfile();
			if (playerProfile == null)
			{
				return null;
			}
			if (NetworkServer.active)
			{
				return Ensure(playerProfile);
			}
			string text = Key(playerProfile);
			string playerName = playerProfile.playerName;
			if (View == null)
			{
				return null;
			}
			for (int i = 0; i < View.Length; i++)
			{
				Acc acc = View[i];
				if (acc != null)
				{
					if (!string.IsNullOrEmpty(text) && acc.id == text)
					{
						return acc;
					}
					if (!string.IsNullOrEmpty(playerName) && acc.name == playerName)
					{
						return acc;
					}
				}
			}
			return null;
		}

		internal static void SyncUpgradePanel(ulong steamId)
		{
			if (steamId == 0)
			{
				return;
			}
			Acc acc = AccFromSteam(steamId);
			if (acc == null)
			{
				return;
			}
			try
			{
				UpgradeManager instance = NetworkSingleton<UpgradeManager>.Instance;
				if (instance == null)
				{
					return;
				}
				if (AccDuelNoBuffs(acc))
				{
					instance.SetUpgradeData(steamId, PlayerUpgradeType.GamblersConfidence, 1f);
					instance.SetUpgradeData(steamId, PlayerUpgradeType.Insurance, 0f);
					instance.SetUpgradeData(steamId, PlayerUpgradeType.Stakeholder, 1f);
					instance.SetUpgradeData(steamId, PlayerUpgradeType.BonusDraw, 0f);
					return;
				}
				if (acc.confStacks > 0)
				{
					instance.SetUpgradeData(steamId, PlayerUpgradeType.GamblersConfidence, (float)(1.0 + ConfMorePctRaw(acc)));
				}
				if (acc.insStacks > 0)
				{
					instance.SetUpgradeData(steamId, PlayerUpgradeType.Insurance, (float)InsEffectiveRaw(acc));
				}
				if (acc.stakeStacks > 0)
				{
					instance.SetUpgradeData(steamId, PlayerUpgradeType.Stakeholder, (float)StakeFactorRaw(acc));
				}
				if (acc.bonusDraw > 0)
				{
					instance.SetUpgradeData(steamId, PlayerUpgradeType.BonusDraw, BonusDrawUiValue(acc));
				}
			}
			catch
			{
			}
		}

		internal static void PaintLocalUpgradeUi()
		{
			Acc acc = LocalViewAcc();
			if (acc == null)
			{
				acc = LocalAccRow();
			}
			bool flag = AccDuelNoBuffs(acc);
			if ((acc == null || (acc.confStacks <= 0 && acc.insStacks <= 0 && acc.stakeStacks <= 0 && acc.bonusDraw <= 0)) && !flag && LocalJob != 2)
			{
				return;
			}
			try
			{
				UpgradeUI[] array = UnityEngine.Object.FindObjectsByType<UpgradeUI>(FindObjectsInactive.Include, FindObjectsSortMode.None);
				if (array == null)
				{
					return;
				}
				UpgradeUI[] array2 = array;
				foreach (UpgradeUI upgradeUI in array2)
				{
					if (upgradeUI == null)
					{
						continue;
					}
					if (acc != null)
					{
						if (acc.confStacks > 0)
						{
							upgradeUI.UpdateUpgradeUI(PlayerUpgradeType.GamblersConfidence, (float)(1.0 + ConfMorePctRaw(acc)), 0f);
						}
						if (acc.insStacks > 0)
						{
							upgradeUI.UpdateUpgradeUI(PlayerUpgradeType.Insurance, (float)InsEffectiveRaw(acc), 0f);
						}
						if (acc.stakeStacks > 0)
						{
							upgradeUI.UpdateUpgradeUI(PlayerUpgradeType.Stakeholder, (float)StakeFactorRaw(acc), 0f);
						}
						if (acc.bonusDraw > 0)
						{
							upgradeUI.UpdateUpgradeUI(PlayerUpgradeType.BonusDraw, BonusDrawUiValue(acc), 0f);
						}
						SortUpgradeUi(upgradeUI);
					}
					PaintDuelUpgradeCrosses(upgradeUI, flag);
				}
			}
			catch
			{
			}
		}

		internal static float BonusDrawUiValue(Acc a)
		{
			if (a == null || a.bonusDraw < 1)
			{
				return 0f;
			}
			return 0.25f;
		}

		private static void SortUpgradeUi(UpgradeUI ui)
		{
			if (ui == null)
			{
				return;
			}
			try
			{
				if (_upEntF == null)
				{
					_upEntF = AccessTools.Field(typeof(UpgradeUI), "_upgradeEntries");
				}
				object obj = ((_upEntF != null) ? _upEntF.GetValue(ui) : null);
				IDictionary dictionary = obj as IDictionary;
				if (dictionary == null)
				{
					return;
				}
				PlayerUpgradeType[] array = new PlayerUpgradeType[4]
				{
					PlayerUpgradeType.BonusDraw,
					PlayerUpgradeType.Stakeholder,
					PlayerUpgradeType.Insurance,
					PlayerUpgradeType.GamblersConfidence
				};
				for (int i = 0; i < array.Length; i++)
				{
					if (dictionary.Contains(array[i]))
					{
						UpgradeEntryUI upgradeEntryUI = dictionary[array[i]] as UpgradeEntryUI;
						if (!(upgradeEntryUI == null) && !(upgradeEntryUI.transform == null))
						{
							upgradeEntryUI.transform.SetAsFirstSibling();
						}
					}
				}
			}
			catch
			{
			}
		}

		internal static void ForceSortUpgradeUi(UpgradeUI ui)
		{
			SortUpgradeUi(ui);
		}

		internal static void PaintDuelUpgradeCrosses(UpgradeUI ui, bool on)
		{
			if (ui == null)
			{
				return;
			}
			try
			{
				if (_upEntF == null)
				{
					_upEntF = AccessTools.Field(typeof(UpgradeUI), "_upgradeEntries");
				}
				object obj = ((_upEntF != null) ? _upEntF.GetValue(ui) : null);
				IDictionary dictionary = obj as IDictionary;
				if (dictionary == null)
				{
					return;
				}
				foreach (object value in dictionary.Values)
				{
					UpgradeEntryUI ent = value as UpgradeEntryUI;
					StampDuelCross(ent, on);
				}
			}
			catch
			{
			}
		}

		internal static void StampDuelCross(UpgradeEntryUI ent, bool on)
		{
			if (ent == null)
			{
				return;
			}
			Transform transform = ent.transform;
			if (transform == null)
			{
				return;
			}
			Transform transform2 = transform.Find("DuelX");
			if (!on)
			{
				if (transform2 != null)
				{
					transform2.gameObject.SetActive(false);
				}
				return;
			}
			if (transform2 == null)
			{
				GameObject gameObject = new GameObject("DuelX");
				gameObject.transform.SetParent(transform, false);
				RectTransform rectTransform = gameObject.AddComponent<RectTransform>();
				rectTransform.anchorMin = Vector2.zero;
				rectTransform.anchorMax = Vector2.one;
				rectTransform.offsetMin = Vector2.zero;
				rectTransform.offsetMax = Vector2.zero;
				TextMeshProUGUI textMeshProUGUI = gameObject.AddComponent<TextMeshProUGUI>();
				textMeshProUGUI.text = "X";
				textMeshProUGUI.alignment = TextAlignmentOptions.Center;
				textMeshProUGUI.color = new Color(1f, 0.12f, 0.12f, 0.92f);
				textMeshProUGUI.fontSize = 64f;
				textMeshProUGUI.raycastTarget = false;
				transform2 = gameObject.transform;
			}
			transform2.gameObject.SetActive(true);
		}

		internal static void PaintBonusDrawBottle(Upgrade u)
		{
			if (u == null)
