				object value = AccessTools.Field(typeof(Upgrade), "upgradeType").GetValue(u);
				if (value == null || (PlayerUpgradeType)value != PlayerUpgradeType.BonusDraw)
				{
					return;
				}
				FieldInfo fieldInfo = AccessTools.Field(typeof(Upgrade), "value");
				if (fieldInfo != null)
				{
					fieldInfo.SetValue(u, 0.25f);
				}
				FieldInfo fieldInfo2 = AccessTools.Field(typeof(Upgrade), "valueText");
				object obj = ((fieldInfo2 != null) ? fieldInfo2.GetValue(u) : null);
				if (obj != null)
				{
					PropertyInfo property = obj.GetType().GetProperty("text");
					if (property != null)
					{
						property.SetValue(obj, "25%", null);
					}
				}
			}
			catch
			{
			}
		}

