		internal static bool ApplyUpgradeDrink(ulong steamId, PlayerUpgradeType type)
		{
			Acc acc = AccFromSteam(steamId);
			if (acc == null)
			{
				PlayerProfile p = ProfileFromSteam(steamId);
				acc = Ensure(p);
			}
			if (acc == null)
			{
				return false;
			}
			if (AccDuelNoBuffs(acc))
			{
				return false;
			}
			switch (type)
			{
			case PlayerUpgradeType.GamblersConfidence:
				acc.confStacks++;
				break;
			case PlayerUpgradeType.Insurance:
			{
				acc.insStacks++;
				int num = ((IsGambler(acc) || acc.job == 2 || GetJob(acc) == 2) ? 6 : 5);
				if (acc.insStacks > num)
				{
					acc.insStacks = num;
				}
				break;
			}
			case PlayerUpgradeType.Stakeholder:
				acc.stakeStacks++;
				break;
			case PlayerUpgradeType.BonusDraw:
				acc.bonusDraw = 1;
				return false;
			default:
				return false;
			}
			SyncUpgradePanel(steamId);
			return true;
		}

		internal static bool HasImmunityBuff(PlayerProfile p)
		{
			if (p == null)
			{
				return false;
			}
			try
			{
				PlayerBuff component = null;
				p.TryGetComponent<PlayerBuff>(out component);
				if (component == null)
				{
					component = p.GetComponentInChildren<PlayerBuff>();
				}
				if (component == null)
				{
					component = p.GetComponentInParent<PlayerBuff>();
				}
				if (component == null)
				{
					return false;
				}
				return component.GetValue(PlayerBuffType.Immunity) > 0.0001f;
			}
			catch
			{
			}
			return false;
		}

		internal static void BeginPayoutMoney(GameBase game, double multiplier, PlayerProfile p)
		{
			_payoutMoneyDone = false;
			_payoutMult = multiplier;
			_payoutWho = p;
			_payoutBet = 0.0;
			if (p != null)
			{
				string key = Key(p);
				if (_betAmt.ContainsKey(key))
				{
					_payoutBet = _betAmt[key];
				}
			}
			double num = GameStakeAmount(game);
			if (num > _payoutBet)
			{
				_payoutBet = num;
			}
		}

		internal static void ApplyPayoutMoney(PlayerProfile hint)
		{
			if (_payoutMoneyDone)
			{
				return;
			}
			_payoutMoneyDone = true;
			PlayerProfile playerProfile = _payoutWho ?? hint;
			if (playerProfile == null)
			{
				return;
			}
			Acc acc = Ensure(playerProfile);
			if (acc == null)
			{
				return;
			}
			double money = acc.money;
			double num = _payoutBet;
			if (num <= 0.0001)
			{
				string key = Key(playerProfile);
				if (_betAmt.ContainsKey(key))
				{
					num = _betAmt[key];
				}
			}
			if (num < 0.0)
			{
				num = 0.0;
			}
			double payoutMult = _payoutMult;
			double num2 = 1.0 + ConfMorePct(acc);
			if (num2 < 1.0)
			{
				num2 = 1.0;
			}
			double num3 = 0.0;
			double num4 = 0.0;
			if (payoutMult > 1.0001)
			{
				double num5 = num * (payoutMult - 1.0);
				if (num5 < 0.0)
				{
					num5 = 0.0;
				}
				num3 = num5 * num2;
				num4 = num + num3;
			}
			else if (payoutMult >= 0.999)
			{
				num3 = 0.0;
				num4 = num;
			}
			else if (HasImmunityBuff(playerProfile))
			{
				num3 = 0.0;
				num4 = num;
				NotifyMoney(acc, "圣像保护，赌资已退回", 1);
			}
			else
			{
				double num6 = num * (1.0 - payoutMult);
				if (num6 < 0.0)
				{
					num6 = 0.0;
				}
				num3 = (0.0 - num6) * (1.0 - InsEffective(acc));
				num4 = num + num3;
				if (num4 < 0.0)
				{
					num4 = 0.0;
				}
			}
			acc.money = money + num4;
			if (acc.money < 0.0)
			{
				acc.money = 0.0;
			}
			try
			{
				if (_inst != null)
				{
					_inst.Logger.LogInfo("[INS] who=" + (acc.id ?? "") + " bet=" + num.ToString("0.##", CultureInfo.InvariantCulture) + " mult=" + payoutMult.ToString("0.###", CultureInfo.InvariantCulture) + " insRaw=" + InsEffectiveRaw(acc).ToString("0.###", CultureInfo.InvariantCulture) + " insUsed=" + InsEffective(acc).ToString("0.###", CultureInfo.InvariantCulture) + " duel=" + (acc.duelPeer ?? "") + " immune=" + HasImmunityBuff(playerProfile) + " before=" + money.ToString("0.##", CultureInfo.InvariantCulture) + " after=" + acc.money.ToString("0.##", CultureInfo.InvariantCulture));
				}
			}
			catch
			{
			}
			if (IsGambler(acc) && Math.Abs(num3) > 0.0001)
			{
				RefreshGoalDay(acc);
				acc.winDay += num3;
				TouchGoalHud(acc);
			}
			if (num3 < -0.01)
			{
				TakeBossCut(acc, 0.0 - num3);
			}
			Broadcast();
		}

		private static int BonusDrawTicketsFromPct(double pct)
		{
			if (pct + 1E-07 >= 15.0)
			{
				return 15;
			}
			if (pct + 1E-07 >= 12.5)
			{
				return 13;
			}
			if (pct + 1E-07 >= 10.0)
			{
				return 11;
			}
			if (pct + 1E-07 >= 9.0)
			{
				return 10;
			}
			if (pct + 1E-07 >= 8.0)
			{
				return 9;
			}
			if (pct + 1E-07 >= 7.0)
			{
				return 8;
			}
			if (pct + 1E-07 >= 6.0)
			{
				return 7;
			}
			if (pct + 1E-07 >= 5.0)
			{
				return 6;
			}
			if (pct + 1E-07 >= 4.0)
			{
				return 5;
			}
			if (pct + 1E-07 >= 3.0)
			{
				return 4;
			}
			if (pct + 1E-07 >= 2.0)
			{
				return 3;
			}
			if (pct + 1E-07 >= 1.0)
			{
				return 2;
			}
			if (pct + 1E-07 >= 0.5)
			{
				return 1;
			}
			return 0;
		}

		private static int BonusDrawTicketsLegacy(double betFrac, double multiplier)
		{
			int result = 0;
			if (betFrac + 1E-07 >= 1.0)
			{
				if (multiplier + 1E-07 >= 10.0)
				{
					result = 10;
				}
				else if (multiplier + 1E-07 >= 5.0)
				{
					result = 7;
				}
				else
				{
					result = ((!(multiplier + 1E-07 >= 3.0)) ? 3 : 5);
				}
			}
			else if (betFrac + 1E-07 >= 0.5)
			{
				if (multiplier + 1E-07 >= 5.0)
				{
					result = 5;
				}
				else
				{
					result = ((!(multiplier + 1E-07 >= 3.0)) ? 2 : 3);
				}
			}
			else if (betFrac + 1E-07 >= 0.25)
			{
				result = ((multiplier + 1E-07 >= 5.0) ? 3 : ((!(multiplier + 1E-07 >= 3.0)) ? 1 : 2));
			}
			return result;
		}

		internal static void TryBonusDrawTickets(GameBase game, PlayerProfile p, double multiplier)
		{
			if (p == null)
			{
				return;
			}
			Acc acc = Ensure(p);
			if (!HasBonusDraw(p, acc) || EconomyFrozen() || multiplier <= 1.0001)
			{
				return;
			}
			if (game != null)
			{
				try
				{
					uint num = ((game.netIdentity != null) ? game.netIdentity.netId : 0u);
					if (num != 0 && num == _bonusTixGame && Time.unscaledTime - _bonusTixAt < 0.35f)
					{
						return;
					}
					if (num != 0)
					{
						_bonusTixGame = num;
						_bonusTixAt = Time.unscaledTime;
					}
				}
				catch
				{
				}
			}
			string key = Key(p);
			double num2 = 0.0;
			double num3 = 0.0;
			if (_betMoney.ContainsKey(key))
			{
				num2 = _betMoney[key];
			}
			if (_betAmt.ContainsKey(key))
			{
				num3 = _betAmt[key];
			}
			if (num3 <= 0.0 && game != null)
			{
				try
				{
					num3 = game.currentBet.ToDouble();
				}
				catch
				{
				}
			}
			if (num3 < 0.0)
			{
				num3 = 0.0;
			}
			double num4 = acc.money;
			if (num4 + 0.0001 < num3)
			{
				num4 += num3;
			}
			if (num2 < num4)
			{
				num2 = num4;
			}
			if (num2 <= 0.0001 || num3 <= 0.0 || num2 + 0.0001 < 1000.0)
			{
				return;
			}
			double num5 = 1.0 + ConfMorePct(acc);
			if (num5 < 1.0)
			{
				num5 = 1.0;
			}
			double num6 = num3 * (multiplier - 1.0) * num5;
			if (!(num6 <= 0.0001))
			{
				int num7 = BonusDrawTicketsFromPct(num6 / num2);
				if (num7 > 0)
				{
					acc.tickets += num7;
					NotifyMoney(acc, "+" + num7.ToString(CultureInfo.InvariantCulture) + " 金票 额外抽奖", 3);
					Broadcast();
				}
			}
		}

