				acc.bonusDraw = 1;
			}
		}

		internal static bool IsBasketBall(Item item)
		{
			if (item == null)
			{
				return false;
			}
			if (item is Basketball)
			{
				return true;
			}
			string text = ((item.gameObject != null) ? item.gameObject.name : "");
			if (item.spawnableSo != null && !string.IsNullOrEmpty(item.spawnableSo.spawnableName))
			{
				text = text + " " + item.spawnableSo.spawnableName;
			}
			string s = text.ToLowerInvariant();
			if (!HasTxt(s, "basket"))
			{
				return HasTxt(s, "basketball");
			}
			return true;
		}

		internal static void NoteBallThrow(Item item)
		{
			if (NetworkServer.active && !(item == null) && (IsBasketBall(item) || item is PlayerCarry))
			{
				PlayerProfile playerProfile = null;
				try
				{
					playerProfile = ProfileFromInventory(item.NetworkHolder);
				}
				catch
				{
				}
				if (!(playerProfile == null))
				{
					_lastBallShooter = playerProfile;
					_lastBallId = item.GetInstanceID();
				}
			}
		}

		internal static PlayerProfile ShooterFromBall(Item item)
		{
			if (item == null)
			{
				return _lastBallShooter;
			}
			PlayerProfile playerProfile = null;
			try
			{
				playerProfile = ProfileFromInventory(item.NetworkHolder);
			}
			catch
			{
			}
			if (playerProfile != null)
			{
				return playerProfile;
			}
			if (item.GetInstanceID() == _lastBallId && _lastBallShooter != null)
			{
				return _lastBallShooter;
			}
			try
			{
				Vector3 position = item.transform.position;
				PlayerProfile[] array = UnityEngine.Object.FindObjectsByType<PlayerProfile>(FindObjectsSortMode.None);
				float num = 28f;
				if (array != null)
				{
					PlayerProfile[] array2 = array;
					foreach (PlayerProfile playerProfile2 in array2)
					{
						if (!(playerProfile2 == null))
						{
							float num2 = Vector3.Distance(position, playerProfile2.transform.position);
							if (num2 < num)
							{
								num = num2;
								playerProfile = playerProfile2;
							}
						}
					}
				}
			}
			catch
			{
			}
			return playerProfile ?? _lastBallShooter;
		}

		internal static void OnBasketMade(Item item)
		{
			if (!NetworkServer.active)
			{
				return;
			}
			PlayerProfile playerProfile = ShooterFromBall(item);
			if (playerProfile == null)
			{
				return;
			}
			Acc acc = Ensure(playerProfile);
			if (acc == null || !IsGambler(acc) || acc.hoopDay == SharedDay || EconomyFrozen())
			{
				return;
			}
			acc.hoopDay = SharedDay;
			bool flag = UnityEngine.Random.value < 0.5f;
			if (flag)
			{
				acc.money *= 2.0;
			}
			else
			{
				double num = acc.quota;
				if (num < 0.0)
				{
					num = 0.0;
				}
				acc.hoopBonus += num;
				acc.quota += num;
			}
			Broadcast();
			SendHoopFx(playerProfile, flag);
		}

