		internal static bool AccIsPlayer(Acc a, PlayerProfile p)
		{
			if (a == null || p == null)
			{
				return false;
			}
			string text = Key(p);
			if (!string.IsNullOrEmpty(a.id) && a.id == text)
			{
				return true;
			}
			if (!string.IsNullOrEmpty(a.name) && a.name == p.playerName)
			{
				return true;
			}
			if (p.steamId != 0 && a.id == "s" + p.steamId)
			{
				return true;
			}
			uint num = NetIdOf(p);
			if (num != 0 && a.id == "n" + num)
			{
				return true;
			}
			return false;
		}

		internal static void PayoffBonusForStreak(int streak, out int tix, out double cash)
		{
			int num = streak;
			if (num < 1)
			{
				num = 1;
			}
			if (num > 5)
			{
				num = 5;
			}
			tix = num;
			if (num <= 1)
			{
				cash = 500.0;
				return;
			}
			switch (num)
			{
			case 2:
				cash = 1000.0;
				break;
			case 3:
				cash = 3000.0;
				break;
			case 4:
				cash = 4000.0;
				break;
			default:
				cash = 5000.0;
				break;
			}
		}

