		private static byte[] MakeToggleWav(bool on)
		{
			int num = 4851;
			short[] array = new short[num];
			double num2 = (on ? 520 : 420);
			double num3 = (on ? 880 : 220);
			for (int i = 0; i < num; i++)
			{
				double num4 = (double)i / 22050.0;
				double num5 = num4 / 0.22;
				double num6 = num2 + (num3 - num2) * num5;
				double num7 = 1.0;
				if (num4 < 0.012)
				{
					num7 = num4 / 0.012;
				}
				else if (num4 > 0.14)
				{
					num7 = Math.Max(0.0, (0.22 - num4) / 0.08);
				}
				double num8 = Math.Sin(Math.PI * 2.0 * num6 * num4) * 0.7 + Math.Sin(Math.PI * 2.0 * num6 * 2.0 * num4) * 0.15;
				array[i] = (short)(Math.Max(-1.0, Math.Min(1.0, num8 * num7)) * 26000.0);
			}
			MemoryStream memoryStream = new MemoryStream();
			WriteWav16(memoryStream, array, 22050);
			return memoryStream.ToArray();
		}

