		internal static void ShowPayToast(string line, int tone, bool ding)
		{
			if (string.IsNullOrEmpty(line))
			{
				return;
			}
			if (line.StartsWith("技能冷却中"))
			{
				for (int i = 0; i < PayToasts.Count; i++)
				{
					PayToast payToast = PayToasts[i];
					if (payToast != null && !string.IsNullOrEmpty(payToast.line) && payToast.line.StartsWith("技能冷却中"))
					{
						payToast.line = line;
						payToast.tone = tone;
						payToast.born = Time.unscaledTime;
						if (ding)
						{
							PlayWav(MakeDingWav());
						}
						return;
					}
				}
			}
			PayToasts.Add(new PayToast
			{
				line = line,
				tone = tone,
				born = Time.unscaledTime
			});
			while (PayToasts.Count > 8)
			{
				PayToasts.RemoveAt(0);
			}
			if (ding)
			{
				PlayWav(MakeDingWav());
			}
		}

