		private static void WriteWav16(MemoryStream ms, short[] pcm, int rate)
		{
			int num = pcm.Length * 2;
			BinaryWriter binaryWriter = new BinaryWriter(ms, Encoding.ASCII);
			binaryWriter.Write(Encoding.ASCII.GetBytes("RIFF"));
			binaryWriter.Write(36 + num);
			binaryWriter.Write(Encoding.ASCII.GetBytes("WAVEfmt "));
			binaryWriter.Write(16);
			binaryWriter.Write((short)1);
			binaryWriter.Write((short)1);
			binaryWriter.Write(rate);
			binaryWriter.Write(rate * 2);
			binaryWriter.Write((short)2);
			binaryWriter.Write((short)16);
			binaryWriter.Write(Encoding.ASCII.GetBytes("data"));
			binaryWriter.Write(num);
			for (int i = 0; i < pcm.Length; i++)
			{
				binaryWriter.Write(pcm[i]);
			}
			binaryWriter.Flush();
		}

		private static byte[] MakeHoorayWav()
		{
			return BuildHoorayWav(1.0);
		}

		private static byte[] MakeQuietHoorayWav()
		{
			return BuildHoorayWav(0.22);
		}

		private static byte[] BuildHoorayWav(double vol)
		{
			if (vol < 0.05)
			{
				vol = 0.05;
			}
			if (vol > 1.0)
			{
				vol = 1.0;
			}
			int num = 27562;
			short[] array = new short[num];
			double[] array2 = new double[4] { 523.25, 659.25, 783.99, 1046.5 };
			for (int i = 0; i < num; i++)
			{
				double num2 = (double)i / 22050.0;
				double num3 = Math.Sin(Math.PI * Math.Min(1.0, num2 / 1.2));
				if (num2 > 0.95)
				{
					num3 *= Math.Max(0.0, (1.2 - num2) / 0.25);
				}
				int num4 = (int)(num2 * 3.2);
				if (num4 < 0)
				{
					num4 = 0;
				}
				if (num4 >= array2.Length)
				{
					num4 = array2.Length - 1;
				}
				double num5 = Math.Sin(Math.PI * 2.0 * array2[num4] * num2) * 0.55 + Math.Sin(Math.PI * 2.0 * array2[num4] * 2.0 * num2) * 0.18 + Math.Sin(Math.PI * 2.0 * (array2[num4] * 1.5) * num2) * 0.12;
				array[i] = (short)(Math.Max(-1.0, Math.Min(1.0, num5 * num3)) * 28000.0 * vol);
			}
			MemoryStream memoryStream = new MemoryStream();
			WriteWav16(memoryStream, array, 22050);
			return memoryStream.ToArray();
		}

		private static byte[] MakeFartWav()
		{
			int num = 18742;
			short[] array = new short[num];
			double num2 = 0.13;
			for (int i = 0; i < num; i++)
			{
				double num3 = (double)i / 22050.0;
				num2 = (num2 * 1103515245.0 + 12345.0) % 2147483648.0;
				double num4 = num2 / 2147483648.0 * 2.0 - 1.0;
				double num5 = 180.0 - 120.0 * (num3 / 0.85);
				double num6 = Math.Sin(Math.PI * 2.0 * num5 * num3) * 0.55 + Math.Sin(Math.PI * 2.0 * (num5 * 0.5) * num3) * 0.35 + num4 * 0.25;
				double num7 = 1.0;
				if (num3 < 0.05)
				{
					num7 = num3 / 0.05;
				}
				else if (num3 > 0.55)
				{
					num7 = Math.Max(0.0, (0.85 - num3) / 0.3);
				}
				array[i] = (short)(Math.Max(-1.0, Math.Min(1.0, num6 * num7)) * 24000.0);
			}
			MemoryStream memoryStream = new MemoryStream();
			WriteWav16(memoryStream, array, 22050);
			return memoryStream.ToArray();
		}

		private static string AccKeepKey(Acc a)
		{
			if (a == null)
			{
				return "";
			}
			if (!string.IsNullOrEmpty(a.id))
			{
				return a.id;
			}
			return a.name ?? "";
		}

		private static bool AccKeepsUpgrades(Acc a)
		{
			if (a == null)
			{
				return false;
			}
			if (KeepUpgradeAccs.Contains(a))
			{
				return true;
			}
			if (!IsGambler(a) && a.job != 2 && GetJob(a) != 2)
			{
				return false;
			}
			string text = AccKeepKey(a);
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			if (KeepUpgradeKeys.ContainsKey(text))
			{
				return true;
			}
			if (!string.IsNullOrEmpty(a.name) && KeepUpgradeKeys.ContainsKey(a.name))
			{
				return true;
			}
			if (!string.IsNullOrEmpty(a.id) && KeepUpgradeKeys.ContainsKey(a.id))
			{
				return true;
			}
			return false;
		}

		internal static void ClearAllUpgrades()
		{
			ClearAllUpgrades(true);
		}

		internal static void ClearAllUpgrades(bool keepGambler)
		{
			if (!NetworkServer.active)
			{
				return;
			}
			UpgradeManager upgradeManager = null;
			try
			{
				upgradeManager = NetworkSingleton<UpgradeManager>.Instance;
			}
			catch
			{
			}
			foreach (Acc value in Accs.Values)
			{
				if (value == null)
				{
					continue;
				}
				if (keepGambler && AccKeepsUpgrades(value))
				{
					ulong result;
					if (string.IsNullOrEmpty(value.id) || value.id.Length <= 1 || value.id[0] != 's' || !ulong.TryParse(value.id.Substring(1), out result))
					{
						continue;
					}
					try
					{
						if (upgradeManager != null)
						{
							upgradeManager.SetUpgradeData(result, PlayerUpgradeType.BonusDraw, BonusDrawUiValue(value));
							if (value.confStacks > 0)
							{
								upgradeManager.SetUpgradeData(result, PlayerUpgradeType.GamblersConfidence, (float)(1.0 + ConfMorePctRaw(value)));
							}
							if (value.insStacks > 0)
							{
								upgradeManager.SetUpgradeData(result, PlayerUpgradeType.Insurance, (float)InsEffectiveRaw(value));
							}
							if (value.stakeStacks > 0)
							{
								upgradeManager.SetUpgradeData(result, PlayerUpgradeType.Stakeholder, (float)StakeFactorRaw(value));
							}
						}
						SyncUpgradePanel(result);
					}
					catch
					{
					}
					continue;
				}
				value.bonusDraw = 0;
				value.confStacks = 0;
				value.insStacks = 0;
				value.stakeStacks = 0;
				ulong result2;
				if (upgradeManager != null && !string.IsNullOrEmpty(value.id) && value.id.Length > 1 && value.id[0] == 's' && ulong.TryParse(value.id.Substring(1), out result2))
				{
					try
					{
						upgradeManager.SetUpgradeData(result2, PlayerUpgradeType.GamblersConfidence, 1f);
						upgradeManager.SetUpgradeData(result2, PlayerUpgradeType.Insurance, 0f);
						upgradeManager.SetUpgradeData(result2, PlayerUpgradeType.Stakeholder, 1f);
						upgradeManager.SetUpgradeData(result2, PlayerUpgradeType.BonusDraw, 0f);
					}
					catch
					{
					}
				}
			}
			try
			{
				Upgrade[] array = UnityEngine.Object.FindObjectsByType<Upgrade>(FindObjectsSortMode.None);
				if (array != null)
				{
					for (int i = 0; i < array.Length; i++)
					{
						if (!(array[i] == null) && !(array[i].gameObject == null))
						{
							NetworkServer.Destroy(array[i].gameObject);
						}
					}
				}
			}
			catch
			{
			}
			if (keepGambler)
			{
				QueueRestoreGamblerUi();
			}
		}

		internal static void RefreshLoanDay(Acc a)
		{
			if (a != null && a.loanDay != SharedDay)
			{
				a.loanDay = SharedDay;
				a.loanUsed = 0.0;
			}
		}

		internal static double LoanLeft(Acc a)
		{
			RefreshLoanDay(a);
			if (a == null)
			{
				return 0.0;
			}
			if (EconomyFrozen())
			{
				return 0.0;
			}
			double num = 5000.0 - a.loanUsed;
			if (num < 0.0)
			{
				num = 0.0;
			}
			return num;
		}

		internal static void Loan(Acc a, double amount)
		{
			if (a == null || amount <= 0.0)
			{
				return;
			}
			if (EconomyFrozen())
			{
				_saveMsg = "第11天金钱和票已锁定。";
				return;
			}
			RefreshLoanDay(a);
			double num = LoanLeft(a);
			if (num <= 0.001)
			{
				_saveMsg = a.name + " 今日可贷款已用完（$5000）";
				return;
			}
			if (amount > num)
			{
				amount = num;
			}
			a.money += amount;
			a.loanUsed += amount;
			double num2 = amount * 1.2;
			a.loanExtra += num2;
			a.quota += num2;
			_saveMsg = a.name + " 贷了 " + MoneyDollar(amount) + " · 今日还可贷 " + MoneyDollar(LoanLeft(a));
			NotifyMoney(a, "+" + MoneyDollar(amount) + " 贷款", true);
			Broadcast();
		}

