		private void Update()
		{
			JobPick.Tick();
			EnforceHostPc();
			TickClientLicense();
			TickStealWindow();
			TickMorphWindow();
			TickDiceNoCrouch();
			TickDuelWindows();
			TickThiefMove();
			HideNpcPlayerNames();
			TickCosmeticUnlocks();
			TickUpgradeUiRestore();
			HideVanillaTickets();
			if (!NetworkClient.active)
			{
				_clientHandler = false;
			}
			TryRegisterClient();
			if (NetworkServer.active)
			{
				if (!_shopHandler)
				{
					try
					{
						NetworkServer.ReplaceHandler<ShopMsg>(OnShopCmd, false);
						NetworkServer.ReplaceHandler<SideMsg>(OnSideCmd, false);
						_shopHandler = true;
					}
					catch
					{
					}
				}
				if (!_didLoad)
				{
					_didLoad = true;
					LoadFromDisk();
					EnsureAll();
					Broadcast();
				}
				if (Time.unscaledTime - _ensureAt >= 5f)
				{
					_ensureAt = Time.unscaledTime;
					EnsureAll();
				}
				_syncT += Time.unscaledDeltaTime;
				if (_syncT >= 8f)
				{
					_syncT = 0f;
					Broadcast();
				}
			}
			bool flag = false;
			try
			{
				Keyboard current = Keyboard.current;
				if (current != null && current.f9Key.wasPressedThisFrame)
				{
					flag = true;
				}
			}
			catch
			{
			}
			try
			{
				if (Input.GetKeyDown(KeyCode.F9))
				{
					flag = true;
				}
			}
			catch
			{
			}
			bool flag2 = false;
			try
			{
				Keyboard current2 = Keyboard.current;
				if (current2 != null && current2.mKey.wasPressedThisFrame)
				{
					flag2 = true;
				}
			}
			catch
			{
			}
			try
			{
				if (Input.GetKeyDown(KeyCode.M))
				{
					flag2 = true;
				}
			}
			catch
			{
			}
			if (flag2)
			{
				TryLocalFaceMorphKey();
			}
			bool flag3 = false;
			bool flag4 = false;
			bool flag5 = false;
			try
			{
				Keyboard current3 = Keyboard.current;
				if (current3 != null)
				{
					if (current3.pKey.wasPressedThisFrame)
					{
						flag3 = true;
					}
					if (current3.pKey.wasReleasedThisFrame)
					{
						flag4 = true;
					}
					if (current3.pKey.isPressed)
					{
						flag5 = true;
					}
				}
			}
			catch
			{
			}
			try
			{
				if (Input.GetKeyDown(KeyCode.P))
				{
					flag3 = true;
				}
			}
			catch
			{
			}
			try
			{
				if (Input.GetKeyUp(KeyCode.P))
				{
					flag4 = true;
				}
			}
			catch
			{
			}
			try
			{
				if (Input.GetKey(KeyCode.P))
				{
					flag5 = true;
				}
			}
			catch
			{
			}
			if (flag3)
			{
				_pHoldAt = Time.unscaledTime;
				_pHoldFired = false;
			}
			if (flag5 && !_pHoldFired && _pHoldAt > 0f && Time.unscaledTime - _pHoldAt >= 2f)
			{
				_pHoldFired = true;
				RequestReturnBetsOnMe();
			}
			if (flag4)
			{
				_pHoldAt = -1f;
			}
			try
			{
				string text = SceneManager.GetActiveScene().name;
				if (text != _scanScene)
				{
					_scanScene = text;
					ResetWorldCaches();
				}
			}
			catch
			{
			}
			if (NetworkClient.active || NetworkServer.active)
			{
				if (!_bootScanDone && _bootScanStep < 0)
				{
					_bootScanStep = 0;
				}
				if (_bootScanStep >= 0 && _bootScanStep <= 6)
				{
					RunBootScanPiece(_bootScanStep);
					_bootScanStep++;
					if (_bootScanStep == 7)
					{
						_bootScanDone = true;
						_bootScanStep = -1;
					}
				}
			}
			if (flag && NetworkServer.active)
			{
				_showLoan = !_showLoan;
			}
			PollSideBetLook();
			if (_showShop)
			{
				RefreshZoneCache();
				EnsureShopCache(false);
			}
			if (Time.unscaledTime - _elevLockAt >= 1f)
			{
				_elevLockAt = Time.unscaledTime;
				ApplyAllElevatorLocks();
			}
		}

