					GUI.Label(new Rect(0f, (float)Screen.height * 0.08f, Screen.width, (float)Screen.height * 0.7f), "L", _hoopBig);
				}
				GUI.color = color;
			}
		}

		private static float PayoffScale()
		{
			float num = Time.unscaledTime - _payFxAt;
			if (num < 0f)
			{
				return 0f;
			}
			if (num < 0.35f)
			{
				float num2 = num / 0.35f;
				num2 = num2 * num2 * (3f - 2f * num2);
				return 0.12f + 0.88f * num2;
			}
			if (num < 3.35f)
			{
				return 1f;
			}
			float num3 = (num - 0.35f - 3f) / 0.35f;
			if (num3 >= 1f)
			{
				return 0f;
			}
			num3 = num3 * num3 * (3f - 2f * num3);
			return 1f - 0.88f * num3;
		}

		private static void DrawPayoffFx()
		{
			if (_payFxAt < 0f)
			{
				return;
			}
			float num = PayoffScale();
			if (num <= 0.02f)
			{
				if (Time.unscaledTime - _payFxAt > 3.8f)
				{
					_payFxAt = -99f;
				}
				return;
			}
			if (_payFailSt == null)
			{
				GUIStyle gUIStyle = new GUIStyle(GUI.skin.label);
				gUIStyle.fontSize = 48;
				gUIStyle.fontStyle = FontStyle.Bold;
				gUIStyle.alignment = TextAnchor.MiddleLeft;
				gUIStyle.clipping = TextClipping.Overflow;
				gUIStyle.normal.textColor = new Color(1f, 0.84f, 0.18f, 1f);
				_payTixSt = gUIStyle;
				GUIStyle gUIStyle2 = new GUIStyle(_payTixSt);
				gUIStyle2.fontSize = 48;
				gUIStyle2.normal.textColor = new Color(0.18f, 1f, 0.32f, 1f);
				_payCashSt = gUIStyle2;
				GUIStyle gUIStyle3 = new GUIStyle(_payTixSt);
				gUIStyle3.fontSize = 42;
				gUIStyle3.alignment = TextAnchor.MiddleCenter;
				gUIStyle3.normal.textColor = new Color(1f, 0.84f, 0.18f, 1f);
				_payRankSt = gUIStyle3;
				GUIStyle gUIStyle4 = new GUIStyle(_payTixSt);
				gUIStyle4.fontSize = 56;
				gUIStyle4.alignment = TextAnchor.MiddleCenter;
				gUIStyle4.normal.textColor = new Color(1f, 0.16f, 0.12f, 1f);
				_payFailSt = gUIStyle4;
			}
			Vector2 pivotPoint = new Vector2((float)Screen.width * 0.5f, (float)Screen.height * 0.42f);
			Matrix4x4 matrix = GUI.matrix;
			GUIUtility.ScaleAroundPivot(new Vector2(num, num), pivotPoint);
			if (_payFxMiss)
			{
				GUI.Label(new Rect(0f, (float)Screen.height * 0.36f, Screen.width, 80f), "目标未完成", _payFailSt);
				GUI.matrix = matrix;
				return;
			}
			if (_payOkSt == null)
			{
				GUIStyle gUIStyle5 = new GUIStyle(_payFailSt);
				gUIStyle5.normal.textColor = new Color(0.18f, 1f, 0.32f, 1f);
				_payOkSt = gUIStyle5;
			}
			GUI.Label(new Rect(0f, (float)Screen.height * 0.3f, Screen.width, 80f), "目标已完成", _payOkSt);
			if (_payFxCash <= 0.0001 && _payFxTix <= 0)
			{
				GUI.matrix = matrix;
				return;
			}
			string text = "奖励：";
			string text2 = ((_payFxCash > 0.0001) ? MoneyDollar(_payFxCash) : "");
			string text3 = ((_payFxTix > 0) ? (_payFxTix.ToString(CultureInfo.InvariantCulture) + "金票") : "");
			Vector2 vector = _payCashSt.CalcSize(new GUIContent(text));
			Vector2 vector2 = (string.IsNullOrEmpty(text2) ? Vector2.zero : _payCashSt.CalcSize(new GUIContent(text2 + "  ")));
			Vector2 vector3 = (string.IsNullOrEmpty(text3) ? Vector2.zero : _payTixSt.CalcSize(new GUIContent(text3)));
			float num2 = vector.x + vector2.x + vector3.x;
			float y = (float)Screen.height * 0.42f;
			float num3 = (float)Screen.width * 0.5f - num2 * 0.5f;
			GUI.Label(new Rect(num3, y, vector.x + 8f, 70f), text, _payCashSt);
			if (!string.IsNullOrEmpty(text2))
			{
				GUI.Label(new Rect(num3 + vector.x, y, vector2.x + 8f, 70f), text2 + "  ", _payCashSt);
			}
			if (!string.IsNullOrEmpty(text3))
			{
				GUI.Label(new Rect(num3 + vector.x + vector2.x, y, vector3.x + 8f, 70f), text3, _payTixSt);
			}
			GUI.matrix = matrix;
		}

		private static bool CanSeeWorld(Camera cam, Vector3 aim, Transform root)
		{
			if (cam == null)
			{
				return false;
			}
			Vector3 vector = cam.transform.position + cam.transform.forward * 0.05f;
			Vector3 vector2 = aim - vector;
			float magnitude = vector2.magnitude;
			if (magnitude < 0.08f)
			{
				return true;
			}
			RaycastHit hitInfo;
			if (!Physics.Raycast(vector, vector2 / magnitude, out hitInfo, magnitude, -5, QueryTriggerInteraction.Ignore))
			{
				return true;
			}
			Transform transform = ((hitInfo.collider != null) ? hitInfo.collider.transform : null);
			if (transform == null)
			{
				return false;
			}
			if (root != null && (transform == root || transform.IsChildOf(root) || root.IsChildOf(transform)))
			{
				return true;
			}
			Transform transform2 = transform;
			int num = 0;
			while (transform2 != null && num < 8)
			{
				if (transform2.GetComponent<Bat>() != null || transform2.GetComponent<BatHolder>() != null || transform2.GetComponent<Item>() != null)
				{
					return true;
				}
				transform2 = transform2.parent;
				num++;
			}
			if (magnitude - hitInfo.distance <= 0.55f)
			{
				return true;
			}
			return false;
		}

		private static bool AimedAt(Camera cam, Transform root, Vector3 aim)
		{
			if (cam == null)
			{
				return false;
			}
			Vector3 origin = cam.transform.position + cam.transform.forward * 0.08f;
			RaycastHit hitInfo;
			try
			{
				if (!Physics.SphereCast(origin, 0.14f, cam.transform.forward, out hitInfo, 14f, -5, QueryTriggerInteraction.Ignore))
				{
					return false;
				}
			}
			catch
			{
				return false;
			}
			Transform transform = ((hitInfo.collider != null) ? hitInfo.collider.transform : null);
			if (transform == null)
			{
				return false;
			}
			if (root != null && (transform == root || transform.IsChildOf(root) || root.IsChildOf(transform)))
			{
				return true;
			}
			Transform transform2 = transform;
			int num = 0;
			while (transform2 != null && num < 8)
			{
				if ((transform2.GetComponent<Bat>() != null || transform2.GetComponent<BatHolder>() != null || transform2.GetComponent<Item>() != null || transform2.GetComponent<GameBase>() != null || transform2.GetComponent<GachaMachine>() != null || transform2.GetComponent<BodyShreddingMachine>() != null) && root != null && (transform2 == root || transform2.IsChildOf(root) || root.IsChildOf(transform2)))
				{
					return true;
				}
				transform2 = transform2.parent;
				num++;
			}
			Vector3 point = hitInfo.point;
			float num2 = point.x - aim.x;
			float num3 = point.y - aim.y;
			float num4 = point.z - aim.z;
			return num2 * num2 + num3 * num3 + num4 * num4 <= 0.7225f;
		}

		private static void DrawWorldBatLabel(Camera cam, Vector3 aim, string txt, GUIStyle st, Transform root, bool skipElev)
		{
			DrawWorldBatLabel(cam, aim, txt, st, root, skipElev, true);
		}

		private static void DrawWorldBatLabel(Camera cam, Vector3 aim, string txt, GUIStyle st, Transform root, bool skipElev, bool needAim)
		{
			if (cam == null || string.IsNullOrEmpty(txt) || st == null)
			{
				return;
			}
			Vector3 vector = aim + Vector3.up * 0.38f;
			Vector3 vector2 = cam.WorldToScreenPoint(vector);
			if (vector2.z < 0.15f)
			{
				return;
			}
			Vector3 vector3 = cam.WorldToViewportPoint(vector);
			if (!(vector3.x < 0f) && !(vector3.x > 1f) && !(vector3.y < 0f) && !(vector3.y > 1f))
			{
				float num = aim.x - cam.transform.position.x;
				float num2 = aim.y - cam.transform.position.y;
				float num3 = aim.z - cam.transform.position.z;
				if (!(num * num + num2 * num2 + num3 * num3 > 784f) && (!needAim || AimedAt(cam, root, aim)) && CanSeeWorld(cam, vector, root))
				{
					GUI.Label(new Rect(vector2.x - 90f, (float)Screen.height - vector2.y - 28f, 180f, 36f), txt, st);
				}
			}
		}

