		private static Vector3 CachedLabelAim(Component c)
		{
			if (c == null)
			{
				return Vector3.zero;
			}
			int instanceID = c.GetInstanceID();
			Vector3 value;
			if (_labelAims.TryGetValue(instanceID, out value))
			{
				return value;
			}
			value = LabelAim(c);
			_labelAims[instanceID] = value;
			return value;
		}

		private static Vector3 LabelAim(Component c)
		{
			if (c == null)
			{
				return Vector3.zero;
			}
			try
			{
				Renderer[] componentsInChildren = c.GetComponentsInChildren<Renderer>();
				if (componentsInChildren != null && componentsInChildren.Length > 0)
				{
					Bounds bounds = default(Bounds);
					bool flag = false;
					int num = Math.Min(componentsInChildren.Length, 12);
					for (int i = 0; i < num; i++)
					{
						Renderer renderer = componentsInChildren[i];
						if (renderer == null || !renderer.enabled)
						{
							continue;
						}
						string text = renderer.GetType().Name;
						if (text.IndexOf("Particle") < 0 && text.IndexOf("Trail") < 0 && text.IndexOf("Line") < 0)
						{
							if (!flag)
							{
								bounds = renderer.bounds;
								flag = true;
							}
							else
							{
								bounds.Encapsulate(renderer.bounds);
							}
						}
					}
					if (flag)
					{
						return new Vector3(bounds.center.x, bounds.max.y + 0.12f, bounds.center.z);
					}
				}
			}
			catch
			{
			}
			return c.transform.position + Vector3.up * 0.8f;
		}

		private static bool LabelHasBody(Component c)
		{
			if (c == null || c.gameObject == null || !c.gameObject.activeInHierarchy)
			{
				return false;
			}
			try
			{
				Renderer[] componentsInChildren = c.GetComponentsInChildren<Renderer>();
				if (componentsInChildren == null)
				{
					return false;
				}
				int num = Math.Min(componentsInChildren.Length, 12);
				for (int i = 0; i < num; i++)
				{
					Renderer renderer = componentsInChildren[i];
					if (!(renderer == null) && renderer.enabled)
					{
						string text = renderer.GetType().Name;
						if (text.IndexOf("Particle") < 0 && text.IndexOf("Trail") < 0 && text.IndexOf("Line") < 0 && !(renderer.bounds.size.sqrMagnitude < 0.0001f))
						{
							return true;
						}
					}
				}
			}
			catch
			{
			}
			return false;
		}

		private static bool SkipDupOwnerLabel(Component c)
		{
			if (c == null)
			{
				return true;
			}
			try
			{
				if (c is Keypad)
				{
					return true;
				}
				if (c.GetComponent<Keypad>() != null)
				{
					return true;
				}
				if (c.GetComponentInParent<Keypad>() != null)
				{
					return true;
				}
				GameBase gameBase = c as GameBase;
				if (gameBase != null)
				{
					return false;
				}
				if (c.GetComponentInParent<GameBase>() != null)
				{
					return true;
				}
				if (c.GetComponentInParent<GachaMachine>() != null && !(c is GachaMachine))
				{
					return true;
				}
				if (c.GetComponentInParent<BodyShreddingMachine>() != null && !(c is BodyShreddingMachine))
				{
					return true;
				}
			}
			catch
			{
			}
			return false;
		}

		private static void DrawBatPriceLabels()
		{
			if (Event.current.type != EventType.Repaint)
			{
				return;
			}
			Styles();
			EnsureWorldScan();
			Camera main = Camera.main;
			if (main == null)
			{
				return;
			}
			int num = BatShopCost();
			int num2 = LocalTicketCount();
			bool flag = num2 >= num && !EconomyFrozen();
			_batPriceSt.normal.textColor = (flag ? new Color(1f, 0.84f, 0.18f, 1f) : new Color(1f, 0.22f, 0.18f, 1f));
			string txt = num + " 金票";
			Dictionary<int, int> dictionary = new Dictionary<int, int>();
			Dictionary<uint, int> dictionary2 = new Dictionary<uint, int>();
			Vector3 position = main.transform.position;
			try
			{
				Bat[] scanBats = _scanBats;
				if (scanBats != null)
				{
					if (_batSpawnF == null)
					{
						_batSpawnF = AccessTools.Field(typeof(Bat), "spawnPoint");
					}
					Bat[] array = scanBats;
					foreach (Bat bat in array)
					{
						if (bat == null)
						{
							continue;
						}
						uint num3 = NetIdOf(bat);
						try
						{
							if (bat.NetworkHolder != null)
							{
								dictionary[bat.GetInstanceID()] = 1;
								if (num3 != 0)
								{
									dictionary2[num3] = 1;
								}
								continue;
							}
						}
						catch
						{
						}
						if (!LabelHasBody(bat))
						{
							continue;
						}
						Vector3 position2 = bat.transform.position;
						float num4 = position2.x - position.x;
						float num5 = position2.y - position.y;
						float num6 = position2.z - position.z;
						if (!(num4 * num4 + num5 * num5 + num6 * num6 > 784f))
						{
							dictionary[bat.GetInstanceID()] = 1;
							if (num3 != 0)
							{
								dictionary2[num3] = 1;
							}
							string text = OwnerNameOf(bat);
							if (!string.IsNullOrEmpty(text))
							{
								DrawWorldBatLabel(main, position2, text, OwnerNameStyle(bat), bat.transform, false, false);
							}
							else
							{
								DrawWorldBatLabel(main, position2, txt, _batPriceSt, bat.transform, false, false);
							}
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				BatHolder[] scanHolders = _scanHolders;
				if (scanHolders != null)
				{
					if (_holderSpawnF == null)
					{
						_holderSpawnF = AccessTools.Field(typeof(BatHolder), "batSpawnPoint");
					}
