		private static bool LoadPng(Texture2D tex, byte[] png)
		{
			Type type = Type.GetType("UnityEngine.ImageConversion, UnityEngine.ImageConversionModule");
			if (type == null)
			{
				return false;
			}
			MethodInfo[] methods = type.GetMethods();
			MethodInfo methodInfo = null;
			for (int i = 0; i < methods.Length; i++)
			{
				if (!(methods[i].Name != "LoadImage"))
				{
					ParameterInfo[] parameters;
					try
					{
						parameters = methods[i].GetParameters();
					}
					catch
					{
						continue;
					}
					if (parameters.Length == 3 && parameters[1].ParameterType == typeof(byte[]))
					{
						return (bool)methods[i].Invoke(null, new object[3] { tex, png, false });
					}
					if (parameters.Length == 2 && parameters[1].ParameterType == typeof(byte[]))
					{
						methodInfo = methods[i];
					}
				}
			}
			if (methodInfo != null)
			{
				return (bool)methodInfo.Invoke(null, new object[2] { tex, png });
			}
			return false;
		}

		private static void EnsureHudArt()
		{
			if (_pfpTried)
			{
				return;
			}
			_pfpTried = true;
			try
			{
				Texture2D texture2D = new Texture2D(2, 2, TextureFormat.RGBA32, false);
				if (LoadPng(texture2D, HudPfp.Bytes()))
				{
					texture2D.filterMode = FilterMode.Bilinear;
					texture2D.wrapMode = TextureWrapMode.Clamp;
					texture2D.hideFlags = HideFlags.HideAndDontSave;
					_pfpTex = texture2D;
					_pfpOutline = MakePfpOutline(texture2D);
				}
			}
			catch
			{
			}
			try
			{
				_dimTex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
				_dimTex.SetPixel(0, 0, new Color(0f, 0f, 0f, 0.4f));
				_dimTex.Apply();
				_dimTex.hideFlags = HideFlags.HideAndDontSave;
			}
			catch
			{
			}
		}

		private static Texture2D MakePfpOutline(Texture2D src)
		{
			if (src == null)
			{
				return null;
			}
			try
			{
				int width = src.width;
				int height = src.height;
				Color[] pixels = src.GetPixels();
				Color[] array = new Color[pixels.Length];
				int num = 5;
				Color color = new Color(1f, 0.88f, 0.28f, 1f);
				for (int i = 0; i < height; i++)
				{
					for (int j = 0; j < width; j++)
					{
						int num2 = i * width + j;
						float a = pixels[num2].a;
						if (a >= 0.07f)
						{
							continue;
						}
						float num3 = 99f;
						for (int k = -num; k <= num; k++)
						{
							int num4 = i + k;
							if (num4 < 0 || num4 >= height)
							{
								continue;
							}
							for (int l = -num; l <= num; l++)
							{
								int num5 = j + l;
								if (num5 < 0 || num5 >= width)
								{
									continue;
								}
								float a2 = pixels[num4 * width + num5].a;
								if (!(a2 < 0.08f))
								{
									float num6 = Mathf.Sqrt(l * l + k * k);
									if (num6 < num3)
									{
										num3 = num6;
									}
								}
							}
						}
						if (!(num3 > (float)num))
						{
							float num7 = 1f - num3 / (float)num;
							num7 = num7 * num7 * (3f - 2f * num7);
							if (!(num7 < 0.12f))
							{
								array[num2] = new Color(color.r, color.g, color.b, Mathf.Clamp01(0.35f + num7 * 0.75f));
							}
						}
					}
				}
				Texture2D texture2D = new Texture2D(width, height, TextureFormat.RGBA32, false);
				texture2D.SetPixels(array);
				texture2D.Apply();
				texture2D.filterMode = FilterMode.Bilinear;
				texture2D.wrapMode = TextureWrapMode.Clamp;
				texture2D.hideFlags = HideFlags.HideAndDontSave;
				return texture2D;
			}
			catch
			{
				return null;
			}
		}

		private static Rect FitPfp(Rect pr)
		{
			if (_pfpTex == null)
			{
				return pr;
			}
			float num = (float)_pfpTex.width / (float)Math.Max(1, _pfpTex.height);
			float num2 = pr.width / Math.Max(1f, pr.height);
			if (num > num2)
			{
				float num3 = pr.width / num;
				return new Rect(pr.x, pr.y + (pr.height - num3) * 0.5f, pr.width, num3);
			}
			float num4 = pr.height * num;
			return new Rect(pr.x + (pr.width - num4) * 0.5f, pr.y, num4, pr.height);
		}

		private static bool HitPfp(Rect fitted, Vector2 mouse)
		{
			if (_pfpTex == null || !fitted.Contains(mouse))
			{
				return false;
			}
			try
			{
				float num = (mouse.x - fitted.x) / Math.Max(1f, fitted.width);
				float num2 = (mouse.y - fitted.y) / Math.Max(1f, fitted.height);
				int x = Mathf.Clamp(Mathf.FloorToInt(num * (float)_pfpTex.width), 0, _pfpTex.width - 1);
				int y = Mathf.Clamp(Mathf.FloorToInt((1f - num2) * (float)_pfpTex.height), 0, _pfpTex.height - 1);
				return _pfpTex.GetPixel(x, y).a > 0.06f;
			}
			catch
			{
				return fitted.Contains(mouse);
			}
		}

		private static Acc FindMine(Acc[] rows, int n)
		{
			PlayerProfile playerProfile = LocalProfile();
			if (NetworkServer.active && playerProfile != null)
			{
				Acc acc = Ensure(playerProfile);
				if (acc != null && !string.IsNullOrEmpty(acc.name))
				{
					return acc;
				}
			}
			string text = Key(playerProfile);
			string text2 = ((playerProfile != null) ? playerProfile.playerName : null);
			if (rows == null)
			{
				return null;
			}
			for (int i = 0; i < n; i++)
			{
				Acc acc2 = rows[i];
				if (acc2 != null && !string.IsNullOrEmpty(text) && !string.IsNullOrEmpty(acc2.id) && acc2.id == text)
				{
					return acc2;
				}
			}
			if (!string.IsNullOrEmpty(text2))
			{
				for (int j = 0; j < n; j++)
				{
					Acc acc3 = rows[j];
					if (acc3 != null && acc3.name == text2)
					{
						return acc3;
					}
				}
			}
			return null;
		}

