		private static Vector2 DrawShopLines(ShopLine[] lines, Vector2 scroll, bool enabled, float viewH)
		{
			int num = ((lines != null) ? lines.Length : 0);
			Rect rect = GUILayoutUtility.GetRect(1f, viewH, GUILayout.ExpandWidth(true));
			float height = Math.Max(viewH, (float)num * 32f + 6f);
			scroll = GUI.BeginScrollView(rect, scroll, new Rect(0f, 0f, Math.Max(8f, rect.width - 18f), height));
			if (num == 0)
			{
				GUI.Label(new Rect(8f, 8f, Math.Max(8f, rect.width - 24f), 28f), "暂无", _shopMuted);
			}
			else
			{
				int num2 = (int)(scroll.y / 32f);
				if (num2 < 0)
				{
					num2 = 0;
				}
				int num3 = (int)(viewH / 32f) + 3;
				int num4 = num2 + num3;
				if (num4 > num)
				{
					num4 = num;
				}
				bool flag = GUI.enabled;
				GUI.enabled = enabled;
				float width = Math.Max(8f, rect.width - 26f);
				for (int i = num2; i < num4; i++)
				{
					ShopLine shopLine = lines[i];
					if (shopLine == null || string.IsNullOrEmpty(shopLine.cmd))
					{
						continue;
					}
					int num5 = shopLine.cost;
					if (shopLine.cmd[0] == 'I' && GuardFreeTool(shopLine.src) && IsGuard(_shopMine))
					{
						num5 = 0;
					}
					else
					{
						if (shopLine.cmd[0] == 'I' && !IsBoss(_shopMine))
						{
							num5 += ToolDayExtra();
						}
						num5 = ShopHalfInt(_shopMine, num5);
					}
					string text = ((num5 <= 0) ? "免费" : (num5 + " 张票"));
					if (GUI.Button(new Rect(4f, (float)i * 32f, width, 29f), Zh(shopLine.src) + "  ·  " + text, _shopGoldBtn))
					{
						SendShop(shopLine.cmd);
					}
				}
				GUI.enabled = flag;
			}
			GUI.EndScrollView();
			return scroll;
		}

