		internal static void HideVanillaMoney(GameUI ui)
		{
			if (!(ui == null))
			{
				GameObject gameObject = AccessTools.Field(typeof(GameUI), "moneyHolder").GetValue(ui) as GameObject;
				GameObject gameObject2 = AccessTools.Field(typeof(GameUI), "contributionsHolder").GetValue(ui) as GameObject;
				if (gameObject != null)
				{
					gameObject.SetActive(false);
				}
				if (gameObject2 != null)
				{
					gameObject2.SetActive(false);
				}
				HideVanillaTickets();
			}
		}

		internal static void HideVanillaTickets()
		{
			if (_tixHid || Time.unscaledTime < _tixHideAt + 2f)
			{
				return;
			}
			_tixHideAt = Time.unscaledTime;
			try
			{
				MoneyDisplayAndFeedbacks[] array = UnityEngine.Object.FindObjectsByType<MoneyDisplayAndFeedbacks>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
				if (array == null)
				{
					return;
				}
				FieldInfo fieldInfo = AccessTools.Field(typeof(MoneyDisplayAndFeedbacks), "ticketBalanceLabel");
				if (fieldInfo == null)
				{
					return;
				}
				bool flag = false;
				MoneyDisplayAndFeedbacks[] array2 = array;
				foreach (MoneyDisplayAndFeedbacks moneyDisplayAndFeedbacks in array2)
				{
					if (moneyDisplayAndFeedbacks == null)
					{
						continue;
					}
					Component component = fieldInfo.GetValue(moneyDisplayAndFeedbacks) as Component;
					if (!(component == null) && !(component.transform == null))
					{
						Transform parent = component.transform.parent;
						if (parent != null)
						{
							parent.gameObject.SetActive(false);
						}
						else
						{
							component.gameObject.SetActive(false);
						}
						flag = true;
					}
				}
				if (flag)
				{
					_tixHid = true;
				}
			}
			catch
			{
			}
		}

		private static string Trim(string s, int n)
		{
			if (string.IsNullOrEmpty(s))
			{
				return "?";
			}
			if (s.Length > n)
			{
				return s.Substring(0, n);
			}
			return s;
		}

		private static void SideAppend(char d)
		{
			if (_sideAmt == null)
			{
				_sideAmt = "";
			}
			if (_sideAmt.Length < 8)
			{
				if (_sideAmt == "0" || _sideAmt == "")
				{
					_sideAmt = d.ToString();
				}
				else
				{
					_sideAmt += d;
				}
			}
		}

		private static void SideBack()
		{
			if (!string.IsNullOrEmpty(_sideAmt))
			{
				_sideAmt = _sideAmt.Substring(0, _sideAmt.Length - 1);
			}
		}

