		public static PlayerProfile HoveredOtherPlayer(Camera cam, PlayerProfile me, string mk)
		{
			if (cam == null)
			{
				return null;
			}
			Vector3 origin = cam.transform.position + cam.transform.forward * 0.08f;
			Vector3 forward = cam.transform.forward;
			PlayerProfile playerProfile = HoveredFromCasts(origin, forward, me, mk, 0.08f);
			if (playerProfile != null)
			{
				return playerProfile;
			}
			playerProfile = HoveredFromCasts(origin, forward, me, mk, 0.62f);
			if (playerProfile != null)
			{
				return playerProfile;
			}
			return HoveredNearLookRay(origin, forward, me, mk);
		}

		private static PlayerProfile HoveredFromCasts(Vector3 origin, Vector3 fwd, PlayerProfile me, string mk, float radius)
		{
			RaycastHit[] array = null;
			try
			{
				array = ((!(radius <= 0.12f)) ? Physics.SphereCastAll(origin, radius, fwd, 12f, -5, QueryTriggerInteraction.Collide) : Physics.RaycastAll(origin, fwd, 12f, -5, QueryTriggerInteraction.Collide));
			}
			catch
			{
				return null;
			}
			if (array == null || array.Length == 0)
			{
				return null;
			}
			for (int i = 0; i < array.Length; i++)
			{
				int num = i;
				for (int j = i + 1; j < array.Length; j++)
				{
					if (array[j].distance < array[num].distance)
					{
						num = j;
					}
				}
				if (num != i)
				{
					RaycastHit raycastHit = array[i];
					array[i] = array[num];
					array[num] = raycastHit;
				}
			}
			Transform transform = null;
			try
			{
				if (me != null)
				{
					transform = me.transform;
				}
			}
			catch
			{
			}
			for (int k = 0; k < array.Length; k++)
			{
				Collider collider = array[k].collider;
				if (collider == null)
				{
					continue;
				}
				Transform transform2 = collider.transform;
				if (transform != null)
				{
					try
					{
						if (transform2 == transform || transform2.IsChildOf(transform))
						{
							continue;
						}
						goto IL_0127;
					}
					catch
					{
						goto IL_0127;
					}
				}
				goto IL_0127;
				IL_0127:
				PlayerProfile playerProfile = null;
				try
				{
					MorphFollow componentInParent = collider.GetComponentInParent<MorphFollow>();
					if (componentInParent != null && componentInParent.who != null)
					{
						playerProfile = componentInParent.who.GetComponent<PlayerProfile>() ?? componentInParent.who.GetComponentInParent<PlayerProfile>() ?? componentInParent.who.GetComponentInChildren<PlayerProfile>();
					}
				}
				catch
				{
				}
				if (playerProfile == null)
				{
					try
					{
						playerProfile = collider.GetComponentInParent<PlayerProfile>();
					}
					catch
					{
					}
				}
				if (!(playerProfile == null) && !(playerProfile == me) && !ProfileIsNpcBody(playerProfile))
				{
					string text = Key(playerProfile);
					if (!string.IsNullOrEmpty(text) && !(text == mk))
					{
						return playerProfile;
					}
				}
			}
			return null;
		}

		private static PlayerProfile HoveredNearLookRay(Vector3 origin, Vector3 fwd, PlayerProfile me, string mk)
		{
			List<PlayerProfile> list = PresentProfiles();
			if (list == null)
			{
				return null;
			}
			PlayerProfile result = null;
			float num = 0.9f;
			for (int i = 0; i < list.Count; i++)
			{
				PlayerProfile playerProfile = list[i];
				if (playerProfile == null || playerProfile == me || playerProfile.transform == null || ProfileIsNpcBody(playerProfile))
				{
					continue;
				}
				string text = Key(playerProfile);
				if (string.IsNullOrEmpty(text) || text == mk)
				{
					continue;
				}
				Vector3 vector = FaceFlat(playerProfile);
				if (vector.sqrMagnitude < 0.2f)
				{
					vector = FlatDir(playerProfile.transform.forward);
				}
				Vector3 position = playerProfile.transform.position;
				try
				{
					string text2 = Key(playerProfile);
					GameObject value;
					if (!string.IsNullOrEmpty(text2) && MorphClone.TryGetValue(text2, out value) && value != null)
					{
						position = value.transform.position;
					}
				}
				catch
				{
				}
				Vector3 vector2 = position - vector * 0.35f + Vector3.up * 1.05f;
				Vector3 vector3 = vector2 - origin;
				float num2 = Vector3.Dot(vector3, fwd);
				if (!(num2 < 0.35f) && !(num2 > 12f))
				{
					float magnitude = Vector3.Cross(fwd, vector3).magnitude;
					if (!(magnitude >= num))
					{
						num = magnitude;
						result = playerProfile;
					}
				}
			}
			return result;
		}

