		private static bool TryLocalFaceMorphKey()
		{
			PlayerProfile playerProfile = LocalProfile();
			if (string.IsNullOrEmpty(LocalFaceName))
			{
				return false;
			}
			if (LocalJob != 3 && GetJob(playerProfile) != 3)
			{
				bool flag = false;
				Acc[] view = View;
				if (view != null && playerProfile != null)
				{
					Acc[] array = view;
					foreach (Acc acc in array)
					{
						if (acc != null && acc.job == 3 && (AccIsPlayer(acc, playerProfile) || acc.name == playerProfile.playerName))
						{
							flag = true;
							break;
						}
					}
				}
				if (!flag)
				{
					return false;
				}
			}
			if (_showShop || _showLoan || _showSide || _showTip || _showUsury || _showUsuryAsk)
			{
				return true;
			}
			if (DayStatsOpen || EconomyFrozen())
			{
				return true;
			}
			if (LocalMorphed())
			{
				return true;
			}
			if (Time.unscaledTime < LocalMorphCoolUntil)
			{
				return true;
			}
			LocalMorphUntil = Time.unscaledTime + 45f;
			LocalMorphPlayer = true;
			LocalMorphCoolUntil = 0f;
			float num = MorphWalkSpeed(playerProfile);
			if (num < 0.4f)
			{
				num = 3.2f;
			}
			LocalMorphSpeed = num;
			string value = "";
			if (!string.IsNullOrEmpty(LocalFaceKey))
			{
				LookBook.TryGetValue(LocalFaceKey, out value);
			}
			PlayerProfile playerProfile2 = ResolveMorphProfile(LocalFaceKey);
			if (playerProfile2 == null)
			{
				playerProfile2 = FindProfileByKey(LocalFaceKey);
			}
			if (string.IsNullOrEmpty(value) && playerProfile2 != null)
			{
				value = CaptureLook(playerProfile2);
			}
			ApplyLook(playerProfile, value, playerProfile2);
			try
			{
				NetworkClient.Send(new SideMsg
				{
					json = "MP\t" + (LocalFaceKey ?? "") + "\t" + (value ?? "")
				});
			}
			catch
			{
			}
			return true;
		}

