		private static void UsuryAppend(char d)
		{
			if (_usuryAmtTxt == null)
			{
				_usuryAmtTxt = "";
			}
			if (_usuryAmtTxt.Length < 12)
			{
				if (_usuryAmtTxt == "0" || _usuryAmtTxt == "")
				{
					_usuryAmtTxt = d.ToString();
				}
				else
				{
					_usuryAmtTxt += d;
				}
			}
		}

		private static void UsuryBack()
		{
			if (!string.IsNullOrEmpty(_usuryAmtTxt))
			{
				_usuryAmtTxt = _usuryAmtTxt.Substring(0, _usuryAmtTxt.Length - 1);
			}
		}

		private static bool UsuryAmtOk()
		{
			double result;
			if (!double.TryParse(_usuryAmtTxt, NumberStyles.Float, CultureInfo.InvariantCulture, out result))
			{
				_usuryNote = "金额无效";
				return false;
			}
			if (result < 1.0)
			{
				_usuryNote = "最少 $1";
				return false;
			}
			if (result > Wallet(LocalProfile()) + 0.0001)
			{
				_usuryNote = "现金不够";
				return false;
			}
			return true;
		}

		private static void SubmitUsury()
		{
			if (!_showUsury)
			{
				return;
			}
			double result;
			if (!double.TryParse(_usuryAmtTxt, NumberStyles.Float, CultureInfo.InvariantCulture, out result))
			{
				_usuryNote = "金额无效";
				return;
			}
			double num = Wallet(LocalProfile());
			if (result < 1.0)
			{
				_usuryNote = "最少 $1";
				return;
			}
			if (result > num + 0.0001)
			{
				_usuryNote = "现金不够";
				return;
			}
			double num2 = UsuryMulOf(_usuryRate);
			try
			{
				NetworkClient.Send(new SideMsg
				{
					json = "UL\t" + _usuryKey + "\t" + result.ToString("R", CultureInfo.InvariantCulture) + "\t" + num2.ToString("R", CultureInfo.InvariantCulture)
				});
			}
			catch
			{
			}
			CloseUsuryLocal();
		}

