			float num4 = ((float)Screen.height - num2) * 0.5f;
			if (_sideGold != null)
			{
				GUI.DrawTexture(new Rect(num3 - 8f, num4 - 8f, num + 16f, num2 + 16f), _sideGold);
			}
			if (_sideInner != null)
			{
				GUI.DrawTexture(new Rect(num3, num4, num, num2), _sideInner);
			}
			string text = (string.IsNullOrEmpty(_usuryName) ? "玩家" : _usuryName);
