		private static Vector3 SmoothScr(int who, Vector3 sp)
		{
			if (who == 0)
			{
				return sp;
			}
			if (who != _hovWho || (_hovScr - sp).sqrMagnitude > 80000f)
			{
				_hovWho = who;
				_hovScr = sp;
				return sp;
			}
			_hovScr.x += (sp.x - _hovScr.x) * 0.3f;
			_hovScr.y += (sp.y - _hovScr.y) * 0.3f;
			_hovScr.z = sp.z;
			return _hovScr;
		}

		private static Rect SmoothRect(int who, Rect r)
		{
			if (who == 0)
			{
				return r;
			}
			if (who != _hovRectWho || Mathf.Abs(r.x - _hovRect.x) > 90f || Mathf.Abs(r.y - _hovRect.y) > 90f)
			{
				_hovRectWho = who;
				_hovRect = r;
				return r;
			}
			_hovRect.x += (r.x - _hovRect.x) * 0.3f;
			_hovRect.y += (r.y - _hovRect.y) * 0.3f;
			_hovRect.width += (r.width - _hovRect.width) * 0.3f;
			_hovRect.height += (r.height - _hovRect.height) * 0.3f;
			return _hovRect;
		}

		private static Bounds SmoothBound(int who, Bounds b)
		{
			if (who == 0)
			{
				return b;
			}
			if (who != _hovBoundWho || (b.center - _hovBCenter).sqrMagnitude > 8f)
			{
				_hovBoundWho = who;
				_hovBCenter = b.center;
				_hovBSize = b.size;
				return b;
			}
			_hovBCenter += (b.center - _hovBCenter) * 0.3f;
			_hovBSize += (b.size - _hovBSize) * 0.3f;
			return new Bounds(_hovBCenter, _hovBSize);
		}

		private static bool PlayerWorldBounds(PlayerProfile p, out Bounds b)
		{
			b = default(Bounds);
			if (p == null || p.transform == null)
			{
				return false;
			}
			Vector3 position = p.transform.position;
			Transform transform = MorphVisOf(p);
			if (transform != null)
			{
				position = transform.position;
				b = new Bounds(position + Vector3.up * 0.85f, new Vector3(0.85f, 1.7f, 0.85f));
				return true;
			}
			try
			{
				CharacterController characterController = p.GetComponent<CharacterController>();
				if (characterController == null)
				{
					characterController = p.GetComponentInChildren<CharacterController>();
				}
				if (characterController != null)
				{
					Vector3 center = p.transform.TransformPoint(characterController.center);
					float num = characterController.radius * 2f;
					if (num < 0.7f)
					{
						num = 0.7f;
					}
					float num2 = characterController.height;
					if (num2 < 1.5f)
					{
						num2 = 1.5f;
					}
					b = new Bounds(center, new Vector3(num, num2, num));
					return true;
				}
			}
			catch
			{
			}
			b = new Bounds(position + Vector3.up * 0.85f, new Vector3(0.85f, 1.7f, 0.85f));
			return true;
		}

		public static bool PlayerScreenRect(PlayerProfile p, Camera cam, out Rect gui)
		{
			gui = default(Rect);
			if (p == null || cam == null)
			{
				return false;
			}
			Bounds b;
			if (!PlayerWorldBounds(p, out b))
			{
				return false;
			}
			Vector3 center = b.center;
			Vector3 extents = b.extents;
			float num = 1E+09f;
			float num2 = -1E+09f;
			float num3 = 1E+09f;
			float num4 = -1E+09f;
			bool flag = false;
			for (int i = 0; i < 8; i++)
			{
				Vector3 position = center + new Vector3(((i & 1) != 0) ? extents.x : (0f - extents.x), ((i & 2) != 0) ? extents.y : (0f - extents.y), ((i & 4) != 0) ? extents.z : (0f - extents.z));
				Vector3 vector = cam.WorldToScreenPoint(position);
				if (!(vector.z < 0.05f))
				{
					float x = vector.x;
					float num5 = (float)Screen.height - vector.y;
					if (x < num)
					{
						num = x;
					}
					if (x > num2)
					{
						num2 = x;
					}
					if (num5 < num3)
					{
						num3 = num5;
					}
					if (num5 > num4)
					{
						num4 = num5;
					}
					flag = true;
				}
			}
			if (!flag || num2 - num < 8f || num4 - num3 < 8f)
			{
				return false;
			}
			gui = new Rect(num, num3, num2 - num, num4 - num3);
			return true;
		}

