				Vector3 position4 = center + new Vector3(0f - extents.x, 0f - extents.y, extents.z);
				Vector3 position5 = center + new Vector3(0f - extents.x, extents.y, 0f - extents.z);
				Vector3 position6 = center + new Vector3(extents.x, extents.y, 0f - extents.z);
				Vector3 position7 = center + new Vector3(extents.x, extents.y, extents.z);
				Vector3 position8 = center + new Vector3(0f - extents.x, extents.y, extents.z);
