				_sideLr.SetPosition(6, position6);
				_sideLr.SetPosition(7, position2);
				_sideLr.SetPosition(8, position6);
				_sideLr.SetPosition(9, position7);
				_sideLr.SetPosition(10, position3);
				_sideLr.SetPosition(11, position7);
