		private static void SyncSideOutline(PlayerProfile p)
		{
			if (p == null)
			{
				ClearSideOutline();
				return;
			}
			Bounds b;
			if (!PlayerWorldBounds(p, out b))
			{
				ClearSideOutline();
				return;
			}
			int instanceID = p.GetInstanceID();
			if (_sideOl == null || _sideLr == null)
			{
				EnsureOutlineMat();
				_sideOl = new GameObject("SoloSideOL");
				_sideOl.hideFlags = HideFlags.HideAndDontSave;
				_sideLr = _sideOl.AddComponent<LineRenderer>();
				_sideLr.useWorldSpace = true;
				_sideLr.loop = false;
				_sideLr.shadowCastingMode = ShadowCastingMode.Off;
				_sideLr.receiveShadows = false;
				_sideLr.numCapVertices = 2;
				_sideLr.numCornerVertices = 2;
				_sideLr.widthMultiplier = 0.035f;
				_sideLr.startColor = new Color(1f, 0.84f, 0.12f, 1f);
				_sideLr.endColor = new Color(1f, 0.84f, 0.12f, 1f);
				if (_sideOlMat != null)
				{
					_sideLr.sharedMaterial = _sideOlMat;
				}
				try
				{
					_sideLr.alignment = LineAlignment.View;
				}
				catch
				{
				}
			}
			_sideOlOn = instanceID;
			SetBoxLine(SmoothBound(instanceID, b));
		}

