		private static void DrawParkedHead(Camera cam, PlayerProfile show, string mk)
		{
			if (cam == null || show == null || _sideHeadSt == null || !LocalIsBoss() || show == _sideLook || ProfileLooksNpcMorphed(show))
			{
				return;
			}
			string text = Key(show);
			double amt;
			double cost;
			if (string.IsNullOrEmpty(text) || text == mk || !TryMineOn(text, out amt, out cost))
			{
				return;
			}
			Bounds b;
			Vector3 vector = ((!PlayerWorldBounds(show, out b)) ? (show.transform.position + Vector3.up * 2.3f) : new Vector3(b.center.x, b.max.y + 0.55f, b.center.z));
			float num = Vector3.Distance(cam.transform.position, show.transform.position);
			if (num > 5f)
			{
				return;
			}
			Vector3 vector2 = cam.WorldToViewportPoint(vector);
			if (!(vector2.z < 0.2f) && !(vector2.x < -0.02f) && !(vector2.x > 1.02f) && !(vector2.y < -0.02f) && !(vector2.y > 1.02f) && CanSeeWorld(cam, vector, show.transform))
			{
				Vector3 vector3 = SmoothScr(show.GetInstanceID(), cam.WorldToScreenPoint(vector));
				float x = vector3.x;
				float num2 = (float)Screen.height - vector3.y;
				float num3 = (num - 1.2f) / 3.8f;
				if (num3 < 0f)
				{
					num3 = 0f;
				}
				if (num3 > 1f)
				{
					num3 = 1f;
				}
				int num4 = (int)(68f - num3 * 50f);
				if (num4 < 16)
				{
					num4 = 16;
				}
				Color textColor = new Color(1f, 0.86f, 0.18f);
				if (amt + 0.5 < cost)
				{
					textColor = new Color(1f, 0.22f, 0.22f);
				}
				else if (amt > cost + 0.5)
				{
					textColor = new Color(0.22f, 1f, 0.32f);
				}
				_sideHeadSt.normal.textColor = textColor;
				_sideHeadSt.fontSize = num4;
				float num5 = (float)num4 * 7f;
				float num6 = (float)num4 * 1.25f;
				GUI.Label(new Rect(x - num5 * 0.5f, num2 - num6 * 0.55f, num5, num6), MoneyDollar(amt), _sideHeadSt);
			}
		}

		private void DrawSideHeads()
		{
			Camera main = Camera.main;
			if (main == null)
			{
				ClearSideOutline();
				return;
			}
			EnsureSideArt();
			PlayerProfile playerProfile = LocalProfile();
			string mk = ((playerProfile != null) ? Key(playerProfile) : "");
			List<PlayerProfile> list = PresentProfiles();
			if (_sideHeadSt == null)
			{
				return;
			}
			if (list != null)
			{
				for (int i = 0; i < list.Count; i++)
				{
					DrawParkedHead(main, list[i], mk);
				}
			}
			if (!_showSide && !_showTip && !_showUsury && !_showUsuryAsk && _sideLook != null)
			{
				bool flag = ProfileLooksNpcMorphed(_sideLook);
				bool flag2 = StealLookOk(playerProfile, _sideLook) && !IsGuard(_sideLook) && flag;
				bool flag3 = LocalIsBoss() && !flag && BossHoverNear(_sideLook);
				bool flag4 = MarkLookOk(playerProfile, _sideLook);
				bool flag5 = !flag3 && !flag4 && (IsGuard(_sideLook) || IsStealVictimLook(_sideLook) || flag);
				if (flag && !flag2 && !flag3 && !flag4)
				{
					ClearSideOutline();
				}
				else if (flag5)
				{
					ClearSideOutline();
				}
				else
				{
					SyncSideOutline(_sideLook);
					Rect gui;
