					{
						DrawRectOutline(SmoothRect(_sideLook.GetInstanceID(), gui), 3f);
					}
				}
				Bounds b;
				Vector3 sp = main.WorldToScreenPoint((!PlayerWorldBounds(_sideLook, out b)) ? (_sideLook.transform.position + Vector3.up * 2.25f) : new Vector3(b.center.x, b.max.y + 0.48f, b.center.z));
				Vector3 vector = SmoothScr(_sideLook.GetInstanceID(), sp);
				if (vector.z >= 0.2f)
				{
					_sideTagSt.fontSize = 26;
					_sideTagSt.alignment = TextAnchor.MiddleCenter;
					_sideTagSt.normal.textColor = new Color(1f, 0.86f, 0.18f);
					double amt;
					double cost;
					bool flag6 = TryMineOn(Key(_sideLook), out amt, out cost);
					string text = "";
					if (flag3)
					{
						text = ((!flag6 && !SideBetPlacedToday(Key(_sideLook))) ? "B 押注    T 打赏    Y 放贷" : "B 提现    T 打赏    Y 放贷");
					}
					if (StealLookOk(playerProfile, _sideLook) && !IsGuard(_sideLook))
					{
