					{
						text = (string.IsNullOrEmpty(text) ? "" : (text + "    ")) + (LocalNpcMorph() ? "左键记住TA的脸" : "记住长相");
					}
					else if (flag4)
					{
						text = (string.IsNullOrEmpty(text) ? "" : (text + "    ")) + "右键标记";
					}
					else if (!flag5 && RecoverPromptOk(playerProfile, _sideLook))
					{
						text = (string.IsNullOrEmpty(text) ? "" : (text + "    ")) + ((GetJob(playerProfile) == 4) ? "抱起2秒抓住小偷" : "抱起2秒拿回钱");
