		private void DrawPayToasts()
		{
			if (PayToasts.Count == 0)
			{
				return;
			}
			if (_toastSt == null)
			{
				GUIStyle gUIStyle = new GUIStyle(GUI.skin.label);
				gUIStyle.fontSize = 32;
				gUIStyle.fontStyle = FontStyle.Bold;
				gUIStyle.alignment = TextAnchor.MiddleLeft;
				gUIStyle.clipping = TextClipping.Overflow;
				gUIStyle.wordWrap = false;
				gUIStyle.font = ((_nameSt != null) ? _nameSt.font : GUI.skin.label.font);
				_toastSt = gUIStyle;
			}
			_toastSt.fontSize = 32;
			float unscaledTime = Time.unscaledTime;
			float x = 22f;
			float num = (float)Screen.height - 44f;
			for (int num2 = PayToasts.Count - 1; num2 >= 0; num2--)
			{
				PayToast payToast = PayToasts[num2];
				if (payToast != null)
				{
					float num3 = unscaledTime - payToast.born;
					if (num3 > 12f)
					{
						PayToasts.RemoveAt(num2);
					}
					else
					{
						num -= 42f;
						if (num < 8f)
						{
							num = 8f;
						}
						float num4 = 1f;
						if (num3 > 10.2f)
						{
							num4 = (12f - num3) / 1.8f;
						}
						if (num4 < 0f)
						{
							num4 = 0f;
						}
						Color textColor = new Color(1f, 0.32f, 0.28f, num4);
						if (payToast.tone == 1)
						{
							textColor = new Color(0.28f, 1f, 0.42f, num4);
						}
						else if (payToast.tone == 2)
						{
							textColor = new Color(0.35f, 0.72f, 1f, num4);
						}
						else if (payToast.tone == 3)
						{
							textColor = new Color(0.98f, 0.78f, 0.16f, num4);
						}
						_toastSt.normal.textColor = textColor;
						GUI.Label(new Rect(x, num, 920f, 44f), payToast.line, _toastSt);
					}
				}
			}
		}

