		private void DrawNpcBang()
		{
			if (NpcMarkUntil.Count == 0 && _npcMarkNet == 0)
			{
				return;
			}
			Camera main = Camera.main;
			if (main == null)
			{
				return;
			}
			List<uint> list = new List<uint>();
			foreach (KeyValuePair<uint, float> item in NpcMarkUntil)
			{
				list.Add(item.Key);
			}
			if (_npcMarkNet != 0)
			{
				bool flag = false;
				for (int i = 0; i < list.Count; i++)
				{
					if (list[i] == _npcMarkNet)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					list.Add(_npcMarkNet);
				}
			}
			for (int j = 0; j < list.Count; j++)
			{
				DrawNpcBangOne(main, list[j]);
			}
		}

		private void DrawNpcBangOne(Camera cam, uint nid)
		{
			if (nid == 0)
			{
				return;
			}
			float value = 0f;
			float value2 = 0f;
			if (!NpcMarkUntil.TryGetValue(nid, out value2))
			{
				if (nid != _npcMarkNet)
				{
					return;
				}
				value = _npcMarkShowAt;
				value2 = _npcMarkUntil;
			}
			else
			{
				NpcMarkShow.TryGetValue(nid, out value);
			}
			if (value2 > 0.01f && Time.unscaledTime >= value2)
			{
				NpcMarkShow.Remove(nid);
				NpcMarkUntil.Remove(nid);
			}
			else
			{
				if (Time.unscaledTime < value)
				{
					return;
				}
				NPC nPC = NpcFromNetId(nid);
				if (nPC == null || nPC.transform == null)
				{
					return;
				}
				Vector3 position = nPC.transform.position + Vector3.up * 2.2f;
				try
				{
					Renderer[] componentsInChildren = nPC.GetComponentsInChildren<Renderer>();
					if (componentsInChildren != null && componentsInChildren.Length > 0)
					{
						Bounds bounds = componentsInChildren[0].bounds;
						for (int i = 1; i < componentsInChildren.Length; i++)
						{
							if (componentsInChildren[i] != null)
							{
								bounds.Encapsulate(componentsInChildren[i].bounds);
							}
						}
						position = new Vector3(bounds.center.x, bounds.max.y + 0.35f, bounds.center.z);
					}
				}
				catch
				{
				}
				Vector3 vector = cam.WorldToScreenPoint(position);
				if (!(vector.z < 0.2f))
				{
					float num = Mathf.Abs(Mathf.Sin(Time.unscaledTime * 9.5f)) * 22f;
					if (_npcBangSt == null)
					{
						_npcBangSt = new GUIStyle(GUI.skin.label);
						_npcBangSt.fontSize = 56;
						_npcBangSt.fontStyle = FontStyle.Bold;
						_npcBangSt.alignment = TextAnchor.MiddleCenter;
						_npcBangSt.wordWrap = false;
					}
					_npcBangSt.normal.textColor = new Color(1f, 0.12f, 0.08f);
					GUI.Label(new Rect(vector.x - 40f, (float)Screen.height - vector.y - 58f - num, 80f, 70f), "!", _npcBangSt);
				}
			}
		}

