		private void LoanWin(int id)
		{
			Styles();
			GUILayout.Space(10f);
			GUILayout.Label("贷款会加钱，额度 += 金额 × 1.2。每人每天最多贷 $5000。", _loanLbl);
			GUILayout.Space(8f);
			if (GUILayout.Button("保存（退出后钱包还在）", _loanBtn, GUILayout.Height(44f)))
			{
				SaveToDisk();
			}
			GUILayout.Space(8f);
			if (GUILayout.Button("重置（每人 $1000 / 15张票 / 额度$500）", _loanBtn, GUILayout.Height(44f)))
			{
				ResetWalletsToStart();
			}
			if (!string.IsNullOrEmpty(_saveMsg))
			{
				GUILayout.Label(_saveMsg, _loanLbl);
			}
			GUILayout.Space(8f);
			_loanAmt = GUILayout.TextField(_loanAmt, _loanField, GUILayout.Height(40f));
			GUILayout.Space(8f);
			float num = _loanRect.height - 290f;
			if (num < 140f)
			{
				num = 140f;
			}
			_scroll = GUILayout.BeginScrollView(_scroll, false, true, GUILayout.Height(num), GUILayout.ExpandWidth(true));
			foreach (Acc item in PresentAccs())
			{
				double num2 = LoanLeft(item);
				GUILayout.BeginHorizontal();
				GUILayout.Label(item.name + "   " + MoneyDollar(item.money) + "   票" + item.tickets + "   额度" + MoneyShort(item.quota) + "   今日可贷 " + MoneyDollar(num2), _loanLbl, GUILayout.MinHeight(36f), GUILayout.MinWidth(400f));
				bool flag = GUI.enabled;
				GUI.enabled = num2 > 0.001;
				double result;
				if (GUILayout.Button((num2 > 0.001) ? "贷款" : "已满", _loanBtn, GUILayout.Width(110f), GUILayout.Height(40f)) && double.TryParse(_loanAmt, NumberStyles.Float, CultureInfo.InvariantCulture, out result))
				{
					Loan(item, result);
				}
				GUI.enabled = flag;
				GUILayout.EndHorizontal();
				GUILayout.Space(8f);
			}
			GUILayout.EndScrollView();
			GUI.DragWindow(new Rect(0f, 0f, 10000f, 24f));
		}
	}
	[HarmonyPatch(typeof(MoneyManager), "TryChangeBalance")]
	internal static class PatchTry
	{
		private static bool Prefix(BigNumber amount, PlayerProfile changer, ref bool __result)
		{
			if (!NetworkServer.active)
			{
				return true;
			}
			if (SoloPlugin.EconomyFrozen())
			{
				__result = true;
				return false;
			}
			if (changer == null)
			{
				return true;
			}
			changer = SoloPlugin.MoneyChanger(changer);
			if (changer == null)
			{
				return true;
			}
			Acc acc = SoloPlugin.Ensure(changer);
			if (SoloPlugin.SwallowPayoutBonusTix)
			{
				SoloPlugin.ApplyPayoutMoney(changer);
				__result = true;
				return false;
			}
			double num = amount.ToDouble();
			double num2 = ((num < 0.0) ? (0.0 - num) : num);
			bool flag = num > 0.0;
			if (!flag && acc.money + 0.0001 < num2)
			{
				__result = false;
				return false;
			}
			acc.money += (flag ? num2 : (0.0 - num2));
			if (acc.money < 0.0)
			{
				acc.money = 0.0;
			}
			SoloPlugin.Broadcast();
			__result = true;
			return false;
		}
	}
