	[HarmonyPatch(typeof(MoneyManager), "TryChangeTicketBalance")]
	internal static class PatchTickets
	{
		private static bool Prefix(long amount, ref bool __result)
		{
			if (!NetworkServer.active)
			{
				return true;
			}
			if (SoloPlugin.EconomyFrozen())
			{
				__result = true;
				return false;
			}
			if (SoloPlugin.OrganCashPlayer != null)
			{
				Acc acc = SoloPlugin.Ensure(SoloPlugin.OrganCashPlayer);
				if (acc == null)
				{
					__result = false;
					return false;
				}
				if (amount > 0)
				{
					acc.money += amount;
				}
				else
				{
					double num = -amount;
					if (acc.money + 0.0001 < num)
					{
						__result = false;
						return false;
					}
					acc.money -= num;
					if (acc.money < 0.0)
					{
						acc.money = 0.0;
					}
				}
				SoloPlugin.Broadcast();
				__result = true;
				return false;
			}
			PlayerProfile playerProfile = ((amount > 0) ? SoloPlugin.TicketAwardee() : SoloPlugin.TicketSpender());
			if (playerProfile == null)
			{
				__result = false;
				return false;
			}
			Acc acc2 = SoloPlugin.Ensure(playerProfile);
			if (acc2 == null)
			{
				__result = false;
				return false;
			}
			if (amount > 0)
			{
				if (SoloPlugin.SwallowVanillaDayTickets(amount))
				{
					__result = true;
					return false;
				}
				acc2.tickets += (int)amount;
				if (SoloPlugin.AwardingChallengeTix)
				{
					SoloPlugin.NotifyMoney(acc2, "+" + amount.ToString(CultureInfo.InvariantCulture) + " 金票 挑战", true);
				}
			}
			else
			{
				long num2 = -amount;
				if (acc2.tickets < num2)
				{
					__result = false;
					return false;
				}
				acc2.tickets -= (int)num2;
			}
			SoloPlugin.Broadcast();
			__result = true;
			return false;
		}
	}
