	[HarmonyPatch(typeof(InteractableBase), "OnInteract")]
	internal static class PatchMachineInteractClient
	{
		private static bool Prefix(InteractableBase __instance, PlayerInteract playerInteract)
		{
			if (SoloPlugin.SideModal)
			{
				return false;
			}
			PlayerProfile playerProfile = SoloPlugin.ProfileFromInteract(playerInteract);
			if (playerProfile == null)
			{
				playerProfile = SoloPlugin.LocalProfile();
			}
			if (SoloPlugin.MorphBlocksMachine(__instance, playerProfile))
			{
				SoloPlugin.NoteMorphNoPlay(playerProfile);
				return false;
			}
			SoloPlugin.AdoptMachinePlayer(__instance, playerProfile);
