	[HarmonyPatch(typeof(GameBase), "TryStartGame")]
	internal static class PatchTryStartWho
	{
		private static bool Prefix(GameBase __instance, PlayerInteract playerInteract)
		{
			PlayerProfile playerProfile = SoloPlugin.ProfileFromInteract(playerInteract);
			if (playerProfile == null && !NetworkServer.active)
			{
				playerProfile = SoloPlugin.LocalProfile();
			}
			if (SoloPlugin.MorphBlocksPlay(playerProfile))
			{
				SoloPlugin.NoteMorphNoPlay(playerProfile);
				return false;
			}
			SoloPlugin.PendingPadPlayer = playerProfile;
			SoloPlugin.BalanceContext = playerProfile;
			if (SoloPlugin.GameIsPlaying(__instance))
			{
				SoloPlugin.AdoptMachinePlayer(__instance, playerProfile);
				return false;
			}
			SoloPlugin.AdoptMachinePlayer(__instance, playerProfile);
			if (SoloPlugin.UsesChipBets(__instance))
			{
				if (NetworkServer.active && SoloPlugin.EconomyFrozen())
				{
					return false;
				}
				if (NetworkServer.active && !SoloPlugin.TryChargeMachineUse(__instance, playerProfile))
				{
					return false;
				}
				SoloPlugin.NoteBetStart(__instance, playerProfile);
				if (NetworkServer.active)
				{
					SoloPlugin.ApplySideToStart(__instance, playerProfile);
				}
				return true;
			}
			if (NetworkServer.active && SoloPlugin.EconomyFrozen())
			{
				return false;
			}
			if (!SoloPlugin.CanAffordPlay(playerProfile))
			{
				return false;
			}
			if (!SoloPlugin.BetAllowsStart(__instance, playerProfile))
			{
				return false;
			}
			if (NetworkServer.active && !SoloPlugin.TryChargeMachineUse(__instance, playerProfile))
			{
				return false;
			}
			SoloPlugin.NoteBetStart(__instance, playerProfile);
			if (NetworkServer.active)
			{
				SoloPlugin.ApplySideToStart(__instance, playerProfile);
			}
			return true;
		}

		private static void Postfix(GameBase __instance)
		{
			if (SoloPlugin.GameIsPlaying(__instance))
			{
				SoloPlugin.StickRoundPlayer(__instance);
			}
			else
			{
				SoloPlugin.ReleaseGameRound(__instance);
			}
			SoloPlugin.BalanceContext = null;
		}
	}
	[HarmonyPatch(typeof(GameBase), "CanGameStart")]
	internal static class PatchCanGameStart
	{
		private static void Postfix(GameBase __instance, ref bool __result)
		{
			if (!__result)
			{
				return;
			}
			if (SoloPlugin.GameIsPlaying(__instance))
			{
				__result = false;
				return;
			}
			PlayerProfile playerProfile = SoloPlugin.PendingPadPlayer ?? SoloPlugin.LastPressProfile(__instance) ?? SoloPlugin.PlayerForGame(__instance);
			if (playerProfile == null)
			{
				playerProfile = SoloPlugin.BetUiPlayer();
			}
			if (SoloPlugin.MorphBlocksPlay(playerProfile))
			{
				__result = false;
			}
			else if (SoloPlugin.UsesChipBets(__instance))
			{
				if (!SoloPlugin.CanPlayOwnedMachine(__instance, playerProfile))
				{
					__result = false;
				}
			}
			else if (!SoloPlugin.CanAffordPlay(playerProfile) || !SoloPlugin.BetAllowsStart(__instance, playerProfile))
			{
				__result = false;
			}
			else if (!SoloPlugin.CanPlayOwnedMachine(__instance, playerProfile))
			{
				__result = false;
			}
		}
	}
	[HarmonyPatch(typeof(GameBase), "StartGame")]
	internal static class PatchStartGameBroke
	{
		private static bool Prefix(GameBase __instance)
		{
			if (SoloPlugin.GameIsPlaying(__instance))
			{
				SoloPlugin.StickRoundPlayer(__instance);
				return false;
			}
			PlayerProfile playerProfile = SoloPlugin.PendingPadPlayer ?? SoloPlugin.LastPressProfile(__instance) ?? SoloPlugin.PlayerForGame(__instance);
			if (playerProfile == null)
			{
				playerProfile = SoloPlugin.LastBetPlayer ?? SoloPlugin.LocalProfile();
			}
			if (SoloPlugin.MorphBlocksPlay(playerProfile))
			{
				SoloPlugin.NoteMorphNoPlay(playerProfile);
				return false;
			}
			if (SoloPlugin.UsesChipBets(__instance))
			{
				if (NetworkServer.active && !SoloPlugin.TryChargeMachineUse(__instance, playerProfile))
				{
					return false;
				}
				SoloPlugin.ClaimGameRound(__instance, playerProfile);
				SoloPlugin.StickRoundPlayer(__instance);
				if (NetworkServer.active)
				{
					SoloPlugin.NoteBetStart(__instance, playerProfile);
					SoloPlugin.CaptureSideRide(__instance, playerProfile);
				}
				return true;
			}
			if (!SoloPlugin.CanAffordPlay(playerProfile))
			{
				return false;
			}
			if (!SoloPlugin.BetAllowsStart(__instance, playerProfile))
			{
				return false;
			}
			if (NetworkServer.active && !SoloPlugin.TryChargeMachineUse(__instance, playerProfile))
			{
				return false;
			}
			SoloPlugin.ClaimGameRound(__instance, playerProfile);
			SoloPlugin.StickRoundPlayer(__instance);
			SoloPlugin.MarkLendPreset(__instance);
			if (NetworkServer.active)
			{
				SoloPlugin.NoteBetStart(__instance, playerProfile);
				SoloPlugin.CaptureSideRide(__instance, playerProfile);
			}
			return true;
		}
	}
	[HarmonyPatch(typeof(GameBase), "Payout")]
	internal static class PatchBonusDrawPayout
	{
		private static void Prefix(GameBase __instance, double multiplier)
		{
			SoloPlugin.SwallowPayoutBonusTix = true;
			SoloPlugin.StickRoundPlayer(__instance);
			SoloPlugin.ForceMoneyPlayer = SoloPlugin.PayoutTarget(__instance);
			if (NetworkServer.active)
			{
				PlayerProfile p = SoloPlugin.PayoutTarget(__instance) ?? SoloPlugin.PlayerForGame(__instance) ?? SoloPlugin.RoundOwnerProfile(__instance);
				SoloPlugin.CaptureSideRide(__instance, p);
				SoloPlugin.BeginPayoutMoney(__instance, multiplier, p);
			}
			if (NetworkServer.active)
			{
				PlayerProfile p2 = SoloPlugin.PayoutTarget(__instance) ?? SoloPlugin.BetServerPlayer(__instance);
				SoloPlugin.TryBonusDrawTickets(__instance, p2, multiplier);
			}
		}

		private static void Postfix(GameBase __instance, double multiplier)
		{
			if (NetworkServer.active)
			{
				SoloPlugin.ApplyPayoutMoney(SoloPlugin.PayoutTarget(__instance));
			}
			SoloPlugin.SwallowPayoutBonusTix = false;
			SoloPlugin.ForceMoneyPlayer = null;
			if (NetworkServer.active && !SoloPlugin.IsRoulette(__instance))
			{
				SoloPlugin.ApplySideRide(__instance, multiplier);
				SoloPlugin.ApplyOwnerProfitCut(__instance, multiplier);
			}
		}
	}
