	[HarmonyPatch(typeof(UpgradeManager), "ChangeUpgradeData")]
	internal static class PatchChangeUpgradeData
	{
		private static bool Prefix(ulong steamId, PlayerUpgradeType type, float amount)
		{
			if (!NetworkServer.active)
			{
				return true;
			}
			if (type == PlayerUpgradeType.BonusDraw)
			{
				Acc acc = SoloPlugin.AccFromSteam(steamId);
				if (acc != null)
				{
					acc.bonusDraw = 1;
				}
				try
				{
					UpgradeManager instance = NetworkSingleton<UpgradeManager>.Instance;
					if (instance != null)
					{
						instance.SetUpgradeData(steamId, PlayerUpgradeType.BonusDraw, 0.25f);
					}
				}
				catch
				{
				}
				return false;
			}
			return !SoloPlugin.ApplyUpgradeDrink(steamId, type);
		}
	}
