	internal static class PatchOrganPrices
	{
		private static bool Prefix(BodyShreddingMachine __instance)
		{
			if (!NetworkServer.active)
			{
				return true;
			}
			AccessTools.Field(typeof(BodyShreddingMachine), "_eyePrice").SetValue(__instance, 1000);
			AccessTools.Field(typeof(BodyShreddingMachine), "_mouthPrice").SetValue(__instance, 2000);
			AccessTools.Field(typeof(BodyShreddingMachine), "_bodyPrice").SetValue(__instance, 5000);
			MethodInfo methodInfo = AccessTools.Method(typeof(BodyShreddingMachine), "RpcSetPrices");
			if (methodInfo != null)
			{
				methodInfo.Invoke(__instance, new object[3] { 5000, 1000, 2000 });
			}
			return false;
		}
	}
	[HarmonyPatch(typeof(BodyShreddingMachine), "UserCode_RpcSetPrices__Int32__Int32__Int32")]
	internal static class PatchOrganBoard
	{
		private static void Postfix(BodyShreddingMachine __instance, int bodyPrice, int eyePrice, int mouthPrice)
		{
			object value = AccessTools.Field(typeof(BodyShreddingMachine), "priceTag").GetValue(__instance);
			if (value == null)
			{
				return;
			}
			string text = AccessTools.Field(typeof(BodyShreddingMachine), "localizedEyeString").GetValue(__instance) as string;
			string text2 = AccessTools.Field(typeof(BodyShreddingMachine), "localizedMouthString").GetValue(__instance) as string;
			string text3 = AccessTools.Field(typeof(BodyShreddingMachine), "localizedBodyString").GetValue(__instance) as string;
			if (string.IsNullOrEmpty(text))
			{
				text = "眼睛";
			}
			if (string.IsNullOrEmpty(text2))
			{
				text2 = "嘴巴";
			}
			if (string.IsNullOrEmpty(text3))
			{
				text3 = "身体";
			}
			string value2 = text + " $" + eyePrice + "\n" + text2 + " $" + mouthPrice + "\n" + text3 + " $" + bodyPrice;
			Type type = value.GetType();
			while (type != null)
			{
				PropertyInfo property = type.GetProperty("text");
				if (property != null)
				{
					property.SetValue(value, value2, null);
					break;
				}
				type = type.BaseType;
			}
		}
	}
