	[HarmonyPatch(typeof(BodyShreddingMachine), "TryShredEye")]
	internal static class PatchOrganShredEye
	{
		private static bool Prefix(BodyShreddingMachine __instance, PlayerOrgans po, PlayerOrganData data, ref bool __result)
		{
			if (!NetworkServer.active)
			{
				return true;
			}
			__result = false;
			if (po == null || data == null)
			{
				return false;
			}
			if (!SoloPlugin.TryChargeMachineUse(__instance, SoloPlugin.ProfileFromOrgans(po)))
			{
				return false;
			}
			if (!data.leftEye && !data.rightEye)
			{
				return false;
			}
			if (!SoloPlugin.PayOrganCash(po, 1000.0))
			{
				return false;
			}
			OrganManager organManager = SoloPlugin.OrgMgr();
			if (organManager != null)
			{
				if (data.leftEye)
				{
					organManager.ServerToggleOrgan(po, OrganType.LeftEye, false);
				}
				else
				{
					organManager.ServerToggleOrgan(po, OrganType.RightEye, false);
				}
			}
			SoloPlugin.CallOrganRpc(__instance, "RpcOnEyeShredded");
			__result = true;
			return false;
		}
	}
