	[HarmonyPatch(typeof(UIColorManager), "GetPlayerColor")]
	internal static class PatchMorphPlayerColor
	{
		private static bool Prefix(UIColorManager __instance, ref Color __result)
		{
			if (__instance == null)
			{
				return true;
			}
			PlayerProfile playerProfile = null;
			try
			{
				playerProfile = __instance.GetComponent<PlayerProfile>();
			}
			catch
			{
			}
			if (playerProfile == null)
			{
				try
				{
					playerProfile = __instance.GetComponentInParent<PlayerProfile>();
				}
				catch
				{
				}
			}
			if (playerProfile == null)
			{
				try
				{
					playerProfile = __instance.GetComponentInChildren<PlayerProfile>();
				}
				catch
				{
				}
			}
			Color col;
			if (SoloPlugin.TryMorphTint(playerProfile, __instance, out col) && col.r <= 0.92f && col.g <= 0.92f && col.b <= 0.92f)
			{
				__result = col;
				return false;
			}
			return true;
		}
	}
