	internal static class JobPick
	{
		private static int _picked;

		private static float _open = 1f;

		private static float _appearAt;

		private static bool _delayArm;

		private static GUIStyle _coolSt;

		private static GUIStyle _title;

		private static GUIStyle _nameSt;

		private static GUIStyle _descSt;

		private static GUIStyle _hint;

		private static GUIStyle _badge;

		private static Texture2D _gold;

		private static Texture2D _green;

		private static Texture2D _black;

		private static Texture2D _silver;

		private static Texture2D _fade;

		private static Texture2D _glow;

		internal static void Tick()
		{
			if (!NetworkClient.active)
			{
				_delayArm = false;
				return;
			}
			int localJob = SoloPlugin.LocalJob;
			if (localJob == 0)
			{
				_picked = 0;
				_open = 1f;
				if (!_delayArm)
				{
					_appearAt = Time.unscaledTime + 2f;
					_delayArm = true;
				}
				if (!(Time.unscaledTime < _appearAt))
				{
					int num = DigitPressed();
					if (num >= 1 && num <= 4 && CanPick(num))
					{
						Pick(num);
					}
				}
			}
			else
			{
				_picked = localJob;
				_delayArm = false;
				_open = Mathf.MoveTowards(_open, 0f, Time.unscaledDeltaTime / 0.4f);
			}
		}

		private static bool CanPick(int job)
		{
			switch (job)
			{
			case 2:
				return true;
			case 3:
				return SoloPlugin.SeatThief < 2;
			case 1:
				return !SoloPlugin.SeatBoss;
			case 4:
				if (SoloPlugin.SeatBoss)
				{
					return !SoloPlugin.SeatGuard;
				}
				return false;
			default:
				return false;
			}
		}

		private static int DigitPressed()
		{
			try
			{
				Keyboard current = Keyboard.current;
				if (current != null)
				{
					if (current.digit1Key.wasPressedThisFrame || current.numpad1Key.wasPressedThisFrame)
					{
						return 1;
					}
					if (current.digit2Key.wasPressedThisFrame || current.numpad2Key.wasPressedThisFrame)
					{
						return 2;
					}
					if (current.digit3Key.wasPressedThisFrame || current.numpad3Key.wasPressedThisFrame)
					{
						return 3;
					}
					if (current.digit4Key.wasPressedThisFrame || current.numpad4Key.wasPressedThisFrame)
					{
						return 4;
					}
				}
			}
			catch
			{
			}
			try
			{
				if (Input.GetKeyDown(KeyCode.Alpha1) || Input.GetKeyDown(KeyCode.Keypad1))
				{
					return 1;
				}
				if (Input.GetKeyDown(KeyCode.Alpha2) || Input.GetKeyDown(KeyCode.Keypad2))
				{
					return 2;
				}
				if (Input.GetKeyDown(KeyCode.Alpha3) || Input.GetKeyDown(KeyCode.Keypad3))
				{
					return 3;
				}
				if (Input.GetKeyDown(KeyCode.Alpha4) || Input.GetKeyDown(KeyCode.Keypad4))
				{
					return 4;
				}
			}
			catch
			{
			}
			return 0;
		}

		private static void Pick(int job)
		{
			if (!CanPick(job))
			{
				return;
			}
			_picked = job;
			SoloPlugin.LocalJob = job;
			try
			{
				NetworkClient.Send(new SideMsg
				{
					json = "J\t" + job
				});
			}
			catch
			{
			}
		}

		internal static void Draw()
		{
			Styles();
			if (SoloPlugin.LocalJob == 0 && NetworkClient.active && Time.unscaledTime >= _appearAt)
			{
				Event current = Event.current;
				if (current != null && current.type == EventType.KeyDown)
				{
					int num = 0;
					if (current.keyCode == KeyCode.Alpha1 || current.keyCode == KeyCode.Keypad1 || current.character == '1')
					{
						num = 1;
					}
					else if (current.keyCode == KeyCode.Alpha2 || current.keyCode == KeyCode.Keypad2 || current.character == '2')
					{
						num = 2;
					}
					else if (current.keyCode == KeyCode.Alpha3 || current.keyCode == KeyCode.Keypad3 || current.character == '3')
					{
						num = 3;
					}
					else if (current.keyCode == KeyCode.Alpha4 || current.keyCode == KeyCode.Keypad4 || current.character == '4')
					{
						num = 4;
					}
					if (num > 0 && CanPick(num))
					{
						Pick(num);
						current.Use();
					}
				}
			}
			if (_picked == 0 && SoloPlugin.LocalJob != 0)
			{
				_picked = SoloPlugin.LocalJob;
			}
			if (_picked != 0 && _open <= 0.02f)
			{
				DrawBadge();
			}
			else
			{
				if ((_picked == 0 && SoloPlugin.LocalJob == 0 && SoloPlugin.SharedDay != 1) || !NetworkClient.active)
				{
					return;
				}
				if (_picked == 0 && _open < 0.99f)
				{
					_open = 1f;
				}
				if (_picked == 0 && SoloPlugin.LocalJob == 0)
				{
					if (!_delayArm)
					{
						_appearAt = Time.unscaledTime + 2f;
						_delayArm = true;
					}
					if (Time.unscaledTime < _appearAt)
					{
						return;
					}
				}
				float open = _open;
				if (open <= 0.35f)
				{
					DrawBadge();
					return;
				}
				float num2 = 1f;
				if (_picked == 0 && SoloPlugin.LocalJob == 0)
				{
					num2 = Mathf.Clamp01((Time.unscaledTime - _appearAt) / 0.85f);
					num2 = num2 * num2 * (3f - 2f * num2);
				}
				open *= num2;
				float num3 = 780f;
				float num4 = 325f;
				float num5 = 885f;
				float num6 = 1035f;
				float num7 = 515f;
				float num8 = 625f;
				float num9 = num5 - num3;
				float num10 = num6;
				float num11 = num7 - num4;
				float num12 = num8;
				if ((float)Screen.width != 1920f || (float)Screen.height != 1080f)
				{
					float num13 = (float)Screen.width / 1920f;
					float num14 = (float)Screen.height / 1080f;
					num9 *= num13;
					num10 *= num13;
					num11 *= num14;
					num12 *= num14;
					num3 *= num13;
					num4 *= num14;
				}
				GUI.color = new Color(1f, 1f, 1f, open);
				GUI.Label(new Rect(0f, 8f, Screen.width, 40f), "职业", _title);
				DrawCard(new Rect(num9, num11, num3, num4), _gold, "1  赌场老板", "1. 商店金票价钱永久减半且不会涨价\n2. 其他玩家用你买的机子会给你分成\n3. 其他玩家输钱的一部分会进你的口袋\n4. 可以打赏 或 向其他玩家贷款", new Color(0.25f, 0.14f, 0.02f), CanPick(1) || SoloPlugin.LocalJob == 1, CardIn(0));
				DrawCard(new Rect(num10, num11, num3, num4), _green, "2  赌徒", "1. 所有升级不会重置\n2. 所有升级可以叠加\n3. 每日投篮有概率将你的奖金或指标翻倍\n4. 每日可以标记一位玩家来对决 胜者将得到败家所有现金", new Color(0.02f, 0.18f, 0.06f), true, CardIn(1));
				DrawCard(new Rect(num9, num12, num3, num4), _black, "3  小偷", "1. 可以偷其他玩家或者NPC的钱\n2. 可以伪装成其他玩家或者NPC\n3. 移动速度更快", Color.white, CanPick(3) || SoloPlugin.LocalJob == 3, CardIn(2));
				DrawCard(new Rect(num10, num12, num3, num4), _silver, "4  保安", "1. 你和老板是一伙的 (不要见钱眼开)\n2. 买球棒或手枪不花钱\n3. 拿起球棒速度增加15%\n4. 抓住小偷会让你的工资增加 (老板生气第二天你将不会得到工资)", new Color(0.12f, 0.14f, 0.18f), CanPick(4) || SoloPlugin.LocalJob == 4, CardIn(3));
				GUI.Label(new Rect(0f, (float)Screen.height - 36f, Screen.width, 28f), "按 1 / 2 / 3 / 4 选择 · 小偷最多2人", _hint);
				GUI.color = Color.white;
			}
		}

		private static float CardIn(int i)
		{
			if (_picked != 0 || SoloPlugin.LocalJob != 0)
			{
				return 1f;
			}
			float value = (Time.unscaledTime - _appearAt - (float)i * 0.08f) / 0.7f;
			value = Mathf.Clamp01(value);
			return value * value * (3f - 2f * value);
		}

		private static void DrawCard(Rect r, Texture2D bg, string name, string desc, Color nameCol, bool lit, float fade)
		{
			if (fade <= 0.01f)
			{
				return;
			}
			Color color = GUI.color;
			float num = color.a * fade;
			float num2 = 0.94f + 0.06f * fade;
			float num3 = r.x + r.width * 0.5f;
			float num4 = r.y + r.height * 0.5f;
			r = new Rect(num3 - r.width * num2 * 0.5f, num4 - r.height * num2 * 0.5f, r.width * num2, r.height * num2);
			GUI.color = new Color(color.r, color.g, color.b, num);
			if (lit)
			{
				if (_glow != null)
				{
					GUI.DrawTexture(new Rect(r.x - 6f, r.y - 6f, r.width + 12f, r.height + 12f), _glow);
				}
				GUI.DrawTexture(r, bg);
			}
			else
			{
				GUI.color = new Color(color.r, color.g, color.b, num * 0.32f);
				GUI.DrawTexture(r, bg);
				if (_fade != null)
				{
					GUI.DrawTexture(r, _fade);
				}
				GUI.color = new Color(color.r, color.g, color.b, num);
			}
			_nameSt.fontSize = Mathf.Clamp((int)(r.height * 0.11f), 22, 36);
			_descSt.fontSize = Mathf.Clamp((int)(r.height * 0.088f), 18, 26);
			_descSt.alignment = TextAnchor.MiddleCenter;
			Color textColor = nameCol;
			if (!lit)
			{
				textColor = new Color(nameCol.r, nameCol.g, nameCol.b, 0.38f);
			}
			_nameSt.normal.textColor = textColor;
			_descSt.normal.textColor = textColor;
			GUI.Label(new Rect(r.x + 16f, r.y + 10f, r.width - 32f, r.height * 0.2f), name, _nameSt);
			string[] array = desc.Split(new char[1] { '\n' });
			int num5 = ((array != null) ? array.Length : 0);
			if (num5 < 1)
			{
				num5 = 1;
			}
			float num6 = (float)_descSt.fontSize * 1.62f;
			float num7 = (float)num5 * num6;
			float num8 = r.y + r.height * 0.24f;
			float num9 = r.height * 0.7f;
			float num10 = num8 + (num9 - num7) * 0.5f;
			if (num10 < num8)
			{
				num10 = num8;
			}
			for (int i = 0; i < num5; i++)
			{
				GUI.Label(new Rect(r.x + 24f, num10 + (float)i * num6, r.width - 48f, num6), array[i], _descSt);
			}
			GUI.color = color;
		}

		private static void DrawBadge()
		{
			string text = JobName(_picked);
			Color textColor = Color.black;
			Texture2D image = _black;
			if (_picked == 1)
			{
				textColor = new Color(0.28f, 0.16f, 0.02f);
				image = _gold;
			}
			else if (_picked == 2)
			{
				textColor = new Color(0.02f, 0.2f, 0.07f);
				image = _green;
			}
			else if (_picked == 4)
			{
				textColor = new Color(0.12f, 0.14f, 0.18f);
				image = _silver;
			}
			if (_picked == 4)
			{
				text = "【" + text + "】";
			}
			float num = 168f;
			float height = 44f;
			float num2 = ((float)Screen.width - num) * 0.5f;
			GUI.DrawTexture(new Rect(num2, 10f, num, height), image);
			_badge.normal.textColor = textColor;
			GUI.Label(new Rect(num2, 10f, num, height), text, _badge);
			if (_picked == 4)
			{
				_coolSt.alignment = TextAnchor.MiddleLeft;
				GUI.Label(new Rect(num2 + num + 10f, 10f, 64f, height), SoloPlugin.LocalCatches.ToString(), _coolSt);
			}
			if (_picked == 3 && Time.unscaledTime < SoloPlugin.StealCoolUntil)
			{
				int num3 = (int)Mathf.Ceil(SoloPlugin.StealCoolUntil - Time.unscaledTime);
				if (num3 < 0)
				{
					num3 = 0;
				}
				GUI.Label(new Rect(num2 + num + 8f, 10f, 90f, height), num3 + "s", _coolSt);
			}
		}

		private static string JobName(int job)
		{
			switch (job)
			{
			case 1:
				return "赌场老板";
			case 2:
				return "赌徒";
			case 3:
				return "小偷";
			case 4:
				return "保安";
			default:
				return "职业";
			}
		}

		private static Texture2D Solid(Color c)
		{
			Texture2D texture2D = new Texture2D(1, 1, TextureFormat.RGBA32, false);
			texture2D.SetPixel(0, 0, c);
			texture2D.Apply();
			texture2D.hideFlags = HideFlags.HideAndDontSave;
			return texture2D;
		}

		private static void Styles()
		{
			if (_title == null)
			{
				_gold = Solid(new Color(0.98f, 0.82f, 0.22f, 1f));
				_green = Solid(new Color(0.22f, 0.82f, 0.38f, 1f));
				_black = Solid(new Color(0.16f, 0.16f, 0.18f, 1f));
				_silver = Solid(new Color(0.78f, 0.82f, 0.9f, 1f));
				_fade = Solid(new Color(0.02f, 0.02f, 0.03f, 0.78f));
				_glow = Solid(new Color(1f, 0.95f, 0.55f, 0.85f));
				GUIStyle gUIStyle = new GUIStyle(GUI.skin.label);
				gUIStyle.fontSize = 34;
				gUIStyle.fontStyle = FontStyle.Bold;
				gUIStyle.alignment = TextAnchor.MiddleCenter;
				_title = gUIStyle;
				_title.normal.textColor = new Color(1f, 0.86f, 0.28f);
				GUIStyle gUIStyle2 = new GUIStyle(GUI.skin.label);
				gUIStyle2.fontSize = 20;
				gUIStyle2.fontStyle = FontStyle.Bold;
				gUIStyle2.alignment = TextAnchor.MiddleCenter;
				gUIStyle2.wordWrap = true;
				_nameSt = gUIStyle2;
				GUIStyle gUIStyle3 = new GUIStyle(GUI.skin.label);
				gUIStyle3.fontSize = 15;
				gUIStyle3.alignment = TextAnchor.UpperCenter;
				gUIStyle3.wordWrap = true;
				_descSt = gUIStyle3;
				GUIStyle gUIStyle4 = new GUIStyle(GUI.skin.label);
				gUIStyle4.fontSize = 16;
				gUIStyle4.alignment = TextAnchor.MiddleCenter;
				_hint = gUIStyle4;
				_hint.normal.textColor = new Color(0.85f, 0.85f, 0.85f);
				GUIStyle gUIStyle5 = new GUIStyle(GUI.skin.label);
				gUIStyle5.fontSize = 24;
				gUIStyle5.fontStyle = FontStyle.Bold;
				gUIStyle5.alignment = TextAnchor.MiddleCenter;
				_badge = gUIStyle5;
				GUIStyle gUIStyle6 = new GUIStyle(GUI.skin.label);
				gUIStyle6.fontSize = 22;
				gUIStyle6.fontStyle = FontStyle.Bold;
				gUIStyle6.alignment = TextAnchor.MiddleRight;
				_coolSt = gUIStyle6;
				_coolSt.normal.textColor = new Color(0.85f, 0.88f, 0.95f);
			}
		}
	}
